INSERT INTO `wp_affair` (`id`, `affair_type`, `accurate`, `year`, `month`, `day`, `title`, `country_code`, `brief`, `description`, `baidu_url`, `path_point`, `status`) VALUES
(1, 'keypoint', '', 1380, 2, 2, '胡惟庸案', 'mingchao', '朱元璋诛杀丞相胡惟庸，废除丞相之职，设承宣布政使司、提刑按察使司、都指挥使司三司分掌权力，进一步的加强了中央集权。', '明洪武十三年（1380年）正月，朱元璋以“图谋不轨”罪诛左丞相的胡惟庸，取消中书省，废除丞相之职，更定六部。此案为明初三大案之首，涉及面广，杀死官员之多为历代所罕见。', '', '', 0),
(2, 'keypoint', '', 1371, 0, 0, '明朝施政', 'mingchao', '正月确立文武官岁禄制度，细化九品十八级俸禄标准；六月陶凯受命改制宴享乐章，摒弃元代旧乐，确立《本太初》等九奏雅乐。', '', '', '', 0),
(3, 'keypoint', '', 1380, 0, 0, '查理六世加冕', 'waluwawangchao', '又称可爱的查理。瓦卢瓦王朝第四位国王（1380年－1422年在位）。查理五世之子。', '', '', '', 0),
(4, 'keypoint', '', 1380, 0, 0, '《臣戒录》编成', 'mingchao', '朱元璋便命翰林儒臣纂录历代诸王、宗戚、宦臣之属悖逆不道者凡二百一十二人，备其行事，以类编辑。颁示中外之臣，俾知所警。', '', '', '', 0),
(5, 'keypoint', '', 1368, 0, 0, '元明更替', 'mingchao', '朱元璋在应天府称帝，建立明朝，明军北伐攻克元大都，元顺帝北逃，元朝统治终结。明朝由此开始276年的统治，初期定都南京，后迁至北京。', '', '', '', 0),
(6, 'keypoint', '', 1368, 0, 0, '朱升纂修《女诫》', 'mingchao', '朱元璋命翰林儒臣修《女诫》。纂述女诫及古贤妃可以效法的事例。翰林学士朱升等遂奉命纂修。不久，即呈送朱元璋。', '', '', '', 0),
(7, 'keypoint', '', 1369, 0, 0, '明朝施政', 'mingchao', '设立都转运盐使司、盐课提举司、巡检司韵；改定朝贺赞呼；立临濠(今安徽凤阳临淮镇)为中都。', '', '', '', 0),
(8, 'keypoint', '', 1369, 0, 0, '明朝施政', 'mingchao', '纂修《元史》；编撰《祖训录》；定封建诸王国邑及官属之制；天下府州皆立学校；立功臣庙；更定翰林院官制；', '', '', '', 0),
(9, 'keypoint', '', 1369, 0, 0, '人物动向', 'mingchao', '朱元璋论仁义暴虐、名爵职守；刘基论待大臣之礼；朱升献安邦策；刑部尚书世家宝坐事贬庐陵知县；户部尚书朱昭贬谪苏州知府；', '', '', '', 0),
(10, 'keypoint', '', 1370, 0, 0, '帖木儿汗国建立', 'tiemuerdiguo', '西察合台蒙古贵族帖木儿建立帖木儿帝国，帖木儿帝国吸收不同民族的优秀文化成果，交融汇合，展现了具有突厥特色的文化新貌，进一步发展了突厥—伊朗文化。', '', '', '', 0),
(11, 'keypoint', '', 1370, 0, 0, '明朝施政', 'mingchao', '推行多项制度变革，包括分封藩王；设立五等勋爵；颁布科举制雏形及建立钦天监；命徐达带兵北伐迫使北元北撤；并实施海禁。', '', '', '', 0),
(12, 'keypoint', '', 1370, 0, 0, '明朝施政', 'mingchao', '严肃殿陛礼法；王府官制的制定；分封诸皇子为王；五等勋爵的制定；封阿答阿者为占城国王。', '', '', '', 0),
(13, 'keypoint', '', 1370, 0, 0, '利摩日大屠杀', '', '百年战争中，英占区的法国城市利摩日（Limoges）暴动，时患绝症的黑太子爱德华率英军破城，残杀居民3000余人，史称利摩日大屠杀。', '', 'https://baike.baidu.com/item/利摩日大屠杀/0', '', 0),
(14, 'keypoint', '', 1370, 5, 4, '施特拉尔松德条约', '', '结束了汉萨同盟与丹麦王国之间的战争，也标志着汉萨同盟到达其力量的巅峰。', '', 'https://baike.baidu.com/item/施特拉尔松德条约/8867324', '', 0),
(15, 'keypoint', '', 1371, 0, 0, '明朝军事动向', 'mingchao', '二月起兵分两路平定四川，汤和、傅友德率军攻克重庆、成都，终结明昇割据政权；工部制定用宝金牌、武臣符牌制度，规范军务信物形制与使用规则。逃军惩罚条章的制定', '', '', '', 0),
(16, 'keypoint', '', 1371, 0, 0, '明朝施政', 'mingchao', '吏部奏报天下府州县数额；亲王宫殿规制的制定；内城门禁法的制定。', '', '', '', 0),
(17, 'keypoint', '', 907, 0, 0, '朱温篡唐', 'houliang', '该年四月，朱温迫使唐哀帝禅让，建立后梁政权并定都开封，张文蔚等唐朝旧臣参与政权交接。', '', '', '', 0),
(18, 'keypoint', '', 907, 0, 0, '淮南政归张颢、徐温', 'yangwu', '正月九日，淮南左、右牙指挥使张颢、徐温以\"兵谏\"名义，帅牙兵入使府庭院，挝杀淮南节度使、弘农王杨渥的亲信数十人，控制淮>南政权。', '', '', '', 0),
(19, 'keypoint', '', 907, 0, 0, '马殷径封楚王', 'nanchu', '四月，梁王朱温即帝位后，即行封赏。二十五日，以特殊恩典，不经郡王，而径封武安节度使马殷为楚王。', '', '', '', 0),
(20, 'keypoint', '', 907, 0, 0, '李茂贞自开岐王府', 'houliang', '凤翔节度使李茂贞仍奉唐朔，但以自己辖地兵力不强，虽知唐亡而不敢称帝。遂开岐王府，置百官，自己称王而妻称皇后。', '', '', '', 0),
(21, 'keypoint', '', 907, 0, 0, '梁进钱镠爵吴越王', 'wuyue', '梁进封两浙节度使钱镠吴越王。钱镠在李唐时曾求为吴越王，未获允。此时后梁新建国，为笼络人心，封钱镠为吴越王。', '', '', '', 0),
(22, 'keypoint', '', 907, 0, 0, '高季昌节度荆南', 'nanping', '梁以唐权知荆南留后高季昌为节度使。季昌也借机发展，荆南才逐渐成为独立于各势力集团之间的地方政权。', '', '', '', 0),
(23, 'keypoint', '', 907, 0, 0, '吴越取处州', 'wuyue', '两浙节度使钱镠命子传璙、传瓘讨温州。擒斩卢佶。继而又移兵袭处州卢约。五月，卢约以处州降吴越。', '', '', '', 0),
(24, 'keypoint', '', 907, 0, 0, '楚、淮浏阳之战', 'yangwu', '淮南弘农王杨渥以鄂岳观察使刘存为西南面招讨使，率陈知新、刘威等领三万水军攻楚。淮军裨将战死百余人，士卒伤亡数以万计，楚获>准军战舰八百艘。', '', '', '', 0),
(25, 'keypoint', '', 907, 0, 0, '蜀王建称帝', 'qianshu', '蜀王王建于成都即皇帝位，建虽出身行伍，但好与书生谈论，粗晓其理。唐末战乱，衣冠之族多避难于蜀，建皆能礼而用之，因此，蜀中典章\r\n文物多有唐代遗风。', '', '', '', 0),
(26, 'keypoint', '', 907, 0, 0, '雷彦恭为祸荆、楚', 'houliang', '梁武贞节度使雷彦恭贪残狡狯，常攻掠四方，深为荆、湖之患。梁于九月二十二日削其官爵，命楚王马殷、荆南节度使高季昌讨之。', '', '', '', 0),
(27, 'keypoint', '', 907, 0, 0, '梁赦逃亡士卒之罪', 'houliang', '朱全忠为藩镇时，用法苛严，将校战死，部士卒一律斩首，称“跋队斩”。士卒失去主将便多逃亡。下诏赦免亡卒之罪，亦准其归还乡里，于是盗减十之七八。', '', '', '', 0),
(28, 'keypoint', '', 907, 0, 0, '辽国建立', 'liaoguo', '辽太祖耶律阿保机统一契丹各部称汗，国号“契丹”。', '', '', '', 0),
(29, 'keypoint', '', 965, 0, 0, '宋师平蜀', 'beisong', '西路王全斌，东路刘廷让，两路直逼成都，孟昶举城投降，后蜀灭亡。', '', '', '', 0),
(30, 'keypoint', '', 965, 0, 0, '全师雄揭竿作乱', 'beisong', '王全斌克扣军饷，后蜀将领全师雄，反叛朝廷。后为刘光义，曹彬击溃败亡。', '', '', '', 0),
(31, 'keypoint', '', 965, 0, 0, '嘉州之战', 'beisong', '虎捷指挥使吕翰据嘉州反叛，与全师雄部将刘泽合兵，众至五万，诛杀刺史、通判；曹彬与王仁赡率大军包围嘉州，吕翰弃城遁逃，曹彬重创叛军，吕翰率残军逃至雅州。', '', '', '', 0),
(32, 'keypoint', '', 965, 0, 0, '康延泽定普州', 'beisong', '诏以西川兵马都监康延泽为普州刺史。大败叛将刘泽三万余众。普州境内始平，诏以延泽兼东川七州招、安巡检使。', '', '', '', 0),
(33, 'keypoint', '', 965, 0, 0, '室韦叛辽', 'beisong', '近侍东儿进匕箸不时，耶律璟手刃刺之。大黄室韦酋长寅尼吉叛。小黄室韦叛辽，雅里斯、楚思率军征讨，为宋军所败。后室韦酋长寅尼吉率部逃入敌烈。', '', '', '', 0),
(34, 'keypoint', '', 965, 0, 0, '吕余庆整顿吏治', 'beisong', '蜀境骚然，群盗四起，太祖特命参知政事吕余庆权知成都府。吕余庆到位后，大力整顿吏治。将士畏服，蜀民安居，境内宴然。以功加吏部侍\r\n郎。', '', '', '', 0),
(35, 'keypoint', '', 965, 0, 0, '冯瓒知梓州', 'beisong', '宋师初平剑外，盗寇横行。诏命枢密直学士冯瓒知梓州。后蜀军校上官进哗变，冯瓒俘获上官进，立斩于市。冯瓒招降敌军千余人，赦其罪，梓州\r\n始安。', '', '', '', 0),
(36, 'keypoint', '', 965, 0, 0, '王全斌屠杀蜀降兵', 'beisong', '全师雄率蜀军作乱，宋将请求尽诛降兵。康延泽请求释放七千余老幼病残者，诸将不从，尽诛蜀兵二万七千余人；蜀民闻讯，坚拒宋军。', '', '', '', 0),
(37, 'keypoint', '', 964, 0, 0, '潘美伐南汉', 'beisong', '潘美率军攻克郴州，为平定南汉建立据点；南汉主刘鋹昏庸无能，权力由宦官及宫女分掌。', '', '', '', 0),
(38, 'keypoint', '', 964, 0, 0, '王全斌等伐蜀', 'beisong', '初蜀相李吴曾主张通使于宋，以保平安。但掌管军政机要的王昭远则主张抗宋，劝说蜀主派赵彦韬等以蜡书间行，约北汉济河同举兵，夹攻宋兵。宋太祖知道后，出兵伐蜀。', '', '', '', 0),
(39, 'keypoint', '', 964, 0, 0, '茶叶产销专卖', 'beisong', '宋初为加强税赋管理，在淮南等地设立了管理茶场的机构，推行榷茶制度以管控茶叶专卖，相继有十三处买卖茶场。榷茶制度历经交引法、茶引法等变革至北宋中期改为自由交易。', '', '', '', 0),
(40, 'keypoint', '', 964, 0, 0, '乌古叛辽', 'beisong', '乌古叛辽，劫掠百姓财产牲畜。详稳僧隐率军平定，辽军失利，僧隐阵亡。', '', '', '', 0),
(41, 'keypoint', '', 964, 0, 0, '始置参知政事', 'beisong', '范质、王溥、魏仁浦罢相。枢密使赵普迁为门下侍郎、平章事、集贤院大学士。以兵部侍郎薛居正等并本官参知政事，以分普权。后参知政事成为实权要职，奠定中枢权力制衡格局。', '', '', '', 0),
(42, 'keypoint', '', 964, 0, 0, '攻取辽州', 'beisong', '太祖命李继勋与康延泽、尹训等率步骑万余人攻辽州。李继勋因攻取辽州有功，于乾德五年加同平章事。', '', '', '', 0),
(43, 'keypoint', '', 964, 0, 0, '太祖夜至普宅', 'beisong', '太祖、晋王至普宅。三人就地设垫，炽炭烧肉，普妻行酒。共商平太原计。普以太原可阻边患，不如先征蜀国。遂计议平蜀之策。', '', '', '', 0),
(44, 'keypoint', '', 964, 0, 0, '最早春联实物', 'houshu', '后蜀主孟昶于当年除夕命学士辛寅逊题写“新年纳余庆，嘉节号长春”桃符联，被后世视为现存最早春联实物，标志春联由驱邪桃符向文学形式转>变。', '', '', '', 0),
(45, 'keypoint', '', 963, 0, 0, '年号变更', 'beisong', '十一月十六日，赵匡胤在汴京南郊举行祭祀大典，宣布当年改元乾德。此次改元与平定荆湖地区的军事胜利直接相关，典礼中同时赦免死刑以下罪犯\r\n。', '', '', '', 0),
(46, 'keypoint', '', 963, 0, 0, '南方军事行动', 'beisong', '潘美部于农历二月在湖南江华县歼灭南汉军队，巩固了北宋对湖南地区的实际控制权。同年七月，后蜀雅州守将曹光实主动归附北宋，献出州城\r\n府库并协助宋军接管防务。', '', '', '', 0),
(47, 'keypoint', '', 963, 0, 0, '法典制定', 'beisong', '工部尚书窦仪领衔编纂的《宋建隆重详定刑统》于七月完成。首次采用雕版印刷在全国发行。其创新性地将刑事敕令与律文合编，确立了\"折杖法\"等新型刑罚体系。', '', '', '', 0),
(48, 'keypoint', '', 963, 0, 0, '政策方针', 'beisong', '针对新占领的湖南地区颁布特殊税收政策：免除当地全年茶税；降低商税至十取其一；统一全国斛斗计量标准；允许士兵复员领取耕牛务农；', '', '', '', 0),
(49, 'keypoint', '', 963, 0, 0, '安陵改葬工程坍塌', 'beisong', '十二月安陵改葬工程发生坍塌事故，造成200余名工匠死亡。朝廷随即暂停工程建设，对遇难者家属进行抚恤，并追究工部相关官员的监管>责任。', '', '', '', 0),
(50, 'keypoint', '', 963, 0, 0, '常德瘟疫', 'beisong', '湖南常德地区夏季爆发大规模瘟疫，朝廷由太医局调配防疫药方设立官办药局免费发放药物。', '', '', '', 0),
(51, 'keypoint', '', 963, 0, 0, '高丽使臣遇海难', 'beisong', '高丽使臣金律来华途中遭遇海难，太祖诏令登州官府：打捞沉船中朝贡物品；妥善安葬23名遇难船员；护送幸存者至汴京觐见', '', '', '', 0),
(52, 'keypoint', '', 963, 0, 0, '施政和人事变动', 'beisong', '罢除武成王庙白起配享资格；追赠马全义为镇国节度使；推行文官出任州郡长官制度；礼部尚书张昭正式致仕；', '', '', '', 0),
(53, 'keypoint', '', 962, 0, 0, '柴宗训迁至房州', 'beisong', '原后周皇帝柴宗训被移往房陵（今湖北省房县）居住居住。', '', '', '', 0),
(54, 'keypoint', '', 962, 0, 0, '高保勖病逝', 'nanping', '荆南高保勖病逝，其侄（高保融之子）高继冲继位。', '', '', '', 0),
(55, 'keypoint', '', 962, 0, 0, '伽色尼王朝', '', '萨曼王朝突厥将领阿尔普特勤于962年攻占加兹尼后奠定基础，其女婿萨布克特勤正式建立政权。', '', '', '', 0),
(56, 'keypoint', '', 962, 0, 0, '奥托一世加冕', 'shenshengluomadiguo', '德意志国王、萨克森王朝的奥托一世在罗马由教宗约翰十二世加冕称帝（962年－973年在位），成为罗马的监护人和罗马天主教世\r\n界的最高统治者。', '', '', '', 0),
(57, 'keypoint', '', 961, 0, 0, '杯酒释兵权', 'beisong', '宋太祖赵匡胤通过“杯酒释兵权”，解除禁军将领石守信、王审琦等人的兵权，此举为宋朝重文轻武体制的开端。', '', '', '', 0),
(58, 'keypoint', '', 961, 0, 0, '昭宪太后逝世', 'beisong', '昭宪太后，宋太祖赵匡胤生母，赵弘殷正室。据传有金匮之盟，即杜太后临终时召赵普入宫记录遗言，交代未来的皇位继承问题，劝说太祖赵匡胤死后传位于其弟。', '', '', '', 0),
(59, 'keypoint', '', 961, 0, 0, '李璟洪州', 'nantang', '南唐元宗李璟于该年二月迁都洪州（今南昌），并大兴土木仿建金陵皇宫，但在迁都三个月后逝世。其子李煜继位，成为南唐后主，此\n时南唐已处于北宋逐步统一的进程中。', '', '', '', 0),
(60, 'keypoint', '', 951, 0, 0, '后周平徐州', 'houzhou', '后周平定徐州叛乱，巩固新政权；', '', '', '', 0),
(61, 'keypoint', '', 951, 0, 0, '刘崇建北汉', 'beihan', '后汉河东节度使刘崇在太原称帝建立北汉，依托并、汾等十二州与后周对峙；', '', '', '', 0),
(62, 'keypoint', '', 951, 0, 0, '南汉控制岭南', 'nanhan', '南汉乘楚国内乱之机扩张，控制岭南全境。', '', '', '', 0),
(63, 'keypoint', '', 951, 0, 0, '南唐灭楚', 'nantang', '南唐将领边镐攻灭马楚政权，占据湖南地区。楚指挥使徐威等囚马希萼于衡山。立马希崇。马希崇引南唐入楚，并遣使使奉笺请降。南唐军入长沙，楚亡国。', '', '', '', 0),
(64, 'keypoint', '', 951, 0, 0, '察割政变', 'liaoguo', '契丹贵族察割发动政变弑君，后被世宗弟娄国亲手杀死察割。耶律璟继位为辽穆宗；', '', '', '', 0),
(65, 'keypoint', '', 951, 0, 0, '北汉结辽寇晋州', 'beihan', '刘崇对辽自称侄皇帝，并请辽行册礼，辽于六月册刘崇为大汉神武皇帝。辽世宗耶律阮亲率诸部南下援北汉攻后周，途中遇弑。', '', '', '', 0),
(66, 'keypoint', '', 952, 0, 0, '折德扆挫败汉军', 'houzhou', '正月，北汉寇府州(今陕西府谷)，府州防御使折德扆击败北汉军，杀二千余人。二月，折德扆又拔北汉岢岚(今山西岚县北)军。', '', '', '', 0),
(67, 'keypoint', '', 952, 0, 0, '太祖敕令禁掳掠', 'houzhou', '九月庚午(十七日)，后周太祖敕令北部边境官吏百姓不得进入契丹地界掳掠人口财物。', '', '', '', 0),
(68, 'keypoint', '', 952, 0, 0, '周平慕容彦超', 'houzhou', '郭威亲征兖州。五月至兖州，招降，被拒，于是诸军攻城，克城，慕容彦超与妻投井而亡。郭威平兖后，至曲阜拜孔子祠、墓，访孔子、颜渊之\r\n后，任为曲阜令及主簿。', '', '', '', 0),
(69, 'keypoint', '', 952, 0, 0, '辽袭冀州', 'houzhou', '辽将高谟翰以苇为筏渡胡卢河南侵，至冀州(今河北冀县)。后周成德节度使何福进派兵屯于贝州(今河北南宫东南)拒之，辽军仓猝北撤。', '', '', '', 0),
(70, 'keypoint', '', 952, 0, 0, '后周税牛皮', 'houzhou', '后周诏将历年所纳牛皮数减收三分之二，每夏秋苗十顷，纳连角牛皮一张。皮由该户自送至本州，所司不得邀难，其余听\n民自用及买卖。惟不准买与敌国。自此公私便之。', '', '', '', 0),
(71, 'keypoint', '', 952, 0, 0, '周平庆州党项', 'houzhou', '后周庆州刺史郭彦钦性贪，致党项野鸡族反。后周黜废郭彦钦，又诌定青白盐税，并禁绝私自抽税。庆州党项始平。', '', '', '', 0),
(72, 'keypoint', '', 952, 0, 0, '周定盐曲之刑', 'houzhou', '后汉禁私制盐、曲，立法严酷，如有触犯，不论多少一律处死。后周始以所犯斤两定刑。', '', '', '', 0),
(73, 'keypoint', '', 952, 0, 0, '越相裴坚去世', 'wuyue', '九月，甲寅朔(初一)，吴越丞相裴坚去世。任命台州刺史吴延福共同参预丞相府事务。', '', '', '', 0),
(74, 'keypoint', '', 952, 0, 0, '张峦攻桂州失败', 'nantang', '南唐平楚之后，派知全州张峦兼桂林招讨使，谋取桂州(今广西桂林)。南汉于山谷中设伏，南唐军大败。张峦收散卒数百逃归全州。', '', '', '', 0),
(75, 'keypoint', '', 952, 0, 0, '汉、唐争郴州', 'nantang', '南汉派潘崇彻、谢贯领兵攻郴州。南唐武安节度使(治潭州，今湖南长沙)边镐出兵救援郴州。南唐军败，南汉取郴州。', '', '', '', 0),
(76, 'keypoint', '', 952, 0, 0, '南唐初行贡举', 'nantang', '南唐开国以后，不设礼部贡举，人材的选拔只凭言事遇合，随材进用。952年二月，南唐始以翰林学士江文蔚知贡举，后因南唐执政者均不由科>举出身，加以阻毁，南唐意罢贡举。', '', '', '', 0),
(77, 'keypoint', '', 952, 0, 0, '朗州刘言取潭州', 'nantang', '南唐召武平留后(治朗州，今湖南常德)刘言入朝，兵屯于益阳图谋取朗。朗将王逵、周行逢等劝刘言取潭州(今湖南长沙)。攻克\n潭州，刘言尽复马氏楚国旧地(除郴、连)。', '', '', '', 0),
(78, 'keypoint', '', 952, 0, 0, '《祖堂集》撰成', 'nantang', '泉州昭庆寺静、筠二禅师撰成《祖堂集》二十卷，为禅宗现存最早的灯史。此书旨在弘法，史实虽有缺失，但也有为后世灯史不载者，一些史\r\n料赖此书留存。', '', '', '', 0),
(79, 'keypoint', '', 953, 0, 0, '北方大水', 'houzhou', '秋，北方东自青（今山东益都）、徐，西至丹（今陕西宜川），慈（今山西吉县），北至贝（今河北南宫东南）、镇（今河北正定），皆大水。', '', '', '', 0),
(80, 'keypoint', '', 953, 0, 0, '后周除二王', 'houzhou', '王峻佐命之功最多，恃功骄矜，对太祖言事多出语不逊。太祖不堪其无君，幽峻，贬为商州司马，至州病\n卒。邺都留守王殷与王峻同佐命，太祖，执王殷，流登州，出城杀之。', '', '', '', 0),
(81, 'keypoint', '', 953, 0, 0, '彰武更换节度', 'houzhou', '正月，彰武节度使（治延州，今陕西延安北）高允权卒，其子高绍基谋袭父位。后周以向训权知延州。', '', '', '', 0),
(82, 'keypoint', '', 953, 0, 0, '周罢营田、牛课', 'houzhou', '正月废除营田务制度，将营田民户划归州县管辖，其田产、农具赐予现耕佃户为永业，并免除东南各州延续数十年的牛课，当年户部新增民户三万余。', '', '', '', 0),
(83, 'keypoint', '', 953, 0, 0, '雕版印刷《九经》', 'houzhou', '后周国子监完成雕版印刷《九经》工程。', '', '', '', 0),
(84, 'keypoint', '', 953, 0, 0, '郭威推行廉政', 'houzhou', '下诏罢免四方贡奉珍美食物，将汉宫玉器碎于庭以示节俭。', '', '', '', 0),
(85, 'keypoint', '', 953, 0, 0, '南唐大旱', 'nantang', '六至七月，南唐不雨，大旱，井泉干涸，淮河可涉水而过。饥民相继渡淮入后周之境。', '', '', '', 0),
(86, 'keypoint', '', 953, 0, 0, '南唐筑百水塘', 'nantang', '十月，南唐以楚州（今江苏淮安）刺史田敬洙所请，于楚州筑白水塘以灌溉屯田。常、吏因缘为好，强夺民田，民怨\n。知制诰徐铉至楚州，悉取所夺之田还民，后徐铉因谗被贬。', '', '', '', 0),
(87, 'keypoint', '', 954, 0, 0, '郭威嘱薄葬', 'houzhou', '嘱晋王郭（柴）荣于其身后薄葬，工役均用私雇，募近陵民三十户，蠲其徭役以守陵。只于陵前刻石，题“周天子平生好俭约，遗令用纸衣，瓦棺，嗣天子不敢违也。”', '', '', '', 0),
(88, 'keypoint', '', 954, 0, 0, '后周塞决河', 'houzhou', '正月，派前登州刺史周训等分别在黄河容易决口处提前预防。', '', '', '', 0),
(89, 'keypoint', '', 954, 0, 0, '柴荣即位后周', 'houzhou', '郭威病逝，养子柴荣即位。郭威死前，黜退一批恃功倨傲之臣，又任命一批新官吏，将朝政委归柴荣，因此权力移交顺利。', '', '', '', 0),
(90, 'keypoint', '', 954, 0, 0, '败汉辽于高平', 'houzhou', '北汉联合辽国发动高平之战，柴荣亲征获胜。此役中赵匡胤因战功升任殿前都虞候，李继勋升任侍卫步军都指挥使。通过军\n政改革强化禁军，赵匡胤逐渐掌握核心军权。', '', '', '', 0),
(91, 'keypoint', '', 954, 0, 0, '后周施政', 'houzhou', '正月初一，后周大赦天下并改元显德，颁布蜀境通商政策。初五，晋王柴荣加兼侍中，判内外兵马事。', '', '', '', 0),
(92, 'keypoint', '', 954, 0, 0, '安南吴昌文附于南汉', 'nanhan', '正月，交州吴昌文遣使至南汉求节钺。南汉以吴昌文为静海军节度使、兼安南都护，派给事中李玙招之。吴昌文以海贼阻道为由，止李玙>于白州，李玙还。', '', '', '', 0),
(93, 'keypoint', '', 955, 0, 0, '王朴《开边策》', 'houzhou', '世宗采纳王朴《开边策》，确立先取江南、后定北方的统一战略，军事与制度改革为后续中原统一奠定基础。', '', '', '', 0),
(94, 'keypoint', '', 955, 0, 0, '世宗亲征南唐', 'houzhou', '发动对南唐三次亲征，迫使其割让长江以北领地并取消帝号。', '', '', '', 0),
(95, 'keypoint', '', 955, 0, 0, '攻取后蜀四州', 'houzhou', '周师克秦、凤、阶、成四州。世宗诏赦秦、凤、阶、成四州两税征科，及后蜀所立诸色科徭。所俘后蜀将士，自愿遣返。后周又复后汉所失四州。', '', '', '', 0),
(96, 'keypoint', '', 955, 0, 0, '后周施政', 'houzhou', '推行漕运改革，扩建大梁城并规划都城格局，颁布经济政策如整顿佛教寺院、收缴铜器铸钱，并疏通河道防御契丹。', '', '', '', 0),
(97, 'keypoint', '', 955, 0, 0, '规划大梁城', 'houzhou', '柴荣以大梁（今河南开封）城中迫隘，诏拓展外城。先立标帜街道、仓场、公廨，其余空地听百姓随便建屋。城中街衢扳直拓宽。后动员开封府及近畿州民十余万筑大梁外城。', '', '', '', 0),
(98, 'keypoint', '', 957, 0, 0, '征伐南唐', 'houzhou', '周军持续围攻寿州（今安徽寿县），南唐守将刘仁赡被迫投降。后周水陆并进，在紫金山大破南唐援军。后周攻占泗州、濠州等地，控制淮河流域，为日后统一奠定基础。', '', '', '', 0),
(99, 'keypoint', '', 957, 0, 0, '后周施政', 'houzhou', '后周整肃内政，修订刑律、疏浚汴水，并处理贪污案件。', '', '', '', 0),
(100, 'keypoint', '', 957, 0, 0, '北汉改元天会', 'beihan', '北汉大赦，改元天会，试图联契丹南侵未果。', '', '', '', 0),
(101, 'keypoint', '', 958, 0, 0, '柴荣亲征南唐', 'houzhou', '柴荣第三次亲征南唐，攻克楚州等地，迫使南唐李璟献出江北、淮南十四州，称臣，去年号。', '', '', '', 0),
(102, 'keypoint', '', 958, 0, 0, '彬州冯晖墓主下葬', 'houzhou', '陕西彬州冯晖墓志记载墓主下葬于958年，该墓出土6件五代耀州窑青瓷器，证实耀州窑采用满釉裹足支钉烧工艺，创烧的天青釉瓷对后世汝窑及南宋官窑产生影响。', '', '', '', 0),
(103, 'keypoint', '', 958, 0, 0, '后周隰州退北汉', 'houzhou', '北汉乘机侵周隰州（今山西隰县），后周隰州权州事李谦溥坚守待援。后周建雄节度使杨廷璋自晋州（今山西临汾）率军救援，内外相应袭北汉营，北汉军惊溃，遂解围而去。', '', '', '', 0),
(104, 'keypoint', '', 958, 0, 0, '辽汉侵周失利', 'houzhou', '辽侵后周。世宗命张永德领兵御北边；成德节度使郭祟攻拔辽束城（今河北河间东北）。后周昭义节度使李\n筠奏击北汉石会关（今山西榆社西）；晋时李谦溥击破北汉孝义。', '', '', '', 0),
(105, 'keypoint', '', 958, 0, 0, '后周行《大周刑统》', 'houzhou', '七月，后周行《大周刑统》。《刑统》始作于显德四年五月，周世宗以律令文左难知，格敕烦杂不一，命侍御史知杂事张湜等十人详定格律。至是完成进上。', '', '', '', 0),
(106, 'keypoint', '', 958, 0, 0, '后周均定赋税', 'houzhou', '七月，周世宗赐诸道节度使、刺史元稹《均田图》各一面，准备均定天下赋税。十月，后周派遣左散骑常侍艾颖等三十四人分别均定六十州赋税。', '', '', '', 0),
(107, 'keypoint', '', 958, 0, 0, '后周罢课户、俸户', 'houzhou', '十二月，后周以诸色课户、俸户归州县，其幕职、州县官自今以后支俸钱及米麦。', '', '', '', 0),
(108, 'keypoint', '', 958, 0, 0, '占城国进献香水', 'nanhan', '占城国使者向南汉政权进献15瓶蔷薇香水。广州人借鉴阿拉伯蒸馏技术，以素馨花、茉莉花为原料制>成本土香水，被称为“广南真法”，形成蒸馏香水产业。', '', '', '', 0),
(109, 'keypoint', '', 958, 0, 0, '南唐改元中兴', 'nantang', '正月，南唐改元中兴。其时南唐与后周激战于江北。', '', '', '', 0),
(110, 'keypoint', '', 958, 0, 0, '南唐改元交泰', 'nantang', '三月，南唐大赦，改元交泰。因皇太弟李景遂屡上表辞位，以景遂为晋王；齐王李景达因败军辞元帅，以景达为抚州大都督。立燕王李弘冀为太子，参治朝政。', '', '', '', 0),
(111, 'keypoint', '', 958, 0, 0, '南汉刘晟卒', 'nanhan', '八月，南汉中宗刘晟卒，子刘继兴即位，更名鋹，改元大宝。是为南汉后主，刘鋹年仅十六，朝政均由宦官龚澄枢、女宠卢琼仙等把持。', '', '', '', 0),
(112, 'keypoint', '', 959, 0, 0, '后周柴荣卒', 'houzhou', '六月十九，周世宗柴荣病卒。二十日，宣遗诏，以子柴宗训即皇帝位，年仅六岁，是为周恭帝。', '', '', '', 0),
(113, 'keypoint', '', 959, 0, 0, '世宗北伐', 'houzhou', '四月至五月，周世宗北伐收复瀛州、莫州等三州十七县，设立雄州、霸州。六月，后周昭义节度使李筠拔北汉辽州（今山西左权），获辽州刺史。', '', '', '', 0),
(114, 'keypoint', '', 959, 0, 0, '后周施政', 'houzhou', '正月，周世宗柴荣命王朴巡视河防，疏浚汴水、蔡水、五丈渠等漕运工程。二月，开封府核减虚报田税3.8万顷，并赈济淮南饥荒。', '', '', '', 0),
(116, 'keypoint', '', 959, 0, 0, '南唐铸大钱', 'nantang', '七月，南唐因连年与北周战于淮上，又割地输币，府藏空竭，物价腾贵，从礼部侍郎钟谟之请铸大钱\n“永通泉货”以一当十，又钱当二钱“唐国通宝”。至十月，废永通钱。', '', '', '', 0),
(117, 'keypoint', '', 959, 0, 0, '南唐建南都', 'nantang', '割江北十四州入后周后，都城金陵（今江苏南京）与后周只隔一条长江，洪州（今江西南昌）居金陵上游，据南江要会之地，议迁都。十一月，南唐改洪州为南昌府，建南都于南昌。', '', '', '', 0),
(118, 'keypoint', '', 959, 0, 0, '辽与南唐绝交', 'nantang', '初两国使节不断。南唐宋齐丘就曾利用杀辽使以离间后晋、契丹。十二月，辽遣使至南唐，南唐人夜宴辽使者，被后周泰州团练使荆罕所募刺客所杀。从此辽与南唐断绝往来。', '', '', '', 0),
(119, 'keypoint', '', 960, 0, 0, '陈桥兵变', 'beisong', '正月，赵匡胤在陈桥驿发动兵变，夺取（后）周政权，建立了宋朝。', '', '', '', 0),
(120, 'keypoint', '', 960, 0, 0, '军政改革', 'beisong', '将禁军精锐收归中央，削弱藩镇兵权；留用范质、王溥等后周旧臣，封石守信等将领为节度使。通过军政改革与权力分配，逐步实现\"强干弱枝\"的中央集权框架。', '', '', '', 0),
(121, 'keypoint', '', 960, 0, 0, '割据势力', 'beisong', '迅速平定昭义节度使李筠、淮南李重进等地方叛乱。南唐清源节度使留从效、荆南高保融相继归附，中原局势渐趋稳定。', '', '', '', 0),
(122, 'keypoint', '', 960, 0, 0, '施政', 'beisong', '更戍法调整禁军驻防、铸造\"宋通元宝\"统一货币、废除宰相坐议旧制等措施强化统治。', '', '', '', 0),
(123, 'keypoint', '', 960, 0, 0, '辽耶律寿远等谋反', 'liaoguo', '七月，辽政事令耶律寿远、太保库阿布等谋反，伏诛。至十月，辽穆宗从弟赵王耶律喜隐谋反，其父耶律李胡受其牵连，囚死狱中。', '', '', '', 0),
(124, 'keypoint', '', 966, 0, 0, '施政', 'beisong', '该年延续了建隆年间确立的\"强干弱枝\"政策，通过盐监等专业管理机构加强中央集权，同时采取减免赋税等措施恢复战后经济。该项调整强化了北宋初年\r\n对战略物资的统筹管理能力。', '', '', '', 0),
(125, 'keypoint', '', 966, 0, 0, '富义监', 'beisong', '富义县因盐业经济繁荣升格为州级盐监富义监。盐监机构的设置标志着中央政府对盐业经济的直接管控，富义监下设盐井管理机构与运输枢纽，形成\">以盐立监\"的特殊行政区划体系。', '', '', '', 0),
(126, 'keypoint', '', 966, 0, 0, '石经幢', 'beisong', '山西平顺大云禅院大殿前保存有966年的石经幢，幢体刻《佛顶尊胜陀罗尼经》全文，是现存最早的有明确纪年的北宋石经幢。石经幢题记包含功德主姓名与捐造时间。', '', '', '', 0),
(127, 'keypoint', '', 968, 0, 0, '进攻北汉', 'beisong', '八月，宋太祖命李继勋为主帅、党进为副帅、曹彬为都监，大举进攻北汉。十一月宋军因辽军耶律挞烈率兵逼近而退兵。', '', '', '', 0),
(128, 'keypoint', '', 968, 0, 0, '越南丁朝建立', '', '定国号为“大瞿越”，结束越南“北属”时代，开启自主王朝的阶段。仅在形式上承认中原王朝的宗主权，由直接管辖转变为藩属国。被视为越南民族独立意识发展的关键节点。', '', '', '', 0),
(129, 'keypoint', '', 968, 0, 0, '北汉内乱', 'beihan', '刘钧病卒，刘钧养子继恩嗣位。北汉内乱，刘继恩被杀，刘继元被拥立为帝。', '', '', '', 0),
(130, 'keypoint', '', 969, 0, 0, '亲征北汉', 'beisong', '赵匡胤亲征北汉，宋军久攻不下退兵', '', '', '', 0),
(131, 'keypoint', '', 969, 0, 0, '太祖宴藩臣', 'beisong', '太祖将参加宴会的节度罢镇改官，以行德为太子太傅，从义为左金吾卫上将军，彦超为右金吾卫上将军，重赞为左千牛卫上将军，廷璋为右千牛卫\r\n上将军。', '', '', '', 0),
(132, 'keypoint', '', 969, 0, 0, '龙翔寺建寺', 'beisong', '龙翔寺，建于969年，塔下的兴庆寺，现已辟为温州博物馆。', '', '', '', 0),
(133, 'keypoint', '', 969, 0, 0, '段思着知灵州', 'beisong', '后周恭帝时，冯继业杀兄，代父镇灵武。后举族内迁。太祖遂以考功郎中段思恭代知灵州。矫正继业的过失，绥抚羌落，境内遂安。因拘留回鹘\r\n使者数日，致回鹘多年不朝贡。', '', '', '', 0),
(134, 'keypoint', '', 969, 0, 0, '辽穆宗遇刺', 'liaoguo', '二月，近侍小哥等六人谋反，诛杀穆宗。耶律贤被推举为帝,尊号天赞皇帝,改元为保宁。', '', '', '', 0),
(135, 'keypoint', '', 969, 0, 0, '伊赫什德王朝灭亡', '', '北非法蒂玛王朝将领昭海尔率大军攻入埃及，王室不战而降，伊赫什德王朝灭亡。', '', '', '', 0),
(136, 'keypoint', '', 969, 0, 0, '曼苏里耶城', '', '从突尼斯入侵的一支伊斯兰人在其北建立了一个长方形新城——曼苏里耶城。', '', '', '', 0),
(137, 'keypoint', '', 969, 0, 0, '安和之变', 'jp', '日本发生安和之变。', '', '', '', 0),
(138, 'keypoint', '', 969, 0, 0, '本笃会隐修院', '', '圣米歇尔山是法国著名古迹和基督教圣地，位于芒什省一小岛上，距海岸两公里。公元969年，在岛顶上建造了本笃会隐修院。', '', '', '', 0),
(139, 'keypoint', '', 969, 0, 0, '西保加利亚王国建国', '', '以萨穆伊尔为首的西保加利亚封建贵族脱离保加利亚王国,建立西保加利亚王国 ,定都奥克里达(今南斯 拉夫境内)。', '', '', '', 0),
(140, 'keypoint', '', 969, 0, 0, '大理边乱', '', '大理东部发生边乱,延众镇长宗奇、求州首领代连弄兔,攻陷糜乃等三邑,段素顺派都统、长皇叔、布燮段子标，统军平定边寨,诛代连弄兔等。', '', '', '', 0),
(141, 'keypoint', '', 970, 0, 0, '宋省官益俸', 'beisong', '宋初，朝廷机构臃肿，人浮于事，办事效率低，而且官吏俸禄低微。太祖下诏，推行州县依户口裁员政策以精简官僚，并提升官吏俸禄整顿吏治。\r\n', '', '', '', 0),
(142, 'keypoint', '', 970, 0, 0, '宋师平南汉', 'beisong', '潘美率军征讨南汉，攻克贺、韶等州后迫使南汉主刘鋹降宋，将岭南六十州纳入版图。', '', '', '', 0),
(143, 'keypoint', '', 970, 0, 0, '三千打六万', 'beisong', '十月，辽发六万骑围攻定州，太祖命判四方馆事田钦祚率三千士兵前往抵御。田钦祚与辽军战于满城，追至遂城，辽军死伤惨重。宋军入据遂城，\r\n坚守数日后，顺利突围。', '', '', '', 0),
(144, 'keypoint', '', 969, 0, 0, '始建六和塔', 'wuyue', '吴越国在杭州始建六和塔以镇钱塘江潮，塔名源自佛教“六和敬”思想。', '', '', '', 0),
(145, 'keypoint', '', 931, 0, 0, '后唐杀安重诲', 'houtang', '闰五月，后唐杀枢密使安重诲并其二子。明宗自邺都起事，佐命之功第一。独揽大权。后唐以李从璋节度河中。安重诲械二子还京师，行至陕州（今河南三门峡），下狱，见杀。', '', '', '', 0),
(146, 'keypoint', '', 931, 0, 0, '王延禀败死', 'miguowang', '闽奉国节度使兼中书令王延禀曾助王延钧夺闽王之位。王延钧将王仁达以诈降之计诱杀王继雄，继之又攻王延禀，擒之。五月，王延钧杀王延禀\n，复其本姓名周彦琛。', '', '', '', 0),
(147, 'keypoint', '', 932, 0, 0, '吴越钱镠卒', 'wuyue', '吴越王钱镠病，传位于子钱传瓘。钱传瓘更元瓘，兄弟名“传”者均改为“元”，以钱镠遗命去国仪，年号，复用藩镇之法。', '', '', '', 0),
(148, 'keypoint', '', 932, 0, 0, '楚马希声卒', 'nanchu', '七月，武安、静江节度使马希声卒。八月，湖南六军使袁诠、潘约于朗州（今湖南常德）迎马希范而立。', '', '', '', 0),
(149, 'keypoint', '', 932, 0, 0, '唐讨党项', 'houtang', '以静难节度使药彦稠、前朔方节度使康福领兵七千讨党项；二月，药彦稠等破党项十九族。七月，朔方（治灵\n州）又击退夏州（今内蒙白城子）党项的袭击。', '', '', '', 0),
(150, 'keypoint', '', 932, 0, 0, '孟知祥据有两川', 'houshu', '后唐以孟知祥为东西两川节度使、蜀王。', '', '', '', 0),
(151, 'keypoint', '', 932, 0, 0, '后唐征史于江南', 'houtang', '后唐以唐宣宗、懿宗、僖宗、昭宗四朝实录尚未纂修，于各地购募典籍，但北方因连年战火，图书灭绝，久征而未贡献。遂征书于江南，以江南安定，富于典藏之故。', '', '', '', 0),
(152, 'keypoint', '', 932, 0, 0, '卢龙筑辕护民', 'houtang', '后唐卢龙节度使辖地与契丹接壤，下属州县常遭契丹寇掠。卢龙节度使赵德钧于沿沟筑城保护粮运，为良乡县（今北京良乡），又于城东五十里修潞县（今北京通县东）。', '', '', '', 0),
(153, 'keypoint', '', 933, 0, 0, '李从荣作乱', 'houtang', '明宗次子李从荣，为天下兵马大元帅，位在宰相之上。欲以兵入侍，以保自己能嗣位。潞王李从珂之子李重吉等兵讨李从荣，李从荣逃归\n河南府，为皇城使安从益杀之于府邸。', '', '', '', 0),
(154, 'keypoint', '', 933, 0, 0, '李彝超拒不受代', 'houtang', '二月，定难节度使（治夏州，今内蒙白城子，领夏、银、绥等州）李仁福卒。军中立其子李彝超为留后。三月以李彝超为延州（今陕西延安）\r\n彰武军留后。李彝超拒不奉诏。', '', '', '', 0),
(155, 'keypoint', '', 933, 0, 0, '后唐明宗卒', 'houtang', '十一月二十六日，后唐明宗经秦王之乱，病情加剧而卒。死前，命宣徽使孟汉琼往邺都（今河北大名东北）召宋王李从厚。在闵李从厚即帝位即四\r\n个月即为潞王李从珂所废，遇害。', '', '', '', 0),
(156, 'keypoint', '', 933, 0, 0, '闽王延钧称帝', 'minguowang', '正月，以旧宅为龙跃宫，于宝皇宫即帝位，更己名为王鏻，国号大闽，建元龙启。', '', '', '', 0),
(157, 'keypoint', '', 933, 0, 0, '后唐置同二品衔', 'houtang', '唐初，中书、门下、尚书三省长官为宰相，凡以其他官员参预政事，而本官品阶较低者，加“同中书门下三品”或“同中书门下平章事”以为宰相\n，享有同等权力及待遇。', '', '', '', 0),
(158, 'keypoint', '', 950, 0, 0, '查文徽兵败福州', 'nantang', '南唐查文徽率军攻福州反被吴越军俘虏，经交换战俘后归国；', '', '', '', 0),
(159, 'keypoint', '', 950, 0, 0, '后汉将相交恶', 'houhan', '后汉立国后，文臣武将相互蔑视，渐成水火之势。大将史弘肇称：“安定国家，在长枪大剑，安用毛锥（指毛笔）！”三司使王章回答：“无毛锥，\r\n则财赋何可出？”', '', '', '', 0),
(160, 'keypoint', '', 950, 0, 0, '南汉宦官女宠当道', 'nanhan', '南汉中宗刘弘熙以宫人卢琼仙、黄琼芝为女侍中，着朝服出面参决政事。宦官林延遇等用事。林延遇、卢琼仙等掠夺商人金帛。而诸臣皆被>猜疑，宗室勋旧诛戮殆尽。', '', '', '', 0),
(161, 'keypoint', '', 950, 0, 0, '郭威建立周朝', 'beizhou', '后汉隐帝疑忌重臣，密令诛杀杨邠、史弘肇等人，引发邺都留守郭威兵变。郭威率军入汴京，被拥立为帝，次年建立后周政权，后汉灭亡。', '', '', '', 0),
(162, 'keypoint', '', 950, 0, 0, '南楚国主内斗', 'nanchu', '南楚国主兄弟内斗加剧，马希萼联合蛮族进攻长沙，引发潭州战事。', '', '', '', 0),
(163, 'keypoint', '', 949, 0, 0, '李彝殷割据自立', 'houhan', '夏州（今内蒙白城子）定难节度使李彝殷割据一方，后汉采取羁縻政策缓和矛盾；正月，李彝殷又请以静州归定难军，后汉准其请。', '', '', '', 0),
(164, 'keypoint', '', 949, 0, 0, '楚马希广死', 'nanchu', '楚国内部马希萼与马希广兄弟争权，引发多次军事冲突，最终马希萼联合南唐攻陷长沙，赐死马希广并自立为楚王。', '', '', '', 0),
(165, 'keypoint', '', 949, 0, 0, '吴越境无弃田', 'wuyue', '原吴越丁身钱最重，有人不入籍，以逃避赋税。钱弘俶自即位以来，下令募民垦荒田，不收税。境内无弃田。又置营田卒七、八千人，专于淞江辟土而耕，筑河堤减少水患。', '', '', '', 0),
(166, 'keypoint', '', 949, 0, 0, '留从效节度泉南二州', 'nantang', '南唐南州（原名漳州，今属福建）副使留从愿鸩杀刺史，据州以附弟留从效。南唐不能制，开泉州为清源军，以留从效为节度使。留从效遂据有泉、南二州。', '', '', '', 0),
(167, 'keypoint', '', 949, 0, 0, '后汉平定河中', 'houhan', '后汉平定河中李守贞叛乱、赵思绾投降及伏诛等事件。', '', '', '', 0),
(168, 'keypoint', '', 949, 0, 0, '契丹侵扰', 'houhan', '契丹侵扰河北，后汉派郭威率军抵御，北方藩镇多闭城自守。', '', '', '', 0),
(169, 'keypoint', '', 948, 0, 0, '后汉改元', 'houhan', '正月，后汉大赦，改元乾佑。后汉高祖刘知远更名为暠。', '', '', '', 0),
(170, 'keypoint', '', 948, 0, 0, '刘知远卒', 'houhan', '正月，刘知远病重，顾命于苏逢吉、杨邠、史弘肇、郭威等人，并嘱谨防杜重威，二十七日卒。苏逢吉等秘不发丧，以诏杀杜重威。后发丧，宣遗制，周王即皇帝位，即后汉隐帝。', '', '', '', 0),
(171, 'keypoint', '', 948, 0, 0, '后汉三叛连兵', 'houhan', '河中（李守贞）、凤翔（王景崇）、永兴（赵思绾）三镇相继叛乱。后汉以郭威为统帅征讨，历时近两年平定，李守贞自焚，赵思绾、王景崇相>继覆灭。', '', '', '', 0),
(172, 'keypoint', '', 948, 0, 0, '吴越东渡求经', 'wuyue', '钱弘俶迎天台山僧人德韶为国师。天台宗僧义寂以天台宗教典自会昌焚毁，零落不全，又新罗国本甚备。钱弘俶遣使赴新罗、日本寻回天台宗散佚\r\n佛典，促成教典回流中土。', '', '', '', 0),
(173, 'keypoint', '', 948, 0, 0, '高保融知荆南', 'nanping', '十月，荆南节度使、南平王高从诲卒，其子高保融知荆南留后。', '', '', '', 0),
(174, 'keypoint', '', 948, 0, 0, '南汉刘弘熙攻楚', 'nanhan', '八月，南汉中宗刘弘熙派人求婚于楚，楚王马希广不许。十二月，南汉攻楚贺州（今广西贺县南），入城。南汉军又掠昭州（今广西平乐西）而回。', '', '', '', 0),
(175, 'keypoint', '', 947, 0, 0, '晋帝北迁', 'houjin', '正月，契丹迁晋帝及家人于大梁封禅寺，备受困窘、冻馁，准备将晋帝等迁往黄龙府（今吉林农安）。大同二年，晋太后迁往建州（今辽宁朝阳西南），次年晋帝亦迁至建州。', '', '', '', 0),
(176, 'keypoint', '', 947, 0, 0, '契丹打草谷', 'liaoguo', '辽三十万铁骑直驱入中原。耶律德光入大梁，令骑兵四出以牧马为名剽掠，称\"打草谷\"。后耶律德光自认有三失致使天下叛，其中二为打草谷，一为诸道括钱。', '', '', '', 0),
(177, 'keypoint', '', 947, 0, 0, '刘知远称帝', 'houhan', '后晋河东节度使刘知远以辽灭后晋，中原无主，于太原即皇帝位。', '', '', '', 0),
(178, 'keypoint', '', 947, 0, 0, '辽难制中原', 'liaoguo', '辽国残暴的统治激起中原人民的反抗。梁晖乘辽相州无防备，杀辽兵数百人，逐辽守将。人民义军攻陷了宋州（今河南商丘）、毫州（\n今安徽亳县）、密州（今山东诸城）。', '', '', '', 0),
(179, 'keypoint', '', 947, 0, 0, '后蜀复前蜀疆土', 'houshu', '原晋雄武节度使何重建杀辽使，以秦（今甘肃秦安西北）、阶（今甘肃武都东南）、成（今甘肃成县）三州降后蜀。后蜀尽有秦、凤、阶、成>之地，复前蜀疆土。', '', '', '', 0),
(180, 'keypoint', '', 947, 0, 0, '辽改元大同', 'liaoguo', '辽国攻灭后晋，辽太宗耶律德光改元大同，升镇州为中京并构建多元都城体系。契丹在洛阳设洛京留守职，该制度由实职逐渐演变为虚衔，反映辽\r\n对中原控制力的阶段性变化。', '', '', '', 0),
(181, 'keypoint', '', 946, 0, 0, '南唐围攻福州', 'nantang', '南唐泉州刺史王继勋与福州李弘羲交恶，引发南唐围攻福州之战。战事持续至次年三月，最终吴越援军与城中守军合击南唐，致其惨败。', '', '', '', 0),
(182, 'keypoint', '', 946, 0, 0, '契丹攻后晋', 'houjin', '契丹大举攻后晋，后晋将领杜重威率军投降，契丹军攻陷大梁。十二月契丹先锋张彦泽入大梁纵兵掠城，次年契丹改国号为辽。', '', '', '', 0),
(183, 'keypoint', '', 947, 0, 0, '契丹改国号为', 'liaoguo', '耶律德光入大梁，废东京，降开封府为汴州。以诏书赐名藩镇，晋藩镇争相上表称臣。二月初一，契丹建国号辽，改元大同元年（947），以镇>州（今河北正定）为中京。', '', '', '', 0),
(184, 'keypoint', '', 946, 0, 0, '孙方简等聚众自卫', 'houjin', '定州（今河北定县）百姓孙方简、孙行友兄弟因北边赋役烦重，率乡里豪健者占据定州以北狼山自保。后降契丹，后又降于后汉，后汉仍委为义武节度使，以抵御辽。', '', '', '', 0),
(185, 'keypoint', '', 946, 0, 0, '白承福被杀', 'houjin', '吐谷浑白天福五年（940）自契丹境南迁，居于河北、山西交界的山谷之中。刘知远贪图白承福等人的财产，诱杀白承福。吐谷浑部落经此事件后衰微。', '', '', '', 0),
(186, 'keypoint', '', 945, 0, 0, '《旧唐书》撰成', 'houjin', '后晋宰相监修国史刘煦、史官张昭远等上新修《唐书》二百卷。初于941年四月，由当时的宰相监修国史赵莹奏请编修，同时下诏征购史馆所阙\r\n李唐各朝实录，历时四年余完成。', '', '', '', 0),
(187, 'keypoint', '', 945, 0, 0, '续贞元释教录', 'houjin', '沙门恒安撰成《续贞元释教录》。系统整理佛教典籍。此前南方写经多依《开元释教录》，恒安自北方写《贞元释教录》续入藏经所编《续贞元>释教录》。', '', '', '', 0),
(188, 'keypoint', '', 945, 0, 0, '李仁达据福州', 'minguowang', '二月，闽人李仁达杀福州都督王继昌，三月，迎雷峰寺僧人卓岩明为帝，称藩于后晋。五月，李仁达又杀卓岩明自立，称威武留后，用南唐>保大年号，向吴越、南唐称蕃。', '', '', '', 0),
(189, 'keypoint', '', 945, 0, 0, '契丹后晋交战', 'houjin', '正月契丹南侵邢、磁等州，后晋将领赵在礼等展开安阳水之战；二月后晋出帝亲征，三月张从恩等在相州进行拉锯战，皇甫遇以骑兵突袭扭转战>局。', '', '', '', 0),
(190, 'keypoint', '', 944, 0, 0, '契丹入侵河北', 'houjin', '后晋为抵御契丹南侵，加重赋役引发民怨，契丹攻陷贝州、德州等地，但遭府州折从远抵抗；契丹趁机大举入侵河北，迫使后晋调集兵力防御。', '', '', '', 0),
(191, 'keypoint', '', 944, 0, 0, '闽王曦遇弑', 'minguowang', '三月，闽拱宸都指挥使朱文进、閤门使连重遇、指挥拱宸马步使钱达于后父之宅，杀闽帝王曦，又杀王氏宗族五十余人。朱、连二人五年前弑>闽唐宗立王曦。', '', '', '', 0),
(192, 'keypoint', '', 944, 0, 0, '后晋籍乡兵括民财', 'houjin', '三月，后晋抽点乡兵，至四月共得七万多人，称武定军。派人分道括民财。泰宁节度使安审信以军备为名括民财，括率使到兖州，指安审信一言就满足了兖州的十万数额。', '', '', '', 0),
(193, 'keypoint', '', 944, 0, 0, '府州抗契丹', 'houjin', '府州（今陕西府谷）于后晋割地而入契丹，契丹打算将黄河以西的居民迁往辽东，刺史折从远世代为本地镇将，拒迁。六月后晋以折从远为府州团练使。', '', '', '', 0),
(194, 'keypoint', '', 944, 0, 0, '南唐与殷绝交', 'nantang', '正月，南唐中主李璟致书闽帝王曦，殷主王延政责备二人兄弟相残。王曦引唐太宗宣武门故事自比；王延政则复书斥责南唐篡吴。南唐遂与殷绝。此为南唐灭殷张本。', '', '', '', 0),
(195, 'keypoint', '', 926, 0, 0, '契丹灭渤海', 'liaoguo', '阿保机亲征渤海。七月，契丹拔重镇夫余城（今吉林四平），下都城忽汗城（今黑龙江东京城），渤海王大諲撰出降。渤\n海自大祚荣于698年建国，至此而亡。', '', '', '', 0),
(196, 'keypoint', '', 926, 0, 0, '契丹改元天显', 'liaoguo', '二月，契丹改元天显。', '', '', '', 0),
(197, 'keypoint', '', 926, 0, 0, '唐诸镇杀监军', 'houtang', '后唐庄宗任用宦官为监军，藩镇主帅多遭其凌侮。此时邺都军变，各镇多杀监军。', '', '', '', 0),
(198, 'keypoint', '', 926, 0, 0, '后唐置端明殿学士', 'houtang', '五月，置端明殿学士，以翰林学士冯道、赵凤充任。明宗目不识书，四方所上奏章皆由枢密使安重诲宣读，安重诲学识有限，故选\n文学之臣与枢密共事，以供帝王应对。', '', '', '', 0),
(199, 'keypoint', '', 926, 0, 0, '辽太祖卒', 'liaoguo', '七月，契丹王耶律亿灭渤海回师，卒于夫余（今吉林四平）。述律后称制决军国大事，杀难以统驭的将领、酋长以殉葬。与耶律信等护葬\n返皇都（今内蒙巴林左旗东南）。', '', '', '', 0),
(200, 'keypoint', '', 926, 0, 0, '唐征蜀财', 'houtang', '原征蜀将任圜判三司，派盐铁判官赵季良为转运使赴川押运蜀财。十二月，运蜀中金帛十亿到洛阳，后唐中央政权赖此渡过财政困难。', '', '', '', 0),
(201, 'keypoint', '', 927, 0, 0, '', '', '英格兰议会。', '', '', '', 0),
(202, 'keypoint', '', 927, 0, 0, '', '', '新罗第56代王敬顺王即位。公元927年-935年在位。', '', '', '', 0),
(203, 'keypoint', '', 927, 0, 0, '', '', '保加利亚教会成为大主教区,属君士坦丁堡教会管辖。', '', '', '', 0),
(204, 'keypoint', '', 927, 0, 0, '', '', '剑川节度杨干贞以讨伐郑氏为名,起兵攻灭了大长和国,拥清平官赵善政为王,建立“大天兴国”。', '', '', '', 0),
(205, 'keypoint', '', 927, 0, 0, '', '', '草原行者辽太祖辽太祖陵：位于巴林左旗境内，建于天显二年，埋葬着辽朝的开国皇帝耶律阿保机。', '', '', '', 0),
(206, 'keypoint', '', 927, 0, 0, '吴王杨溥称帝', 'yangwu', '十一月，吴王杨溥于江都（今江苏扬州）即帝位。改元乾贞。次年二月，吴遣使至后唐，后唐枢密使安重诲以吴王称帝，且连联结荆南，拒不受>，遣还吴使。后唐遂与吴绝。', '', '', '', 0),
(207, 'keypoint', '', 927, 0, 0, '', '', '开闽三王之子王思义兄弟10人卜居于晋江青阳的杏厝王，是为晋江王氏开基始祖。', '', '', '', 0),
(208, 'keypoint', '', 927, 0, 0, '楚马殷建国', 'nanchu', '六月，后唐封天策五将军、湖南节度使楚王马殷为楚国王。八月后唐册礼使至长沙，马殷始建国，立宫殿，置百官，如天子之制。不建元，仍属中>原王朝正朔。', '', '', '', 0),
(209, 'keypoint', '', 927, 0, 0, '耶律德光继位', 'liaoguo', '耶律德光继位,即辽太宗。萧温被立为辽太宗耶律德光皇后。四年后生下长子耶律璟。', '', '', '', 0),
(210, 'keypoint', '', 927, 0, 0, '宽辅和尚来中国', '', '日本醍醐时代的真玄宗高僧弘顺大使(即宽辅和尚)来中国。', '', '', '', 0),
(211, 'keypoint', '', 927, 0, 0, '', 'liaoguo', '辽太祖耶律阿保机陵墓修建完成。', '', '', '', 0),
(212, 'keypoint', '', 927, 0, 0, '长沙开福寺始建', 'houtang', '位于长沙市区北面，是中国重点佛教寺院之一，属佛教禅宗临济宗杨岐派。', '', '', '', 0),
(213, 'keypoint', '', 927, 0, 0, '羊马城', 'houshu', '西川孟知祥杀监军李严想割据四川称霸一方，在罗城外修建了一座“羊马城”。因打仗需要大量的粮食和肉食,粮食充足而肉食不易征集，所以修筑着马城用\n来饲养牛羊马匹。', '', '', '', 0),
(214, 'keypoint', '', 927, 0, 0, '后唐讨荆南', 'houtang', '二月，后唐夺高季兴官爵，以山南东道节度使刘训、忠武节度使夏鲁奇领四万兵会同东川节度使董璋，楚军三面进攻伐荆南。不能克城，后唐遂撤\r\n师。', '', '', '', 0),
(215, 'keypoint', '', 927, 0, 0, '后唐初置监牧', 'houtang', '三月，后唐依判三司任圜所请，置监牧，以繁殖马匹；并准诸道以绫绢金银随土产折进马之直。', '', '', '', 0),
(216, 'keypoint', '', 927, 0, 0, '后唐征布袋等钱', 'houtang', '六月，后唐下令，命纳租税之人，交纳官仓布袋税，每一袋纳八文钱，931年，又下令于两税斛斗之外，每斗加耗二合，以备仓司>损耗。布袋钱仍由官典同系署，一一分明上报。', '', '', '', 0),
(217, 'keypoint', '', 927, 0, 0, '两川争盐', 'houtang', '蜀中东川、西川两节度所辖境内均有盐井，东川盐利稍多于西川。西川节度使孟知祥于与东川接壤的汉州（今四川广汉）设三处盐场重征盐商以为对策。从此商旅不再往东川。', '', '', '', 0),
(218, 'keypoint', '', 929, 0, 0, '唐平王都', 'houtang', '义武节度使王都联合契丹发动叛乱，唐廷派王晏球率军击败叛军及契丹援军，次年王都自焚，河北地区重归中央控制。', '', '', '', 0),
(219, 'keypoint', '', 929, 0, 0, '后唐置场市党项马', 'houtang', '后唐调整党项马匹交易政策以缓解财政压力。', '', '', '', 0),
(220, 'keypoint', '', 929, 0, 0, '荆南向唐谢罪', 'houtang', '五月，初袭父位的高从诲以唐近吴远，通过楚王马殷谢罪于唐。七月，后唐以高从诲为荆南节度使兼侍中，罢天成二年讨荆南所置荆南招讨使。\r\n', '', '', '', 0),
(221, 'keypoint', '', 929, 0, 0, '吴越与唐绝交', 'houtang', '后唐枢密使安重诲以吴越王钱镠怠慢唐使，言辞不敬奏削钱镠官爵。吴越遂与唐绝交。至长兴二年（931）三月，后唐以削钱镠爵系安重诲所为>，复钱镠名位。', '', '', '', 0),
(222, 'keypoint', '', 929, 0, 0, '吴改元大和', 'yangwu', '十一月，吴帝杨溥加尊号为睿圣文明光孝皇帝，大赦，改元大和。', '', '', '', 0),
(223, 'keypoint', '', 929, 0, 0, '后唐康福安边', 'houtang', '十月，后唐以磁州刺史康福为凉州（今甘肃武威）刺史、朔方河西节度使。在方渠（今甘肃环县），击退羌胡的袭击。康福在镇三年，岁岁丰收\n，有马千匹，境内蕃夷畏服。', '', '', '', 0),
(224, 'keypoint', '', 929, 0, 0, '杨干贞改号大义宁', 'houtang', '原拥立赵善政称帝的东川节度使杨干贞，因受赵的冷落，废赵自立，改国号为大义宁，建元兴圣，后改元大明。937年为段思平所败，废为僧，谥肃恭帝。', '', '', '', 0),
(225, 'keypoint', '', 929, 0, 0, '楚杀高郁', 'nanchu', '七月，楚王马殷之子知政事马希声矫令杀谋主高郁，诬郁谋反，诛其族党。高郁曾推动湖湘经济发展，通过改革赋税、推广茶叶贸易、铸造铅铁钱等>措施增强楚国实力。', '', '', '', 0),
(226, 'keypoint', '', 930, 0, 0, '后唐改元长兴', 'houtang', '二月，后唐明宗祀圜丘，大赦，改元长兴。', '', '', '', 0),
(227, 'keypoint', '', 930, 0, 0, '后唐设三司使', 'houtang', '八月，后唐设三司使总掌国家金帛财物、钱谷收纳，以前许州忠武军节度使张延朗充任，“三司使”之名自此始。为全国最高财政长官。宋代初期\r\n仍沿三司使之制。', '', '', '', 0),
(228, 'keypoint', '', 930, 0, 0, '两川坐大', 'houshu', '后唐西川节度使孟知样、东川节度使董璋恃兵力、财政割据一方，渐成坐大之势。后唐派石敬瑭征讨，最终因后勤不足撤兵，加速西南割据。后唐中>央政权越来越难驾驭两川。', '', '', '', 0),
(229, 'keypoint', '', 930, 0, 0, '南汉攻拔交州', 'nanhan', '九月，南汉高祖刘龚派梁克贞、李守鄘攻交州（今越南河内），拔之，擒静海节度使曲承美，以李进为交州刺史。曲氏自唐末景颢据交州，至此>而败。', '', '', '', 0),
(230, 'keypoint', '', 930, 0, 0, '楚马殷卒', 'nanchu', '十一月初十，楚王马殷卒，遗命诸子兄弟相继。二十七日，马希声袭位，以马殷遗命去国号，重对后唐行藩镇之礼。十二月，后唐以马声希为武安、>清江节度使，兼中书令。', '', '', '', 0),
(231, 'keypoint', '', 930, 0, 0, '契丹东丹王降唐', 'houtang', '耶律信率部曲四十人，渡海至登州（今山东蓬莱）奔后唐。藏万卷书，性残暴，明宗以庄宗后宫夏氏嫁之，夏氏因其残酷嗜杀，削发为\n尼。唐末帝派人杀耶律信，信自焚而死。', '', '', '', 0),
(232, 'keypoint', '', 928, 0, 0, '丹漠洞', '', '挪威海盗来到爱尔兰,对基尔肯尼附近一带进行洗劫。丹漠洞附近的居民为了逃命,集体躲到洞中。丹漠洞是一个巨大的溶洞,是绝佳的藏身之地。', '', 'https://baike.baidu.com/item/丹漠洞/', '', 0),
(233, 'keypoint', '', 928, 0, 0, '', '', '张昭曾私撰《同光实录》十二卷,经四川节度副史何赞推荐,被任命为左补阙,撰写史书,做《纪年录》二十卷,《庄宗实录》>三十卷。后改任职方员外郞、知制诰兼史馆修撰。', '', '', '', 0),
(234, 'keypoint', '', 928, 0, 0, '南汉攻封州', 'nanhan', '三月,马殷大起水师,由梧州东下,围攻封州(今广东封开)。', '', '', '', 0),
(235, 'keypoint', '', 928, 0, 0, '', '', '南汉王刘龚赐额“光泰禅院”,后又改为“证真禅寺”。', '', '', '', 0),
(236, 'keypoint', '', 928, 0, 0, '国师藻光大师', 'minguowang', '闽王的暴政,福建的老百姓怨声载道,闽王听说了藻光大师的德行后,就把他接到福州,并礼聘他为国师,协助治理福建。', '', '', '', 0),
(237, 'keypoint', '', 928, 0, 0, '陈靖姑祈雨', 'houtang', '后唐天成三年,陈靖姑带孕在闽江祈雨,为万民施降而殉身,陈靖姑府第因之成了祀宫。', '', '', '', 0),
(238, 'keypoint', '', 928, 0, 0, '洪庆携藏经归国', '', '新罗僧人洪庆从中国福建“航载《大藏经》一部至礼成江”，高丽国王王建“亲迎之，置于帝释院”。', '', '', '', 0),
(239, 'keypoint', '', 928, 1, 16, '', '', '女真遣使朝贡契丹。', '', '', '', 0),
(240, 'keypoint', '', 928, 0, 0, '陈靖姑卒', 'houtang', '传奇式的女英雄，享年二十四岁。为民除害、慷慨捐躯之地也在古田（临水洞），殉难之处建有临水宫（即龙源庙，顺懿宫），是纪念这位妇女儿童保护神的“祖殿”、“母宫”。', '', '', '', 0),
(241, 'keypoint', '', 928, 0, 0, '桂琛法师卒', 'houtang', '幼入浙江万岁寺，出家得度。初学戒律，一日为众登台，宣说成本，毕後方悟真解脱不拘小道，圣心不依文解。', '', '', '', 0),
(242, 'keypoint', '', 928, 0, 0, '云霞道人卒', 'houtang', '武当山古称太和山，云霞道人是武当山最早的道教派脉丹鼎派的第八代传人。', '', '', '', 0),
(243, 'keypoint', '', 928, 0, 0, '钱元瓘升官', 'wuyue', '钱元瓘907年升为衙内都指挥史。928年升为镇海、镇东两军节度使。长兴三年(932年)嗣王位,在位十年。', '', '', '', 0),
(244, 'keypoint', '', 928, 0, 0, '始建布拉格城', '', '布拉格城始建于公元928年。据传说，布拉格由丽布施公主和她的丈夫、普热美斯王朝（800至1306）创始人普热美斯建立。', '', '', '', 0),
(245, 'keypoint', '', 934, 0, 0, '', 'nanchu', '马楚政权延续发展农桑政策，在洛阳等地设置茶叶中转站。', '', '', '', 0),
(246, 'keypoint', '', 934, 0, 0, '', 'houtang', '石敬瑭调任镇州节度使，途中幽禁逃亡的李从厚，后被末帝猜忌返回河东。', '', '', '', 0),
(247, 'keypoint', '', 934, 0, 0, '闽吴战建州', 'yangwu', '闽帝王鏻性喜奢侈，中军使薛文杰欲霸占建州（今福建建瓯）吴光的财产，吴光请吴出兵讨闽。吴信州刺史蒋延徽围建州。徐知诰召蒋延晖还师，后贬蒋延徽，遣使与闽求和。', '', '', '', 0),
(248, 'keypoint', '', 934, 0, 0, '孟知祥建国', 'houshu', '闰正月二十七，蜀王孟知祥于成都即帝位，国号蜀。932年杀东川节度使董璋，据两川。933年封蜀王，至是称帝。在位即半年余，明德元年七月卒>。', '', '', '', 0),
(249, 'keypoint', '', 934, 0, 0, '后唐末帝即位', 'houtang', '四月初三，潞王李从珂发动岐阳兵变废黜闵帝自立。后晋高祖石敬瑭联合契丹灭后唐，末帝举族自焚而亡。', '', '', '', 0),
(250, 'keypoint', '', 934, 0, 0, '后唐敛民财赏军', 'houtang', '末帝巧立名目，搜刮百姓钱财赏军。一时牢狱中人满为患，不断有士庶因括财严刽自杀。骄兵悍将虽得赏赐仍不满意，还生怨言。', '', '', '', 0),
(251, 'keypoint', '', 934, 0, 0, '唐末帝挟名命相', 'houtang', '后唐宰相刘眳与李愚二人不和，以至议政之际相互漫骂，政事因此被耽搁。七月，以太常卿卢文纪为中书侍郎，八月以前尚书左丞\n姚觊为中书侍郎。罢刘煦、李愚相位。', '', '', '', 0),
(252, 'keypoint', '', 934, 0, 0, '后蜀孟知祥卒', 'houshu', '七月，孟知祥病重，立子东川节度使孟仁赞为太子，监国，以司空同平章事赵季良、李仁罕等受遗诏辅政。赵季良等宣高祖遗制，太子更名孟昶>即帝位，即后蜀后主。', '', '', '', 0),
(253, 'keypoint', '', 934, 0, 0, '唐蠲逋租', 'houtang', '因三司所报左藏失实，末帝命宰相刘煦判三司。八月，后唐诏免933年十二月以前户部以及诸道拖欠的租税，贫民大悦，而三司奸吏因>无法从虚账中渔利，深为怨恨。', '', '', '', 0),
(254, 'keypoint', '', 934, 0, 0, '吴罢迁都之议', 'yangwu', '徐温执吴政时，建金陵（今江苏南），及徐知诰执吴政，循徐温旧制。931年自广陵（今江苏扬州）移镇金陵，总录朝政。二月，吴帝杨溥以吴人多不欲迁都，罢迁都之议。', '', '', '', 0),
(255, 'keypoint', '', 935, 0, 0, '', 'minguowang', '闽主王昶重用道士陈守元，干预朝政决策。', '', '', '', 0),
(256, 'keypoint', '', 935, 0, 0, '', 'houtang', '契丹频繁侵扰北方边境，加剧中原政权压力。', '', '', '', 0),
(257, 'keypoint', '', 935, 0, 0, '闽改元永和', 'minguowang', '正月初一，闽大赦，改元永和。', '', '', '', 0),
(258, 'keypoint', '', 935, 0, 0, '定难易帅', 'houtang', '正月，夏州（今内蒙白城子）定难节度使李彝超上表称病重，以兄行军司马李彝殷权知军州事。不久，李彝超卒。三月，后唐以李彝殷为定难节度使\r\n。', '', '', '', 0),
(259, 'keypoint', '', 935, 0, 0, '吴改元天祚', 'yangwu', '九月，吴帝杨溥加尊号，大赦，改元天祚。徐知诰逐步扩大权势。', '', '', '', 0),
(260, 'keypoint', '', 935, 0, 0, '后唐马全节保金州', 'houtang', '蜀金州防御使全师郁攻唐金州（今陕西安康），陈知隐不抵抗，防御使马全节打退蜀军。刘延朗求贿赂未能满足，后唐以马全节为横海留后\r\n，末帝虽知刘延朗弄权，但不治其罪。', '', '', '', 0),
(261, 'keypoint', '', 935, 0, 0, '王鏻死王昶袭', 'minguowang', '闽帝王鏻病重，李仿令壮土杀与陈皇后私通的百工使李可殷。李仿又与与王子王继鹏率皇城卫士入宫，杀王鏻及陈后，及后族陈守恩、陈匡>胜，王继鹏即位，更名王昶，', '', '', '', 0),
(262, 'keypoint', '', 935, 0, 0, '蒋承勋出使日本', 'wuyue', '吴越人蒋承勋等赴日本，献羊数头。十二月，日本交易唐物使藏人藤原亲盛赴大宰府，验收蒋承勋所带货物。后多次往返日本。', '', '', '', 0),
(263, 'keypoint', '', 935, 0, 0, '闽杀李仿', 'minguowang', '初闽皇城使李仿与王昶弑王鏻。李仿专制朝政，豢养死士，为王昶所忌。十一月，王昶出伏兵执斩之，枭首示众。李仿部下攻应天门不克，焚启>圣门，夺李仿首级奔吴越。', '', '', '', 0),
(264, 'keypoint', '', 936, 0, 0, '幽云十六州', 'houjin', '石敬瑭割让幽云十六州给契丹。辽太宗将幽州升为南京幽都府，幽州作为行政区划终止。十六州地处太行山东部、北部和西北，地>形险要，其割让使华北平原失去屏障。', '', '', '', 0),
(265, 'keypoint', '', 936, 0, 0, '后唐建义军', 'houtang', '十月，后唐因征讨河东之需，下诏括天下将吏及民间马匹，又发民为兵，自备器甲，称“义军”。寥寥数千兵马，于征讨无补，\n民间却大为困扰。时有作乱，逐刺史。', '', '', '', 0),
(266, 'keypoint', '', 936, 0, 0, '石敬瑭称帝', 'houjin', '契丹王耶律德光册原后唐河东节度使石敬瑭为大晋皇帝。以割地、称臣、称儿、输帛换得契丹的支援，灭后唐。但最终因吐谷浑部叛契丹之事，受>契丹责备忧郁而卒。', '', '', '', 0),
(267, 'keypoint', '', 936, 0, 0, '后晋灭后唐', 'houjin', '闰十一月，石敬瑭借契丹之力破后唐征讨大军于晋安寨。二十六日，后唐末帝李从珂与曹太后、皇后、淮王、宋审虔等携传国宝登玄武楼自焚而死>。当晚石敬瑭入洛阳，后唐亡国。', '', '', '', 0),
(268, 'keypoint', '', 936, 0, 0, '高丽统一朝鲜', '', '高丽王王建出兵攻今朝鲜半岛的新罗、百济、统一今朝鲜半岛。设二京、六府、九节度、一百二十郡。', '', '', '', 0),
(269, 'keypoint', '', 937, 0, 0, '吴册徐知诰为齐王', 'yangwu', '吴执政徐知诰早有代吴之意。正月，徐知诰建齐国，改金陵府为江宁府，如国中之国。二月吴正式册命其为齐国王。三月，徐知诰改名徐诰>。距正式禅代已为时不远。', '', '', '', 0),
(270, 'keypoint', '', 937, 0, 0, '吴与契丹修好', 'yangwu', '五月，吴齐王徐诰用谋士宋齐丘之计，欲联合契丹共取中原，遣使节自海路献美女、珍玩与契丹修好。契丹帝耶律德光亦遣使回报。', '', '', '', 0),
(271, 'keypoint', '', 937, 0, 0, '后晋三镇连叛', 'houjin', '七月，范延光、张从宾、符彦饶魏、孟、滑三镇相继反叛，原对范延光所形成的包围已经失效，后晋朝野震动。晋派杨光远、杜重威等评判。', '', '', '', 0),
(272, 'keypoint', '', 937, 0, 0, '闽复通中原', 'minguowang', '十月，闽帝王昶命其弟王继恭上表于晋，告以嗣闽位之事，并请于后晋都城设邸店，闽于后唐长兴三年（932）绝中原，至此复通好。', '', '', '', 0),
(273, 'keypoint', '', 937, 0, 0, '后蜀改元广政', 'houshu', '二月，后蜀大赦，改938年为广政。', '', '', '', 0),
(274, 'keypoint', '', 937, 0, 0, '段氏大理建国', '', '936年十二月末，大义宁通海节度使段思平会合黑爨、松爨三十七蛮部，自石城（今云南曲靖北）攻大理，大义宁帝杨干贞兵败出逃。937年，段思平建>国大理，以大理为都城。', '', '', '', 0),
(275, 'keypoint', '', 938, 0, 0, '后晋依附契丹', 'houjin', '后晋依附契丹称臣，引发中原政权与北方民族关系变化。此外，后晋内部政局动荡，范延光叛乱及杨光远干政等问题频发，进一步加剧了中央集>权的削弱。', '', '', '', 0),
(276, 'keypoint', '', 938, 0, 0, '李昪建南唐', 'nantang', '徐知诰改名李昪，改国号为唐，史称南唐。', '', '', '', 0),
(277, 'keypoint', '', 938, 0, 0, '辽升幽州为南京', 'liaoguo', '石敬瑭向契丹割让燕云十六州，契丹借此强化对华北控制。耶律德光升幽州为南京，又称燕京，作为陪都。后设置析津府，析津、宛平二县为府治。', '', '', '', 0),
(278, 'keypoint', '', 939, 0, 0, '', 'minguowang', '及闽国修建三清殿。', '', '', '', 0),
(279, 'keypoint', '', 939, 0, 0, '', 'houjin', '后晋诏许民间自铸“天福元宝”钱币，钱文粗糙不一，官铸与民铸并存。', '', '', '', 0),
(280, 'keypoint', '', 939, 0, 0, '楚收诸蛮', 'nanchu', '八月，溪州刺史（今湖南古丈东北）彭士愁率领蛮万余人焚掠镇戍。九月，楚王马希范命刘京、廖匡齐领五千衡山兵讨彭士愁。诸蛮臣服于楚。', '', '', '', 0),
(281, 'keypoint', '', 939, 0, 0, '晋囚闽使', 'houjin', '七月，王昶遇弑，王曦据闽。十月，王昶的使节郑元弼到后晋都城，后晋高祖因王昶致信用敌国之礼，言辞不逊，下诏拒绝闽所进贡物以及福、建诸>州的纲运。囚郑元弼及闽进奏官林恩。', '', '', '', 0),
(282, 'keypoint', '', 939, 0, 0, '册封回鹘可汗', 'houjin', '三月，后晋册封回鹘可汗仁裕为奉化可汗。回鹘为北方少数民族之一，唐末为黠戛斯所败，西徙到甘州（今甘肃张掖）一带。', '', '', '', 0),
(283, 'keypoint', '', 939, 0, 0, '后晋废枢密院', 'houjin', '四月，后晋废枢密院，枢密院印交中书门下。枢密使一职设置于唐宪宗时期，由宦官担任，后渐干政。后唐枢密使权重，安重诲弄权擅政，至使>国破家亡。后晋初由宰臣兼枢密使。', '', '', '', 0),
(284, 'keypoint', '', 939, 0, 0, '闽王昶被杀', 'minguowang', '王昶昏庸而迷信，政事均由林兴传所谓宝皇大帝之命决定。漳、泉二都的军使朱文进、连重遇多次遭王昶的侮辱。连重遇攻杀王昶，陈守元。>迎立王延曦，即王曦为闽王。', '', '', '', 0),
(287, 'keypoint', '', 940, 0, 0, '闽国内乱', 'minguowang', '闽国王曦与弟王延政爆发内战，双方引吴越援军互攻，最终在南唐调停下暂时和解；', '', '', '', 0),
(288, 'keypoint', '', 940, 0, 0, '楚立溪州铜柱', 'nanchu', '二月，楚收服溪、锦、奖三州诸蛮，楚王马希范以铜五千斤铸柱，立于溪州（今湖南古丈东北），确立与彭氏土司的盟约。铜柱高一丈二尺，由学士李弘皋撰文，保存至今。', '', '', '', 0),
(289, 'keypoint', '', 940, 0, 0, '闽广度僧人', 'minguowang', '闽历代君主均奉道佞佛，闽帝王曦度民为僧，因闽赋役颇重，所以百姓为避重赋大多愿出家，度僧竟达一万一千人。', '', '', '', 0),
(290, 'keypoint', '', 940, 0, 0, '后晋废置翰林院', 'houjin', '九月，后晋废翰林学士院，所掌之事归中书舍人。至开运元年（944）六月，复置。', '', '', '', 0),
(291, 'keypoint', '', 940, 0, 0, '南唐建庐山国学', 'nantang', '南唐于庐山白鹿洞建学馆，置田供给学员用度，由李善道为洞主，号\"庐山国学\"。至宋代，在此基础上形成四大书院之一的白鹿洞书院。', '', '', '', 0),
(292, 'keypoint', '', 940, 0, 0, '曹元德继掌归义军', 'houjin', '二月初一，沙州（今甘肃敦煌）归义军节度使曹议金卒，后晋赠太师，以其子曹元德袭归义军节度使位。', '', '', '', 0),
(293, 'keypoint', '', 940, 0, 0, '安州叛晋附南唐', 'houjin', '后晋安州节度使李金全叛附南唐，引发晋唐军事冲突，南唐兵败损失四千余人。', '', '', '', 0),
(294, 'keypoint', '', 940, 0, 0, '赵崇祚编《花间集》', 'houshu', '赵崇祚编《花间集》十卷。赵崇祚字弘基，后蜀官卫尉少卿。《花间集》收录了温庭筠以下晚唐、五代词十八家，不少作品据此得以保存>。此集流传至今，词学重要文献。', '', '', '', 0),
(295, 'keypoint', '', 940, 0, 0, '大藏经音义随函录', 'houjin', '汉中沙门可洪撰成《大藏经音义随函录》，进上，命入大藏。《随函录》三十卷，订正了玄庄、厚师、谦师、郭逐各家的错讹。', '', '', '', 0),
(296, 'keypoint', '', 941, 0, 0, '杨彦询出使契丹', 'houtang', '后晋与契丹因外交争端一度关系紧张，后经杨彦询出使交涉得以缓和。', '', '', '', 0),
(297, 'keypoint', '', 941, 0, 0, '练湖水利工程重建', 'nantang', '南唐丹阳县练湖水利工程因斗门木损毁，由知事吕延贞主持重建，属地方治理的重要举措。', '', '', '', 0),
(298, 'keypoint', '', 941, 0, 0, '闽国内乱', 'minguowang', '闽国王延政与王曦爆发军事冲突，双方屡战于建州等地。', '', '', '', 0),
(299, 'keypoint', '', 941, 0, 0, '安重荣反晋', 'houjin', '后晋成德节度使安重荣联合吐谷浑反叛，晋遣杜重威镇压，安重荣兵败退守。', '', '', '', 0),
(300, 'keypoint', '', 941, 0, 0, '孟昶军事改革', 'houshu', '后蜀孟昶推行军事改革，后蜀罢节度使典禁兵，削夺赵廷隐等节度使实权以巩固中央集权。', '', '', '', 0),
(301, 'keypoint', '', 941, 0, 0, '吴越钱元瓘卒', 'wuyue', '八月，钱元瓘因受惊发狂而卒。吴越内都监章德安秘不发丧，谋杀内牙指挥使，废钱元瓘养子钱弘侑。九月，钱弘佐即位，十二月后晋以钱弘佐为镇海、镇东节度使兼中书令。', '', '', '', 0),
(302, 'keypoint', '', 941, 0, 0, '南唐定民田税', 'nantang', '十一月，南唐派使者分别按民田，以田肥瘦定其税额，民间称平允。从此以后，南唐调兵或劳役、赋敛，均以税钱为准。', '', '', '', 0),
(303, 'keypoint', '', 941, 0, 0, '王定保卒', 'nanhan', '王定保（870-941），琅邪人，南汉中书侍郎、同平章事。900年进士，南奔于楚，不见遇马殷，入岭南，附于刘氏无北归意。著有《唐摭言》，详载唐代贡举之制，流传至今。', '', '', '', 0),
(304, 'keypoint', '', 942, 0, 0, '南汉刘䶮卒', 'nanhan', '南汉刘䶮病重，欲立幼子刘弘昌，遭崇文使萧益反对，遂罢。四月，刘䶮卒。刘弘度以长而立，改名刘玢，改元>光天元年，是为南汉殇帝。次年即遭弑。', '', '', '', 0),
(305, 'keypoint', '', 942, 0, 0, '石敬瑭卒', 'houjin', '石敬瑭因安置吐谷浑南归一事屡遭契丹斥责，忧郁而死。石敬瑭幼子石重睿年幼。冯道与天平节度使、侍卫马步都虞侯景延广立石敬瑭养子齐王石重贵。', '', '', '', 0),
(306, 'keypoint', '', 942, 0, 0, '升元删定格', 'nantang', '南唐升元六年（942）九月，南唐颁行《升元删定格》三十卷。南唐先主李升自即位后便命人着手删定旧法，修订法典，至是始成，施行。', '', '', '', 0),
(307, 'keypoint', '', 942, 0, 0, '后晋重征食盐钱', 'houjin', '三司使董遏为谋利，重征盐商。因盐税过重，盐商渐绝迹，仍旧由官场买卖，但原百姓所纳食盐钱仍不免，双重征缴，民甚苦。此弊一直沿至宋代。', '', '', '', 0),
(308, 'keypoint', '', 942, 0, 0, '晋出帝向契丹称孙', 'jinguo', '晋出帝即位后，向契丹通报晋高祖石敬瑭死讯，景延广以为对契丹可以称孙而不宜称臣。耶律德光勃然大怒，派使节责备晋帝，未事先通报>契丹便即帝位。两国关系紧张。', '', '', '', 0),
(309, 'keypoint', '', 942, 0, 0, '王延政大败王曦', 'minguowang', '富沙王王延政与帝王曦交兵，尤溪口之战大败曦军。曦求和于王延政，王延政不受。', '', '', '', 0),
(310, 'keypoint', '', 942, 0, 0, '闽铸大铁钱', 'minguowang', '941年八月，闽铸“永隆通宝”大铁钱，以一当铅钱百。后王延政立殷，于942年正月铸“天德通宝”大铁钱，以一当铜钱一百，另铸有“天德重宝”，亦铁钱。币制混乱。', '', '', '', 0),
(311, 'keypoint', '', 942, 0, 0, '张遇贤起义', 'nanhan', '741年，循州（今广东龙川）爆发农民起义，义军推县吏张遇贤为首领。742年南汉打败义军，张遇贤撤往南唐虔州（今江西赣州）。义军失利，张遇贤被部下执送南唐，处斩。', '', '', '', 0),
(312, 'keypoint', '', 925, 0, 0, '后唐内斗', 'houtang', '后唐内部权力斗争显现，将领李嗣源遭猜忌，宦官与文官矛盾激化，为后续政局变动埋下伏笔。', '', '', '', 0),
(313, 'keypoint', '', 925, 0, 0, '南汉不复通中原', 'nanhan', '南汉主刘岩所遣使节何词入贡于唐，至邺都（今河北大名东北），观后唐形势。得何词南归复命，称唐帝骄淫无政，不足畏。刘岩大喜，从此>不再与中原王朝来往。', '', '', '', 0),
(314, 'keypoint', '', 925, 0, 0, '后唐灭蜀', 'houtang', '后唐发动灭蜀之战，仅用70天攻灭前蜀，俘获其宗室及大量资源。', '', '', '', 0),
(315, 'keypoint', '', 925, 0, 0, '南汉改元白龙', 'nanhan', '十二月，高祖刘岩因白龙入南宫三清殿，改名刘龚，改元白龙，以承其瑞。', '', '', '', 0),
(316, 'keypoint', '', 925, 0, 0, '吴与吴越绝交', 'yangwu', '十二月，钱镠派沈瑫为使，致书于吴，告以受封为吴越国王。先是两国息兵修好，至此，吴以吴越国名与吴同，与吴越绝交，仍禁止吴越使者及商旅过吴境。', '', '', '', 0),
(317, 'keypoint', '', 925, 0, 0, '华北先旱后涝', 'houtang', '北方春夏持续大旱，至六月中，始降雨。以后自七月三日至九月十八日，连续七十五日阴雨，少有晴日。江河百川水灾为患。', '', '', '', 0),
(318, 'keypoint', '', 925, 0, 0, '唐杀王宗弼', 'houtang', '十二月，唐伐蜀副帅郭崇韬收蜀中书令王宗弼及王宗勋、王宗渥等，族诛之，籍没其家。', '', '', '', 0),
(319, 'keypoint', '', 925, 0, 0, '王审知卒', 'minguowang', '十二月十二，闽威武节度使王审知卒。子王延翰自称留后，十月自称大闽国王，十二月为王延禀所杀。', '', '', '', 0),
(320, 'keypoint', '', 925, 0, 0, '长和郑仁旻求婚', 'nanhan', '唐末，南诏改名大礼，后又改名长和。925年，长和骠信（帝）郑仁旻遣其弟郑昭淳以红鬃白马求婚于南汉。南汉以烈宗刘隐之女增城公主妻之\r\n。', '', '', '', 0),
(321, 'keypoint', '', 924, 0, 0, '后唐复用阉人', 'houtang', '正月，命集唐内宦及诸道监军以及私人所蓄寺人。不论贵贱，一律至京城。自903年诛灭宦官，一直由士人充任的内诸司使，至此复以宦官担任>。', '', '', '', 0),
(322, 'keypoint', '', 924, 0, 0, '置两池榷盐使', 'houtang', '二月，以河中节度使李继麟（朱友谦）为两池榷盐使，以安邑（今山西运城东）、解县（今山西运城西南）两池盐课，每三月一输于省。', '', '', '', 0),
(323, 'keypoint', '', 924, 0, 0, '后唐置内勾使', 'houtang', '二月，置内勾使，掌勾盐铁，度支、户部三司财赋，郭崇韬以宦者李（马）绍宏为之。凡天下钱谷簿账均由内勾使裁遣，徒增州县移报之烦。而\r\n绍宏终不悦。', '', '', '', 0),
(324, 'keypoint', '', 924, 0, 0, '唐浚索水', 'houtang', '二月，后唐诏蔡州刺史朱勅疏浚索水（今河南郑州西），以通漕运。', '', '', '', 0),
(325, 'keypoint', '', 924, 0, 0, '后唐禁铁锡钱', 'houtang', '三月，因江南、湖广等地铸钱杂以铅锡，流至北方，商人以此换好钱收藏，已成流弊，下诏各地禁断行市行用铅锡钱。', '', '', '', 0),
(326, 'keypoint', '', 924, 0, 0, '后唐精核选人', 'houtang', '唐末丧乱，缙绅之家多出售告身（委任状），故选人冒滥者众。枢密使郭崇韬命有司对选人精加考核。此次整饬，选人或号哭道路，或馁死逆旅\r\n。', '', '', '', 0),
(327, 'keypoint', '', 924, 0, 0, '庄宗立刘氏', 'houtang', '二月，庄宗立魏国夫人刘氏为皇后。刘氏出身贫寒，性妬，得庄宗宠幸。既贵，其父来寻女，为后逐出。专务蓄财，政事\n因之混乱。庄宗遇弑后，刘后削发为尼，后被明宗赐死。', '', '', '', 0),
(328, 'keypoint', '', 924, 0, 0, '回鹘入贡后唐', 'houtang', '四月，甘州回鹘权知可汗仁美遣都督李行释迦、副使铁林、都监杨福安等六十六人入贡于后唐。六月后唐遣使册仁美为\"英义可汗\"。', '', '', '', 0),
(329, 'keypoint', '', 924, 0, 0, '李严使蜀', 'houtang', '唐以客省使李严出使于蜀。李严盛称庄宗威德及混一天下之志，言语多侵蜀。蜀君臣愤愤不平。时蜀法禁止锦绮珍奇入中原，只许劣质产品入中原，称“入草物”。庄宗遂生灭蜀之心。', '', '', '', 0),
(330, 'keypoint', '', 924, 0, 0, '安义军乱', 'houtang', '四月，潞州发安义兵三千戍涿州，军士不欲行。安义军牙将杨立聚众攻子城，焚掠市肆，自称留后。唐以李嗣源帅军讨之。潞州乱平，磔杨立。六月，庄宗下令夷平潞州城池。', '', '', '', 0),
(331, 'keypoint', '', 924, 0, 0, '贞峻卒', 'houtang', '四月十二日，开封相国寺僧、著名律师（佛教善解戒律者之称）贞峻卒。891年起任相国寺上座，为新章宗主，开律讲。至梁，度僧尼三千余人。', '', '', '', 0),
(332, 'keypoint', '', 924, 0, 0, '唐庄宋宠优伶', 'houtang', '李存勖自幼善音律，经常粉墨登场，自取优名为“李天下”。因此，唐之优伶常侍左右，多受宠幸。伶人得干预政事。时亲军有从帝百战未得刺史\r\n者，闻之莫不愤叹。', '', '', '', 0),
(333, 'keypoint', '', 924, 0, 0, '归义军入贡', 'houtang', '春，瓜、沙（今甘肃敦煌地区）归义军留后曹议金遣使入贡于后唐。五月，后唐以曹议金为归义军节度使、沙州刺史、检校司空。', '', '', '', 0),
(334, 'keypoint', '', 924, 0, 0, '唐治河患', 'houtang', '后唐与梁战于河上之际，梁曾于923年决黄河以阻唐军。七月，唐以娄继英督汴、滑之兵塞河，不久又坏。925年正月，复命符司于酸枣（今河南延津\r\n西）平地遥筑堤坝以御决河。', '', '', '', 0),
(335, 'keypoint', '', 924, 0, 0, '契丹犯唐', 'houtang', '正月，契丹寇唐境，兵至瓦桥关（今河北雄县西南），唐以天平节度使李嗣源往幽州救援。九至十月，契丹连续犯唐幽州、易定。十二月，唐以李嗣源北出备边。', '', '', '', 0),
(336, 'keypoint', '', 924, 0, 0, '前蜀宦官建节', 'qianshu', '十二月，蜀以宦官王承休为天雄军节度使、鲁国公。宦官建节一方，虽唐末亦未尝有。', '', '', '', 0),
(337, 'keypoint', '', 924, 0, 0, '前蜀改元咸康', 'qianshu', '十二月，蜀改明年为咸康元年。', '', '', '', 0),
(338, 'keypoint', '', 924, 0, 0, '吴越改元宝大', 'wuyue', '吴越以后唐代梁，重自立正朔，以924年为宝大元年。其年十月，吴越王钱镠复修本朝（指属唐朝）职贡，庄宗亦依梁所授，仍以钱镠为天下兵马>都元帅、尚父、尚书令、吴越国王。', '', '', '', 0),
(339, 'keypoint', '', 924, 0, 0, '南汉侵闽', 'nanhan', '南汉主刘岩领兵攻闽，屯于汀（今福建长汀）、漳（今福州漳州）州境上，为闽所败，行归。', '', '', '', 0),
(340, 'keypoint', '', 924, 0, 0, '', 'houtang', '鄜州僧人智严与定州僧人归文于该年启程西行求法。', '', '', '', 0),
(341, 'keypoint', '', 924, 0, 0, '', 'liaoguo', '契丹持续袭扰中原并东征渤海国。', '', '', '', 0),
(342, 'keypoint', '', 923, 0, 0, '晋置百官', 'houtang', '二月，晋王李存勖下教（王之令曰“教”）置百官。又于河东、魏博、易定、镇冀四镇判宫中选唐朝士族，欲以之为相。', '', '', '', 0),
(343, 'keypoint', '', 923, 0, 0, '后唐建立', 'houtang', '908年李存勖击溃梁军于潞州城下，奠定霸业基础。四月，李存勖在魏州（今河北大名东北）称帝，国号大唐，改元同光。十月，后唐灭梁，转向全>力治理内政。', '', '', '', 0),
(344, 'keypoint', '', 923, 0, 0, '吴越建国', 'wuyue', '二月，梁遣兵部侍郎崔协等为使，册封吴越王钱鏐。表面臣属而实际独立。对北方朝廷示好纳贡，注意兴修水利，发展商业及海上交通\n，但赋役繁重，民众苦不堪言。', '', '', '', 0),
(345, 'keypoint', '', 923, 0, 0, '后唐灭梁', 'houtang', '唐经苦战保住杨刘重镇，梁主帅王彦章因副帅段凝及监军掣肘功败垂成，梁以段凝为帅。梁末帝知回天无力，命控鹤都指挥使皇甫麟杀已，皇甫随后\r\n自杀。唐庄宗入大梁。', '', '', '', 0),
(346, 'keypoint', '', 923, 0, 0, '后唐迁都洛阳', 'houtang', '十一月，庄宗从河南尹张全义之请，迁都洛阳。至925年三月，后唐遵唐旧制，复以洛阳为东都，长安为西京，以兴唐府（今河北大名东北）为>邺都。', '', '', '', 0),
(347, 'keypoint', '', 923, 0, 0, '后唐复行唐法律', 'houtang', '后梁曾于910年删改唐代律令格式，并收唐法典旧本焚毁。923年十二月，御史台奏，唯定州敕库有唐法典全本，请下令由定州节度使录副本进\r\n纳，并请后唐法律从唐旧制。', '', '', '', 0),
(348, 'keypoint', '', 923, 0, 0, '高季兴亲自入朝', 'nanping', '荆南节度使高季昌闻后唐灭梁，避唐讳更名为季兴，并亲自入朝为贺。十一月，后唐加高季兴守中书令。庄宗所辜伶人索求无厌，季兴内心不\r\n平。', '', '', '', 0),
(349, 'keypoint', '', 923, 0, 0, '李继韬叛晋', 'houtang', '三月，李继韬以泽潞叛晋附梁。晋昭义旧将裴约据泽州（今山西晋城）自守，城破被杀。因潜谋归镇败露，庄宗斩继韬及二子。后李继俦、继达兄\r\n弟自相攻杀，泽潞遂归朝廷。', '', '', '', 0),
(350, 'keypoint', '', 923, 0, 0, '李嗣源取郓州', 'houtang', '后唐始建国，北有契丹寇幽州，西有泽潞叛附于梁，黄河以南尚为梁有。闰四月，唐李嗣源取郓州（今山东东北西北）。嗣源禁焚掠，抚吏民，\r\n一夕而定。', '', '', '', 0),
(351, 'keypoint', '', 922, 0, 0, '契丹南侵', 'houliang', '阿保机应卢文进之请及受义武节度使王处直子王郁之诱，倾全力南侵，述律后谏，不听。李存勖反击，契丹损失惨重，遂自幽州撤出塞外，絷新州>团练使王郁以归，自是不听其谋。', '', '', '', 0),
(352, 'keypoint', '', 922, 0, 0, '梁复取河北卫', 'houliang', '后梁与晋在河北展开军事争夺，梁军攻占卫州等据点，致使晋军损失三分之一物资储备。', '', '', '', 0),
(353, 'keypoint', '', 922, 0, 0, '王处直逝世', 'houliang', '唐末义武节度使王处存弟，逐侄王郜自立据有定、易二州。五代梁、晋相争，处直结晋抗梁以自存。欲结契丹以自固，为养子王都所囚。922年正月，王处直忧愤卒。', '', '', '', 0),
(354, 'keypoint', '', 922, 0, 0, '闫宝逝世', 'houliang', '唐末兖州朱瑾牙将，朱瑾兵败入梁，宝随梁王多立战功，迁邢洺保义节度使。后降晋。三月晋困镇州，因大意轻敌，致使晋军营垒尽毁，粮蜀尽失>，遂罢职。四月，惭愤成疾而卒。', '', '', '', 0),
(355, 'keypoint', '', 922, 0, 0, '李嗣昭逝世', 'houliang', '唐末河东节度使李克用弟克柔养子。在唐末及梁晋征战中，屡建战功。晋平镇冀，已大胜，嗣昭脑中矢，嗣昭矢尽，即拔矢于脑，一发而毙敌，>己则创血不止，夕卒。', '', '', '', 0),
(356, 'keypoint', '', 922, 0, 0, '契丹改元天赞', 'liaoguo', '契丹耶律亿（阿保机）神册七年（922），改元天赞。', '', '', '', 0),
(357, 'keypoint', '', 922, 0, 0, '王氏高丽建国', '', '大封国王躬乂性残忍，海军统帅王建杀之自立，仍称高丽王，以开州（今朝鲜开城）为东京，以平壤为西京。建伶的宽厚，国人安之。', '', '', '', 0),
(358, 'keypoint', '', 921, 0, 0, '吴改元顺义', 'yangwu', '吴武义三年（921），吴改当年为顺义元年。一月，杨吴建成金陵城,修建紫极宫于冶城旧址。 二月，吴王杨溥派遣使节到晋劝晋称皇帝。 三月，>吴改元顺义，全国境内大赦。', '', '', '', 0),
(359, 'keypoint', '', 921, 0, 0, '梁令出家者试经', 'houliang', '三月，梁禁天下私度僧尼，如愿出家受戒者，须入京比试经业，愿返俗者，听其自便。', '', '', '', 0),
(360, 'keypoint', '', 921, 0, 0, '后梁改元龙德', 'houliang', '贞明七年（921）五月初一，梁改元为龙德。', '', '', '', 0),
(361, 'keypoint', '', 921, 0, 0, '晋并镇冀深赵四州', 'houliang', '八月，李存勖讨张文礼。文礼闻讯惊惧而卒，其子张处瑾全力拒晋。晋耗时一年余，折损大将数员，最终兼并镇、冀、深、赵四州。', '', '', '', 0),
(362, 'keypoint', '', 921, 0, 0, '辰溆蛮侵楚', 'nanchu', '辰州（今湖南沅陵）、溆州（今湖南怀化南）蛮侵楚，楚宁远节度副使姚彦章击退之。', '', '', '', 0),
(363, 'keypoint', '', 921, 0, 0, '成德军乱', 'houliang', '成德节度使（治镇州，今河北正定）王镕事佛求仙，王镕养子王德明（原名张文礼）唆使亲军杀王镕，尽灭王氏之族。晋王欲讨之>，因方与梁争，只好授张文礼为成德留后。', '', '', '', 0),
(364, 'keypoint', '', 921, 0, 0, '梁朱友能反', 'houliang', '三月，梁陈州（今河南淮阳）刺史惠王朱友能（太祖养子）反。朱友能至陈留（今河南开封东南），兵败，逃回陈州，粱军围陈州。七月，朱友>能降。诏赦其死，降为房陵侯。', '', '', '', 0),
(365, 'keypoint', '', 921, 0, 0, '梁杀刘寻', 'houliang', '五月，梁末帝命西都留守张宗奭（全义）鸩杀大将刘寻。刘寻在梁多年征战，有得有失，最终因遭人忌及受姻亲朱友谦附晋之累，仍遭鸩杀。史言>梁自翦爪牙，甚是。', '', '', '', 0),
(366, 'keypoint', '', 921, 0, 0, '义武军乱', 'houliang', '十月，义武节度使（领定、易二州）王处直养子王都以义武军人不愿暗结契丹与张文礼，劫持王处直。王都通告于晋，晋王以都代王处直。此为来日唐明宗朝王都亦召契丹张本。', '', '', '', 0),
(367, 'keypoint', '', 921, 11, 7, '波恩协议', '', '西法兰克国王查理三世与东法兰克国王亨利一世签定波恩协议。互相承认他们莱茵河沿岸的边界。', '', '', '', 0),
(368, 'keypoint', '', 921, 0, 0, '', 'liaoguo', '契丹趁中原动荡南下攻陷涿州，晋王率军抵御。', '', '', '', 0),
(369, 'keypoint', '', 920, 0, 0, '杨溥即吴王位', 'yangwu', '吴王杨隆演病殂，隆演之弟溥即吴王位。由执政徐温以吴王命迎之监国而即位。', '', '', '', 0),
(370, 'keypoint', '', 920, 0, 0, '晋取梁河西之地', 'houliang', '四月，梁河中节度使（今山西永济）朱友谦袭取同州（今陕西大荔），附于晋。梁以刘寻攻同州，晋以李存审、李嗣昭等救援。解同州之围>后，攻华州（今陕西华县），大败梁师。', '', '', '', 0),
(371, 'keypoint', '', 920, 0, 0, '楚与吴越通婚', 'wuyue', '十二月，吴越王钱镠为子钱传琇求婚于楚。楚王马殷许婚，次年七月送女归杭州。', '', '', '', 0),
(372, 'keypoint', '', 920, 0, 0, '契丹造文字', 'liaoguo', '突吕不创契丹大字，阿保机的弟弟鲁不古学习回鹘文后造契丹小字。只是在契丹贵族文人中使用，范围极有限。辽朝的文化主要是依靠汉字作工具\r\n进行传播和发展的。', '', '', '', 0),
(373, 'keypoint', '', 920, 0, 0, '南汉开科选举', 'nanhan', '三月，南汉因兵部侍郎杨洞潜之请，立学校，设铨选，开贡举，每年放进士、明经十余人，有如唐代之制。', '', '', '', 0),
(374, 'keypoint', '', 920, 0, 0, '梁陈州民起事', 'houliang', '七月，陈州（今河南淮阳）民母乙、董乙依佛法自立一宗，渐至千人，攻掠乡社。梁屡发州兵讨捕未果。十月，梁发禁军及数郡兵合力追击，>擒母乙等首领八十余人，斩之。', '', '', '', 0),
(375, 'keypoint', '', 920, 0, 0, '牛峤卒', 'qianshu', '878年进士。前蜀高祖王建节度西川，牛峤为判官。王建称帝，拜给事中。牛峤博学有文，以歌诗著名，尤善词，有集三十>卷，歌诗三卷。有词三十二首今存。', '', '', '', 0),
(376, 'keypoint', '', 919, 0, 0, '亨利一世即位', '', '亨利一世原为萨克森公爵，遵照逝世的康拉德国王的意愿，并把国王的象征物交给了公爵。开启了萨克森王朝。亨利一世通过诸侯推举与军事策略平息巴伐利亚、施瓦本公国挑战。', '', '', '', 0),
(377, 'keypoint', '', 919, 0, 0, '高丽王朝建立', '', '朝鲜半岛高丽王朝正式建立，开启朝鲜历史新阶段。', '', '', '', 0),
(378, 'keypoint', '', 919, 0, 0, '刘隐死', 'nanhan', '刘隐死，其弟刘龚继承王位，称帝，国号大越，翌年改为汉，史称南汉。南汉传四主，即高祖刘、殇帝刘玢、中宗刘晟、后主刘鋹。', '', '', '', 0),
(379, 'keypoint', '', 919, 0, 0, '德胜渡口之战', 'houliang', '正月,晋军将领李存审领兵进占德胜,并夹河筑了两城防守渡口。晋梁开始了德胜渡口之战。', '', '', '', 0),
(380, 'keypoint', '', 919, 0, 0, '', 'yangwu', '徐温、张颢弑杀烈祖杨渥后拥立杨隆演继位，改元武义死。之前吴使用唐昭宗天佑年号。称吴国王，建元武义，以示不复为唐朝之藩镇。', '', '', '', 0),
(381, 'keypoint', '', 919, 0, 0, '', 'wuyue', '吴越与南汉等国展开军事争夺。吴越水军在狼山江战役中采用特殊战术击败吴军。', '', '', '', 0),
(382, 'keypoint', '', 919, 0, 0, '修辽阳城', 'liaoguo', '辽太祖耶律阿保机修葺辽阳城,改为东平郡,置防御使,并“铸铁凤以镇之”,因称辽阳为铁凤城。', '', '', '', 0),
(383, 'keypoint', '', 918, 0, 0, '朝鲜王朝创立', '', '朝鲜封建王朝创立。国号高丽，都开京（今开城）。', '', '', '', 0),
(384, 'keypoint', '', 918, 0, 0, '', 'liaoguo', '渤海遣使朝贡于契丹,企图延缓契丹人东进的攻势。', '', '', '', 0),
(385, 'keypoint', '', 918, 0, 0, '', 'liaoguo', '阿保机令汉人康默记等人建京城,名“皇都”（今内蒙古巴林左旗），奠定辽代都城基础。', '', '', '', 0),
(386, 'keypoint', '', 918, 0, 0, '', 'liaoguo', '辽太祖耶律阿保机攻占辽东城置辽阳府。', '', '', '', 0),
(387, 'keypoint', '', 918, 0, 0, '', 'houliang', '八月,李存勖集中10万大军于魏州,企图南渡黄河进攻汴梁(今河南开封)。', '', '', '', 0),
(388, 'keypoint', '', 918, 0, 0, '', 'liaoguo', '定安国从渤海国分裂出来,统治中心是原渤海西京鸭渌府(今吉林省临江市一带),属地包括今日集安等地。', '', '', '', 0),
(389, 'keypoint', '', 918, 0, 0, '', 'liaoguo', '上京正式筑城,名为皇城。上京是契丹建国之初设立的都城,也是我国古代漠北地区的第一座都城。', '', '', '', 0),
(390, 'keypoint', '', 918, 0, 0, '王建去世', 'qianshu', '前蜀后主王衍登基,在位7年。王衍奢侈荒淫,营建宫殿,巡游诸郡,耗费大量财力,加重了人民的负担。', '', '', '', 0),
(391, 'keypoint', '', 918, 0, 0, '', 'houliang', '朱友能铤而走险,举兵谋反。梁末帝赦免了他的死罪，贬为房陵侯，流放房陵。', '', '', '', 0),
(392, 'keypoint', '', 918, 0, 0, '', 'houliang', 'l后梁与晋国在胡柳陂激战，双方损失惨重。', '', '', '', 0),
(393, 'keypoint', '', 918, 0, 0, '三善清行卒', '', '式部大辅三善清行(公元847年—公元918年)，日本大臣，曾提出了著名的《上谏书》(《意见封事》)12条。', '', '', '', 0),
(394, 'keypoint', '', 918, 0, 0, '朱瑾卒', 'yangwu', '867年-918年，唐末五代时期军阀、将领。袭据兖州，朱温破兖州，他南走投杨行密。后与徐温父子争吴政，杀徐温子知训，以无人支持，势穷自杀。', '', '', '', 0),
(395, 'keypoint', '', 918, 0, 0, '徐知训卒', 'yangwu', '徐温居升州，以长子徐知训居南吴都城扬州(今江苏扬州)控制南吴政权。918年，徐知训因骄傲荒淫为朱瑾所杀。', '', '', '', 0);
INSERT INTO `wp_affair` (`id`, `affair_type`, `accurate`, `year`, `month`, `day`, `title`, `country_code`, `brief`, `description`, `baidu_url`, `path_point`, `status`) VALUES
(396, 'keypoint', '', 917, 0, 0, '', 'houliang', '赵弘殷加入成德军，标志着赵氏家族进入五代军事体系。救援后唐庄宗有功，负责管理禁军。藩镇争霸向侍卫亲军转型的过渡期。', '', '', '', 0),
(397, 'keypoint', '', 917, 0, 0, '', 'houliang', '石敬瑭在莘城之战中率军苦斗数十里，助李嗣源大败后梁刘鄩军队。', '', '', '', 0),
(398, 'keypoint', '', 917, 0, 0, '', 'houliang', '晋军平定河北后，二月攻黎阳未果撤军。', '', '', '', 0),
(399, 'keypoint', '', 917, 0, 0, '晋联吴攻梁', 'houliang', '916年十月，晋王李存勖邀吴国夹击后梁；十一月，吴将徐知训、朱瑾率军攻宋州、亳州并围颍州，次年正月梁军救援颍州致吴军退兵。', '', '', '', 0),
(400, 'keypoint', '', 917, 0, 0, '刘岩即皇帝位', 'nanhan', '八月，清海、建武节度使、南海王刘岩即皇帝位于番禺（今广州），国号“大越”，以本年为乾亨元年。当年铸钱“乾亨重宝”。', '', '', '', 0),
(401, 'keypoint', '', 917, 0, 0, '晋解幽州之围', 'houliang', '卢文进既奔契丹，助契丹为向导。契丹进围幽州（今北京），晋先后以李嗣源、李存审、闫宝救幽州。李嗣源采取“潜行溪涧，袭其不备”击败>契丹。晋援军入幽州。', '', '', '', 0),
(402, 'keypoint', '', 917, 0, 0, '蜀复国号', 'qianshu', '前蜀曾于917年改国号曰大汉，仅一年即复旧称，改元光天。', '', '', '', 0),
(403, 'keypoint', '', 917, 0, 0, '晋威塞军乱', 'houliang', '晋新州（今河北涿鹿）威塞军防御使李存矩（存勖弟）骄惰不治，侍婢预政，为部下所杀，乱军推裨将卢文进为首。文进不能制，率乱军北奔契>丹。晋王弑存矩侍婢及幕僚数人。', '', '', '', 0),
(404, 'keypoint', '', 917, 0, 0, '吴遣契丹猛火油', 'yangwu', '二月，吴王杨隆演遣使往契丹，赠契丹主猛火油（即石油），曰：“攻城，以此油燃火焚楼橹，敌以水沃之，火愈炽。”契丹主耶律亿（阿保机>）大喜。', '', '', '', 0),
(405, 'keypoint', '', 917, 0, 0, '蜀杀刘知俊', 'qianshu', '知俊于梁兼并诸镇多建战功，得为同州匡国军节度使。梁太祖猜忌，遂入岐，为泾州节度使。岐王左右所忌。又入蜀，为\n武信军节度使。后又为王建所忌，以谋叛罪杀被。。', '', '', '', 0),
(406, 'keypoint', '', 917, 0, 0, '晋陷杨刘', 'houliang', '李存勖乘冰封黄河之际，攻占杨刘城（今山东东阿北）。晋王亲自帅军涉水渡黄河，大败梁军，晋遂攻陷梁滨河四寨。', '', '', '', 0),
(407, 'keypoint', '', 916, 0, 0, '', 'liaoguo', '耶律阿保机统合八部，仿汉制立百官、筑城郭，韩延徽主持军政改革，设立汉城安置移民，奠定辽国政治基础', '', '', '', 0),
(408, 'keypoint', '', 916, 0, 0, '梁军突袭晋阳', 'houliang', '梁末帝朱瑱用王檀之策，突至晋阳（今山西太原）城下，昼夜急攻。河东监军张承业大惧。其时退居太原的代北故将安金全出城袭击敌师以待>援军，梁军大掠而还。', '', '', '', 0),
(409, 'keypoint', '', 916, 0, 0, '吴越绕道入贡于梁', 'houliang', '吴越与梁之间隔有淮南杨氏（杨氏不附梁，且系吴越敌国）。吴越为通使后梁，绕道闽、楚并派遣皮光业完成外交使命；后陆路不通走水>路入贡。', '', '', '', 0),
(410, 'keypoint', '', 916, 0, 0, '蜀取岐宝鸡陇州', 'houliang', '蜀以王宗绾攻取岐之宝鸡。以王宗播取岐之陇州（今陕西陇县），岐保胜节度使李继岌（桑宏志）弃州降蜀。两军会同攻凤翔，会天大雪，>蜀撤军。', '', '', '', 0),
(411, 'keypoint', '', 916, 0, 0, '晋尽取梁河北地', 'houliang', '梁昭德节度使弃相州（今河南安阳）而逃，闫宝闻相州已破，亦举邢州而降。梁河北州县尽入晋图版，唯黎阳（今河南浚县东）尚为梁守。', '', '', '', 0),
(412, 'keypoint', '', 916, 0, 0, '契丹寇晋', 'liangguo', '阿保机帅部三十万，攻陷河东蔚州（今河北蔚县），虏据武节度使李嗣本。攻云州（今山西大同），李存璋全力拒敌。李存勖领兵救援，契丹闻讯撤军。以李存璋为大同节度使。', '', '', '', 0),
(413, 'keypoint', '', 916, 0, 0, '闽浙、晋楚通好', 'houliang', '十二月，吴越王钱镠为子钱传瓘迎娶闽王审知次女，自是，闽与吴越通好。楚王马殷闻晋王平河北，遣使通好，晋王亦遣使报之。', '', '', '', 0),
(414, 'keypoint', '', 916, 0, 0, '前蜀改元天汉', 'qianshu', '十二月二十七日，蜀大赦，改次年为天汉元年，国号“大汉”。', '', '', '', 0),
(415, 'keypoint', '', 916, 0, 0, '闽铸铅钱', 'minguowang', '闽铸铅钱，与铜钱同时流通。', '', '', '', 0),
(416, 'keypoint', '', 916, 0, 0, '契丹称帝建元', 'liaoguo', '二月，契丹可汗阿保机称皇帝，国号契丹。辽太祖以良策治军，所部日见昌盛。仿效汉制，以妻述律平为后，备置百官。辽太祖野心更盛，“颇>有窥中国之志”。', '', '', '', 0),
(417, 'keypoint', '', 916, 0, 0, '契丹以韩延徽为相', 'liaoguo', '韩延徽原为刘守光参军。述律后贤之。契丹能威服诸国，延徽之力居多。后欲事晋王未果，复归契丹。阿保机称帝，即以延徽为相。庄宗之\r\n世，二国无大战，延徽亦有力焉。', '', '', '', 0),
(418, 'keypoint', '', 915, 0, 0, '', '', '', '', '', '', 0),
(419, 'keypoint', '', 915, 0, 0, '李存勖取魏博', 'houliang', '梁末帝欲对魏博行分而治之之策。魏州士卒不愿分徙进而，魏州军乱。张彦请罢昭德军未果，遂迫贺德伦求援于晋。李存勖杀张彦等。贺德伦>迎晋王入魏州军府，奉印节。', '', '', '', 0),
(420, 'keypoint', '', 915, 0, 0, '邠、宁叛岐', 'houliang', '先是岐静难节度使李继徽为其子彦鲁毒死，彦鲁自为留后。四月，继徽养子李保衡杀李彦鲁，以邠、宁二州地（今陕西彬县、宁县）叛岐附梁。梁以李保衡为感化节度使（今华州）。', '', '', '', 0),
(421, 'keypoint', '', 915, 0, 0, '徐温专吴政', 'yangwu', '八月，吴以镇海节度使徐温为管内水陆马步诸军都指挥使、两浙都招讨使、守侍中、齐国公，镇润州（今江苏镇江）。徐温留子徐知训于广陵秉吴>政，自己居外遥决军国大事如故。', '', '', '', 0),
(422, 'keypoint', '', 915, 0, 0, '后梁康王之乱', 'houliang', '十月，梁康王朱友敬（太祖第八子）以己目有重瞳，欲弑帝自立未果，被杀。末帝疏忌宗室，任租庸使赵岩及德妃兄弟张汉鼎、张汉杰等>人。敬翔、李振等言多不用，政事日紊。', '', '', '', 0),
(423, 'keypoint', '', 915, 0, 0, '后梁改元', 'houliang', '十一月初九，改乾化五年为贞明元年。', '', '', '', 0),
(424, 'keypoint', '', 915, 0, 0, '蜀略岐地', 'qianshu', '蜀以王宗绾、王宗播攻岐秦州（今甘肃秦安北）；王宗瑶、王宗翰攻岐凤州（今陕西凤县东北）。王宗绾取岐成州（今甘肃成县）。王宗铎取岐阶州（今甘肃武都东）。', '', '', '', 0),
(425, 'keypoint', '', 915, 0, 0, '岭南绝梁', 'houliang', '清海、建武节度使（驻邕州）兼中书令、南海王刘岩以钱镠已为吴越国王，乃上表于梁，求封南越国王，加都统，梁未允。自是不再入贡于梁。为日后自建国张本。', '', '', '', 0),
(426, 'keypoint', '', 915, 0, 0, '吴越兴修水利', 'wuyue', '钱镠以东南一隅之地，处干戈扰攘之际，以务农为先，为富境强兵。吴越设都水营田司，专掌水利之事，水利之法甚为完备。因此钱氏治吴越\r\n百年间，岁多丰稔，少有水患。', '', '', '', 0),
(427, 'keypoint', '', 915, 0, 0, '前蜀改元通正', 'qianshu', '十二月，前蜀改明年元曰“通正”。', '', '', '', 0),
(428, 'keypoint', '', 915, 0, 0, '刘岩迎娶于楚', 'nanhan', '八月，南海王刘岩迎娶于楚。楚王马殷遣永顺节度使马存送亲。先是，刘岩于乾化三年十月求婚于楚，马殷许以女妻之，至是两地成婚姻之好。', '', '', '', 0),
(429, 'keypoint', '', 915, 0, 0, '晋梁莘县之役', 'houliang', '李存勖得梁魏博，与梁将刘寻相峙于河北。战于莘县（今山东莘县），梁师大败，刘寻仅以数十骑逃免，晋围歼梁军七万人。', '', '', '', 0),
(430, 'keypoint', '', 915, 0, 0, '杨师厚卒', 'houliang', '三月，梁天雄军节度使、邺王杨师厚卒。后梁立国后因功封检校太保、同平章事。帅梁军东征西讨。末帝封之为邺王，倍受尊崇。其卒后，梁为抑>制强藩，酿成魏博军乱。', '', '', '', 0),
(431, 'keypoint', '', 914, 0, 0, '后梁调整节度使', 'houliang', '后梁调整节度使任命，康怀英改镇长安，韩洙继任朔方节度使。', '', '', '', 0),
(432, 'keypoint', '', 914, 0, 0, '南诏侵蜀', 'qianshu', '南诏入侵蜀地，遭夔王王宗范等三路击溃，溺毙数万于大渡河。', '', '', '', 0),
(433, 'keypoint', '', 914, 0, 0, '柴用再破刘崇景', 'yangwu', '吴袁州刺史刘崇景叛，附于楚。崇景，威之子也。楚将许贞将万人授之，吴都指挥使柴再用、米志诚帅诸将讨之。', '', '', '', 0),
(434, 'keypoint', '', 914, 0, 0, '谏阻水淹江陵', 'qianshu', '峡上有堰，或劝蜀主乘夏秋江涨，决之以灌江陵，毛文锡谏曰：“高季昌不服，其民何罪！陛下方以德怀天下，忍以邻国之民为鱼鳖食乎。”蜀主乃止。', '', '', '', 0),
(435, 'keypoint', '', 914, 0, 0, '王宗训被诛', 'qianshu', '前蜀诛杀擅归成都的节度使王宗训。蜀武泰节度使王宗训镇黔州，贪暴不法；擅还成都，庚辰，见蜀主，多所邀求，言辞狂悖。蜀主怒，命卫士殴杀之。', '', '', '', 0),
(436, 'keypoint', '', 914, 0, 0, '许德勋袭吴', 'nanchu', '楚将许德勋率水军奇袭吴国黄州，掳刺史而归。', '', '', '', 0),
(437, 'keypoint', '', 914, 0, 0, '王殷投吴国', 'houliang', '后梁徐州节度使王殷叛投吴国，遭牛存节讨伐。', '', '', '', 0),
(438, 'keypoint', '', 914, 0, 0, '李彦鲁弑父', 'houliang', '岐国李彦鲁弑父李继徽自立。', '', '', '', 0),
(439, 'keypoint', '', 914, 0, 0, '高季昌攻蜀', 'nanping', '荆南高季昌攻蜀夔州遭火攻反噬，兵败撤退。', '', '', '', 0),
(440, 'keypoint', '', 914, 0, 0, '李存勖攻克幽州', 'houliang', '李存勖攻克幽州后，处决刘仁恭、刘守光父子，以白绢缚俘献太庙，并受推举为尚书令，仿唐太宗旧制设行台。', '', '', '', 0),
(441, 'keypoint', '', 913, 0, 0, '李存勖亲征幽州', 'houliang', '年末，晋王李存勖亲征幽州，刘守光兵败逃亡，燕政权濒临崩溃。', '', '', '', 0),
(442, 'keypoint', '', 913, 0, 0, '晋国扩张', 'houliang', '晋（后唐前身）持续扩张，周德威率军攻占燕地顺州、安远军，幽州陷入孤立。契丹虽受燕主刘守光求援，但未予支>持。', '', '', '', 0),
(443, 'keypoint', '', 913, 0, 0, '后梁改元凤历', 'houliang', '正月二十，梁郢王朱友硅朝享太庙，二十一日祀天大赦，改元凤历。仅一月，被均王朱友贞联合禁军诛杀。朱友>贞继位为梁末帝，复称乾化年号。。', '', '', '', 0),
(444, 'keypoint', '', 913, 0, 0, '友贞诛友珪', 'houliang', '朱友贞、太祖之婿赵岩、外甥袁象先密谋诛郢王。袁象先率禁军突入洛阳宫中。朱友珪命廷谔先杀张氏，后杀己，>廷谔亦自刭。禁卫军大掠洛阳，袁象先、赵岩赴大梁迎朱友贞。', '', '', '', 0),
(445, 'keypoint', '', 913, 0, 0, '吴攻吴越衣锦军', 'yangwu', '三月，吴将李涛帅兵二万自干秋岭（今安徽宁国东南）攻吴越衣锦军（今浙江临安）。钱传瓘伐千秋岭之木断吴>军之后，大败吴军。后吴再次攻吴越，又被打败。', '', '', '', 0),
(446, 'keypoint', '', 913, 0, 0, '高季昌进爵', 'nanping', '八月，梁封荆南节度使高季昌为渤海王，势力膨胀。', '', '', '', 0),
(447, 'keypoint', '', 913, 0, 0, '梁侵吴淮寿', 'houliang', '梁以王景仁为淮南西北行营招讨使帅万余兵攻吴庐州（今安徽合肥），寿州（今安徽寿县）。吴徐温、朱瑾亲帅诸>将拒敌。战于霍丘（今安徽霍县），梁军大败。', '', '', '', 0),
(448, 'keypoint', '', 913, 0, 0, '王元膺被杀', 'qianshu', '前蜀太子王元膺因内斗被杀，王建改立王宗衍为太子，为日后亡国埋下隐患。王元膺与蜀高祖嬖臣唐\n道袭不和，唐道袭告太子谋反，被元膺攻杀。蜀高祖诛元膺及其同党。', '', '', '', 0),
(449, 'keypoint', '', 912, 0, 0, '洛阳兵变', 'houliang', '朱温晚年荒淫暴躁，与众儿媳均有乱伦关系。朱温病危，想立养子朱友文。友珪带兵进入宫中，杀死朱温，并矫诏令友贞杀友文，然后才为帝发丧>。即皇帝位。', '', '', '', 0),
(450, 'keypoint', '', 912, 0, 0, '梁废建昌宫使', 'houliang', '后梁设有建昌宫使，专掌天下金谷，以博王朱友文为之。六月，朱友硅篡位并杀博王，梁废建昌宫使，以张宗奭（全义）为国计使，替代原建昌宫。', '', '', '', 0),
(451, 'keypoint', '', 912, 0, 0, '荆南不再朝贡', 'nanping', '荆南节度使高季昌暗有窃据荆南之志。闰五月，高季昌扩建江陵，又声称助梁伐晋，出兵攻襄州（今湖北襄阳），为梁山南东\n道节度使孔勅击败。自此，荆南不再朝贡于梁。', '', '', '', 0),
(452, 'keypoint', '', 912, 0, 0, '义昌军乱', 'houliang', '先是，燕王刘守光以子继威为义昌节度使，治沧州。继威淫于都指挥使张万进家，万进怒杀继威，自称留后。三月，遣人分别请降于梁、晋。梁帝>以张万进为义昌节度使。', '', '', '', 0),
(453, 'keypoint', '', 912, 0, 0, '蜀平维州羌乱', 'qianshu', '四月，维州（今四川理县东北）羌胡董琢反，前蜀主王建派军讨平之。', '', '', '', 0),
(454, 'keypoint', '', 912, 0, 0, '徐温服诸将', 'yangwu', '徐温自由牙将而握淮南大政，原杨行密旧部多不服。徐温以李遇少子为人质，迫李遇降，使柴再用斩之，族其家。刘威、陶雅、李简等，不敢违徐>温之命。', '', '', '', 0),
(455, 'keypoint', '', 912, 0, 0, '杨师厚掌天雄军', 'houliang', '天雄军节度使（治魏州）罗周翰年纪幼小，军府事皆决于都指挥使潘晏。杨师厚执杀潘晏，引兵入魏博，朱友硅以杨师厚为天雄军节度使，迁罗周翰为宣义节度使（今河南滑县）。', '', '', '', 0),
(456, 'keypoint', '', 912, 0, 0, '朱友谦投晋', 'houliang', '郢王以韩京讨护国节度使冀王朱友谦（太祖养子）。友谦以河中附于晋以求救。晋王大破梁兵，友谦自至猗氏（今山西临猗）谢晋王。>后末帝立，友谦复称藩，然仍依附于晋。', '', '', '', 0),
(457, 'keypoint', '', 911, 0, 0, '', '', '加洛林王朝最后一位君主去世，东法兰克王国公爵们推举康拉德一世为国王，使东法兰克王国成为德意志民族发展基地，标志着德意志封建国家的形成开端。', '', '', '', 0),
(458, 'keypoint', '', 911, 0, 0, '柏乡之战', 'houliang', '朱温企图吞并成德、义武两镇，派王景仁率军进驻深、冀二州。成德节度使王镕识破其意图，联合义武王处直向李存勖求援。后梁战败，精锐兵力>损失惨重。', '', 'https://baike.baidu.com/item/柏乡之战/1031190', '', 0),
(459, 'keypoint', '', 910, 0, 0, '容、高二州附楚', 'nanhan', '宁远节度使（驻容州，今广西北流）庞巨昭、高州（今广东高州东北）防御使刘昌鲁二人皆唐官，唐亡后，刘隐据岭南，二州不附。请附于楚。马殷遂遣横州刺史姚彦章将兵迎之。', '', '', '', 0),
(460, 'keypoint', '', 911, 0, 0, '岭南刘隐卒', 'nanhan', '三月，清海、静海节度使、南海王刘隐病笃，上表后梁，以其弟节度使刘岩权知留后。刘隐性好贤士，此辈为其建立制度，多为南海重臣。弟岩建>南汉，尊隐为襄皇帝，庙号烈宗。', '', '', '', 0),
(461, 'keypoint', '', 911, 0, 0, '后梁改元乾化', 'houliang', '五月初一，后梁大赦，改开平五年为乾化元年。', '', '', '', 0),
(462, 'keypoint', '', 911, 0, 0, '刘守光称帝', 'houliang', '七月，燕王刘守光于幽州（今北京）即皇帝位，国号“大燕”。初刘守光囚父卢龙节度使刘仁恭自立，又杀兄守文，杀侄延祚。913年913年）被晋>王李存勖所灭杀。', '', '', '', 0),
(463, 'keypoint', '', 911, 0, 0, '岐蜀相攻', 'qianshu', '前蜀与岐接壤，岐王李茂贞常求财贷于蜀，蜀主王建均与之，以求保境息民。，岐王从子继崇妇、前蜀普慈公主归宁不返，岐、蜀遂绝交并交战。岐蜀交兵近一年，以蜀取胜告终。', '', '', '', 0),
(464, 'keypoint', '', 911, 0, 0, '刘岩取虔、韶', 'nanhan', '江西百胜军（今江西赣州）指挥使黎球杀镇南留后卢延昌自立，梁以黎球为虔州（今赣州）防御使。岭南清海节度使刘岩乘机发>兵取韶州（今广东韶关）。复取潮州、容州、高州。', '', '', '', 0),
(465, 'keypoint', '', 910, 0, 0, '', '', '阿斯图里亚斯王国分为阿斯图里亚斯、莱昂、加利西亚三国。', '', '', '', 0),
(466, 'keypoint', '', 910, 0, 0, '燕破沧州', 'houliang', '刘守光围攻沧州，沧州节度判官吕兖等推守文之子延柞为帅拒敌。正月刘延祚力尽出降。刘守光以幼子继威镇守沧州，派张万进、周知裕辅佐之。派人暗杀守文，归罪于杀者。', '', '', '', 0),
(467, 'keypoint', '', 910, 0, 0, '册封杨隆演', 'yangwu', '淮南节度使、弘农王杨隆演袭位，曾遣万全感往晋，岐告以嗣位。二月，万全感返回淮南。岐王李茂贞承制加杨隆演兼中书令、嗣吴王（唐昭宗曾封杨行密为吴王）。吴王大赦境内。', '', '', '', 0),
(468, 'keypoint', '', 910, 0, 0, '吴越取湖州', 'wuyue', '高彦、高澧父子相继为湖州（今浙江吴兴）刺史。高澧性凶忍，尝召州吏议曰：“吾欲尽杀百姓，可否？”钱镠以弟钱镖帅师讨之。三月，吴越王谬巡视湖州，以弟镖为刺史。', '', '', '', 0),
(469, 'keypoint', '', 910, 0, 0, '刘隐进封南海王', 'nanhan', '四月，梁加封南平王刘隐为南海王。', '', '', '', 0),
(470, 'keypoint', '', 910, 0, 0, '吴越乞留原宦官', 'wuyue', '初，朱全忠与崔胤悉诛宦官，并诏天下捕杀在外宦者，但有不少宦官为各镇藏匿，如河东监军张承业。诸镇僭越，拟用帝制，故以宦\n官为给事，尤以吴越为多，钱镠因有是请。', '', '', '', 0),
(471, 'keypoint', '', 910, 0, 0, '浙筑捍海塘', 'wuyue', '钱塘江海潮向为杭城之患，八月，吴越始筑杭州捍海石塘，至十月而成。钱氏又扩建杭州城，大修亭台楼馆、通衢巷陌，由是杭城富庶甲于东南。', '', '', '', 0),
(472, 'keypoint', '', 910, 0, 0, '后梁颁行新律令', 'houliang', '初后梁太常卿李燕、御史萧顷、中书舍人张衮等六人为首以一年时间刊定《梁律令格式》。于十二月十七日颁下施行。', '', '', '', 0),
(473, 'keypoint', '', 910, 0, 0, '前蜀改元永平', 'qianshu', '十二月二十五日，前蜀大赦，改明年元为永平元年。', '', '', '', 0),
(474, 'keypoint', '', 909, 0, 0, '后梁迁都洛阳', 'houliang', '正月，后梁自大梁迁都洛阳，以博王朱友文为东都（开封）留守。按：朱全忠初驻大梁，唐封之为梁王。既称帝，亦都大梁。今国朝不改而迁>都洛，则“梁”之为梁失其据矣。', '', '', '', 0),
(475, 'keypoint', '', 909, 0, 0, '百官全俸', 'houliang', '自唐末黄巢起义以后，时局动荡不已，百官俸料徒有其名，只存数额。正月二十九日，梁以国用稍为充足，开始给百官全额俸料。', '', '', '', 0),
(476, 'keypoint', '', 909, 0, 0, '后梁略取两镇', 'houliang', '太祖朱晃自至河中（今山西永济），发兵会合岐降将高万兴、万余兄弟共取岐之丹（今陕西宜川）、延（今陕西延安东）二州。鄜州都将严弘>倚举城降梁。', '', '', '', 0),
(477, 'keypoint', '', 909, 0, 0, '淮南初置选举', 'yangwu', '春，淮南节度使辖境内通过设置选举制度完善官僚体系。以骆知祥掌之。', '', '', '', 0),
(478, 'keypoint', '', 909, 0, 0, '梁封闽、粤王', 'houliang', '四月，梁进封威武军节度使王审知为闽王，清海、静海节度使刘隐为南平王。924年唐进封荆南高季兴为南平王，两“南平王”，不同时，亦不同\r\n地。', '', '', '', 0),
(479, 'keypoint', '', 909, 0, 0, '刘守光获封燕王', 'houliang', '五月，守文重赂契丹与吐谷浑，又倾其兵力合四万人于荆州（今河北蓟县），大败守光，守文未杀守光，反被守光部将元行钦所擒。向梁告>捷，梁以刘守光为燕王。', '', '', '', 0),
(480, 'keypoint', '', 909, 0, 0, '江西尽入淮南', 'yangwu', '八月，虔州（今江西赣县）刺史卢光稠亦附于淮南，至是江西之地尽入淮南杨氏。', '', '', '', 0),
(481, 'keypoint', '', 909, 0, 0, '蒙阬阻击战', 'houliang', '蒙阬（今山西曲沃北四十里）为晋、绛之间一大险隘，为历来军家胜败所系。二军既接，死伤甚巨，晋将肖万通战死，师厚进至晋州城下。晋军>攻晋州无功，只得引兵北还。', '', '', '', 0),
(482, 'keypoint', '', 909, 0, 0, '西汉金山国', 'houliang', '梁自汴徙都洛阳，张奉（即张承奉）以沙州乱。在敦煌建立西汉金山国，领瓜州、沙州两州。归义军节度使张淮鼎的幼子。张淮鼎死，托孤索勋>。索勋自立后被杀。', '', '', '', 0),
(483, 'keypoint', '', 909, 0, 0, '法蒂玛王朝建立', '', '法蒂玛王朝建立于公元909年，1171年灭亡，曾一度统治北非大部分地区和中东部分地区。', '', '', '', 0),
(484, 'keypoint', '', 908, 0, 0, '徐温弑杀杨渥', 'yangwu', '初徐温与张颢共领牙兵，杨行密死后，在兵变中架空嗣主杨渥。徐温弑杀杨渥而拥立杨隆演，随即又袭杀张颢，以左右牙都指挥使独掌吴国军政>大权。', '', '', '', 0),
(485, 'keypoint', '', 908, 0, 0, '王建镇压权臣', 'qianshu', '前蜀王建镇压权臣王宗佶强化集权，', '', '', '', 0),
(486, 'keypoint', '', 908, 0, 0, '李克用卒', 'houtang', '正月，河东节度使、晋王李克用卒。全忠篡唐，河东仍奉唐正朔。克用临卒，以三矢付其子存勖曰：“一矢讨刘仁恭，一矢击契丹>，一矢灭朱温，汝能成此三志，吾死无恨矣！”', '', '', '', 0),
(487, 'keypoint', '', 908, 0, 0, '李存勖袭晋王', 'houliang', '河东政权李存勖继晋王位后清除李克宁叛乱，启用周德威等将领重组军队；年末李存勖通过三垂冈战役奇袭后梁主力，扭转战略态势。', '', '', '', 0),
(488, 'keypoint', '', 908, 0, 0, '前蜀建元武成', 'qianshu', '正月初八，前蜀主王建祀南郊。初九，大赦，建元武成。', '', '', '', 0),
(489, 'keypoint', '', 908, 0, 0, '楚得澧朗二州', 'nanchu', '初梁削武贞节度使雷彦恭官爵，命荆、楚讨之。楚将秦彦晖破郎州，雷彦恭逃奔淮南，澧州亦降，朗、澧二州遂尽为楚所有。', '', '', '', 0),
(490, 'keypoint', '', 908, 0, 0, '淮南吴越争苏州', 'yangwu', '九月，淮南遣将周本、吕师造攻吴越围苏州。吴越钱镠派弟钱镖及大将张仁保攻拔太湖之滨东洲，淮南兵损失万余人。909年，又大败淮南军，\r\n苏州仍归吴越所有。', '', '', '', 0),
(491, 'keypoint', '', 906, 0, 0, '王茂章叛附钱镠', 'tang', 'yangwu', '初，杨行密子杨渥离宣州，欲取其幄幕及亲兵同行，观察使王茂章不许。渥既袭位，遣李简将兵攻茂章。茂章度不能守，帅众奔两浙>。', '', '', 0),
(492, 'keypoint', '', 906, 0, 0, '魏博罗绍威自屠牙兵', 'tang', '魏博牙军自田承嗣以来父子相继，骄横难制。天雄节度使罗绍威厌且畏之，求朱全忠以诛讨。朱全忠入魏（今河北大名北），诱杀天雄牙兵>八千家，罗绍威供应巨亿。', '', '', '', 0),
(493, 'keypoint', '', 906, 0, 0, '杨渥攻湖南', 'yangwu', '三月，淮南节度使杨渥遣将陈知新攻湖南。知新拔岳州（今湖南岳阳），逐刺史许德勋，渥即以知新为岳州刺史。', '', '', '', 0),
(494, 'keypoint', '', 906, 0, 0, '朱全忠不受三司使', 'tang', '三月二十五日，诏以朱全忠为盐铁、度支、户部三司都制置使。三司之名始于此。全忠辞不受。', '', '', '', 0),
(495, 'keypoint', '', 906, 0, 0, '镇南军钟传卒', 'tang', '四月，唐南平郡王、镇南军（今江西南昌）节度使钟传卒。钟传据洪州（今江西南昌），盘据江西达三十年，官至中书令。', '', '', '', 0),
(496, 'keypoint', '', 906, 0, 0, '杨渥取江西', 'tang', '镇南节度使钟传以养子延规为江州（今江西九江）刺史。传卒，军中立其子匡时为留后。延规降淮南。淮南节度使杨渥以升州刺史秦裴将兵取江西。秦裴攻拔洪州，虏钟匡时。', '', '', '', 0),
(497, 'keypoint', '', 906, 0, 0, '复忠义军', 'tang', '五月，废戍昭军，并均（今湖北均县西北）、房（今湖北房县）二州隶忠义军；以武定节度使冯行袭为匡国节度使。六月，复以忠义军为山南东道。', '', '', '', 0),
(498, 'keypoint', '', 906, 0, 0, '朱全忠攻沧州', 'tang', '幽州（今北京）刘仁恭及沧州（今河北沧州东南）刘守文父子威胁魏博，朱全忠攻沧州。仁恭求救于河东。李克用遣周德威、李嗣昭攻取潞州（今山西长治）。全忠撤军。', '', '', '', 0),
(499, 'keypoint', '', 906, 0, 0, '钱镠取衢州', 'tang', '八月，钱镠遣方永珍进围衢州（今浙江衢县），刺史陈璋告急于淮南，杨渥遣将周本以兵迎璋。浙兵遂取衢州。婺（今浙江金华）、睦（今浙江建德>）、衢三州悉归于钱镠。', '', '', '', 0),
(500, 'keypoint', '', 906, 0, 0, '朱全忠败杨崇本', 'tang', '九月，静难节度使杨崇本攻夏州（今内蒙古乌审旗南白城子），全忠遣刘知俊及其将康怀贞往救，大破杨崇本军。邠、岐两军自是不振。', '', '', '', 0),
(501, 'keypoint', '', 906, 0, 0, '蜀王建立行台', 'tang', '十月六日，蜀王王建始立行台于成都，称自昭宗迁洛，制命不通，权立行台，承制封拜。乃以榜帖告谕所属藩镇州县。', '', '', '', 0),
(502, 'keypoint', '', 906, 0, 0, '高季昌进荆南', 'tang', '武贞节度使雷彦威屡寇荆南（今湖北江陵），留后贺环闭城自守。朱全忠以颍川防御使高季昌代为留后，雷彦威引兵退去。此为来日高季昌据有荆南（南平）张本。', '', '', '', 0),
(503, 'keypoint', '', 906, 0, 0, '彭玕降湖南', 'tang', '十二月，钟传旧将、吉州刺史彭玕遣使请降于湖南。玕乃江西土著蛮酋，钟氏既亡，故请降于马殷。', '', '', '', 0),
(504, 'keypoint', '', 906, 0, 0, '阿保机为契丹主', 'liaoguo', '契丹迭刺部酋领阿保机，降附其四周诸部落。虏掠大量人民及财产，势力逐渐强大。十二月，契丹主痕德堇可汗卒，阿保机成为契丹主，且不受诸部之代，自称国王。', '', '', '', 0),
(505, 'keypoint', '', 905, 0, 0, '', 'tang', '学士韩偓为避朱全忠迫害，率族南迁依附福建威武军节度使王审知。', '', '', '', 0),
(506, 'keypoint', '', 905, 0, 0, '杨行密平安仁义', 'tang', '杨行密部将、润州团练使安仁义据城叛，其人深得众心。王茂章久围润州（今江苏镇江），擒仁义，斩之。淮南三将田君、朱延寿、安仁义叛乱>，至此始完全平定。', '', '', '', 0),
(507, 'keypoint', '', 905, 0, 0, '王师范徙河阳', 'tang', '正月，朱全忠命李振知青州（今山东益都）事，代王师范。李振至青州，师范举族素服乘驴至大梁（今河南开封）。三月，以王师范为河阳节度使>（今河南孟县）。', '', '', '', 0),
(508, 'keypoint', '', 905, 0, 0, '朱全忠诛杀皇子', 'tang', '二月九日，朱全忠使蒋玄晖邀昭宗诸子德王裕等九人，置酒九曲池，酒酣，悉缢杀之，投尸池中。', '', '', '', 0),
(509, 'keypoint', '', 905, 0, 0, '杨行密取鄂州', 'tang', '杨行密平定内乱后，正月败两浙兵于睦州（今浙江建德东）。解朱全忠寿州之围。淮南将刘存攻拔鄂州（今湖北武汉）城，斩首杜洪、延柞及汴兵>。以刘存为鄂岳观察使。', '', '', '', 0),
(510, 'keypoint', '', 905, 0, 0, '朱全忠逐杀朝士', 'tang', '柳璨、李振劝朱全忠尽去朝士以塞灾异。朱全忠旋聚裴枢等及朝士被贬者三十余人于白马驿（今河南滑县境），一夕尽杀之，投尸于河。', '', '', '', 0),
(511, 'keypoint', '', 905, 0, 0, '朱全忠掠地', 'tang', '朱全忠遣武宁节度使杨师厚攻取山南东道节度使赵匡凝。荆南节度使赵匡明弃城奔成都。荆南牙将王建武遣使降。以贺环为荆南留后，杨师厚为山南>东道节度使（今湖北襄阳）。', '', '', '', 0),
(512, 'keypoint', '', 905, 0, 0, '王建取金州', 'tang', '初蜀将王宗贺等攻冯行袭，所向皆捷。905年九月，行袭弃金州（今陕西安康），东奔归附朱全忠，其将全师朗以城降。王建改师朗姓名曰王宗朗，补\r\n金州观察使。', '', '', '', 0),
(513, 'keypoint', '', 905, 0, 0, '杨吴吴越争战', 'tang', '杨吴西南招讨使陶雅和吴越钱镠弟钱镖围绕睦州（今浙江建德东）、婺州（今浙江金华）、衢（今浙江衢县），展开一些列的战争。', '', '', '', 0),
(514, 'keypoint', '', 905, 0, 0, '杨行密卒', 'tang', '九月，杨行密寝疾。十月，行密承制以渥为淮南留后。十一月二十六日，杨行密卒。死后不久其子杨渥称王。后追尊为太祖武皇帝。', '', '', '', 0),
(515, 'keypoint', '', 905, 0, 0, '朱全忠攻光、寿', 'tang', '朱全忠取荆、襄二镇后，拓地千里，欲乘胜击淮南。十月，大军逾淮进抵光州（今河南潢川）。光州刺史柴再用严守。全忠又进围寿州（今安徽>寿县），无果乃渡淮北返。', '', '', '', 0),
(516, 'keypoint', '', 905, 0, 0, '朱全忠杀蒋玄晖', 'tang', '十一月，朱全忠急于称帝，密使蒋玄晖、柳璨议传禅。玄晖认为应先封全忠为魏王，加九锡，再禅让。全忠怒其滞缓，故让九锡不受。不久，杀>蒋玄晖、柳璨。', '', '', '', 0),
(517, 'keypoint', '', 905, 0, 0, '张承奉自立', 'tang', '唐沙州（今甘肃敦煌）归义军节度使张承奉已自立，称白衣天子，号西汉金山国。', '', '', '', 0),
(518, 'keypoint', '', 904, 0, 0, '', 'tang', '岭南刘隐通过贿赂获得节度使职位。', '', '', '', 0),
(519, 'keypoint', '', 904, 0, 0, '', 'tang', '朱全忠（朱温）通过武力控制朝政，导致唐朝统治名存实亡。朱全忠全面掌控禁军与朝政，任命亲信把持要职，并诛杀昭宗近侍以隔绝内外联系。', '', '', '', 0),
(520, 'keypoint', '', 904, 0, 0, '迁都洛阳', 'tang', '正月，朱全忠请昭宗迁都洛阳。宰相裴枢促百官东行，并驱徙士民。因东都宫室缮修未成，暂驻陕州（今河南三门峡）。何后泣曰：“自今大家（指皇上）夫妇委身全忠矣！”', '', '', '', 0),
(521, 'keypoint', '', 904, 0, 0, '以长安为佑国军', 'tang', '昭宗既被迫东迁，长安已成空城。三月，诏以朱全忠兼判左、右神策及六军诸卫事。全忠奏以长安为佑国军，以韩建为佑国军节度使，以郑州刺>史刘知俊为匡国留后。', '', '', '', 0),
(522, 'keypoint', '', 904, 0, 0, '昭宗密诏诸镇', 'tang', '昭宗被迫东迂，二、三月间屡遣间使以御札、绢诏告难于藩镇王建、李克用、杨行密等，令纠合诸镇兵攻朱全忠，以图匡复。各藩镇志在扩土，并>无勤王之兵。', '', '', '', 0),
(523, 'keypoint', '', 904, 0, 0, '昭宗至东都', 'tang', '朱全忠威逼昭宗搬往洛阳。帝左右职掌使令皆全忠之人。闰四月十日，车驾至洛阳，御正殿，受朝贺。十一日，赦天下，改元天祐，以天复四年为天>祐元年。', '', '', '', 0),
(524, 'keypoint', '', 904, 0, 0, '东都封授官爵', 'tang', '昭宗在东都封授内外官爵。内外诸使诸将皆朱全忠心腹。诏以张全义为天平节度使；朱全忠为护国、宣武、宣义、忠武四镇节度使。钱镠为吴王。>进天雄节度使罗绍威爵为邺王。', '', '', '', 0),
(525, 'keypoint', '', 904, 0, 0, '诸镇讨朱全忠', 'tang', '李茂贞、王建、李继徽（杨崇本）传檄合兵以讨朱全忠，全忠率大军西讨。时李克用、刘仁恭、杨行密、赵匡凝杨崇和李茂贞等移檄往来，皆以匡>复为辞，若讨朱全忠。', '', '', '', 0),
(526, 'keypoint', '', 904, 0, 0, '朱全忠弑昭宗', 'tang', '朱全忠欲立幼君，以谋禅代。蒋玄晖派牙将史太夜入宫弑昭宗。立辉王祚为皇太子，更名柷，是为哀帝。全忠杀朱友恭、氏叔琮。以张全义为河南>尹兼忠武节度使，领宿卫。', '', '', '', 0),
(527, 'keypoint', '', 904, 0, 0, '朱全忠掠淮南', 'tang', '十月，光州（今河南潢川）叛淮南，降朱全忠。杨行密遣兵围城。朱全忠屯军霍丘（今安徽），并分兵救鄂州（今湖北武昌）杜洪。杨行密回广陵>（今江苏扬州）。全忠大掠淮南。', '', '', '', 0),
(528, 'keypoint', '', 903, 0, 0, '王师范讨朱温', 'tang', '淄青节度使王师范起兵讨伐权臣朱全忠。韩全诲以诏书征藩镇兵入援乘舆，师范泣下沾衿。', '', '', '', 0),
(529, 'keypoint', '', 903, 0, 0, '李茂贞初诛宦官', 'tang', '李茂贞请昭宗诛宦官\"四贵\"，以便与朱全忠连和，奉车驾还京。昭宗喜，即遣凤翔卒收中尉韩全诲、张彦弘、枢密使袁易简、周敬容四人，斩其>首。', '', '', '', 0),
(530, 'keypoint', '', 903, 0, 0, '凤翔解围', 'tang', '李茂贞卑辞致书请崔胤率百官赴行在。凤翔启城门将放唐昭宗出城，茂贞复请昭宗女平原公主嫁其子李侃。车驾出凤翔幸全忠营，二十七日入长安。帝>被胁出奔半年，至是始返。', '', '', '', 0),
(531, 'keypoint', '', 903, 0, 0, '朱全忠尽诛宦官', 'tang', '昭宗还长安，胤奏请根除宦官祸害，悉罢诸司使，罢诸道监军。朱全忠以兵驱宦官第五可范等数百人于内侍省，尽杀之，出使监军在外者，诏所>在收捕诛杀。', '', '', '', 0),
(532, 'keypoint', '', 903, 0, 0, '崔胤专权', 'tang', '时宰相崔胤恃朱全忠势专权，朝廷诏书独无凤翔，宰相陆扆有异议，崔胤奏贬之。翰林学士韩偓荐御史大夫赵崇、兵部侍郎王赞为相，崔胤连同朱全忠，迫昭宗贬韩偓濮州司马。', '', '', '', 0),
(533, 'keypoint', '', 903, 0, 0, '朱全忠进爵梁王', 'tang', '昭宗以皇子为兵马元帅，全忠为副元帅。崔胤承全忠密旨，以幼童李祚充元帅。加全忠守太尉、进爵梁王。以胤为司徒兼侍中。又以朱全忠判元帅府事，天下兵马尽归其统辖。', '', '', '', 0),
(534, 'keypoint', '', 903, 0, 0, '朱全忠辞归镇', 'tang', '汴将朱友裕为镇国节度使；朱友论为左军宿卫都指挥使，汴将张廷范为宫苑使、王殷为皇城使、蒋玄晖充街使。全忠之党遍布禁卫及京辅，全忠辞归大梁。昭宗饯行。', '', '', '', 0),
(535, 'keypoint', '', 903, 0, 0, '王师范拒朱全忠', 'tang', '三月，朱全忠至大梁（今河南开封）调集大军进攻淄青王师范。王师范求救于淮南，淮南兵合淄青兵攻拔密州（今山东诸城）。朱全忠大破淄青>、淮南兵，收复密州。', '', '', '', 0),
(536, 'keypoint', '', 903, 0, 0, '杨行密攻鄂', 'tang', '杨行密遣李神福围鄂州（今湖北武昌）杜洪。全忠遣将韩京救援，又请荆南节度使成汭、武安节度使马殷、武贞节度使雷彦威救洪。马殷、雷彦威袭>江陵，成汭赴水死。韩京引兵还。', '', '', '', 0),
(537, 'keypoint', '', 903, 0, 0, '李茂贞辞尚书令', 'tang', '朱全忠守中书令。李茂贞为尚书令，官在全忠上。茂贞畏朱全忠之强，居官不敢在全忠上，累表乞辞尚书令。天复三年（903）五月，诏复以李茂贞为中书令。', '', '', '', 0),
(538, 'keypoint', '', 903, 0, 0, '云州叛晋', 'tang', '五月，李克用所署云州（今山西大同）都将王敬晖杀刺史刘再立，叛降刘仁恭。李克用遣李嗣昭、李存审讨击。敬晖乘晋军退走弃城而逃。克用怒嗣昭、存审失王敬晖，削其官。', '', '', '', 0),
(539, 'keypoint', '', 903, 0, 0, '崔胤募禁卫兵', 'tang', '五月，崔胤奏请募兵。诏命京兆尹郑元规立格召兵于市。朱全忠自此疑崔胤。汴将朱友伦击球坠马而卒。崔胤畏全忠，解释募兵为>防李茂贞。全忠暗中使人应募以察其变。', '', '', '', 0),
(540, 'keypoint', '', 903, 0, 0, '王建进爵蜀王', 'tang', '八月十三日，诏加西川节度使、西平郡王王建守司徒，进爵蜀王。', '', '', '', 0),
(541, 'keypoint', '', 903, 0, 0, '杨行密三将叛变', 'tang', '杨行密部将宁国节度使田君与润州团练使安仁义居功不满，八月同举兵反。田君约奉国节度使朱延寿同叛。行密用计执斩延寿。淮南将李神福、>台濛斩杀田君。王茂章攻润州无果。', '', '', '', 0),
(542, 'keypoint', '', 903, 0, 0, '王师范降于朱温', 'tang', '九月，王师范求降于朱全忠，称韩全诲、李茂贞以朱书御札使之举兵。淄青行军司马刘寻亦以兖州降于汴将葛从周，朱全忠表为保大军（驻节鄜州，今陕西富县）留后，以拒李茂贞。', '', '', '', 0),
(543, 'keypoint', '', 903, 0, 0, '王建掠地', 'tang', '王建以宗本为开道都指挥使，将兵东下三峡。夔州（今四川奉节）刺史侯矩因成汭死，以州降宗本。蜀遂平定夔、忠（今四川忠县）、万（今四川万县>）、施（今湖北恩施）四州之地。', '', '', '', 0),
(544, 'keypoint', '', 903, 0, 0, '契丹建开教寺', 'tang', '七月，阿保机率众攻掠河东代北诸郡，虏获甚丰。九月，阿保机于潢河（今西辽河支流黄水）之南建龙化州，并在城内建开教寺，此为契丹信佛教>之始。', '', '', '', 0),
(545, 'keypoint', '', 903, 0, 0, '赵匡凝袭荆南', 'tang', '成汭败死，荆南节镇无主。十月，山南东道节度使赵匡凝袭荆南（今湖北江陵），逐雷彦威，据江陵。匡凝表其弟匡明为荆南留后。时诸道贡赋多>不上供，唯匡明兄弟委输不绝。', '', '', '', 0),
(546, 'keypoint', '', 903, 0, 0, '朱温杀张浚', 'tang', '致仕宰相张浚曾策动王师范举兵反朱全忠。令河南尹张全义杀浚。朱全忠胁昭宗迁都洛阳，浚即知其将行篡弑，致被全忠杀害，其家百余人并遭难。>子格逃至荆南而入蜀。', '', '', '', 0),
(547, 'keypoint', '', 903, 0, 0, '刘仁恭挫契丹', 'tang', '卢龙节度使刘仁恭知契丹虚实，常深入塞外讨击，焚塞下野草，使契丹马多饿死。十二月，契丹阿保机遣其妻兄阿钵入寇，刘守光佯与之和，设伏>擒之，后阿保机以重赂赎回。', '', '', '', 0),
(548, 'keypoint', '', 903, 0, 0, '日僧能光入蜀', 'tang', '洞山良价弟子瓦室和尚能光（日本国人）入蜀，永泰军节度使鹿虔扆舍宅为禅院，俾能光居之。', '', '', '', 0),
(549, 'keypoint', '', 903, 0, 0, '朱全忠杀崔胤', 'tang', '正月，密表崔胤专权乱国，并其党六军诸卫副使郑元规、威远军使陈班等，皆请诛之，诏贬胤等；解散胤所募兵；以崔远、柳璨为宰相。全忠密令>朱友谅诛杀胤及郑元规、陈班等。', '', '', '', 0),
(550, 'keypoint', '', 902, 0, 0, '李克用攻河中', 'tang', '朱全忠大军在关中，正月，李克用遣将李嗣昭、周德威攻河中，以分全忠兵势。时李茂贞在凤翔坚守不出战，全忠有后顾之忧，二月，还军河中。', '', '', '', 0),
(551, 'keypoint', '', 902, 0, 0, '朱全忠攻河东', 'tang', '三月，汴将氏叔琮、朱友宁乘胜进攻河东将李嗣昭、周德威营。汴军收复慈（今山西吉县）、隰（今山西隰县）、汾（今山西汾阳）三州，进围晋>阳。', '', '', '', 0),
(552, 'keypoint', '', 902, 0, 0, '朱全忠兵围晋阳', 'tang', '三月，汴军围晋阳（今山西太原），氏叔琮攻城甚急，李克用欲弃城北走云中，诸将劝止。会大疫，氏叔琮引兵还。自是李克用不敢与朱全忠争>者累年。', '', '', '', 0),
(553, 'keypoint', '', 902, 0, 0, '朱全忠二度入关', 'tang', '三月，朱全忠还河中，遣朱友宁将兵西击李茂贞。四月，崔胤至河中（今山西永济），请朱全忠速迎大驾，以免李茂贞劫帝幸蜀。', '', '', '', 0),
(554, 'keypoint', '', 902, 0, 0, '大封地方官吏', 'tang', '昭宗在凤翔遣使拜杨行密为东面行营都统、中书令，封吴王。又加朱瑾为平卢节度使、冯弘铎为武宁节度使、朱延寿为奉国节度使，加武安节度使>马殷使相，令即日起兵勤王。', '', '', '', 0),
(555, 'keypoint', '', 902, 0, 0, '回鹘遣使入贡', 'tang', '四月辛丑，回鹘遣使入贡，兼请发兵勤王赴难。昭宗命翰林学士承旨答书许之，韩偓恐外族乘危入侵，以为不可，遂沮其议。', '', '', '', 0),
(556, 'keypoint', '', 902, 0, 0, '钱镠进封越王', 'tang', '昭宗征兵淮浙，天复二年（902）五月，诏镇海、镇东节度使彭城郡王钱镠进封越王。', '', '', '', 0),
(557, 'keypoint', '', 902, 0, 0, '杨行密收升州', 'tang', '武宁节度使冯弘铎驻节升州（今江苏南京）。六月，宁国节度使田君募升州船工造战舰，弘铎举兵袭宣州，被田君击破。弘铎被杨行密招抚，行密>遂以李神福为升州刺史。', '', '', '', 0),
(558, 'keypoint', '', 902, 0, 0, '杨行密讨朱温', 'tang', '六月，淮南节度使杨行密发兵讨朱全忠，军至宿州（今安徽宿县），运河航道重载不能进，都知兵马使徐温建议用小艇。行密由是倚重温。攻宿州>不克，以粮运不济，引还。', '', '', '', 0),
(559, 'keypoint', '', 902, 0, 0, '韦贻范复相', 'tang', '时昭宗在凤翔，有君无相；宰相百官在华州，有相无君，宦官与藩帅李茂贞欲以韦贻范为宰相。韩偓拒草复韦贻范宰相制。昭宗赐诏褒赏韩偓。姚洎>草制，贻范仍复相。', '', '', '', 0),
(560, 'keypoint', '', 902, 0, 0, '杭州军乱', 'tang', '钱镠多招孙儒淮西散卒为兵，号武勇都。七月，武勇右都指挥使徐绾起兵反，左都指挥使许再思与之合，进逼杭州牙城，并引宣州田君（杨行密将）兵>围杭州。', '', '', '', 0),
(561, 'keypoint', '', 902, 0, 0, '王建并山南西道', 'tang', '西川节度使王建借口勤王，请假道于兴元（今陕西汉中），李茂贞所署山南西道节度使李继密拒之。王宗涤克兴元。建并有山南西道。', '', '', '', 0),
(562, 'keypoint', '', 902, 0, 0, '王建杀王宗涤', 'tang', '山南西道节度使王宗涤本名华洪，王建养子，官邛州刺史。有勇略，得众心，王建深忌之，被缢杀。王建乃以指挥使王宗贺权任兴元（今陕西汉中>）留后。', '', '', '', 0),
(563, 'keypoint', '', 902, 0, 0, '李茂贞请和', 'tang', '朱全忠以计诱李茂贞出战。凤翔军连败，李茂勋请降于全忠。于是茂贞山南州镇皆入王建，关中州镇皆入全忠，茂贞坐守孤城，乃密谋诛宦官自赎，致书朱全忠请和，全忠准允。', '', '', '', 0),
(564, 'keypoint', '', 902, 0, 0, '淮南建制敕院', 'tang', '朝廷使者李俨至扬州，征杨行密兵以讨朱全忠。杨行密始建制敕院，每有封拜，辄以告俨，于紫极宫唐玄宗像前陈制书，再拜然后下，以示对李唐>王朝忠心不二。', '', '', '', 0),
(565, 'keypoint', '', 902, 0, 0, '昭宗窃见学士', 'tang', '昭宗在凤翔受到宦官的严密监视。昭宗使赵国夫人趁学士院宦官二使不在，急召翰林学士韩偓、姚洎，执手相泣。姚洎恐为宦官发现，劝昭宗速还>，昭宗遽去。', '', '', '', 0),
(566, 'keypoint', '', 902, 0, 0, '卢光稠攻岭南', 'tang', '虔州（今江西赣州）刺史卢光稠攻岭南，陷韶州（今广东韶关），进围潮州。清海节度使刘隐发兵击走之，进夺韶州。卢光稠及其部将谭全播遂设>伏大破刘隐军，隐奔还广州。', '', '', '', 0),
(567, 'keypoint', '', 902, 0, 0, '道膺禅师卒', 'tang', '云居道膺初受具于范阳延寿寺，本师令习经律，叹曰：“大丈夫岂可桎梏于经律”，乃去更受法洞山良价。说法三十年，徒众常至千五百之数。其禅学>传承对佛教发展产生重要影响。', '', '', '', 0),
(568, 'keypoint', '', 901, 0, 0, '昭宗复辟', 'tang', '王正月一日，仲先入朝，至安福门，被孙德昭伏兵擒斩。崔胤率百官迎昭宗复位。周承海擒刘季述、王彦范等，二人被乱棍打死，诏灭两中尉、两枢密>之族，废太子为德王。', '', '', '', 0),
(569, 'keypoint', '', 901, 0, 0, '宦官不得干政', 'tang', '昭宗下敕：近年宰臣延英奏事，枢密使侍立傍侧，参预议政，致使争论纷然。今重申宣宗大中旧制，枢密使须待宰臣奏事毕，方得升延英殿承受公>事，以使宦官不得干预朝政。', '', '', '', 0),
(570, 'keypoint', '', 901, 0, 0, '李茂贞加官', 'tang', '凤翔、彰义节度使李茂贞入京朝见昭宗，诏加茂贞守尚书令，兼侍中，进爵岐王。太宗之后二百多年不复授人。今以授李茂贞，正见唐朝王纲不振，>法制荡然。。', '', '', '', 0),
(571, 'keypoint', '', 901, 0, 0, '任命中尉枢密', 'tang', '宰相崔胤、陆扆上言，请罢宦官典兵，由胤掌左军，扆掌右军。诏以前凤翔监军韩全诲及现任凤翔监军张彦弘为左、右神策军中尉。以袁易简，周>敬容为枢密使。', '', '', '', 0),
(572, 'keypoint', '', 901, 0, 0, '李茂贞留兵', 'tang', '正月，李茂贞辞还镇，宰相崔胤请茂贞留兵三千于京师充宿卫，左谏议大夫韩偃以为留此兵则家国两危，不留则家国两安，胤不从。是年李继筠终与宦官劫昭宗幸凤翔。', '', '', '', 0),
(573, 'keypoint', '', 901, 0, 0, '朱全忠取河中', 'tang', '朱全忠既羁服河北，欲再取河中（今山西永济）以制河乐。汴将张存敬引兵围河中，河中护国节度使王珂请降。全忠送王珂入朝，遣人杀之于路。', '', '', '', 0),
(574, 'keypoint', '', 901, 0, 0, '李克用修好朱全忠', 'tang', '朱全忠大军在晋，准备进攻李克用。朝廷急赐诏令晋、汴和解，李克用以重币向朱全忠修好。会全忠妻张夫人疾急，乃自河中（今山西永济）>东归。', '', '', '', 0),
(575, 'keypoint', '', 901, 0, 0, '昭宗命相', 'tang', '昭宗以户部侍郎王溥和吏部侍郎裴枢同平章事；又加幽州节度使刘仁恭、魏博节度使罗绍威并兼侍中为使相。加镇海、镇东节度使钱镠守侍>中；佑国节度使张全义兼中书令。', '', '', '', 0),
(576, 'keypoint', '', 901, 0, 0, '朱全忠攻河东', 'tang', '朱全忠以氏叔琮为主力发兵六路大举攻李克用。连下四州。攻晋阳（今山西太原）时全忠乃召兵还。朱全忠遣丁会守潞州，以遏河东兵。', '', '', '', 0),
(577, 'keypoint', '', 901, 0, 0, '朱全忠领四镇', 'tang', '朱全忠奏请朝廷再加已河中节度使。诏以全忠为宣武、宣义、天平、护国四镇节度使，是地最大、兵最多的藩镇。河中上可制朝廷，下可制李克用>。', '', '', '', 0),
(578, 'keypoint', '', 901, 0, 0, '改元昭雪', 'tang', '四月，昭宗谒太庙，赦天下，改元，以光化四年为天复元年。宰相崔胤等议诛宦官，昭雪835年甘露之变时被宦官杀害的宰相王涯等十七家。', '', '', '', 0),
(579, 'keypoint', '', 901, 0, 0, '罢神策军卖酒曲', 'tang', '先是杨复恭为中尉，借度支卖酒曲一年之利以赡两军。崔胤欲抑宦官，故罢左右神策军卖酒曲。凤翔节度使李茂贞与左军中尉韩全诲相结反对。>崔胤则拉拢与朱全忠。', '', '', '', 0),
(580, 'keypoint', '', 901, 0, 0, '李克用取隰、慈', 'tang', '六月，李克用遣李嗣昭、周德威趁朱全忠退兵之机，收复失地。攻隰州（今山西隰县），刺史唐礼投降；攻慈州，刺史张环又降。', '', '', '', 0),
(581, 'keypoint', '', 901, 0, 0, '道士起事', 'tang', '道士杜从法以迷信煽动昌（今四川大足）、普（今四川安岳）、合（今四川合川）三州民起事。王建遣行营兵马使王宗黯会东川、武信兵攻讨。七月，杜从法及其众皆被镇压。', '', '', '', 0),
(582, 'keypoint', '', 901, 0, 0, '痕德堇可汗立', 'tang', '契丹痕德堇可汗以契丹迭刺部酋长耶律阿保机为本部夷离堇，专征讨。是年连破室韦、于厥、奚等部族，俘获甚众。十月，痕德堇可汗授阿保机大>迭烈府夷离堇。', '', '', '', 0),
(583, 'keypoint', '', 901, 0, 0, '崔胤折抑宦官', 'tang', '昭宗复辟后，悉以军国事委宰相崔胤，胤请帝尽诛宦官。左军中尉韩全诲等谋划去胤。崔胤遗书朱全忠，令全忠迎车驾幸东都。时李茂贞欲帝幸凤翔。', '', '', '', 0),
(584, 'keypoint', '', 901, 0, 0, '杨行密攻杭州', 'tang', '谣传钱镠为盗所杀，杨行密遣李神福攻杭州，两浙将顾全武列八寨以拒。后李神福知钱镠不死，而杭州城坚，乃遣人守卫镠祖考墓，镠遣使谢，神>福受镠犒赂而还军。', '', '', '', 0),
(585, 'keypoint', '', 901, 0, 0, '朱全忠入关', 'tang', '十月，朱全忠大举发兵入关。士民亡窜山谷，百官皆不敢入朝。全忠至长安，宰相率百官列队迎于长乐坡。', '', '', '', 0),
(586, 'keypoint', '', 901, 0, 0, '复许宦官延英议政', 'tang', '宦官首领左神策军中尉韩全诲胁昭宗入阁召百官，追废不许宦官参预宰臣延英奏对之敕。先是，咸通以来，例准宦官两军中尉、两枢密预延英>奏对，位同宰相。', '', '', '', 0),
(587, 'keypoint', '', 901, 0, 0, '宦官劫驾', 'tang', '朱全忠举兵入关中，全诲令凤翔将李继筠与禁军都将李彦弼等勒兵劫昭宗幸凤翔。因宰相百官不从，权以兵部侍郎卢光启参知机务。', '', '', '', 0),
(588, 'keypoint', '', 901, 0, 0, '朱全忠追驾', 'tang', '唐昭宗被劫至凤翔，朱全忠追至凤翔。后移兵北取邠州（今陕西彬县）。静难节度使李继徽（杨崇本）请降。戎昭节度使冯行袭尽杀韩全诲中使，王建声言迎车驾意在山南诸州。', '', '', '', 0),
(589, 'keypoint', '', 901, 0, 0, '刘隐为广州留后', 'tang', '十一月，广州清海节度使徐彦若卒，遗表荐行军司马刘隐权知留后，刘隐始得广州。', '', '', '', 0),
(590, 'keypoint', '', 901, 0, 0, '钟传围抚州', 'tang', '十二月，江西节度使钟传将兵围抚州（今江西临川），天火（雷击）烧其城，诸将请急攻，传制止，曰：“乘人之危，非仁也。”。刺史危全讽谢罪听>命，以女妻传子匡时。', '', '', '', 0),
(591, 'keypoint', '', 901, 0, 0, '曹松进士及第', 'tang', '及第时年已七十余岁，特授校书郎。工诗，诗作有《己亥岁暮》等，有《曹松诗集》传世。', '', '', '', 0),
(592, 'keypoint', '', 901, 0, 0, '吴融任户部侍郎', 'tang', '889年进士，官终翰林学士承旨。诗作有《金桥感事》等。有《唐英歌诗》。', '', '', '', 0),
(593, 'keypoint', '', 901, 0, 0, '刁光胤入蜀', 'tang', '唐末画家，长安人，居蜀三十多年，八十余岁死。作画甚勤，\"非病不休，非老不息\"。为寺院作壁画甚多。黄筌、孔嵩皆师之，系五代。北宋时黄氏>花鸟画之先导。', '', '', '', 0),
(594, 'keypoint', '', 901, 0, 0, '本寂禅师卒', 'tang', '曹山本寂随缘放旷，如愚若讷，后受请住抚州（今江西）曹山，更迁荷玉山，两处法席鼎盛，学者云集。洪州（今江西南昌）镇帅钟传屡请，不往，写《大梅山居颂》一首以答。', '', '', '', 0),
(595, 'keypoint', '', 901, 0, 0, '洪湮禅师卒', 'tang', '径山洪湮从无上大师出家，时无上大师入住径山，召之往就。865年无上大师圆寂，洪湮继席。洪湮识钱镠于微时，爱镠才识。感念洪湮，径山于时兴大无比。', '', '', '', 0),
(596, 'keypoint', '', 900, 0, 0, '朱全忠攻刘仁恭', 'tang', '四月，朱全忠遣葛从周讨击卢龙节度使刘仁恭。李克用遣周德威救之。双方各有胜负。', '', '', '', 0),
(597, 'keypoint', '', 900, 0, 0, '崔胤复相', 'tang', '崔胤复相，知昭宗恶宦官，与昭宗谋去之。南北司益相憎嫉，各结藩镇以为援。王抟明达有度量，时称良相，请去宦官勿过急。崔胤乃谮与宦官勾结>；罢王抟相，崔胤专制朝廷。', '', '', '', 0),
(598, 'keypoint', '', 900, 0, 0, '徐彦若、崔远罢相', 'tang', '崔胤专制朝政，恶太保、门下侍郎、同平章事徐彦若位在己上，彦若亦自求引退。九月，诏以彦若为清海节度使，出镇广州。又罢崔远相位，>以刑部尚书裴贽为宰相。', '', '', '', 0),
(599, 'keypoint', '', 900, 0, 0, '马殷攻刘士政', 'tang', '九月，升桂管经略使为静江军节度使，以经略使刘士政为节度使。殷遂遣秦彦晖、李琼将兵七千击士政。刘士政出降。于是，桂管所属五州之地尽>属湖南。', '', '', '', 0),
(600, 'keypoint', '', 900, 0, 0, '王镕再附朱全忠', 'tang', '朱全忠以王镕与李克用相结，自治州（今河北邯郸东北）移兵伐之，攻镇州（今河北正定）南门。镕遣周式往全忠营请和。自是成德镇附汴。', '', '', '', 0),
(601, 'keypoint', '', 900, 0, 0, '朱全忠攻刘仁恭', 'tang', '成德判官张泽劝王镕说朱全忠兼服卢龙、义武二镇，以制河东。全忠遣张存敬北击刘仁恭，先攻取其义昌军，引兵攻义武军，节度使王郜奔李克用。留后王处直向朱全忠请和。', '', '', '', 0),
(602, 'keypoint', '', 900, 0, 0, '朱全忠羁服河北', 'tang', '十月，卢龙节度使刘仁恭遣其子守光将兵救定州（今河北定县），朱全忠遣张存敬逆袭。自是幽人服汴，河北四镇魏博、成德、义武、卢龙皆羁>服于全忠，但全忠不能并其地。', '', '', '', 0),
(603, 'keypoint', '', 900, 0, 0, '晋兵下太行', 'tang', '九月，义武节度使王郜告急于河东，十月李克用遣李嗣昭将步骑三万下太行退汴兵，攻拔怀州（今河南沁阳），又进攻河阳（今河南孟县）。佑国军将阎宝引兵来救，河东兵乃退。', '', '', '', 0),
(604, 'keypoint', '', 900, 0, 0, '刘季述囚昭宗', 'tang', '宰相崔胤与昭宗谋尽诛宦官，宦官皆惧，谋废帝以太子监国，引藩镇李茂贞、韩建为援。神策左军中尉刘季述率禁兵千人破门入宫，囚昭宗，矫诏>令太子即皇帝位，更名李缜。', '', '', '', 0),
(605, 'keypoint', '', 900, 0, 0, '杀人立威', 'tang', '宦官刘季述等既废昭宗，欲求媚于众，乃加百官爵秩，将士皆受优赏。为树立权威，每夜杀人，昼以十车载尸出宫。欲杀崔胤，而惮朱全忠，但解胤度>支盐铁转运使职而已。', '', '', '', 0),
(606, 'keypoint', '', 900, 0, 0, '藩镇反对废立', 'tang', '退休宰相张浚给诸藩镇写信，劝藩帅勤王诛宦竖。刘季述遣使见朱全忠，全忠囚季述使，遣亲吏蒋玄晖往京师见崔胤，谋诛宦官。太子即位累旬，>藩镇笺表多不至。', '', '', '', 0),
(607, 'keypoint', '', 900, 0, 0, '《又玄集》', 'tang', '诗人韦庄编辑《又玄集》，收唐诗人杜甫等一百五十家诗三百首。今本《又玄集》仍存一百四十二家，诗二百九十七首。', '', '', '', 0),
(608, 'keypoint', '', 900, 0, 0, '甄萱建后百济', '', '后百济（900年—936年）是朝鲜半岛后三国时期政权之一，由原新罗将领甄萱建立，定都全州（后迁光州），疆域覆盖半岛西南部，与后高句丽、新罗形成三足鼎立局面。', '', '', '', 0),
(609, 'keypoint', '', 999, 0, 0, '祭祀韩文公', 'beisong', '陈尧佐于999年立庙祭祀韩文公（韩愈）。陈尧佐与韩愈有相似的经历，因言事曾被贬潮州，经历的相似和思想的趋同，促使他祭祀韩文公。', '', '', '', 0),
(610, 'keypoint', '', 999, 0, 0, '孙何施政', 'beisong', '孙何上奏宋真宗，改革人事制度，裁汰冗馀官员；调整国家职能部门，把三司所辖的部门和机构归还给户部，逐步恢复六部，各司其职。傅潜等渎职\r\n官员被惩处。', '', '', '', 0),
(611, 'keypoint', '', 999, 0, 0, '', 'beisong', '阿拉伯人在大加那利岛登陆并经商。大加那利岛，今属西班牙加纳利自治区的岛屿，位于北非大西洋沿岸。', '', '', '', 0),
(612, 'keypoint', '', 999, 0, 0, '川峡士兵起义', 'beisong', '王均领导士兵起义。王均原为北宋益州神卫军指挥使，因主将符昭寿克扣军饷、纵容部属欺压士兵，被部将拥立为帝，建立\"大蜀\"政权并改元\">化顺\"。被镇压后自缢身亡。', '', '', '', 0),
(613, 'keypoint', '', 999, 0, 0, '', 'beisong', '邢昺奉诏撰《论语》、《孝经》和《尔雅》诸疏，后世习称邢疏。', '', '', '', 0),
(614, 'keypoint', '', 999, 7, 0, '设置市舶司', 'beisong', '宋真宗置翰林侍读学士、侍讲学士。这是前代所没有的。推动文官体系完善。', '', '', '', 0),
(615, 'keypoint', '', 999, 7, 0, '集兵南伐', 'beisong', '契丹主下诏诸道，集兵南伐。', '', '', '', 0),
(616, 'keypoint', '', 999, 9, 0, '', 'beisong', '宋真宗诏示在杭州（今浙江杭州）、明州（今浙江宁波）设置市舶司，让外来客商经营得到方便，加强对外贸易的管理。宋代封建经济获得一定的发展，对外贸易>也随之发达。。', '', '', '', 0),
(617, 'keypoint', '', 999, 9, 0, '萧太后幸南京', 'beisong', '萧太后与契丹主幸南京，以皇弟梁王耶律隆庆（景宗四子）为先锋，大举南伐。魏王、北院枢密使耶律斜轸却因病去世，契丹主命韩德让代替其\r\n职务，继续南下。', '', '', '', 0),
(618, 'keypoint', '', 999, 10, 24, '契丹军至遂城', 'beisong', '守遂城是已故太尉杨业之子——保州缘边都巡检使杨延昭（当时名“延朗”，“延昭”为后改）。 发生遂城之战。杨延昭以冰筑城智退契丹军，此>役后被称“铁遂城”。', '', '', '', 0),
(619, 'keypoint', '', 999, 0, 0, '萨曼王朝被灭', '', '黑汗王朝哈仑与哥疾宁王朝（977-1186，今阿富汗境内）马合木联手终结萨曼王朝（819-999，位于阿姆河与锡尔河之间的河中地区），中亚格局重构。\r\n', '', '', '', 0),
(620, 'keypoint', '', 998, 0, 0, '除诸路遭欠', 'beisong', '太宗朝对于各路拖欠的钱财时有赦免，但地方官府仍令百姓交纳。真宗采纳判理欠司王钦若的建议，派遣使者乘邮传通知。共免放欠款一千余万，\r\n同时还释放囚徒三千余人。', '', '', '', 0),
(621, 'keypoint', '', 998, 0, 0, '三司调整税收', 'beisong', '八月，真宗诏令三司度量茶、盐，酒三项税额，以之作为岁用。并责令不得加重百姓的赋税负担，各项开支宜加节约。', '', '', '', 0),
(622, 'keypoint', '', 998, 0, 0, '绫锦院改织绢', 'beisong', '绫锦院是少府监所属机构，以供皇帝服饰。九月，绫锦院已有锦绮机四百余台，真宗认为锦绮不属军需国用，下令全改为织绢。绫锦院开始以新\r\n织绢进贡皇室。', '', '', '', 0),
(623, 'keypoint', '', 998, 0, 0, '宋置估马司', 'beisong', '建市马务，遣派官员主持。当时年计进马五千余匹，用布帛、茶叶等物品偿付马值。估马司设勾当官三人。后来，估马司隶属群牧司下。', '', '', '', 0),
(624, 'keypoint', '', 998, 0, 0, '修《太宗实录》', 'beisong', '初，真宗诏令工部侍郎、集贤院学士钱若水监修《太宗实录》。参加修纂的有柴成务、宋度、吴淑、杨亿等。八月，修成《太宗实录》八十卷\r\n，其中五十六卷为杨亿独修。', '', '', '', 0),
(625, 'keypoint', '', 998, 0, 0, '游龙钵献马于宋', 'beisong', '河西军（即西凉府，今甘肃武威）右厢副使、归德将军折逋游龙钵（吐蕃人，四代都被宋廷命为酋长）亲自到宋廷朝贡，献马二干余匹，被宋\r\n加封为安远大将军。', '', '', '', 0),
(626, 'keypoint', '', 998, 0, 0, '', 'liaoguo', '辽圣宗下诏减免燕地赋税，归还宋境散失牲畜。', '', '', '', 0),
(627, 'keypoint', '', 998, 0, 0, '辽册封高丽', 'liaoguo', '997年十一月，高丽（今朝鲜半岛）国王王治卒，其侄王诵遣使告于辽。辽圣宗遣使致祭，诏命王诵权知国事。998年冬十一月，辽遣使册封王诵为\r\n王。', '', '', '', 0),
(628, 'keypoint', '', 998, 0, 0, '耶律休哥卒', 'liaoguo', '辽朝将领，耶律德光族兄弟。大败宋军于高梁河。任南京留守，兼南面行营总管，总南面军务。又任上均戍兵，立更休法，劝农桑，修武备，成效\r\n颇著。', '', '', '', 0),
(629, 'keypoint', '', 1000, 0, 0, '匈牙利立国', '', '匈牙利大公伊什特万一世推行天主教，获天主教教皇加冕成为匈牙利第一位国王。传统上认为马扎儿人国家是由阿尔帕德大公建立的，他于9世纪末带领>马扎尔人来到潘诺尼亚平原。', '', '', '', 0),
(630, 'keypoint', '', 997, 0, 0, '道制演变为路', 'beisong', '北宋初为中央监察区，997年确立15路框架后逐步转为行政区，其行政层级相当于明清的\"省\"。通过分散路级行政权力，避免唐>代藩镇割据，但导致地方资源薄弱，影响边防效能', '', '', '', 0),
(631, 'keypoint', '', 997, 5, 8, '宋太宗崩', 'beisong', '在高梁河之战中大腿中了两箭，“岁岁必发”。', '', '', '', 0),
(632, 'keypoint', '', 997, 5, 8, '真宗即位', 'beisong', '赵德昌（赵恒）继任宋朝皇帝。', '', '', '', 0),
(633, 'keypoint', '', 996, 0, 0, '征剿李继迁受挫', 'beisong', '宋太宗命洛苑使白守荣护送刍粟四十万赴灵州。李继迁大败宋军，尽夺刍粟，又进围灵州，顿兵不去。太宗令李继隆等五路进讨，直趋平夏。\r\n宋师乃无功而还。', '', '', '', 0),
(634, 'keypoint', '', 996, 0, 0, '苏易简卒', 'beisong', '980年，举进士，后历仕知审官院、知审刑院、掌吏部选、给事中、参知政事。卒年三十九岁，赠礼部尚书。著作有《文房四谱》、《续翰林志》等>。', '', '', '', 0),
(635, 'keypoint', '', 996, 0, 0, '王鸬鹚起义', 'beisong', '王鸬鹚曾参加李顺农民起义军，李顺失败后，996年率众起义。自称“邛南王”，率兵攻打邛、蜀等地。太宗免除蜀地租税，命石普为西川都提举捉>贼使，镇压起义军。', '', '', '', 0),
(636, 'keypoint', '', 996, 0, 0, '宋琪卒', 'beisong', '941年中进士，署寿安王（耶律璟）侍读。赵延寿节镇幽州，辟为从事。赵延寿节之子赵赞领河中节度，署为记室。太宗即位，召补阙。累拜吏部尚书>，拜右仆射。', '', '', '', 0),
(637, 'keypoint', '', 995, 0, 0, '赵恒任开封府尹', 'beisong', '宋太宗在长子赵元佐（已疯）之后，属意第三子赵恒。995年，赵恒被任命为开封府尹，这是一个明确的皇位继承人信号，为后来的顺利即位铺平了道路。', '', '', '', 0),
(638, 'keypoint', '', 995, 0, 0, '吕蒙正复相', 'beisong', '名相吕蒙正于当年二月再次被任命为宰相。他曾以直言敢谏著称，他的复出是宋太宗晚年调整中枢人事的重要举措。', '', '', '', 0),
(639, 'keypoint', '', 994, 0, 0, '', 'liaoguo', '契丹政权颁布均税法', '', '', '', 0),
(640, 'keypoint', '', 994, 0, 0, '起义遇挫', 'beisong', '王小波妻弟李顺继任为王小波、李顺起义首领。宋朝军队攻克成都，李顺失踪，余部由张余带领转战四川境内。', '', '', '', 0),
(641, 'keypoint', '', 994, 0, 0, '王小波卒', 'beisong', '北宋初年四川农民起义领袖。993年，王小波率贫苦旁户、茶农数百人起事后，提出：“吾疾贫富不均，今为汝均之。”。重创宋军，杀死西川都巡检>使张玘。因中箭伤重病逝。', '', '', '', 0),
(642, 'keypoint', '', 993, 0, 0, '', 'beisong', '河南地区发生水灾并引发疫病流行，宋太宗采取发粮赈济等措施应对灾情。', '', '', '', 0),
(643, 'keypoint', '', 993, 0, 0, '王小波起义', 'beisong', '春天，青城县爆发王小波、李顺起义，起义军攻克彭山县，同年十二月王小波战死后由李顺领导。北宋政府通过博买务垄断贸易、强制征收铜钱等政策加剧民众负担。', '', '', '', 0),
(644, 'keypoint', '', 993, 0, 0, '黎桓受封', 'beisong', '黎桓受北宋封为交趾郡王。黎桓，越南前黎朝开国君主，980年-1005年在位。原是丁朝的开国功臣，担任十道将军殿前都指挥使。980年被军队拥立>为帝，定都华闾。', '', '', '', 0),
(645, 'keypoint', '', 992, 0, 0, '首位波兰国王', '', '波列斯瓦夫一世继任为波兰君主。继承大公位后流放继母与异母兄弟独掌大权，通过征服波美拉尼亚（994年）、西里西亚、摩拉维亚及斯洛伐克（999>年）扩展疆域。', '', '', '', 0),
(646, 'keypoint', '', 991, 0, 0, '', 'beisong', '始设提点刑狱司监督州县案件审理及弹劾违法官员。', '', '', '', 0),
(647, 'keypoint', '', 991, 0, 0, '余铉卒', 'beisong', '文字学家余铉（916—991）。铉字鼎臣，广陵人。初仕南唐。校订《说文解字》，世称“大徐本”。另著《骑省集》。', '', '', '', 0),
(648, 'keypoint', '', 991, 0, 0, '置内殿崇班', 'beisong', '正月，置内殿崇班，为武阶官名。政和六年（1116），改修武郎，为武臣第四十四阶。', '', '', '', 0),
(649, 'keypoint', '', 991, 0, 0, '置左右侍禁', 'beisong', '正月，置左右侍禁，系武臣阶官名，为三班小使臣。政和二年 （1112），左侍禁改名忠训郎，右侍禁改名忠翊郎。', '', '', '', 0),
(650, 'keypoint', '', 991, 0, 0, '', 'beisong', '正月，殿前承旨改为三班奉职，无职掌，高于三班借职而低于右班殿直，为低级武臣阶官。政和二年 （1112），改名承节郎。', '', '', '', 0),
(651, 'keypoint', '', 991, 0, 0, '诏立刘福遗爱碑', 'beisong', '刘福在雄州五年，谋略有方，为政简易，境内宴然，深得百姓爱戴。刘福卒后，百姓拦截转运使，追述刘福治迹，转运使上奏其事，太宗诏立\r\n遗爱碑，以志纪念。', '', '', '', 0),
(652, 'keypoint', '', 991, 0, 0, '祖吉弃市', 'beisong', '初监察御史祖吉知晋州时，违法受贿，积财达数以万计。事发，祖吉伏诛，没收家产，亲属隶为官奴。', '', '', '', 0),
(653, 'keypoint', '', 991, 0, 0, '李继迁奉表归顺', 'beisong', '李继迁奉表归顺，宋为断契丹右臂，授李继迁银州观察使，赐姓名赵保吉，授李继冲为绥州团练使，赐姓名赵保宁，李德明为管内蕃落使行军\r\n司马。', '', '', '', 0),
(654, 'keypoint', '', 991, 0, 0, '宋置审刑院', 'beisong', '太宗体恤百姓，恐大理寺、刑部官吏专断。在宫内特置审刑院。案件由审刑院印讫，付大理寺、刑部裁断，报审刑院审查，由知院与详议\n官出书面意见，报中书，奏请皇帝裁决。', '', '', '', 0),
(655, 'keypoint', '', 991, 0, 0, '李继捧降辽', 'beisong', '988年，太宗采用以夷制夷的策略，起用李继捧为定难军节度使，回镇夏州，牵制李继迁。991年李继捧降辽，辽封其为西平王。', '', '', '', 0),
(656, 'keypoint', '', 991, 0, 0, '女真请兵', 'beisong', '辽为阻女真朝贡宋朝，于女真通向宋朝的路上置三栅，断绝贡路。女真首领野里雉等遣使泛海入朝，请发兵与女真各部共平三栅。太宗只降\n诏抚谕拒绝出师，女真遂降辽。', '', '', '', 0),
(657, 'keypoint', '', 991, 0, 0, '辽掠银州', 'liaoguo', '李继迁在投靠辽的同时，为取得经济利益，暗通宋朝。宋任继迁为银州观察使，引起辽圣宗猜忌，辽军乃于992年二月大掠银州而还。。', '', '', '', 0),
(658, 'keypoint', '', 990, 0, 0, '', 'beisong', '钱若水因平反同州冤案升任秘书丞', '', '', '', 0),
(659, 'keypoint', '', 990, 0, 0, '太宗施政', 'beisong', '五月，调整中央司法机构，刑部新置详覆官六人，审核死刑案件及纠正司法程序疏漏；御史台增设推勘官二十人专责审理重大刑狱。皇帝亲核重案制\n度。元丰改制后废止。', '', '', '', 0),
(660, 'keypoint', '', 990, 0, 0, '推行货币改革', 'beisong', '太宗亲书\"淳化元宝\"钱文，分真书、行书、草书三体，开御书钱先例，分大小两种规格，其中大钱作当十钱使用。自此确立年号钱制度，此后改元必铸新钱。', '', '', '', 0),
(661, 'keypoint', '', 993, 0, 0, '陈靖出使高丽', 'beisong', '初，高丽国王王治遣使韩彦恭朝贡宋朝，并求佛经。太宗诏赐《藏经》等经书。993年王治遣使白思莱答谢圣恩。太宗特遣秘书丞直史馆陈靖等>出使高丽。王治亲迎于郊，尽藩臣礼。', '', '', '', 0),
(662, 'keypoint', '', 990, 0, 0, '姚益恭治须城', 'beisong', '姚益恭为兴国军判官时，清正廉洁，召赴阙，百姓拦道乞留，晚上离城赴任。在须城时，刑罚不用，境内大治。采访使上奏其事，太宗赐绢二十匹，米二十二石。', '', '', '', 0),
(663, 'keypoint', '', 990, 0, 0, '王济通判镇州', 'beisong', '王济为刑部详覆官时，屡次上书封事。太宗遂命为镇州通判，其治下多勋旧武臣，恃贵凌下。镇州守卒恣暴不法，立即斩首。都校孙进酒后伤人\n，王济令人杖脊。太宗连下三诏褒奖。', '', '', '', 0),
(664, 'keypoint', '', 990, 0, 0, '辽国施政', 'liaoguo', '辽国进行地方行政建置调整。七月，辽圣宗诏令裁撤遂、妫、松等十州及玉田、辽丰等八县建制，新设定霸、保和、宣化三县，将裁撤州县人口划归邻近政区管辖。', '', '', '', 0),
(665, 'keypoint', '', 990, 0, 0, '', '', '维京人抵达美洲。', '', '', '', 0),
(666, 'keypoint', '', 990, 0, 0, '迎娶安娜公主', '', '基辅罗斯大公弗拉基米尔一世·斯维亚托斯拉维奇迎娶拜占庭帝国安娜公主，使基辅罗斯得以被解释为东罗马帝国的继承人。', '', '', '', 0),
(667, 'keypoint', '', 990, 1, 1, '', '', '基辅罗斯采用儒略历。', '', '', '', 0),
(668, 'keypoint', '', 989, 0, 0, '', 'beisong', '八月，密州上报蝗灾但未形成重大灾情，治蝗政策开始呈现制度化特征，地方官员已开始突破\"天人感应\"迷信，采取积极灭蝗措施。此后陆续颁布《除殄蝗虫\r\n种子法》与《捕蝗法》。', '', '', '', 0),
(669, 'keypoint', '', 989, 0, 0, '潘皇后去世', 'beisong', '章怀皇后（968年－989年），真宗赵恒元配，北宋名将、忠武军节度潘美第八女。太宗赐婚，册封莒国夫人。', '', 'https://baike.baidu.com/item/章怀皇后/11062909', '', 0),
(670, 'keypoint', '', 988, 0, 0, '唐河之战', 'beisong', '辽军南侵涿州、祁州等地，北宋将领李继隆违背坚壁清野指令，率静塞军千余骑在唐河地区击溃八万辽军精锐，斩首一万五千级，缴获战马万匹，巩\r\n固宋军定州防线。', '', '', '', 0),
(671, 'keypoint', '', 988, 0, 0, '罗斯受洗', '', '基辅罗斯大公弗拉基米尔987年与拜占庭帝国结盟，次年迎娶安娜公主，988年接受基督教洗礼。下令全民在第聂伯河集体受洗，烧毁多神教神像，确立基督>教为国教。（据《往年纪事》)', '', '', '', 0),
(672, 'keypoint', '', 987, 0, 0, '承认越南政权', 'beisong', '宋朝承认黎桓在越南的统治地位。黎桓是丁朝的开国功臣，担任十道将军殿前都指挥使（全国军队的最高统帅）。980年被军队拥立为帝。', '', '', '', 0),
(673, 'keypoint', '', 987, 0, 0, '小亚细亚叛乱', '', '拜占庭帝国爆发小亚细亚行省叛乱，拜占庭皇帝瓦西里二世为镇压叛乱向基辅罗斯求援，基辅王公弗拉基米尔同意派遣援军。此后，基辅罗斯统治集团>接受基督教为国教。', '', '', '', 0),
(674, 'keypoint', '', 987, 0, 0, '卡佩王朝建立', '', '由雨果·卡佩建立，名称源于建立者喜好的短披肩（法语称“cape”）。实行邑督制，构建起中央集权的治理框架。1328年主系绝嗣后由瓦卢瓦家族继位。', '', '', '', 0),
(675, 'keypoint', '', 986, 0, 0, '杨业被俘', 'beisong', '北宋将领杨业在北伐中任云应路行营副都部署，被辽军俘获后绝食而死，宋太宗随后追赠其为太尉、大同军节度使。', '', '', '', 0),
(676, 'keypoint', '', 986, 0, 0, '辽向宋朝开战', 'beisong', '十月十七日，辽圣宗向拒马河南六州军民下诏，宣布向宋朝开战。', '', '', '', 0),
(677, 'keypoint', '', 986, 0, 0, '君子馆之战', 'beisong', '十一月，君子馆之战，宋军惨败，河北防线受到重创。', '', 'https://baike.baidu.com/item/君子馆之战/0', '', 0),
(678, 'keypoint', '', 986, 0, 0, '土墱寨之战', 'beisong', '十二月，土墱寨之战，宋将张齐贤击败辽军，守住代州。', '', 'https://baike.baidu.com/item/土墱寨之战/0', '', 0),
(679, 'keypoint', '', 986, 0, 0, '新版《说文解字》', 'beisong', '北宋徐铉与句中正、葛湍、王惟恭等奉诏校定《说文解字》，新增字形并加注反切音，由国子监雕版刊行，该版本被称为“大徐本”。', '', '', '', 0),
(680, 'keypoint', '', 986, 8, 1, '', '', '一条天皇即位，为第66代天皇。', '', '', '', 0),
(681, 'keypoint', '', 986, 0, 0, '', '', '保加利亚沙皇萨穆伊尔入侵帖撒利亚，占领拉里撒与都拉基乌姆，并趁拜占廷内讧之机，向保加利亚以东扩张。', '', '', '', 0),
(682, 'keypoint', '', 985, 0, 0, '赵元俨出生', 'beisong', '太宗第八子赵元俨（后世称\"八贤王\"原型人物）出生。广颡丰颐，严毅不可犯，人称“八大王”。政治家、文学家、书法家、藏书家，对宋朝统治做出了贡献。', '', '', '', 0),
(683, 'keypoint', '', 985, 0, 0, '太子被废', 'beisong', '太宗长子赵元佐因患狂病焚宫，被废为庶人。此事导致太宗在立储问题上长期迟疑，最终于995年下诏立赵元侃（即宋真宗）为太子。>该事件收录于夏坚勇《东京梦寻录》。', '', 'https://baike.baidu.com/item/赵元佐/8727834', '', 0),
(684, 'keypoint', '', 984, 0, 0, '', 'beisong', '太子赵元佐因同情被贬死的叔父赵匡美，发疯，并伤及旁人。', '', '', '', 0);
INSERT INTO `wp_book` (`id`, `code`, `category`, `name`, `book_path`, `path_label`, `path_point`, `path_old`, `position`, `nationality`, `orderlist`, `description`, `baidu_url`, `douban_url`, `author`, `is_ancientread`, `is_onlineread`, `is_otherread`, `status`, `deal_status`, `publish_at`, `created_at`, `updated_at`, `extfield`) VALUES
(481, '1914nianyihoudehuobiyuwaihui', '', '1914年以后的货币与外汇', '', '', '', 'books/学术名著/其他国家/瑞典/卡塞尔/1914年以后的货币与外汇', '', '瑞典', 0, '《1914 年以后的货币和外汇》自1922年印行以来，很快成为国际金融研究领域一部经典之作。作者在书中首次系统地提出了购买力平价理论，从理论和统计上论证了决定货币内在价值和影响汇率波动的主导因素，并对物价上涨的表现和通货紧缩的运行作了严肃考察，至今不乏学术价值和启发意义。', 'https://baike.baidu.com/item/1914年以后的货币与外汇/22185432', 'https://book.douban.com/subject/26819034/', '', 0, 0, 0, 11, 0, '1922', NULL, '2025-01-06 07:19:06', ''),
(96, 'agulikelazhuanriermanniyazhi', 'other', '阿古利可拉传 日耳曼尼亚志', '汉译世界学术名著丛书/其它卷/阿古利可拉传_日耳曼尼亚志_古罗马_塔西佗', '', '', 'books/学术名著/其他国家/罗马/塔西佗/阿古利可拉传_日耳曼尼亚志', '', '古罗马', 0, '《阿古利可拉传 日耳曼尼亚志》即是研究古代不列颠和日耳曼的极其重要的史料。阿古利可拉是完成并巩固罗马在不列颠统治的人物，《阿古利可拉传》中大部分篇幅是叙述不列颠的情况，因此它不仅是一部传记，也是研究古代不列颠的一部历史文献。《日耳曼尼亚志》详细叙述了古罗马日耳曼尼亚以及居住在日耳曼尼亚的各个部落的情况，同样极具历史价值。', 'https://baike.baidu.com/item/日耳曼尼亚志/10951567', 'https://book.douban.com/subject/1116356/', 'taxituo', 0, 1, 0, 11, 0, '0', '2021-07-31 07:26:05', '2025-01-06 07:19:06', 'taxituo'),
(759, 'aikehatedashiwenji', '', '爱克哈特大师文集', '', '', '', 'books/学术名著/德国/爱克哈特/爱克哈特大师文集', '', '', 0, '埃克哈特大师 (Meister Johannes Eckhart，约1260～1327)是得到自觉的灵，他的全名是约翰尼斯·埃克哈特（Johannes Eckhart），但无论是在他活着的时候和他死去以后，也无论是他自称还是别人称呼他，都是以埃克哈特（也有译为爱克哈特或艾克哈特的）大师而闻名于世的。约翰尼斯·埃克哈特(Johannes Eckhart) 是宗教改革运动的发起者、基督教新教的创始人马丁·路德心中的指路明灯。马丁·路德在其主持编印的《德意志神学》中，对爱克哈特的神学思想备加赞扬。', 'https://baike.baidu.com/item/埃克哈特大师文集/4951524', 'https://book.douban.com/subject/5254829/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:49:58', ''),
(470, 'aimier', '', '爱弥儿(上下卷)', '', '', '', 'books/学术名著/法国/卢梭/爱弥儿_上下卷', '', '法', 0, '爱弥儿》是法国思想家让-雅克·卢梭创作的教育学著作，首次出版于1762年。该书是一本夹叙夹议的教育小说，书中以富家孤儿爱弥儿为主人公，论述了男子的教育改革，批判英国旧教育的荒谬腐朽，并提出新教育的原则和理想。并且借爱弥儿未来妻子苏菲的教育，论证了女子教育的革新。全书反映了自然主义教育思想，阐述性善论。其思想对后世许多教育家都有启发和影响。该书在西方教育史上首次系统提出了新的儿童教育观，从而在教育史上掀起了一场“哥白尼式的革命”。', 'https://baike.baidu.com/item/爱弥儿/72845', 'https://book.douban.com/subject/1022318/', '', 0, 0, 0, 11, 0, '1762', NULL, '2025-01-04 09:49:59', ''),
(760, 'aiyinsitanwenji', '', '爱因斯坦文集', '', '', '', 'books/学术名著/美国/爱因斯坦/爱因斯坦文集', '', '美', 0, '本书收录了爱因斯坦关于自然科学哲学问题和一般自然科学方面比较有代表性的论述，内容主要是爱因斯坦自己写的文章、讲稿和通信，也包括别人写的爱因斯坦的谈话记录。此外，还收了几封别人写的有关的通信，作为附件。', 'https://baike.baidu.com/item/爱因斯坦文集', 'https://book.douban.com/subject/6060527/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:49:58', ''),
(294, 'akeluofusipengsihesidigelicilunwenjingxuan', '', '阿克洛夫、斯彭斯和斯蒂格利茨论文精选', '', '', '', 'books/学术名著/美国/斯蒂格利茨/阿克洛夫_斯彭斯和斯蒂格利茨论文精选', '', '', 0, '《阿克洛\r\n夫、斯彭斯和斯蒂格利茨论文精选》是汉译世界学术名著丛书经济类的一本，所蕴藏的思想财富和学术价值，为学人所熟知，毋需赘述。《阿克洛夫、斯彭斯和斯蒂格利茨论文精选》相得益彰，蔚为大观，既便\r\n于研读查考，又利于文化积累。乔治· 阿克洛夫（1940年-），2001年获诺贝尔经济学奖。迈克尔·斯彭斯 （1943年11月7日-），2001年获诺贝尔经济学奖。约瑟夫·斯蒂格利茨（1943年2月9日-），2001年诺贝>\r\n尔经济学奖、2007年获诺贝尔和平奖。本论文集收录了三位经济学家的七篇代表性论文。七篇论文分三个部分，一是三篇原创性论文，《柠檬市场：质量不确定性与市场机制》《劳动力市场的信号发送》《竞争\r\n性保险市场中的均衡：论不完备信息经济学》；二是两篇密切相关的应用性论文 ，《保险、信息与个人行为》《不完备市场信息市场中的信贷配给》；三是格罗斯曼与斯蒂格利茨提出“格罗斯曼－斯蒂格利茨悖\r\n论”的两篇经典论文。', 'https://baike.baidu.com/item/阿克洛夫、斯彭斯和斯蒂格利茨论文精选/7090095', 'https://book.douban.com/subject/1116418/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:50:04', ''),
(656, 'akuinazhengzhizhuzuoxuan', '', '阿奎那政治著作选', '', '', '', 'books/学术名著/意大利/阿奎纳/阿奎那政治著作选', '', '意', 0, '该作主要讲述了阿奎那关于国家和法律的主要观点。这本《阿奎那政治著作选》摘录出阿奎那关于国家和法律的主要观点，对于初读他的著作的人是很方便的。', 'https://baike.baidu.com/item/阿奎那政治著作选', 'https://book.douban.com/subject/1890256/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:50:00', ''),
(876, 'alaboyisilanwenhuashi', '', '阿拉伯伊斯兰文化史', '', '', '', 'books/学术名著/其他国家/埃及/爱敏/阿拉伯伊斯兰文化史', '', '埃及', 0, '本书介绍了阿拉伯伊斯兰国家的政治、经济、社会、文化、学术活动、教派发展等方面的历史。《阿拉伯-伊斯兰文化史》，是埃及学者艾哈迈德·艾敏所著，编撰于20世纪上半叶，共八册。该书内容涉及范围甚广，包括阿拉伯伊斯兰国家的政治、经济、社会、文化、学术活动、教派发展等方面，是为研究伊斯兰历史文化的重要史籍。而中文翻译本，则由80年代起，由北京商务印书馆陆续出版至今。', 'https://baike.baidu.com/item/阿拉伯-伊斯兰文化史/705417', 'https://book.douban.com/subject/2282267/', '', 0, 0, 0, 11, 0, '1950', NULL, '2025-01-06 07:19:06', ''),
(387, 'ameishideshituanchushizhongguorizhi', '', '阿美士德使团出使中国日志', '', '', '', 'books/学术名著/英国/埃利斯/阿美士德使团出使中国日志', '', '英', 0, '公元1816年，阿美士德勋爵受命出使清王朝，以期与满清朝廷商讨中、英贸易外交事宜，企图进一步打开中国国门，史称阿美士德使团。本书作者亨利·埃利斯作为使团书记官同时也是使团的副使，其地位仅次于阿美士德勋爵和斯当东爵士。在这本私人日志中，埃利斯记录了使团出使一路上的见闻。由于在觐见嘉庆皇帝的礼仪问题上，双方产生了分歧，最终清政府取消了觐见，但准许使团沿大运河南下旅行至广州，沿途也得到礼待。使团1817年1月28日在澳门登船返回。并在回国途中谈往了当时正被幽禁在圣拿撒勒岛的前法国皇帝拿破仑·波拿巴。', 'https://baike.baidu.com/item/阿美士德使团出使中国日志/12350719', 'https://book.douban.com/subject/25720374/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:50:03', ''),
(292, 'anggelusakexunbiannianshi', '', '盎格鲁-撒克逊编年史', '', '', '', 'books/学术名著/其他/盎格鲁_撒克逊编年史', '', '', 0, '本书是英国最著名的史书之一，也是中世纪早期\r\n西欧最重要的史学著作之一，是记载公元前50年至公元1154年英国历史的唯一史料，因此具有极高的历史学价值。该书的编写肇始于公元9世纪末，材料来源多种多样，以编年体写成。原书以古英语写作，中译>本根据最权威的《英国历史文献》现代英语译本译出。', 'https://baike.baidu.com/item/盎格鲁-撒克逊编年史', 'https://book.douban.com/subject/1224331/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 06:22:30', ''),
(450, 'aobenhaiguojifa', '', '奥本海国际法', '', '', '', 'books/学术名著/德国/奥本海/奥本海国际法', '', '英', 0, '《奥本海国际法》是拉萨·奥本海创作的国际法学著作，第一版出版于1905-1906年，在奥本海去世后，先后由其学生罗克斯伯、麦克奈尔、劳特派特修订，于1955年出了第八版。该书分上、下两卷。上卷主要探讨平时法，下卷主要探讨争端法、战争法和中立法。该书内容广泛、材料翔实，概括了主要西方国家宣扬的国际法原则和实践，反映了西方国际法的主要动向。尽管原书出版已经多年，但它在国际上仍然很受重视，很有影响。', 'https://baike.baidu.com/item/奥本海国际法', 'https://book.douban.com/subject/1013900/', '', 0, 0, 0, 11, 0, '1906', NULL, '2025-01-04 09:50:00', ''),
(289, 'aoyishu', '', '奥义书', '', '', '', 'books/学术名著/其他/奥义书', '', '', 0, '印度最经典的古老哲学著作，用散文或韵文阐发印度教最古老的吠陀文献的思辨著>作。已知的奥义书约有108种之多，记载印度教历代导师和圣人的观点。奥义书在很大程度上为后来印度哲学的基础。在哲学方面，奥义书特别注意实在的性质。关于独一至高存在本体的概念逐渐形成，以知识>为求得与之融合为一的途径。《奥义书》（Upanishad）是印度古代哲学典籍，《吠陀》的最后一部分，数量约有200多种。这里不能不先说一下《吠陀》（Veda）。《吠陀》是印度上古时期的文献总集，是印度宗教、哲学、文学、文明的基石，历来被认为是印度教最古的经典。作品产生年代可上溯到公元前1500年前，最晚约在公元前6世纪。“吠陀”本义是“知”、“知识”。有广狭二义：狭义指最古的4部集；广义指4部>本集及附加文献。其附加文献主要包括由散文写成的《梵书》、《森林书》、《奥义书》等。《吠陀》包含了人类最早的文明史迹和文学创作，为研究人类文明进程提供了丰富的资料，在印度被尊为圣典。《奥义书》最早出现于公元前9世纪左右，较晚产生于公元后。较早的《奥义书》有《广林奥义书》、《歌者奥义书》、《他氏奥义书》、《由谁奥义书》等。内容涉及的范围很广，颇受印度几百年间许多思想家喜>爱和广泛流传。', 'https://baike.baidu.com/item/奥义书/8081303', 'https://book.douban.com/subject/3269870/', '', 0, 0, 0, 11, 0, '-800', NULL, '2025-01-06 06:22:30', ''),
(694, 'aweisitasuoluoyasidejiaoshengshu', '', '阿维斯塔——琐罗亚斯德教圣书', '', '', '', 'books/学术名著/其他国家/伊朗/杜斯特哈赫/阿维斯塔_琐罗亚斯德教圣书', '', '伊朗', 0, '《阿维斯塔》是伊朗最古老的文献。这部传世之作的成书年代虽难以断定，但起码可以上溯到公元前10世纪以前。全面地探讨《阿维斯塔》，深入地剖析《阿维斯塔》各卷的具体内容及其相互联系，进而从历史、文学和语言学的角度揭示它的本质特征，不是本书的旨趣，也没有这种可能。我们的目的在于，以通俗浏的语言，选编《阿维斯塔》的精华部分，奉献给波斯语读者，为他们了解古代伊朗人的思想和世界观打开一个窗口。总之，波斯古经《阿维斯塔》充分地反映了我们令人尊敬的祖先的英勇、果敢、纯洁、真诚、宽容和乐观的美德，反映了他们对世界上一切事物的明智看法，并且表现出他们为世界繁荣和人类生活的幸福而奋斗不息的热情。', 'https://baike.baidu.com/item/阿维斯塔/3143629', 'https://book.douban.com/subject/4882127/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 07:19:06', ''),
(321, 'azanderendewushushenyuhemofa', '', '阿赞德人的巫术、神谕和魔法', '', '', '', 'books/学术名著/英国/普里查德/阿赞德人的巫术_神谕和魔法', '', '英', 0, '本书为英国著名人类学家埃文思-普>里查德的第一部民族志代表作，是民族志经典中最精致、最富有思想的作品之一，自1937年出版以来一直被人类学者奉为民族志的典范。作者以细腻、精美的笔触描述了中非一个土著部落阿赞德人关于巫术、神\r\n谕和魔法的信仰体系，并在这种描述中巧妙地呈现一种社会、一种生活。这一著作使阿赞德人成为人类学、社会学和哲学等领域的一个著名族群，并关联着相关领域中关于理性与非理性，以及文化相对主义的诸\r\n多讨论。', 'https://baike.baidu.com/item/阿赞德人的巫术、神谕和魔法/1380938', 'https://book.douban.com/subject/1988744/', '', 0, 0, 0, 11, 0, '1937', NULL, '2025-01-04 09:50:00', ''),
(571, 'babuerhuiyilu', '', '巴布尔回忆录', '', '', '', 'books/学术名著/其他国家/印度/巴布尔/巴布尔回忆录', '', '印度', 0, '巴布尔有较好的文学修养，能用波斯语和突厥语写很好的文章，生前曾用突厥语写有自传《巴布尔回忆录》，有较高的史料价值和一定的文学价值，1589年后被译成波斯语，1921年被译成英语。巴布尔（1483—1530），帖木儿大帝后裔，印度莫卧儿王朝的创建者，也是著名诗人和察合台文大师。该书稿是巴布尔的代表作，叙述了从1478年直至1530年其去世之前不久的史实。全书用察哈台文撰写，以时间为经，以事实为纬，逐年记述作者的经历，对于某些人物、事件的历史和缘由以及某些地区的自然、人文情况也做了详细介绍。巴布尔本人是其时代历史的重要参与者、推动者和创造者，本书是当代人写当代史，可作为第一手史料，因而价值巨大', 'https://baike.baidu.com/item/巴布尔回忆录', 'https://book.douban.com/subject/1058876/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 07:19:06', ''),
(147, 'bailin', 'britain', '伯林', '汉译世界学术名著丛书/英国卷/伯林_英_约翰_格雷', '', '', 'books/学术名著/英国/J_格雷/伯林', '', '', 0, '如果说写一本研究伯林思想的著作是一个令人胆怯的任务，这种说法并不意味在伯林著作中有许多含糊不清的地方，恰恰相反，伯林的思想是异常清晰的。虽然伯林的著作涵括了广泛的领域，涉及到许多作者，但它们并非各自分离以至缺乏共同的主题；与之相反，伯林的各种著作都围绕着一个主题。本书的一个中心观点就是，所有伯林的著作都是由一个具有巨大颠覆力的观念贯穿着并使之获得生命力的。我把这个观念叫做价值多元论，其意思是，许多终极人类价值是客观的但又是不可归约地多样化的；这些多样的价值是冲突着的，而且经常是不能和谐共存的；有时，即在它们彼此冲突的时候，它们是不可通约的，即是说，没有任何合理的尺度能对它们加以比较。本书的大部分篇幅将用于阐释和评价这个观念。这个观念在政治哲学上的意义是，所有真正的善和理想都被实现的这种完美社会的理念不仅是一种乌托邦，而且总是自相矛盾的。就像道德生活一样，政治生活中也存在一些在敌对的善和恶之间的基本选择，此时理性弃我们于危难而不顾、我们无论怎么选择都要导致一些损失，有时甚至会出现悲剧。我把伯林的由价值多元论引致的这种政治观称为“竞争的自由主义”（agonistic liberalism）。', 'https://baike.baidu.com/item/伯林/22398467', 'https://book.douban.com/subject/3648988/', 'gelei', 0, 1, 0, 11, 0, '0', '2021-07-31 07:26:31', '2025-01-04 09:50:05', 'yuehan-gelei'),
(116, 'bailintanhualu', 'other', '伯林谈话录', '汉译世界学术名著丛书/其它卷/伯林谈话录_伊朗_贾汉贝格鲁', '', '', 'books/学术名著/其他国家/伊朗/贾汉贝格鲁/伯林谈话录', '', '', 0, '在这本谈话录中，以赛亚·伯林讲述了他的思想及政治哲学的发展历程，其中穿插着许多个人回忆。他谈到了马克思、维柯、赫尔德、赫尔岑等令他着迷并给予他深刻影响的思想家，也谈到了他的诸多挚友，如诺埃尔·安南、W. H. 奥登、大卫·塞西尔、阿尔弗雷德·布伦德尔、斯蒂芬·斯彭德，尤其是他与阿赫马托娃和帕斯捷尔纳克的颇富传奇色彩的交往。从伯林精彩纷呈的谈话中，读者可以分享他对自由主义与宽容的信念，可以分享他对音乐与文学的激情，也可以对他的生活与个性获得一种独特的认知。', 'https://baike.baidu.com/item/伯林谈话录', 'https://book.douban.com/subject/35743527/', 'guhanbeigelu', 0, 1, 0, 11, 0, '0', '2021-07-31 07:26:18', '2025-01-06 07:19:06', 'guhanbeigelu'),
(314, 'baizhantingdiguoshi', '', '拜占庭帝国史：324—1453', '', '', '', 'books/学术名著/美国/瓦西列夫/拜占庭帝国史_324_1453', '', '美', 0, 'A.A.瓦西列夫是国际历史学界公认的、20世纪拜占>庭历史和文化研究权威，其所著《拜占庭帝国史》是在大量分析拜占庭的原始文献的基础上，又充分利用了前人的研究成果而撰写的一部经典著作。作者摆脱了以往研究拜占庭的政治军事传统，把拜占庭的文化\r\n成就置于与政治方面同等地位，全面阐述了拜占庭各方面的成就,堪称关于拜占庭帝国的百科全书；该书还涉及拜占庭与周边各个族群的交往，论述了诸多文明元素相互交融的进程。', 'https://baike.baidu.com/item/拜占庭帝国史/23285945', 'https://book.douban.com/subject/30322990/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:50:03', ''),
(786, 'bali19shijideshoudu', '', '巴黎,19世纪的首都', '', '', '', 'books/学术名著/德国/本雅明/巴黎,19_世纪的首都', '', '德', 0, '本书描述了19世纪资本主义发展进程中，人与自身异化所做的斗争。本书是瓦尔特·本雅明德“拱廊研究计划”的几篇完成稿，德国著名思想家、文艺理论家本雅明受阿拉贡小说的启发，决定通过对大城市异化景观——巴黎拱廊的研究，来展现19世界“资本文化盛事”的风景。在这几篇完成稿中，他用自己独特的叙述风格对波德莱尔的诗歌进行了诠释，同时又敏锐地发现了拱廊在空间上给人类社会生活带来地新变化。通过本书，你可以了解到19世纪资本主义发展进程中，人与自身异化所做的斗争。', 'https://baike.baidu.com/item/巴黎，19世纪的首都/12216604', 'https://book.douban.com/subject/1794666/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:50:03', ''),
(398, 'baligaodengfayuanshi', '', '巴黎高等法院史', '', '', '', 'books/学术名著/法国/伏尔泰/巴黎高等法院史', '', '法', 0, '本书以法国大革命前的法国历史为框架，紧紧围绕这段历史中的法国王位传承和朝代更替这根主轴，叙述巴黎高等法院的源起、发展、演变和消亡。在这个历史时期，在法兰西的国家大舞台上，或先后，或同时上演了治乱交替、兴衰起伏、王位争夺、宫廷变故、内战外战、政教斗争、金融丑闻……等剧目。在这个大舞台上，巴黎高等法院在不同时期、不同的场合，扮演不同的角色，起着正面或者反面的作用。在较长的时期，它只作为配角，置身舞台的边角，入戏较浅，但也曾在短时期内作为主角置身于舞台的中央，入戏较深。一般说来，当国势鼎盛，王权处于强势地位时，它对国王俯首听命、顺从驯服，而当国势衰落、王权处于弱势地位时，它凭恃其具有的登记国王敕令和对国王谏诤的职能，抵制王命，与宫廷分庭抗礼，大唱对台戏。投石党之战就是它与宫廷之间冲突达到顶点的表现。在王权与教权的斗争中，巴黎高等法院通常力挺王权，抗衡教会，矛头指向罗马教廷。本书对上述种种情况进行了相当详细的、生动的叙述。作者行文走笔，夹叙夹议，不时对帝王专制、宗教迷信、宗教狂热痛加挞伐。可以认为，在某种程度上，本书不啻法国大革命前的历史的缩影。巴黎高等法院这个机构所起的作用是极其复杂的。简单地为它贴上一个这样的或者那样的标签，远非恰当之举。', 'https://baike.baidu.com/item/巴黎高等法院史/64591882', 'https://book.douban.com/subject/30297138/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-04 09:50:03', ''),
(291, 'baligongshegongbaoji', '', '巴黎公社公报集(第一、二集)', '', '', '', 'books/学术名著/其他/巴黎公社公报集_第一_二集', '', '法', 0, '巴黎公社是无产阶级革命运动的一个伟大的创\r\n举，是建立在无产阶级民主集中制基础上的新的国家政权形式。《巴黎公社公报》自3月30日至5月24日,共出版66期。5月21日凡尔赛军反扑,兵进巴黎市区,公社一边忙于战争,一边尽最大努力,在战火纷飞之下,>坚持把《公报》出版到5月24日后停刊。全书史料丰富,记载翔实,是一部难得的珍贵历史文献。', 'https://baike.baidu.com/item/巴黎公社公报集（第1集）', 'https://book.douban.com/subject/24719982/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 06:22:30', ''),
(703, 'bamannidesipian', '', '巴曼尼得斯篇', '', '', '', 'books/学术名著/其他国家/古希腊/柏拉图/巴曼尼得斯篇', '', '古希腊', 0, '本书为古希腊哲学家柏拉图（前427—前347）的一篇重要对话。它标志着由《斐多篇》和《国家篇》代表的理念论向柏拉图后期思想的转化。全篇对话分为两个部分。第一部分，柏拉图借爱利亚学派的巴门尼德之口，批评了少年苏格拉底的理念论。第二部分为八组虚拟的逻辑推论，涉及“一”和“存在”是分离还是联系的问题，以及“一”和“多”的问题。', 'https://baike.baidu.com/item/巴曼尼得斯篇', 'https://book.douban.com/subject/1251842/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 07:19:06', ''),
(733, 'baojiafange', '', '薄伽梵歌', '', '', '', 'books/学术名著/其他国家/印度/毗耶娑/薄伽梵歌', '', '古印度', 0, '薄伽梵歌（梵语：भगवद् गीता，罗马字：Bhagavad Gītā，英译：Song of God，汉语意译：神之歌、主黑天之歌），博伽梵歌的字面意思是“主之歌”或“神之歌”，这里的主或者神就是黑天，博伽梵相当于上帝。博伽梵歌是印度教的重要经典与古印度瑜伽典籍，为古代印度的哲学教训诗，收载在印度两大史诗之一《摩诃婆罗多》中（位于Bhisma-Parva章节的23–40)，也简称为《歌（Gītā）》。它是唯一一本记录神，而不是神的代言人或者先知言论的经典，共有700节诗句。成书于公元前五世纪到公元前二世纪，今译为“博伽梵歌”。', 'https://baike.baidu.com/item/薄伽梵歌', 'https://book.douban.com/subject/1763757/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 07:19:06', ''),
(555, 'baojiafangelun', '', '薄伽梵歌论', '', '', '', 'books/学术名著/其他国家/印度/阿罗频多/薄伽梵歌论', '', '印度', 0, '《薄伽梵歌论》所蕴藏的思想财富和学术价值，为学人所熟知，毋需赘述。这些译本过去以单行本印行，难见系统，汇编为丛书，才能相得益彰，蔚为大观，既便于研读查考，又利于文化积累。为此，我们从1981年着手分辑刊行，至2000年已先后分九辑印行名著360余种。现继续编印第十辑。到2004年底出版至400种。今后在积累单本著作的基础上仍将陆续以名著版印行。希望海内外读书界、著译界给我们批评、建议，帮助我们把这套丛书出得更好。', 'https://baike.baidu.com/item/薄伽梵歌论', 'https://book.douban.com/subject/1072989/', '', 0, 0, 0, 11, 0, '', NULL, '2025-01-06 07:19:06', ''),
(399, 'baoshouzhuyi', '', '保守主义', '', '', '', '', '', '英', 0, '本书写于1912年，是英国保守党的重要政治理论著作。作者在书中描述了一般的守旧思想，以及英国保守主义的渊源和形成过程，并认为英国近代保守主义有三个主要来源，即人类天生的守旧倾向、王党主义和帝国主义。在一定意义上，本书也可以看作是一部保守主义思想史。', '', 'https://book.douban.com/subject/2033288/', '', 0, 0, 0, 11, 0, '1912', NULL, NULL, ''),
(946, 'baoweimakesi', '', '保卫马克思', '', '', '', 'books/学术名著/法国/阿尔都塞/保卫马克思', '', '法', 0, '《保卫马克思》是法国哲学家路易·阿尔都塞创作的哲学著作。阿尔都塞是结构主义马克思主义的主要代表，《保卫马克思》是他的成名作。该书收集了作者1960—1965年间发表的8篇文章，是一部论文集。附录《论青年马克思的演变》作于1970年。该书主要包括费尔巴哈的“哲学宣言”、论青年马克思、矛盾与多元决定、关于唯物辩证法、马克思主义和人道主义等。收集的8篇论文围绕一个共同主题展开：反对对马克思主义作人道主义的解释，恢复作为科学的马克思主义的本来面目。', 'https://baike.baidu.com/item/保卫马克思', 'https://book.douban.com/subject/4735985/', '', 0, 0, 0, 11, 0, '1965', NULL, '2025-01-04 09:49:58', ''),
(1305, 'beijingfayuansi', 'liaozhi', '北京法源寺', '文集/李敖/北京法源寺', '', '', '', '', '', 0, '', '', '', 'liaozhi', 0, 1, 0, 0, 0, '', '2026-03-06 06:15:16', '2026-03-06 06:15:16', ''),
(568, 'beijudedansheng', '', '悲剧的诞生', '', '', '', 'books/学术名著/德国/尼采/悲剧的诞生', '', '德', 0, '《悲剧的诞生》（德文原名《悲剧从音乐精神中诞生》）是德国哲学家弗里德里希·威廉·尼采创作的哲学著作，写于1870—1871年，首次出版于1872年。该书以“致瓦格纳”为序言，下分25节，从论述希腊悲剧的诞生入手，展开对艺术和美学的看法。书中的思想深受叔本华和瓦格纳的影响，但克服了悲观主义，认为艺术不是对人生的解脱，而是对人生的征服。希腊悲剧是由于日神阿波罗精神与酒神狄奥尼索斯精神的对抗与调和而产生的，并以酒神精神为主导。书中已表现出将叔本华的生命意志转向权力意志的倾向，主张在悲剧的痛苦中感到一种更高的、征服的欢乐，看到生命是永恒的美。在《悲剧的诞生》一书中，尼采所表达的悲剧艺术观念：第一，艺术是对梦境的模仿，悲剧艺术代表希腊人对生活的理解和体验。第二，艺术欢乐源于酒神狂醉的忘我体验。人们在悲剧合唱队里获得个体生命消失的体验，实现了对终极命运的消解。第三，希腊悲剧是阿波罗形象与狄俄涅索斯精神的结合物，阿波罗形象是希腊悲剧的舞台形式，狄俄涅索斯精神则是希腊悲剧要表现的思想内容。第四，悲剧的功能在于以审美的态度对待人生，获得暂时的解脱。', 'https://baike.baidu.com/item/悲剧的诞生/7585545', 'https://book.douban.com/subject/3765393/', '', 0, 0, 0, 11, 0, '1872', NULL, '2025-01-04 09:49:58', ''),
