INSERT INTO `wp_figure` (`id`, `code`, `name`, `name_card`, `country_code`, `native_place`, `native_place_history`, `description`, `baidu_url`, `path_label`, `path_gather`, `path_point`, `status`, `birth_accurate`, `birth_year`, `birth_month`, `birth_day`, `death_accurate`, `death_year`, `death_month`, `death_day`, `active_at`, `baidu_picture`, `extfield`, `path_old`, `dynasty`, `nationality`, `era`, `codebak`) VALUES
(1, 'luxun', '鲁迅', '周树人', 'cn', '', '', '著名文学家、思想家、革命家、教育家、民主战士，新文化运动的重要参与者，中国现代文学的奠基人。', 'https://baike.baidu.com/item/鲁迅/36231', '', '', '中国/鲁迅/base', 1, '', 1881, 9, 25, '', 1936, 10, 19, 0, '', '1881-1936年 55岁', 'figure/鲁迅/home', '', '中国', 'modern', 'luxun'),
(2, 'russell', '罗素', '伯特兰·阿瑟·威廉·罗素', 'gb', '', '', '英国哲学家、数学\r\n家、逻辑学家、历史学家、文学家，分析哲学的主要创始人，世界和平运动的倡导者和组织者。', 'https://baike.baidu.com/item/伯特兰·阿瑟·威廉·罗素/2131980', '', '', '', 1, '', 1872, 5, 18, '', 1970, 2, 2, 0, '', '1872/5/18-1970/2/2 (98岁)', 'books/学术名著/英国/罗素/figure', '', '英国', '', 'luosu'),
(3, 'guzhun', '顾准', '顾准', 'cn', '', '', '中国当代学者，思想家，经济学家，会计学家，历史学家。提出中国社会主义市场经济理论的第一人。', 'https://baike.baidu.com/item/顾准/420201', '', '', '', 1, '', 1915, 7, 1, '', 1974, 12, 3, 0, '', '1915/7/1-1974/12/3 (59岁)', 'books/学术名著/中国/顾准/figure', '', '中国', 'contemporary', 'guzhun'),
(4, 'stavrianos', '斯塔夫里阿诺斯', '勒芬·斯塔夫罗斯·斯塔夫里阿诺斯', 'us', '', '', '希腊族，美国学者、教授、历史学家。', 'https://baike.baidu.com/item/勒芬·斯塔夫罗斯·斯塔夫里阿诺斯', '', '', '', 1, '', 1913, 2, 5, '', 2004, 3, 23, 0, '', '1913-2004/3/23 (91岁)', 'books/学术名著/美国/斯塔夫里阿诺斯/figure', '', '美国', '', 'sitafulianuosi'),
(5, 'zhaopuchu', '赵朴初', '赵朴初', 'cn', '', '', '中国人民政治协>商会议第九届全国委员会副主席，中国民主促进会中央名誉主席，曾任中国佛教协会会长，著名的社会活动家、杰出的爱国宗教领袖、中国共产党的亲密朋友，中国民主促进会的创始人之一。', 'https://baike.baidu.com/item/赵朴初', '', '', '', 9, '', 1907, 11, 5, '', 2000, 5, 21, 0, '', '', '', '', '中国', 'contemporary', 'zhaopuchu'),
(6, 'fengyoulan', '冯友兰', '冯友兰', 'cn', '', '', '1918年，毕业于\r\n北京大学哲学系。1924年，获美国哥伦比亚大学哲学博士学位，师从约翰·杜威。 [1-2]  回国后，历任清华大学教授、哲学系主任、文学院院长，西南联合大学教授、文学院院长；第四届全国人大代表，第二>至四届政协委员，第六至七届全国政协常委，取得美国普林斯顿大学、印度德里大学、美国哥伦比亚大学名誉文学博士。 [3]  著有《中国哲学史》《中国哲学简史》《中国哲学史新编》《贞元六书》等，成为20世纪中国学术的重要经典，对中国现当代学界乃至国外学界影响深远，称誉为“现代新儒家” 。', 'https://baike.baidu.com/item/冯友兰/119755', '', '', '', 9, '', 1895, 12, 4, '', 1990, 11, 26, 0, '', '', '', '', '中国', 'contemporary', 'fengyoulan'),
(7, 'telier', '特里尔', '罗斯·特里尔', 'us', '', '', '罗斯特里尔，1938年出生于>澳大利亚，毕业于澳大利亚墨尔本大学，获得历史政治科学一级荣誉学位，1970年获得哈佛大学政治学博士学位。2008年被任命为华盛顿伍德罗·威尔逊中心公共政策学者。', 'https://baike.baidu.com/item/罗斯特里尔', '', '', '', 9, '', 1938, 1, 1, 'running', 0, 0, 0, 0, '', '', '', '', '美国', '', 'telier'),
(8, 'wangfuren', '王富仁', '王富仁', 'cn', '', '', '著名学者，1941年生，山东高>唐县人。中共党员。毕业于山东大学外文系。著名学者、中国现代文学研究会原会长、北京师范大学文学院教授、汕头大学文学院终身教授。', 'https://baike.baidu.com/item/王富仁', '', '', '', 9, '', 1941, 1, 1, '', 2017, 5, 2, 0, '', '', '', '', '中国', '', 'wangfuren'),
(9, 'simaqian', '司马迁', '司马迁', 'xihan', '', '', '伟大的史学家、文学家、思想家。其著作《史记》被鲁迅誉为“史家之绝唱，无韵之离骚”。', 'https://baike.baidu.com/item/司马迁/65648', '思想文化', '', '', 9, 'probably', -145, 1, 1, 'unknown', 0, 0, 0, 0, '', '', '', '', '中国', '', 'simaqian'),
(10, 'caoxueqin', '曹雪芹', '曹雪芹', 'qingchao', '', '', '清朝小说家、诗人、画家。《红楼梦》是曹雪芹对中国文学和中国文化的伟大贡献。', 'https://baike.baidu.com/item/曹雪芹/14919', '', '', '', 1, 'probably', 1715, 5, 28, 'probably', 1763, 2, 12, 0, '', '约1715/5/28-约1763/2/12 (48岁)', '', '', '中国', '', 'caoxueqin'),
(11, 'kafka', '卡夫卡', '弗兰兹·卡夫卡', 'at', '', '', '奥匈帝国捷克德语小说家，本职为保险业职员。西方现代主义文学的先驱和大师。', 'https://baike.baidu.com/item/弗兰兹·卡夫卡/26831', '', '', '', 1, '', 1883, 7, 3, '', 1924, 6, 3, 0, '', '1883/7/3-1924/6/3 (41岁)', 'books/名家名作/卡夫卡/figure', '', '奥地利', '', 'kafka'),
(13, 'maozedong', '毛泽东', '毛泽东', 'cn', '湖南湘潭', '', '伟大的马克思主义者，伟大的无产阶级革命家、战略家、理论家，中国共产党、中国人民解放军和中华人民共和国的主要缔造者和领导人。', 'https://baike.baidu.com/item/毛泽东/113835', '', '', '中国/毛泽东/base', 9, '', 1893, 12, 26, '', 1976, 9, 9, 0, 'https://bkimg.cdn.bcebos.com/smart/0eb30f2442a7d933c8955cc8ee17c61373f08202ab4e-bkimg-process', '', '', '', '中国', '', 'maozedong'),
(14, 'wuchucai', '吴楚材', '吴楚材', 'cn', '', '', '名乘权，字子舆，号楚材，浙江\r\n山阴州山（今绍兴）人。幼受家教，勤奋好学。16岁时，患足疾，一病数年，仍手不释卷。疾愈，学问大进，在家设馆授徒。曾多次应考，但屡试不中。与侄吴调侯共同编成《古文观止》一书。', 'https://baike.baidu.com/item/吴楚材/5465602', '', '', '', 9, '', 1655, 0, 0, '', 1719, 0, 0, 0, '', '', '', '', '中国', '', 'wuchucai'),
(15, 'grosse', '格罗塞', '格罗塞', 'de', '', '', '德国艺术史家、社会学家，现代艺术社会学奠基人之一，对马克思主义美学也有重要启发。', 'https://baike.baidu.com/item/格罗塞/1544679', '', '', '', 1, '', 1862, 0, 0, '', 1927, 0, 0, 0, '', '1862-1927 (65岁)', 'books/学术名著/德国/格罗塞/figure', '', '德国', '', 'geluose'),
(16, 'weber', '韦伯', '马克斯·韦伯', 'de', '', '', '德国社会学家、历史学家、政治学家、经济学家、哲学家，现代西方一位极具影响力的思想家，与卡尔·马克思和埃米尔·杜尔凯姆并称为社会学的三大奠基人。', 'https://baike.baidu.com/item/马克斯·韦伯/955480', '', '', '', 1, '', 1864, 4, 21, '', 1920, 6, 14, 0, '', '1864/4/21-1920/6/14 (54岁)', 'books/学术名著/德国/韦伯/figure', '', '德国', '', 'weibo'),
(17, 'fichte', '费希特', '约翰·戈特利布·费希特', 'de', '', '', '德国作家、哲学家、爱国主义者，古典主义哲学的主要代表人之一。', 'https://baike.baidu.com/item/约翰·戈特利布·费希特/6616528', '', '', '', 1, '', 1762, 5, 19, '', 1814, 1, 27, 0, '', '1762/5/19-1814/1/27 (52岁)', 'books/学术名著/德国/费希特/figure', '', '德国', '', 'feixite'),
(18, 'weitling', '魏特林', '威廉·魏特林', 'de', '', '', '19世纪的欧洲中一个重要的激进主义者。魏特林曾被马克思和恩格斯评价为空想社会主义者，同时恩格斯也认为他是“德国共产主义的创始人”。', 'https://baike.baidu.com/item/威廉·魏特林/9058762', '', '', '', 1, '', 1808, 10, 5, '', 1871, 1, 24, 0, '', '1808/10/5-1871/1/24 (63岁)', 'books/学术名著/德国/魏特林/figure', '', '德国', '', 'weitelin'),
(19, 'dahrendorf', '达伦多夫', '拉尔夫·达伦多夫', 'de', '', '', '德国社会学家、思想家，政治家。一代自由主义思想巨人。', 'https://baike.baidu.com/item/达伦多夫/10779395', '', '', '', 1, '', 1929, 0, 0, '', 2009, 6, 17, 0, '', '1929-2009/6/17 (80岁)', 'books/学术名著/德国/达伦多夫/figure', '', '德国', '', 'darendaofu'),
(20, 'hegel', '黑格尔', '格奥尔格·威廉·弗里德里希·黑格尔', 'de', '', '', '德国19世纪唯心主义哲学的代表人物之一、德国古典哲学的代表人物之一。', 'https://baike.baidu.com/item/格奥尔格·威廉·弗里德里希·黑格尔/9442291', '', '', '', 1, '', 1770, 8, 27, '', 1831, 11, 14, 0, '', '1770/8/27-1831/11/14 (61岁)', 'books/学术名著/德国/黑格尔/figure', '', '德国', '', 'heigeer'),
(21, 'heisenberg', '海森堡', '沃纳·海森堡', 'de', '', '', '德国著名物理学家，量子力学的主要创始人，哥本哈根学派的代表人物，1932年诺贝尔物理学奖获得者。', 'https://baike.baidu.com/item/沃纳·海森堡/972614', '', '', '', 1, '', 1901, 12, 5, '', 1976, 2, 1, 0, '', '1901/12/5-1976/2/1 (75岁)', 'books/学术名著/德国/海森堡/figure', '', '德国', '', 'haisenbo'),
(23, 'kant', '康德', '伊曼努尔·康德', 'de', '', '', '德国古典哲学创始人，西方最具影响力的思想家之一。', 'https://baike.baidu.com/item/伊曼努尔·康德/2631177', '', '', '', 1, '', 1724, 4, 22, '', 1804, 2, 12, 0, '', '1724/4/22-1804/2/12 (70岁)', 'books/学术名著/德国/康德/figure', '', '德国', '', 'kangde'),
(24, 'feuerbach', '费尔巴哈', '路德维希·安德列斯·费尔巴哈', 'de', '', '', '德国哲学家，对卡尔·马克思的影响也很大。', 'https://baike.baidu.com/item/路德维希·安德列斯·费尔巴哈/833590', '', '', '', 1, '', 1804, 7, 28, '', 1872, 9, 13, 0, '', '1804/7/28-1872/9/13 (68岁)', 'books/学术名著/德国/费尔巴哈/figure', '', '德国', '', 'feierbaha'),
(25, 'koffka', '考夫卡', '库尔特·考夫卡', 'us', '', '', '美籍德裔心理学家，格式塔心理学的代表人物之一，在儿童生理发展、记忆论和人格学说方面作了杰出贡献。', 'https://baike.baidu.com/item/库尔特·考夫卡/16171492', '', '', '', 1, '', 1886, 3, 18, '', 1941, 11, 22, 0, '', '1886/3/18-1941/11/22 (55岁)', 'books/学术名著/美国/考夫卡/figure', '', '美国', '', 'kaofuka'),
(26, 'mainzer', '迈因策尔', '克劳斯·迈因策尔', 'de', '', '', '研究领域是数学、物理学和哲学。', '', '', '', '', 1, '', 1947, 0, 0, 'running', 0, 0, 0, 0, '', '1947-', 'books/学术名著/德国/迈因策尔/figure', '', '德国', '', 'maiyinceer'),
(27, 'list', '李斯特', '弗里德里希·李斯特', 'de', '', '', '古典经济学的怀疑者和批判者，是德国历史学派的先驱者。', 'https://baike.baidu.com/item/弗里德里希·李斯特/2406784', '', '', '', 1, '', 1789, 0, 0, '', 1846, 0, 0, 0, '', '1789-1846 (57岁)', 'books/学术名著/德国/李斯特/figure', '', '德国', '', 'lisite'),
(28, 'cassirer', '卡西尔', '恩斯特·卡西尔', 'de', '', '', '德国哲学家、文化哲学创始人。新康德主义的马堡学派主要代表人物，“马堡学派的集大成者”。', 'https://baike.baidu.com/item/恩斯特·卡西尔/5746152', '', '', '', 1, '', 1874, 7, 28, '', 1945, 4, 13, 0, '', '1874/7/28-1945/4/13 (71岁)', 'books/学术名著/德国/卡西尔/figure', '', '德国', '', 'kaxier'),
(29, 'schlick', '石里克', '摩里兹·石里克', 'de', '', '', '德国作家、哲学家，维也纳学派和逻辑实证主义的创始人，属于分析哲学学派。', 'https://baike.baidu.com/item/摩里兹·石里克/5742356', '', '', '', 1, '', 1882, 4, 14, '', 1936, 6, 22, 0, '', '1882/4/14-1936/6/22 (54岁)', 'books/学术名著/德国/石里克/figure', '', '德国', '', 'shilike'),
(30, 'montesquieu', '孟德斯鸠', '查理·路易·孟德斯鸠', 'fr', '', '', '法国启蒙思想家、法学家。孟德斯鸠不仅是18世纪法国启蒙时代的著名思想家，也是近代欧洲国家比较早的系统研究古代东方社会与法律文化的学者之一。', 'https://baike.baidu.com/item/查理·路易·孟德斯鸠/8393747', '', '', '', 1, '', 1689, 1, 18, '', 1755, 2, 10, 0, '', '1689/1/18-1755/2/10 (66岁)', 'books/学术名著/法国/孟德斯鸠/figure', '', '法国', '', 'mengdesijiu'),
(31, 'sieyes', '西耶斯', '西耶斯', 'fr', '', '', '对法国的《人权宣言》的制定产生了重要影响。西耶斯出生在一个政府职员家庭，早年在巴黎大学接受神学教育，成为神甫和修道院院长。尽管从职业上看，他是一名神职人员，但他对哲学、政治经济学有着浓厚的兴趣，具有激进的改革思想，>出于改革的热情，他发表了一系列文章和小册子宣传改革的思想，因此当选为当时法国三级会议第三等级的代表。', 'https://baike.baidu.com/item/西耶斯/24114154', '', '', '', 1, '', 1748, 0, 0, '', 1836, 0, 0, 0, '', '', 'books/学术名著/法国/西耶斯/figure', '', '法国', '', 'xiyesi'),
(32, 'leroux', '勒鲁', '皮埃尔·勒鲁', 'fr', '', '', '十九世纪法国著名的哲学家、小资产阶级空想社会主义者。', 'https://baike.baidu.com/item/皮埃尔·勒鲁', '', '', '', 1, '', 1797, 0, 0, '', 1871, 0, 0, 0, '', '1797-1871 (74岁)', 'books/学术名著/法国/勒鲁/figure', '', '法国', '', 'lelu'),
(33, 'grousset', '格鲁塞', '勒内·格鲁塞', 'fr', '', '', '法国著名历史学家，亚洲史研究界的泰斗，以研究中亚和远东著称。', 'https://baike.baidu.com/item/勒内·格鲁塞', '', '', '', 1, '', 1885, 0, 0, '', 1952, 0, 0, 0, '', '1885-1952 (67岁)', 'books/学术名著/法国/格鲁塞/figure', '', '法国', '', 'geluse'),
(34, 'tigar', '泰格', '迈克尔·E·泰格', 'us', '', '', '美国华盛顿大学法学院的研究员和“埃德温·A莫尔斯学者”，他的研究领域涉及比较法、宪法法律、美国最高法院、法国的法律制度、刑法和刑事诉讼法及人权方面。', '', '', '', '', 1, '', 1941, 0, 0, '', 0, 0, 0, 0, '', '1941-', 'books/学术名著/美国/泰格/figure', '', '美国', '', 'taige'),
(35, 'rousseau', '卢梭', '让-雅克·卢梭', 'fr', '', '', '法国十八世纪启蒙思想家、哲学家、教育家、文学家，民主政论家和浪漫主义文学流派的开创者，启蒙运动代表人物之一。', 'https://baike.baidu.com/item/让-雅克·卢梭/7169222', '', '', '', 1, '', 1712, 6, 28, '', 1778, 7, 2, 0, '', '1712/6/28-1778/7/2 (66岁)', 'books/学术名著/法国/卢梭/figure', '', '法国', '', 'lusuo'),
(36, 'napoleon', '拿破仑', '拿破仑·波拿巴', 'fr', '', '', '著名的军事家、政治家、革命家、战略家、征服者，历任法兰西第一共和国第一执政（1799年—1804年），法兰西第一帝国皇帝（1804年5月18日—1815年6月23日）。', 'https://baike.baidu.com/item/拿破仑·波拿巴/173319', '', '', '', 1, '', 1769, 8, 15, '', 1821, 5, 5, 0, '', '1769/8/15-1821/5/5 (52岁)', 'books/学术名著/法国/拿破仑/figure', '', '法国', '', 'napolundeng'),
(37, 'einhard', '艾因哈德', '艾因哈德', 'fr', '', '', '法兰克王国历史学家、政治活动家。是法兰克王国、也是中世纪欧洲最著名的传记家，是查理曼帝国时期所谓加洛林文艺复兴的代表人物之一。', 'https://baike.baidu.com/item/艾因哈德', '', '', '', 1, '', 770, 0, 0, '', 840, 0, 0, 0, '', '770-840 (70岁)', 'books/学术名著/法国/艾因哈德/figure', '', '法国', '', 'yiyinhade'),
(38, 'dezamy', '德萨米', '泰·德萨米', 'fr', '', '', '19世纪法国的空想共产主义者。', 'https://baike.baidu.com/item/德萨米/6402705', '', '', '', 1, '', 1803, 0, 0, '', 1850, 0, 0, 0, '', '1803-1850 (47岁)', 'books/学术名著/法国/德萨米/figure', '', '法国', '', 'desami'),
(39, 'holbach', '霍尔巴赫', '保尔·霍尔巴赫', 'fr', '', '', '十八世纪法国启蒙思想家，哲学家。', 'https://baike.baidu.com/item/霍尔巴赫', '', '', '', 1, '', 1723, 0, 0, '', 1789, 0, 0, 0, '', '1723-1789 (66岁)', 'books/学术名著/法国/霍尔巴赫/figure', '', '法国', '', 'huoerbahe'),
(40, 'pascal', '帕斯卡', '布莱士·帕斯卡', 'fr', '', '', '法国数学家、物理学家、哲学家、散文家。后人为纪念帕斯卡，用他的名字来命名压强的单位“帕斯卡”，简称“帕”。', 'https://baike.baidu.com/item/布莱士·帕斯卡/8791342', '', '', '', 1, '', 1623, 6, 19, '', 1662, 8, 19, 0, '', '1623/6/19-1662/8/19 (39岁)', 'books/学术名著/法国/帕斯卡/figure', '', '法国', '', 'pasikaer'),
(41, 'constant', '贡斯当', '邦雅曼·贡斯当', 'fr', '', '', '法国文学家和政治思想家，近代自由主义的奠基者之一。', 'https://baike.baidu.com/item/邦雅曼·贡斯当/8981409', '', '', '', 1, '', 1767, 10, 25, '', 1830, 12, 8, 0, '', '1767/10/25-1830/12/8 (63岁)', 'books/学术名著/法国/贡斯当/figure', '', '法国', '', 'gongsidang'),
(42, 'foucault', '福柯', '米歇尔·福柯', 'fr', '', '', '法国哲学家、社会思想家和“思想系统的历史学家”，法兰西学院思想体系史教授。', 'https://baike.baidu.com/item/米歇尔·福柯/576152', '', '', '', 1, '', 1926, 10, 15, '', 1984, 6, 25, 0, '', '1926/10/15-1984/6/25 (58岁)', 'books/学术名著/法国/福柯/figure', '', '法国', '', 'fuke'),
(43, 'tocqueville', '托克维尔', '阿历克西·德·托克维尔', 'fr', '', '', '法国历史学家、政治家和社会学（政治社会学）的奠基人。', 'https://baike.baidu.com/item/阿历克西·德·托克维尔/16342236', '', '', '', 1, '', 1805, 7, 29, '', 1859, 4, 16, 0, '', '1805/7/29-1859/4/16 (54岁)', 'books/学术名著/法国/托克维尔/figure', '', '法国', '', 'tuokeweier'),
(45, 'morelly', '摩莱里', '摩莱里', 'fr', '', '', '十八世纪法国杰出的思想家。法国学术史上最神秘的人物之一，一生写了许多著作，但都用不同的笔名发表，“摩莱里”是他笔名，真实名字不详。', 'https://baike.baidu.com/item/摩莱里', '', '', '', 1, 'probably', 1700, 0, 0, '', 1780, 0, 0, 0, '', '约1700-1780 (80岁)', 'books/学术名著/法国/摩莱里/figure', '', '法国', '', 'molaili'),
(47, 'descartes', '笛卡尔', '勒内·笛卡尔', 'fr', '', '', '法国哲学家、数学家、物理学家，解析几何之父。西方现代哲学思想的奠基人之一，是近代唯心论的开拓者，为欧洲的“理性主义”哲学奠定了基础。', 'https://baike.baidu.com/item/笛卡尔/85475', '', '', '', 1, '', 1596, 3, 31, '', 1650, 2, 11, 0, '', '1596/3/31-1650/2/11 (54岁)', 'books/学术名著/法国/笛卡尔/figure', '', '法国', '', 'dikaer'),
(48, 'prigogine', '普里戈金', '伊利亚·普里戈金', 'be', '', '', '比利时物理化学家，布鲁塞尔学派的首领，荣获1977年诺贝尔化学奖，非平衡态统计物理与耗散结构理论奠基人。', 'https://baike.baidu.com/item/伊利亚·普里高津/8722261', '', '', '', 1, '', 1917, 1, 25, '', 2003, 5, 28, 0, '', '1917/1/25-2003/5/28 (86岁)', 'books/学术名著/其他国家/比利时/普里戈金/figure', '', '比利时', '', 'puligaojin'),
(49, 'blanqui', '布朗基', '路易·奥古斯特·布朗基', 'fr', '', '', '法国早期工人运动活动家、革命家、早期共产主义者（与圣西门等人的社会主义不同），巴黎公社的传奇人物，巴黎公社议会主席。', 'https://baike.baidu.com/item/路易·奥古斯特·布朗基/8372144', '', '', '', 1, '', 1805, 2, 1, '', 1881, 1, 1, 0, '', '1805/2/1-1881/1/1 (75岁)', 'books/学术名著/法国/布朗基/figure', '', '法国', '', 'bulangji'),
(51, 'condorcet', '孔多塞', '马奎斯·孔多塞', 'fr', '', '', '18世纪法国启蒙运动时期最杰出的代表之一，同时也是一位数学家和哲学家。1782年当选法兰西科学院院士。', 'https://baike.baidu.com/item/马奎斯·孔多塞/19283061', '', '', '', 1, '', 1743, 9, 17, '', 1794, 3, 28, 0, '', '1743/9/17-1794/3/28 (51岁)', 'books/学术名著/法国/孔多塞/figure', '', '法国', '', 'kongduose'),
(52, 'proudhon', '蒲鲁东', '皮埃尔-约瑟夫·蒲鲁东', 'fr', '', '', '法国政论家，经济学家，小资产阶级社会主义者，无政府主义奠基人之一。', 'https://baike.baidu.com/item/皮埃尔-约瑟夫·蒲鲁东/9128144', '', '', '', 1, '', 1809, 1, 15, '', 1865, 1, 19, 0, '', '1809/1/15-1865/1/19 (56岁)', 'books/学术名著/法国/蒲鲁东/figure', '', '法国', '', 'puludong'),
(53, 'gassendi', '伽森狄', '伽森狄', 'fr', '', '', '法国哲学家，物理学家，天文学家。', 'https://baike.baidu.com/item/伽森狄', '', '', '', 1, '', 1592, 0, 0, '', 1655, 0, 0, 0, '', '1592-1655 (63岁)', 'books/学术名著/法国/伽森狄/figure', '', '法国', '', 'jiasendi'),
(54, 'lebon', '勒庞', '古斯塔夫·勒庞', 'fr', '', '', '法国社会心理学家、社会学家、物理学家，群体心理学的创始人，有“群体社会的马基雅维里”之称。', 'https://baike.baidu.com/item/古斯塔夫·勒庞', '', '', '', 1, '', 1841, 5, 7, '', 1931, 12, 13, 0, '', '1841/5/7-1931/12/13 (90岁)', 'books/学术名著/法国/勒庞/figure', '', '法国', '', 'lepang'),
(55, 'mettrie', '梅特里', '朱里安·奥弗鲁·德·拉·梅特里', 'fr', '', '', '18世纪法国启蒙思想家、哲学家、无神论者、医生。', '', '', '', '', 1, '', 1709, 0, 0, '', 1751, 11, 11, 0, '', '1709-1751 (42岁)', 'books/学术名著/法国/梅特里/figure', '', '法国', '', 'meiteli'),
(56, 'myrdal', '缪达尔', '纲纳·缪达尔', 'se', '', '', '瑞典学派和新制度学派以及发展经济学的主要代表人物之一。', 'https://baike.baidu.com/item/纲纳·缪达尔/6237481', '', '', '', 1, '', 1898, 12, 6, '', 1987, 5, 17, 0, '', '1898/12/6-1987/5/17 (89岁)', 'books/学术名著/其他国家/瑞典/缪达尔/figure', '', '瑞典', '', 'muerdaer'),
(57, 'kropotkin', '克鲁泡特金', '彼得·阿历克塞维奇·克鲁泡特金', 'ru', '', '', '俄国地理学家、无政府主义运动的最高精神领袖和理论家。罗曼·罗兰以著名的格言对他作出评价：“托尔斯泰追求的理想，被他在生活中实践了。”', 'https://baike.baidu.com/item/彼得·阿历克塞维奇·克鲁泡特金/3486797', '', '', '', 1, '', 1842, 12, 9, '', 1921, 2, 8, 0, '', '1842/12/9-1921/2/8 (79岁)', 'books/学术名著/俄罗斯/克鲁泡特金/figure', '', '俄罗斯', '', 'kelupaotejin'),
(58, 'tacitus', '塔西佗', '普布利乌斯·科尔涅利乌斯·塔西陀', 'rome', '', '', '罗马帝国时代著名的历史学家、文学家和演说家，古代杰出的历史学家之一。', 'https://baike.baidu.com/item/普布利乌斯·科尔涅利乌斯·塔西陀/10841608', '', '', '', 9, '', 56, 0, 0, '', 120, 0, 0, 0, '', '', 'books/学术名著/其他国家/罗马/塔西佗/figure', '', '罗马', '', 'taxituo'),
(59, 'croce', '克罗齐', '贝奈戴托·克罗齐', 'it', '', '', '意大利著名文艺批评家、历史学家、哲学家，有时也被认为是政治家。', 'https://baike.baidu.com/item/贝奈戴托·克罗齐/1894470', '', '', '', 1, '', 1866, 2, 25, '', 1952, 11, 20, 0, '', '1866/2/25-1952/11/20 (86岁)', 'books/学术名著/意大利/克罗齐/figure', '', '意大利', '', 'keluoqi'),
(60, 'fukuzawa', '福泽谕吉', '福泽谕吉', 'jp', '', '', '日本近代著名启蒙思想家、明治时期杰出的教育家、日本近代第一位军国主义理论家、日本著名私立大学庆应义塾大学的创立者。', 'https://baike.baidu.com/item/福泽谕吉/1137850', '', '', '', 1, '', 1835, 1, 10, '', 1901, 2, 3, 0, '', '1835/1/10-1901/2/3 (66岁)', 'books/学术名著/其他国家/日本/福泽谕吉/figure', '', '日本', '', 'fuzeyuji'),
(61, 'aristotle', '亚里士多德', '亚里士多德', 'ancientgreek', '', '', '百科全书式的古希腊哲学家、科学家、教育家。', 'https://baike.baidu.com/item/亚里士多德/26769', '', '', '', 1, '', -384, 0, 0, '', -322, 3, 7, 0, '', '前384年-前322/3/7 (62岁)', 'books/学术名著/其他国家/古希腊/亚里士多德/figure', '', '古希腊', '', 'yalishiduode'),
(62, 'spinoza', '斯宾诺莎', '巴鲁赫·斯宾诺莎', 'nl', '', '', '荷兰犹太人，近代西方哲学的三大理性主义者之一，与笛卡尔和莱布尼茨齐名。', 'https://baike.baidu.com/item/巴鲁赫·斯宾诺莎/2628210', '', '', '', 1, '', 1632, 11, 24, '', 1677, 2, 21, 0, '', '1632/11/24-1677/2/21 (45岁)', 'books/学术名著/其他国家/荷兰/斯宾诺莎/figure', '', '荷兰', '', 'sibinnuosha'),
(63, 'augustine', '奥古斯丁', '圣奥古斯丁', 'rome', '', '', '古罗马帝国时期天主教思想家，其思想影响了西方基督教教会和西方哲学的发展，并间接影响了整个西方基督教会。', 'https://baike.baidu.com/item/奥古斯丁/81851', '', '', '', 9, '', 354, 11, 13, '', 430, 8, 28, 0, '', '', 'books/学术名著/其他国家/罗马/奥古斯丁/figure', '', '罗马', '', 'aogusiding'),
(65, 'wittgenstein', '维特根斯坦', '路德维希·维特根斯坦', 'gb', '', '', '出生于奥地利，后入英国籍。哲学家、数理逻辑学家。语言哲学的奠基人，20世纪最有影响的哲学家之一。', 'https://baike.baidu.com/item/路德维希·维特根斯坦/3209559', '', '', '', 1, '', 1889, 4, 26, '', 1951, 4, 29, 0, '', '1889/4/26-1951/4/29 (62岁)', 'books/学术名著/英国/维特根斯坦/figure', '', '英国', '', 'weitegensitan'),
(66, 'plato', '柏拉图', '柏拉图', 'ancientgreek', '', '', '古希腊伟大的哲学家、思想家、教育家、数学家', 'https://baike.baidu.com/item/柏拉图/85471', '', '', '', 1, '', -427, 0, 0, '', -347, 0, 0, 0, '', '前427-前347年(80岁)', 'books/学术名著/其他国家/古希腊/柏拉图/figure', '', '古希腊', '', 'bolatu'),
(67, 'bertalanffy', '贝塔朗菲', '路德维希·冯·贝塔朗菲', 'us', '', '', '美籍奥地利理论生物学家和哲学家。创立了20世纪具有深远意义的一般系统论。', 'https://baike.baidu.com/item/路德维希·冯·贝塔朗菲/10911252', '', '', '', 1, '', 1901, 9, 19, '', 1972, 6, 12, 0, '', '1901/9/19-1972 (71岁)', 'books/学术名著/美国/贝塔朗菲/figure', '', '美国', '', 'beitalangfei'),
(68, 'laszlo', '拉兹洛', '欧文·拉兹洛', 'hu', '', '', '时代的最前沿的思想家和科学家之一。曾任布达佩斯俱乐部基金会（匈牙利）和国际布达佩斯俱乐部（英国）主席。', 'https://baike.baidu.com/item/欧文·拉兹洛/8895365', '', '', '', 1, '', 1932, 0, 0, 'running', 0, 0, 0, 0, '', '', 'books/学术名著/其他国家/匈牙利/拉兹洛/figure', '', '匈牙利', '', 'laziluo'),
(69, 'burckhardt', '布克哈特', '雅各布·布克哈特', 'ch', '', '', '19世纪瑞士著名文化艺术史学家，致力于欧洲文化史研究，以期更开阔的视野来展现欧洲各个历史时期的文化特征与时代风貌。', 'https://baike.baidu.com/item/布克哈特/19175372', '', '', '', 1, '', 1818, 1, 25, '', 1897, 8, 8, 0, '', '1818-1897 (81岁)', 'books/学术名著/其他国家/瑞士/布克哈特/figure', '', '瑞士', '', 'bukehate'),
(70, 'crispus', '撒路斯提乌斯', '撒路斯提乌斯', 'rome', '', '', '罗马政治家和历史学家。', 'https://baike.baidu.com/item/撒路斯提乌斯', '', '', '', 9, '', -86, 0, 0, '', -35, 0, 0, 0, '', '', 'books/学术名著/其他国家/罗马/撒路斯提乌斯/figure', '', '罗马', '', 'salusitiwusi'),
(71, 'xenophon', '色诺芬', '色诺芬', 'ancientgreek', '', '', '雅典人，历史学家，苏格拉底的弟子。他以记录当时的希腊历史、苏格拉底语录而著称。', 'https://baike.baidu.com/item/色诺芬', '', '', '', 1, 'probably', -440, 0, 0, '', -355, 0, 0, 0, '', '约前440-前355 (85岁)', 'books/学术名著/其他国家/古希腊/色诺芬/figure', '', '古希腊', '', 'senuofen'),
(72, 'lustinianus', '查士丁尼', '查士丁尼', 'rome', '', '', '东罗马帝国皇帝（527年—565年），史称查士丁尼大帝。瓦西列夫概括为“一个帝国、一个教会和一部法典”。', 'https://baike.baidu.com/item/查士丁尼一世', '', '', '', 9, '', 482, 5, 5, '', 565, 11, 14, 0, '', '', 'books/学术名著/其他国家/罗马/查士丁尼/figure', '', '罗马', '', 'chashidingni'),
(73, 'havel', '哈维尔', '瓦茨拉夫·哈维尔', 'cz', '', '', '捷克剧作家、政治家、导演、编剧、演员。捷克斯洛伐克联邦共和国总统。', 'https://baike.baidu.com/item/瓦茨拉夫·哈维尔/7806945', '', '', '', 1, '', 1936, 10, 5, '', 2011, 12, 18, 0, '', '1936/10/5-2011/12/18 (75岁)', 'books/学术名著/其他国家/捷克/哈维尔/figure', '', '捷克', '', 'haweier'),
(74, 'suetoanius', '苏维托尼乌斯', '苏维托尼乌斯', 'rome', '', '', '罗马帝国早期的著名历史作家。', 'https://baike.baidu.com/item/苏维托尼乌斯', '', '', '', 9, '', 69, 0, 0, '', 122, 0, 0, 0, '', '', 'books/学术名著/其他国家/罗马/苏维托尼乌斯/figure', '', '罗马', '', 'suweituoniwusi'),
(75, 'jahanbegloo', '贾汉贝格鲁', '拉敏·贾汉贝格鲁', 'ir', '', '', '伊朗哲学家，曾任哈佛大学研究员，现任金达尔全球大学法学院副院长、圣雄甘地非暴力和平研究中心执行理事，2009年获西班牙联合国协会和平奖。', '', '', '', '', 9, '', 1956, 0, 0, 'running', 0, 0, 0, 0, '', '', 'books/学术名著/其他国家/伊朗/贾汉贝格鲁/figure', '', '伊朗', '', 'guhanbeigelu'),
(76, 'freud', '弗洛伊德', '西格蒙德·弗洛伊德', 'at', '', '', '奥地利精神病医师、心理学家、精神分析学派创始人。开创了潜意识研究的新领域，奠定了现代医学模式的新基础，为20世纪西方人文学科提供了重要理论支柱。', 'https://baike.baidu.com/item/西格蒙德·弗洛伊德/313363', '', '', '', 1, '', 1856, 5, 6, '', 1939, 9, 23, 0, '', '1856/5/6-1939/9/23 (83岁)', 'books/学术名著/其他国家/奥地利/弗洛伊德/figure', '', '奥地利', '', 'fuluoyide'),
(77, 'bohr', '玻尔', '尼尔斯·玻尔', 'dk', '', '', '理论物理学家，哥本哈根学派创始人，丹麦皇家科学院院士，1922年诺贝尔物理学奖获得者，俄罗斯科学院外国通讯院士，骑象勋爵，哥本哈根理论物理研究所所长。', 'https://baike.baidu.com/item/尼尔斯·玻尔/315310', '', '', '', 1, '', 1885, 10, 7, '', 1962, 11, 18, 0, '', '1885/10/7-1962/11/18 (77岁)', 'books/学术名著/其他国家/丹麦/玻尔/figure', '', '丹麦', '', 'boer'),
(78, 'jasay', '雅赛', '安东尼·德·雅赛', 'gb', '', '', '牛津大学纳菲尔德学院的经济学研究员。', 'https://baike.baidu.com/item/安东尼·德·雅赛', '', '', '', 1, '', 1925, 10, 15, '', 2019, 1, 23, 0, '', '1925/10/15-2019/1/23 (84岁)', 'books/学术名著/英国/雅赛/figure', '', '英国', '', 'yasai'),
(79, 'piaget', '皮亚杰', '让·皮亚杰', 'ch', '', '', '瑞士人，近代最有名的儿童心理学家。', 'https://baike.baidu.com/item/让·皮亚杰/8159030', '', '', '', 1, '', 1896, 8, 9, '', 1980, 9, 16, 0, '', '1896/8/9-1980/9/16 (84岁)', 'books/学术名著/其他国家/瑞士/皮亚杰/figure', '', '瑞士', '', 'piyajie'),
(80, 'mises', '米瑟斯', '路德维希·冯·米塞斯', 'at', '', '', '20世纪著名的经济学大师，自由主义思想家。奥地利学派第三代掌门人，朝圣山学社成员。', 'https://baike.baidu.com/item/路德维希·冯·米塞斯/6989913', '', '', '', 1, '', 1881, 9, 29, '', 1973, 10, 10, 0, '', '1881/9/29-1973/10/10 (92岁)', 'books/学术名著/其他国家/奥地利/米瑟斯/figure', '', '奥地利', '', 'misesi'),
(81, 'caesar', '凯撒', '盖乌斯·尤利乌斯·恺撒', 'rome', '', '', '史称恺撒大帝，罗马共和国末期杰出的军事统帅、政治家，并且以其优越的才能成为了罗马帝国的奠基者。', 'https://baike.baidu.com/item/盖乌斯·尤利乌斯·恺撒/4842994', '', '', '', 9, '', -100, 7, 13, '', -44, 3, 15, 0, '', '', 'books/学术名著/其他国家/罗马/凯撒/figure', '', '罗马', '', 'kaisa'),
(82, 'herzen', '赫尔岑', '亚历山大·伊万诺维奇·赫尔岑', 'ru', '', '', '俄国哲学家、作家、革命家。赫尔岑被称为俄国社会主义之父。', 'https://baike.baidu.com/item/赫尔岑', '', '', '', 1, '', 1812, 4, 6, '', 1870, 1, 21, 0, '', '1812/4/6-1870/1/21 (58岁)', 'books/学术名著/俄罗斯/赫尔岑/figure', '', '俄罗斯', '', 'heercen'),
(83, 'nitobeinazo', '新渡户稻造', '新渡户稻造', 'jp', '', '', '日本近代著名国际政治活动家、农学家、教育家。曾担任国际联盟副事务长，也是东京女子大学的创立者。', 'https://baike.baidu.com/item/新渡户稻造', '', '', '', 1, '', 1862, 9, 1, '', 1933, 10, 15, 0, '', '1862/9/1-1933/10/15 (71岁)', 'books/学术名著/其他国家/日本/新渡户稻造/figure', '', '日本', '', 'xinduhudaozao'),
(84, 'campanella', '康帕内拉', '托马斯·康帕内拉', 'it', '', '', '意大利文艺复兴时期的空想社会主义者、哲学家、作家。', 'https://baike.baidu.com/item/康帕内拉/2096456', '', '', '', 1, '', 1568, 9, 5, '', 1639, 5, 21, 0, '', '1568-1639 (71岁)', 'books/学术名著/意大利/康帕内拉/figure', '', '意大利', '', 'kangpaneila'),
(85, 'sina', '西拿', '伊本·西拿', 'arab', '', '', '十一世纪的大医学家、诗人、哲学家、自然科学家，被称为世界医学之父。', 'https://baike.baidu.com/item/伊本·西拿/6515867', '', '', '', 1, '', 980, 0, 0, '', 1037, 6, 18, 0, '', '980-1037/6/18 (57岁)', 'books/学术名著/其他国家/伊斯兰/西拿/figure', '', '阿拉伯', '', 'xina'),
(86, 'mach', '马赫', '恩斯特·马赫', 'at', '', '', '奥地利-捷克物理学家、心理学家和哲学家。马赫数和马赫带效应因其得名。马赫直接地影响了维也纳学派的逻辑实证主义。爱因斯坦誉其为相对论的先驱。', 'https://baike.baidu.com/item/恩斯特·马赫', '', '', '', 1, '', 1838, 2, 18, '', 1916, 2, 19, 0, '', '1838/2/18-1916/2/19 (78岁)', 'books/学术名著/其他国家/奥地利/马赫/figure', '', '奥地利', '', 'mahe'),
(87, 'machiavelli', '马基雅维利', '尼可罗·马基亚维利', 'it', '', '', '文艺复兴时期的一位巨人，第一个使政治学独立，同伦理学彻底分家的人，有“资产阶级政治学”奠基人之称，并且是历史学家、军事著作者、诗人和剧作家。', 'https://baike.baidu.com/item/尼可罗·马基亚维利/1117363', '', '', '', 1, '', 1469, 5, 3, '', 1527, 6, 21, 0, '', '1469/5/3-1527/6/21 (58岁)', 'books/学术名著/意大利/马基雅维利/figure', '', '意大利', '', 'majiyaweili'),
(88, 'hobsbawm', '霍布斯鲍姆', '艾瑞克·霍布斯鲍姆', 'gb', '', '', '英国当代马克思主义史学家，是享誉国际、备受推崇的左翼近代史大师。', 'https://baike.baidu.com/item/艾瑞克·霍布斯鲍姆/1790524', '', '', '', 1, '', 1917, 6, 9, '', 2012, 10, 1, 0, '', '1917-2012/10/1 (95岁)', 'books/学术名著/英国/霍布斯鲍姆/figure', '', '英国', '', 'huobusibaomu'),
(89, 'gray', '格雷', '约翰·格雷', 'gb', '', '', '英国的经济学家、空想社会主义者。', '', '', '', '', 1, '', 1798, 0, 0, '', 1850, 0, 0, 0, '', '1798-1850 (52岁)', 'books/学术名著/英国/格雷/figure', '', '英国', '', 'gelei'),
(90, 'maine', '梅因', '亨利·詹姆斯·萨姆那·梅因', 'gb', '', '', '19世纪英国著名的法律史学家，历史法学派在英国的代表人物，晚期历史法学派的集大成者。因其著作《古代法》而被西方学者公认为英国历史法学的创始人，在西方法学界影响颇大。', 'https://baike.baidu.com/item/梅因/11001234', '', '', '', 1, '', 1822, 8, 16, '', 1888, 0, 0, 0, '', '1822/8/16-1888 (66岁)', 'books/学术名著/英国/梅因/figure', '', '英国', '', 'meiyin'),
(91, 'lakatos', '拉卡托斯', '伊姆雷·拉卡托斯', 'hu', '', '', '匈牙利科学哲学家，拉卡托斯奖（Lakatos Award），是伦敦政经学院哲学系的奖项', 'https://baike.baidu.com/item/拉卡托斯', '', '', '', 1, 'probably', 1922, 0, 0, '', 1974, 0, 0, 0, '', '约1922-1974 (52岁)', 'books/学术名著/其他国家/匈牙利/拉卡托斯/figure', '', '匈牙利', '', 'lakatuosi'),
(92, 'darwin', '达尔文', '查尔斯·罗伯特·达尔文', 'gb', '', '', '英国生物学家，进化论的奠基人。达尔文的理论对人类学、心理学、哲学的发展都有不容忽视的影响。', 'https://baike.baidu.com/item/查尔斯·罗伯特·达尔文/82699', '', '', '', 1, '', 1809, 2, 12, '', 1882, 4, 19, 0, '', '1809/2/12-1882/4/19 (73岁)', 'books/学术名著/英国/达尔文/figure', '', '英国', '', 'daerwen'),
(93, 'giddens', '吉登斯', '安东尼·吉登斯', 'gb', '', '', '英国社会学家，是当今世界最重要的思想家之一，他对当代社会学领域作出了卓越的贡献，他是约翰·梅纳德·凯恩斯以来最有名的社会科学学者。', 'https://baike.baidu.com/item/安东尼·吉登斯/8005476', '', '', '', 1, '', 1938, 1, 18, 'running', 0, 0, 0, 0, '', '1938/1/18-', 'books/学术名著/英国/吉登斯/figure', '', '英国', '', 'jidengsi'),
(94, 'lewis', '刘易斯', '阿瑟·刘易斯', 'gb', '', '', '经济学家，作家，教授。在经济发展方面做出了开创性研究，深入研究了发展中国家在发展经济中应特别考虑的问题，于1979年获诺贝尔经济学奖。', 'https://baike.baidu.com/item/威廉·阿瑟·刘易斯/4822570', '', '', '', 1, '', 1915, 1, 23, '', 1991, 6, 15, 0, '', '1915/1/23-1991/6/15 (76岁)', 'books/学术名著/英国/刘易斯/figure', '', '英国', '', 'liuyisi'),
(96, 'milton', '弥尔顿', '约翰·弥尔顿', 'gb', '', '', '英国诗人、政论家，民主斗士。弥尔顿是英国历史上伟大的艺术家，被称为英国文学史上伟大的六位诗人之一。', 'https://baike.baidu.com/item/约翰·弥尔顿/918074', '', '', '', 1, '', 1608, 12, 9, '', 1674, 11, 8, 0, '', '1608/12/9-1674/11/8 (66岁)', 'books/学术名著/英国/弥尔顿/figure', '', '英国', '', 'mierdun'),
(97, 'hawking', '霍金', '斯蒂芬·威廉·霍金', 'gb', '', '', '理论物理学家、宇宙学家、科学思想家、英国皇家学会院士、美国国家科学院外籍院士、英国皇家学会工艺院院士。', 'https://baike.baidu.com/item/斯蒂芬·威廉·霍金/950423', '', '', '', 1, '', 1942, 1, 8, '', 2018, 3, 14, 0, '', '1942/1/8-2018/3/14 (76岁)', 'books/学术名著/英国/霍金/figure', '', '英国', '', 'huojin'),
(98, 'whitehead', '怀特海', '阿弗烈·诺夫·怀海德', 'gb', '', '', '英国数学家、哲学家和教育理论家，创立了20世纪最庞大的形而上学体系。“过程哲学”的创始人。', 'https://baike.baidu.com/item/阿弗烈·诺夫·怀海德/5746247', '', '', '', 1, '', 1861, 2, 15, '', 1947, 12, 30, 0, '', '1861/2/15-1947/12/30 (86岁)', 'books/学术名著/英国/怀特海/figure', '', '英国', '', 'huaitehai'),
(99, 'marshall', '马歇尔', '阿尔弗雷德·马歇尔', 'gb', '', '', '近代英国最著名的经济学家，新古典学派的创始人，剑桥大学经济学教授19世纪末和20世纪初英国经济学界最重要的人物。', 'https://baike.baidu.com/item/阿尔弗雷德·马歇尔/49526', '', '', '', 1, '', 1842, 7, 26, '', 1924, 7, 13, 0, '', '1842/7/26-1924/7/13 (82岁)', 'books/学术名著/英国/马歇尔/figure', '', '英国', '', 'maxieer'),
(100, 'mumby', '姆贝', '丹尼斯.姆贝', 'gb', '', '', '美国著名组织传播学学者，专注于批判理论、话语分析、权力与组织文化研究。', '', '', '', '', 1, 'unknown', 0, 0, 0, 'unknown', 0, 0, 0, 0, '', '', 'books/学术名著/英国/姆贝/figure', '', '英国', '', 'mubei'),
(101, 'hobbes', '霍布斯', '托马斯·霍布斯', 'gb', '', '', '英国政治家、哲学家。创立了机械唯物主义的完整体系，指出宇宙是所有机械地运动着的广延物体的总和。', 'https://baike.baidu.com/item/托马斯·霍布斯/3086013', '', '', '', 1, '', 1588, 4, 5, '', 1679, 12, 4, 0, '', '1588/4/5-1679/12/4 (91岁)', 'books/学术名著/英国/霍布斯/figure', '', '英国', '', 'huobusi'),
(102, 'popper', '波普尔', '卡尔·波普尔', 'at', '', '', '哲学家，批判理性主义的创始人。1965年，他经女王伊丽莎白二世获封爵位，1976年当选英国皇家科学院院士。', 'https://baike.baidu.com/item/卡尔·波普尔/2628746', '', '', '', 1, '', 1902, 7, 28, '', 1994, 9, 17, 0, '', '1902/7/28-1994/9/17 (92岁)', 'books/学术名著/其他国家/奥地利/波普尔/figure', '', '奥地利', '', 'bopuer'),
(103, 'locke', '洛克', '约翰·洛克', 'gb', '', '', '哲学家、医生，英国最早的经验主义者之一。最有影响力的一个启蒙思想家、 自由主义之父。', 'https://baike.baidu.com/item/约翰·洛克/24712', '', '', '', 1, '', 1632, 8, 29, '', 1704, 10, 28, 0, '', '1632/8/29-1704/10/28 (72岁)', 'books/学术名著/英国/洛克/figure', '', '英国', '', 'luoke'),
(104, 'barry', '巴利', '诺尔曼·P·巴利', 'gb', '', '', '英国著名政治哲学家、自由主义和保守主义理论家，以其对古典自由主义、自由市场经济学和保守主义思想的系统研究而闻名。', '', '', '', '', 1, '', 1944, 0, 0, '', 2008, 0, 0, 0, '', '1944-2008 (64岁)', 'books/学术名著/英国/巴利/figure', '', '英国', '', 'bali'),
(105, 'smith', '斯密', '亚当·斯密', 'gb', '', '', '英国经济学家、哲学家、作家，经济学的主要创立者。亚当·斯密强调自由市场、自由贸易以及劳动分工，被誉为“古典经济学之父”“现代经济学之父”。', 'https://baike.baidu.com/item/亚当·斯密/972521', '', '', '', 1, '', 1723, 6, 5, '', 1790, 7, 17, 0, '', '1723/6/5-1790/7/17 (67岁)', 'books/学术名著/英国/斯密/figure', '', '英国', '', 'simi'),
(106, 'hobhouse', '霍布豪斯', '里奥纳德·特里劳尼·霍布豪斯', 'gb', '', '', '英国政治思想家，其理论是20世纪英国政治思想主要代表之一。', 'https://baike.baidu.com/item/霍布豪斯', '', '', '', 1, '', 1864, 0, 0, '', 1929, 0, 0, 0, '', '1864-1929 (65岁)', 'books/学术名著/英国/霍布豪斯/figure', '', '英国', '', 'huobuhaosi'),
(108, 'bacon', '培根', '弗朗西斯·培根', 'gb', '', '', '英国文艺复兴时期散文家、哲学家。英国唯物主义哲学家，实验科学的创始人，是近代归纳法的创始人，又是给科学研究程序进行逻辑组织化的先驱。', 'https://baike.baidu.com/item/弗朗西斯·培根/991349', '', '', '', 1, '', 1561, 1, 22, '', 1626, 4, 9, 0, '', '1561/1/22-1626/4/9 (65岁)', 'books/学术名著/英国/培根/figure', '', '英国', '', 'peigen'),
(109, 'mill', '穆勒', '约翰·穆勒', 'gb', '', '', '英国著名哲学家、心理学家和经济学家，19世纪影响力很大的社会自由主义思想家，支持边沁的功利主义。', 'https://baike.baidu.com/item/约翰·穆勒/4808412', '', '', '', 1, '', 1806, 5, 20, '', 1873, 5, 8, 0, '', '1806/5/20-1873/5/8 (67岁)', 'books/学术名著/英国/穆勒/figure', '', '英国', '', 'mier'),
(110, 'gibbon', '吉本', '爱德华·吉本', 'gb', '', '', '近代英国杰出的历史学家，影响深远的史学名著《罗马帝国衰亡史》一书的作者，十八世纪欧洲启蒙时代史学的卓越代表，有英国启蒙时代文史学之父之称。', 'https://baike.baidu.com/item/爱德华·吉本/5215475', '', '', '', 1, '', 1737, 5, 8, '', 1794, 1, 16, 0, '', '1737/5/8-1794/1/16 (57岁)', 'books/学术名著/英国/吉本/figure', '', '英国', '', 'jiben'),
(111, 'berlin', '伯林', '以赛亚·伯林', 'gb', '', '', '英国哲学家、观念史学家和政治理论家，20世纪最杰出的自由主义思想家和知识分子之一，因为对政治和道德理论的贡献而闻名。', 'https://baike.baidu.com/item/以赛亚·伯林', '', '', '', 1, '', 1909, 6, 6, '', 1997, 11, 5, 0, '', '1909/6/6-1997/11/5 (98岁)', 'books/学术名著/英国/伯林/figure', '', '英国', '', 'bailin'),
(112, 'hayek', '哈耶克', '弗里德里希·奥古斯特·冯·哈耶克', 'gb', '', '', '出生于奥地利的英国知名经济学家、政治哲学家，1974年诺贝尔经济学奖得主，被广泛誉为二十世纪最具影响力的经济学家及社会思想家之一。', 'https://baike.baidu.com/item/弗里德里希·奥古斯特·冯·哈耶克/6691771', '', '', '', 1, '', 1899, 5, 8, '', 1992, 3, 23, 0, '', '1899/5/8-1992/3/23 (93岁)', 'books/学术名著/英国/哈耶克/figure', '', '英国', '', 'hayeke'),
(113, 'collingwood', '科林伍德', '罗宾·乔治·柯林伍德', 'gb', '', '', '英国哲学家，历史学家和美学家，表现主义美学的主要代表之一。', 'https://baike.baidu.com/item/罗宾·乔治·科林伍德/62123206', '', '', '', 1, '', 1889, 2, 22, '', 1943, 1, 9, 0, '', '1889/2/22-1943/1/9 (54岁)', 'books/学术名著/英国/科林伍德/figure', '', '英国', '', 'kelinwude'),
(114, 'law', '罗', '约翰·罗', 'gb', '', '', '英国经济学家、财政金融家。一度任法国财政总监。认为国家财富取决于贸易，货币是交换媒介不能构成财富。', 'https://baike.baidu.com/item/约翰·罗', '', '', '', 1, '', 1671, 0, 0, '', 1729, 0, 0, 0, '', '1671-1729 (58岁)', 'books/学术名著/英国/罗/figure', '', '英国', '', 'luo'),
(115, 'more', '莫尔', '托马斯·莫尔', 'gb', '', '', '欧洲早期空想社会主义学说的创始人，才华横溢的人文主义学者和阅历丰富的政治家，以其名著《乌托邦》而名垂史册。', 'https://baike.baidu.com/item/托马斯·莫尔/5231933', '', '', '', 1, '', 1478, 2, 7, '', 1535, 7, 6, 0, '', '1478/2/7-1535/7/6 (57岁)', 'books/学术名著/英国/莫尔/figure', '', '英国', '', 'moer'),
(116, 'bernal', '贝尔纳', '约翰·贝尔纳', 'gb', '', '', '英国著名物理学家、剑桥大学教授，杰出思想家和社会活动家。1937年成为英国皇家学会会员。科学学学科奠基人。', 'https://baike.baidu.com/item/贝尔纳/19785558', '', '', '', 1, '', 1901, 5, 10, '', 1971, 9, 15, 0, '', '1901/5/10-1971/9/15 (70岁)', 'books/学术名著/英国/贝尔纳/figure', '', '英国', '', 'beierna'),
(119, 'dawkins', '道金斯', '理查德·道金斯', 'gb', '', '', '英国演化生物学家，英国皇家文学会会士，英国皇家学会会士，英国皇家科学院院士。', 'https://baike.baidu.com/item/理查德·道金斯/7025804', '', '', '', 1, '', 1941, 3, 26, 'running', 0, 0, 0, 0, '', '1941/3/26-', 'books/学术名著/英国/道金斯/figure', '', '英国', '', 'daojinsi'),
(120, 'blaug', '布劳格', '马克·布劳格', 'gb', '', '', '当代最伟大的经济思想史学家之一。', 'https://baike.baidu.com/item/马克·布劳格', '', '', '', 1, '', 1927, 0, 0, '', 2011, 11, 18, 0, '', '1927-2011/11/18 (84岁)', 'books/学术名著/英国/布劳格/figure', '', '英国', '', 'bulaoge'),
(121, 'malinowski', '马林诺斯基', '马林诺斯基', 'at', '', '', '英国社会人类学家、功能学派创始人之一，人类学田野工作先驱。', 'https://baike.baidu.com/item/马林诺斯基', '', '', '', 1, '', 1884, 4, 7, '', 1942, 5, 16, 0, '', '1884/4/7-1942/5/16 (58岁)', 'books/学术名著/其他国家/奥匈帝国/马林诺斯基/figure', '', '奥地利', '', 'malinnuosiji'),
