(155, 'rawls', '罗尔斯', '约翰·罗尔斯', 'us', '', '', '美国政治哲学家、伦理学家，20世纪英语世界最著名的政治哲学家之一。', 'https://baike.baidu.com/item/约翰·罗尔斯/1490943', '', '', '', 1, '', 1921, 2, 21, '', 2002, 11, 24, 0, '', '1921/2/21-2002/11/24 (81岁)', 'books/学术名著/美国/罗尔斯/figure', '', '美国', '', 'luoersi'),
(156, 'eowilson', 'E·O·威尔逊', '爱德华·威尔逊', 'us', '', '', '美国生物学家，博物学家，社会生物学的主要开创者。被誉为“现代社会的达尔文”“社会生物学之父”。', 'https://baike.baidu.com/item/爱德华·威尔逊', '', '', '', 1, '', 1929, 6, 10, '', 2021, 12, 26, 0, '', '1929/6/10-2021/12/26 (92岁)', 'books/学术名著/美国/E_O_威尔逊/figure', '', '美国', '', 'weierxun'),
(159, 'clarkson', '克拉克森', '肯尼斯·W·克拉克森', 'us', '', '', '法律经济学与产业组织领域的知名学者，其工作聚焦于市场竞争与政府监管的经济分析。', '', '', '', '', 1, 'unknown', 0, 0, 0, 'unknown', 0, 0, 0, 0, '', '', 'books/学术名著/美国/克拉克森/figure', '', '美国', '', 'kelakesen'),
