(287, 'vasiliev', '瓦西列夫', '亚历山大·亚历山德罗维奇·瓦西列夫', 'us', '', '', '20世纪中期的拜占庭历史和文化的权威和研究先驱。', '', '', '', '', 1, '', 1867, 0, 0, '', 1953, 0, 0, 0, '', '1867-1953 (86岁)', 'books/学术名著/美国/瓦西列夫/figure', '', '美国', '', ''),
(288, 'ajptaylor', '艾伦·泰勒', '艾伦·约翰·珀西瓦尔·泰勒', 'gb', '', '', '20世纪最著名和最具争议性的英国历史学家。', 'https://baike.baidu.com/item/艾伦·约翰·珀西瓦尔·泰勒/3340097', '', '', '', 1, '', 1906, 3, 25, '', 1990, 9, 7, 0, '', '1906/3/25-1990/9/7 (84岁)', 'books/学术名著/英国/艾伦_泰勒/figure', '', '英国', '', ''),
(289, 'lerner', '勒讷', '阿巴·勒纳', 'us', '', '', '美国著名经济学家，对经济理论和政策有众多贡献，尤其是价格等于边际成本的帕累托有效规则。', '', '', '', '', 1, '', 1903, 0, 0, '', 1982, 0, 0, 0, '', '1903-1982 (79岁)', 'books/学术名著/美国/勒讷/figure', '', '美国', '', ''),
(290, 'pigou', '庇古', '阿瑟·赛西尔·庇古', 'gb', '', '', '英国著名经济学家，剑桥学派马歇尔的学生，被视为剑桥学派正统人物及主要代表人物。', 'https://baike.baidu.com/item/阿瑟·塞西尔·庇古/10247584', '', '', '', 1, '', 1877, 11, 18, '', 1959, 3, 17, 0, '', '1877-1959 (86岁)', 'books/学术名著/英国/庇古/figure', '', '英国', '', ''),
