(296, 'singhal', '辛加尔', 'D·P·辛加尔', 'in', '', '', '二十世纪印度著名历史学家，伦敦皇家历史学会和亚洲学会会员。', '', '', '', '', 1, '', 1925, 0, 0, '', 1986, 0, 0, 0, '', '', 'books/学术名著/其他国家/印度/辛加尔/figure', '', '印度', '', ''),
(297, 'pritchard', '普里查德', '爱德华·埃文思-普里查德', 'gb', '', '', '英国社会人类学家，其最重要的贡献是在于，他指出了亲属制度中的裂变分支体系，另外对于原始认知的研究，也成为许多人类学后续研究的出发点。', 'https://baike.baidu.com/item/爱德华·埃文思-普里查德/63891147', '', '', '', 1, '', 1902, 9, 21, '', 1973, 9, 11, 0, '', '1902/9/21-1973/9/11 (71岁)', 'books/学术名著/英国/普里查德/figure', '', '英国', '', ''),
(298, 'carr', '卡尔', '爱德华·霍列特·卡尔', 'gb', '', '', '英国历史学家，专长国际关系史和苏联史。', 'https://baike.baidu.com/item/爱德华·霍列特·卡尔/9987404', '', '', '', 1, '', 1892, 6, 28, '', 1982, 11, 3, 0, '', '1892/6/28-1982/11/3 (90岁)', 'books/学术名著/英国/卡尔/figure', '', '英国', '', ''),
