(301, 'boring', '波林', '埃德温·加里格斯·波林', 'us', '', '', '美国实验心理学家、心理学史家、克拉克大学和哈佛大学的心理学教授。', 'https://baike.baidu.com/item/埃德温·加里格斯·波林/16161808', '', '', '', 1, '', 1886, 10, 23, '', 1968, 7, 1, 0, '', '1886/10/23-1968/7/1 (82岁)', 'books/学术名著/美国/波林/figure', '', '美国', '', ''),
(302, 'thompson', '汤普森', '爱德华·汤普森', 'gb', '', '', '英国历史学家、作家、社会主义者、和平活动家。“道德经济学” 是汤姆森提出的一个重要的概念。', 'https://baike.baidu.com/item/爱德华·汤普森', '', '', '', 1, '', 1924, 2, 3, '', 1993, 8, 28, 0, '', '1924/2/3-1993/8/28 (69岁)', 'books/学术名著/英国/汤普森/figure', '', '英国', '', ''),
(303, 'durkheim', '杜尔凯姆', '埃米尔·杜尔凯姆', 'fr', '', '', '法国犹太裔社会学家、人类学家，法国首位社会学教授，《社会学年鉴》创刊人。与卡尔·马克思及马克斯·韦伯并列为社会学的三大奠基人。', 'https://baike.baidu.com/item/埃米尔·杜尔凯姆', '', '', '', 1, '', 1858, 4, 15, '', 1917, 11, 15, 0, '', '1858/4/15-1917/11/15 (59岁)', 'books/学术名著/法国/杜尔凯姆/figure', '', '法国', '', ''),
