(365, 'baran', '巴兰', '保罗·巴兰', 'us', '', '', '美国当代激进派经济学家（马克思主义经济学家）。', 'https://baike.baidu.com/item/保罗·巴兰/6707070', '', '', '', 1, '', 1910, 0, 0, '', 1964, 0, 0, 0, '', '1910-1964 (54岁)', 'books/学术名著/美国/巴兰/figure', '', '美国', '', ''),
(366, 'thucydides', '修昔底德', '修昔底德', 'ancientgreek', '', '', '雅典人，古希腊历史学家、文学家和雅典十将军之一，以其著《伯罗奔尼撒战争史》而在西方史学史上占有重要地位。', 'https://baike.baidu.com/item/修昔底德/1989542', '', '', '', 1, '', -460, 0, 0, 'probably', -396, 0, 0, 0, '', '前460-约前396 (64岁)', 'books/学术名著/其他国家/古希腊/修昔底德/figure', '', '古希腊', '', ''),
(367, 'fourier', '傅立叶', '夏尔·傅立叶', 'fr', '', '', '19世纪上半叶的法国著名哲学家，经济学家，空想社会主义者。', 'https://baike.baidu.com/item/夏尔·傅立叶/8691959', '', '', '', 1, '', 1772, 4, 7, '', 1837, 10, 10, 0, '', '1772/4/7-1837/10/10 (75岁)', 'books/学术名著/法国/傅立叶/figure', '', '法国', '', ''),
