(511, 'frazer', '弗雷泽', '詹姆斯·乔治·弗雷泽', 'gb', '', '', '享有世界声誉的古典人类学家。神话学和比较宗教学的先驱。', 'https://baike.baidu.com/item/詹姆斯·乔治·弗雷泽/6886434', '', '', '', 1, '', 1854, 1, 1, '', 1941, 5, 7, 0, '', '1854/1/1-1941/5/7 (87岁)', 'books/学术名著/英国/弗雷泽/figure', '', '英国', '', ''),
(512, 'poincare', '庞加莱', '亨利·庞加莱', 'fr', '', '', '法国数学家、天体力学家、数学物理学家、科学哲学家。庞加莱的研究涉及数论、代数学、几何学、拓扑学、天体力学、数学物理、多复变函数论、科学哲学等许多领域。', 'https://baike.baidu.com/item/亨利·庞加莱/4541302', '', '', '', 1, '', 1854, 4, 29, '', 1912, 7, 17, 0, '', '1854/4/29-1912/7/17 (58岁)', 'books/学术名著/法国/庞加莱/figure', '', '法国', '', ''),
(513, 'duncan', '邓肯', '奥蒂斯·杜德里·邓肯', 'us', '', '', '美国社会学家，芝加哥大学博士，先后任教于芝加哥大学、密歇根大学等美国知名大学。邓肯是总体逻辑思想家，积极提倡社会学中的总体逻辑思维，对当今社会学和人口学的量化推理实践起到了极为重要的作用。除本书外，还著有《关于社会测量的注释：从历史和批判的角度》。', '', '', '', '', 9, '', 1921, 0, 0, '', 2004, 0, 0, 0, '', '', '', '', '美国', '', ''),
(514, 'burke', '伯克', '彼得·伯克', 'gb', '', '', '英国历史学家。是当代最著名的新文化史学家之一。', 'https://baike.baidu.com/item/彼得·伯克/6564564', '', '', '', 1, '', 1937, 0, 0, 'running', 0, 0, 0, 0, '', '1937-', 'books/学术名著/英国/伯克/figure', '', '英国', '', ''),
