(2520, 'wutingfang', '伍廷芳', '伍廷芳', 'beiyang', '广东江门', '', '清末民初杰出的政治家、外交家、法学家。生于新加坡，进入北洋大臣李鸿章幕府，孙中山下令为其举行国葬仪式。', 'https://baike.baidu.com/item/伍廷芳/1799972', '', '', '', 0, '', 1842, 7, 30, '', 1922, 6, 23, 0, '', '', '', '', '', '', ''),
(2521, 'jiangchaozong', '江朝宗', '江朝宗', 'beiyang', '安徽旌德', '', '北洋军阀政客、汉奸、北洋政府代理国务总理。参与张勋复辟活动。日军侵占北平后投敌，出任北平治安维持会委员长兼北平市市长。', 'https://baike.baidu.com/item/江朝宗/46385', '', '', '', 0, '', 1861, 0, 0, '', 1943, 0, 0, 0, '', '', '', '', '', '', ''),
(2522, 'sazhenbin', '萨镇冰', '萨镇冰', 'beiyang', '福建福州', '', '近现代海军将领、政治人物。先后担任过清朝的海军统制（总司令）、民国海军总长等重要军职，还曾代理过国务总理。后任政协委员。', 'https://baike.baidu.com/item/萨镇冰/0', '', '', '', 0, '', 1859, 3, 30, '', 1952, 4, 10, 0, '', '', '', '', '', '', ''),
(2523, 'gongxinchen', '龚心湛', '龚心湛', 'beiyang', '安徽合肥', '', '中国实业银行原董事长。曾任安徽省长。在财政总长任上代理国务总理三个月。后致力于兴办实业，任启新董事长，启新被日军军管后他愤懑而死。', 'https://baike.baidu.com/item/龚心湛/0', '', '', '', 0, '', 1871, 0, 0, '', 1943, 0, 0, 0, '', '', '', '', '', '', ''),
(2524, 'wangzengting', '王正廷', '王正廷', 'beiyang', '浙江奉化', '', '近现代政治家、社会活动家，中国近代体育的早期领袖之一。', 'https://baike.baidu.com/item/王正廷/1812485', '', '', '', 0, '', 1882, 7, 25, '', 1961, 5, 21, 0, '', '', '', '', '', '', ''),
(2525, 'gaolingwei', '高凌蔚', '高凌蔚', 'beiyang', '直隶天津', '', '民国时期政客，北洋政府代理国务总理，汉奸。伪中华民国临时政府任命高凌霨为河北省省长兼“天津特别市”市长。', 'https://baike.baidu.com/item/高凌霨/1516379', '', '', '', 0, '', 1870, 9, 12, '', 1939, 0, 0, 0, '', '', '', '', '', '', ''),
(2526, 'huweide', '胡惟德', '胡惟德', 'beiyang', '浙江吴兴', '', '近代外交家、政治家。曾多次担任驻外使节，后任民国外交总长兼代国务总理。', 'https://baike.baidu.com/item/胡惟德/8808218', '', '', '', 0, '', 1863, 0, 0, '', 1933, 0, 0, 0, '', '', '', '', '', '', ''),
(2527, 'zhaoxuanlang', '赵玄朗', '赵玄朗', 'beisong', '', '', '宋太祖追尊轩辕黄帝为赵氏远祖，尊号曰圣祖。宋人张咏《乖崖集》记载宋圣祖又名赵玄朗。', 'https://baike.baidu.com/item/宋圣祖/5820600', '君主', '其他', '', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2528, 'zhaotiao', '赵朓', '赵朓', 'beisong', '河北涿州', '', '唐朝官员，赵匡胤高祖父。追谥为睿和皇帝”，庙号僖祖。历任永清县、文安县、幽都县三县的县令。', 'https://baike.baidu.com/item/赵朓/3662956', '君主', '其他', '', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2529, 'zhaoting', '赵珽', '赵珽', 'beisong', '河北涿州', '', '唐朝官员，赵匡胤的曾祖父。追谥为惠元皇帝，庙号顺祖。在藩镇卢龙节度使手下任从事，累官兼任御史中丞。', 'https://baike.baidu.com/item/赵珽/9352129', '君主', '其他', '', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2530, 'zhaojing', '赵敬', '赵敬', 'beisong', '河北涿州', '', '五代时期大臣，赵匡胤的祖父。追谥为简恭皇帝，庙号翼祖。历营、蓟、涿三州刺史。', 'https://baike.baidu.com/item/赵敬/75655', '君主', '其他', '', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2531, 'yuwenhu', '宇文护', '宇文护', 'beizhou', '内蒙古武川', '代郡武川', '西魏、北周时期权臣、政治家。赵贵、独孤信对其掌权不满，被杀。杨忠联合突厥东征北齐，失败。被宇文邕杀死。', 'https://baike.baidu.com/item/宇文护', '', '其他', '古代中国/魏晋南北朝/北朝/北周/君主', 9, '', 513, 0, 0, '', 572, 4, 12, 0, '', '', '', '', '', '', ''),
(2532, 'houjing', '侯景', '侯景', 'xiaoliang', '内蒙古区包头', '怀朔镇', '鲜卑化羯胡。东魏、梁朝时期名将，侯汉开国皇帝。随尔朱荣弹压六镇义军，投降西魏，又依附于萧梁。被陈霸先击溃后，被部下羊鲲所杀。', 'https://baike.baidu.com/item/侯景/693128', '君主', '其他', '古代中国/魏晋南北朝/南朝/萧梁/君主', 0, '', 502, 0, 0, '', 552, 0, 0, 0, '', '', '', '', '', '', ''),
(2533, 'george5', '乔治五世', '乔治五世', 'wenshawangchao', '伦敦', '', '温莎王朝的开创者。第一次世界大战期间，舍弃了自己的德国姓氏，将王室改称“温莎”。', 'https://baike.baidu.com/item/乔治五世/943240', '君主', '其他', '大国和组织/英国/温莎王朝/君主', 0, '', 1865, 6, 3, '', 1936, 1, 20, 0, 'https://bkimg.cdn.bcebos.com/smart/43a7d933c895d143ad4bc21accab95025aafa40fa9cd-bkimg-process', '', '', '', '', '', ''),
(2534, 'edward8', '爱德华八世', '爱德华八世', 'wenshawangchao', '', '', '爱德华八世为了和辛普森结婚而退位。访问德国引发亲纳粹立场的传闻。追求时尚，曾进行男装风格的创新。', 'https://baike.baidu.com/item/爱德华八世/938505', '君主', '其他', '大国和组织/英国/温莎王朝/君主', 0, '', 1894, 6, 23, '', 1972, 5, 28, 0, 'https://bkimg.cdn.bcebos.com/smart/5366d0160924ab18972b7c9d2ba1f1cd7b899e519d5c-bkimg-process', '', '', '', '', '', '');
INSERT INTO `wp_figure` (`id`, `code`, `name`, `name_card`, `country_code`, `native_place`, `native_place_history`, `description`, `baidu_url`, `path_label`, `path_gather`, `path_point`, `status`, `birth_accurate`, `birth_year`, `birth_month`, `birth_day`, `death_accurate`, `death_year`, `death_month`, `death_day`, `active_at`, `baidu_picture`, `extfield`, `path_old`, `dynasty`, `nationality`, `era`, `codebak`) VALUES
(2535, 'george6', '乔治六世', '乔治六世', 'wenshawangchao', '诺福克郡', '', '拒绝离开受敌军轰炸的伦敦。大英帝国的解体过程加速，逐渐演变成为英联邦，失去印度皇帝头衔，他成为首任英联邦元首。', 'https://baike.baidu.com/item/乔治六世/942233', '君主', '其他', '大国和组织/英国/温莎王朝/君主', 0, '', 1895, 12, 14, '', 1952, 2, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/aec379310a55b319ebc463644df59526cffc1e17b9d4-bkimg-process', '', '', '', '', '', ''),
(2536, 'elizabeth2', '伊丽莎白二世', '伊丽莎白二世', 'wenshawangchao', '伦敦', '', '英国在位时间最长的君主。不断努力试图保持前殖民地与英国的特殊关系。', 'https://baike.baidu.com/item/伊丽莎白·亚历山德拉·玛丽·温莎/56812084', '君主', '其他', '大国和组织/英国/温莎王朝/君主', 0, '', 1926, 4, 21, '', 2022, 9, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/b7fd5266d0160924ab182cc5de5b22fae6cd7a899ee3-bkimg-process', '', '', '', '', '', ''),
(2537, 'charles3', '查尔斯三世', '查尔斯三世', 'wenshawangchao', '伦敦', '', '因情感不和与戴安娜离婚。推动公共服务、医保、慈善和环境保护等事业，为维护和强化英国的团结稳定做出了努力。', 'https://baike.baidu.com/item/查尔斯·菲利普·亚瑟·乔治·蒙巴顿-温莎/56812024', '君主', '其他', '大国和组织/英国/温莎王朝/君主', 0, '', 1948, 11, 14, 'running', 0, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/c75c10385343fbf2b211c3664a28dd8065380cd72165-bkimg-process', '', '', '', '', '', ''),
(2538, 'ebert', '艾伯特', '弗里德里希·艾伯特', 'weimagongheguo', '海德堡', '', '德国社会民主党右翼领袖，魏玛共和国第一任总统。致力于实际工作，领导德国走过一段艰苦的路程，赢得了人们的尊重和支持。', 'https://baike.baidu.com/item/弗里德里希·艾伯特/601905', '君主', '其他', '大国和组织/德国/魏玛共和国/君主', 0, '', 1871, 2, 4, '', 1925, 2, 28, 0, '', '', '', '', '', '', ''),
(2539, 'hindenburg', '兴登堡', '保罗·冯·兴登堡', 'weimagongheguo', '大波兰省 波兹南市', '波森省 波兹南', '德国陆军元帅，政治家，军事家。魏玛共和国的第二任总统。黯淡的精神力量、陈旧的思想和狭隘的观察力。任命希特勒为总理埋下隐患。', 'https://baike.baidu.com/item/保罗·冯·兴登堡/5759949', '君主', '其他', '大国和组织/德国/魏玛共和国/君主', 0, '', 1847, 10, 2, '', 1934, 8, 2, 0, '', '', '', '', '', '', ''),
(2540, 'friedrich_1', '腓特烈一世', '腓特烈一世', 'pulushiwangguo', '哥尼斯堡', '', '霍亨索伦王朝首位普鲁士国王。支持神罗对抗法国。建立普鲁士常备军。创建哈雷大学、柏林艺术学校。修建琥珀屋。', 'https://baike.baidu.com/item/腓特烈一世/2903730', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1657, 7, 11, '', 1713, 2, 25, 0, 'https://bkimg.cdn.bcebos.com/smart/aa18972bd40735fae6cdfcf7dc0318b30f2442a7a279-bkimg-process', '', '', '', '', '', ''),
(2541, 'friedrich_wilhelm_1', '弗里德里希·威廉一世', '弗里德里希·威廉一世', 'pulushiwangguo', '柏林', '', '使普鲁士成为欧洲第三军事强国，国力可匹敌奥地利。实施普鲁士义务教育体系，解放领地农奴并发展重商主义。', 'https://baike.baidu.com/item/弗里德里希·威廉一世/22877432', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1688, 8, 14, '', 1740, 5, 31, 0, 'https://bkimg.cdn.bcebos.com/smart/aa64034f78f0f736afc38267e90ca419ebc4b745b519-bkimg-process', '', '', '', '', '', ''),
(2542, 'friedrich_2', '腓特烈二世', '腓特烈二世', 'pulushiwangguo', '', '', '军事家、政治家、作家。奉行“强权即公理”，厉行改革。国力迅速上升，为德意志的统一和复兴奠定了基础。', 'https://baike.baidu.com/item/腓特烈二世/9079854', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1712, 1, 24, '', 1786, 8, 17, 0, 'https://bkimg.cdn.bcebos.com/smart/0e2442a7d933c895d143ab981a4564f082025bafaa80-bkimg-process', '', '', '', '', '', ''),
(2543, 'friedrich_william_2', '弗里德里希·威廉二世', '弗里德里希·威廉二世', 'pulushiwangguo', '柏林', '', '推行强权政治，领土大幅增长。成为欧洲列强之一。以振兴新教传统来对抗理性启蒙。文化软实力大幅上升，建造勃兰登堡门。', 'https://baike.baidu.com/item/弗里德里希·威廉二世/22878193', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1744, 9, 25, '', 1797, 11, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/5366d0160924ab18972b93634aaff1cd7b899e519d10-bkimg-process', '', '', '', '', '', ''),
(2544, 'friedrich_william_3', '弗里德里希·威廉三世', '弗里德里希·威廉三世', 'pulushiwangguo', '柏林', '', '参加欧洲反法同盟，创立了荣誉象征的铁十字勋章。拿破仑战争后，统治变得保守，制止立宪运动，出兵镇压革命。普鲁士国势渐弱。', 'https://baike.baidu.com/item/弗里德里希·威廉三世/22878238', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1770, 8, 3, '', 1840, 6, 7, 0, 'https://bkimg.cdn.bcebos.com/smart/8c1001e93901213fb80e88b425b021d12f2eb9383f19-bkimg-process', '', '', '', '', '', ''),
(2545, 'friedrich_william_4', '弗里德里希·威廉四世', '弗里德里希·威廉四世', 'pulushiwangguo', '柏林', '', '参与反拿破仑解放战争。不愿满足自由派的立宪要求。后期进入反动时期，竭力消除1848年革命的痕迹。', 'https://baike.baidu.com/item/弗里德里希·威廉四世/22878220', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1795, 10, 15, '', 1861, 1, 2, 0, 'https://bkimg.cdn.bcebos.com/smart/7c1ed21b0ef41bd553480caa57da81cb39db3d51-bkimg-process', '', '', '', '', '', ''),
(2546, 'william_1', '威廉一世', '威廉一世', 'pulushiwangguo', '', '', '率兵镇压柏林革命。起用俾斯麦为首相。经过三次王朝战争而一统德意志，建立德意志帝国。晚年两次遇刺，受重伤。', 'https://baike.baidu.com/item/威廉一世/7594557', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1797, 3, 22, '', 1888, 3, 9, 0, 'https://bkimg.cdn.bcebos.com/smart/a686c9177f3e6709c93d1b21029f883df8dcd000ffef-bkimg-process', '', '', '', '', '', ''),
(2547, 'friedrich_3', '弗里德里希三世', '弗里德里希三世', 'pulushiwangguo', '波茨坦', '', '政治立场受英国妻子维多利亚公主影响持自由主义，与首相俾斯麦存在政见冲突。因喉癌去世，仅在位99天。', 'https://baike.baidu.com/item/弗里德里希三世/22878320', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1831, 10, 18, '', 1888, 6, 15, 0, 'https://bkimg.cdn.bcebos.com/smart/0d338744ebf81a4c6d71de20de2a6059242da693-bkimg-process', '', '', '', '', '', ''),
(2548, 'william_2', '威廉二世', '威廉二世', 'pulushiwangguo', '柏林', '', '普鲁士末代国王，积极推进殖民竞争，闪电战计划的创始人。罢免俾斯麦，推动“施里芬计划”，战败后被迫退位。短暂认可纳粹。', 'https://baike.baidu.com/item/威廉二世/2731987', '君主', '其他', '大国和组织/德国/普鲁士王国/君主', 0, '', 1859, 1, 27, '', 1941, 6, 4, 0, 'https://bkimg.cdn.bcebos.com/smart/77094b36acaf2edda3cc01106c4a16e93901203f358d-bkimg-process', '', '', '', '', '', ''),
(2549, 'bismarck', '俾斯麦', '奥托·冯·俾斯麦', 'deyizhidiguo', '萨克森', '', '号称铁血宰相、德国的领航员。自上而下地统一了德国，帮助镇压巴黎公社。力图运用联盟政策，确立霸权。维护专制主义的保守派。', 'https://baike.baidu.com/item/奥托·冯·俾斯麦/5947618', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1815, 4, 1, '', 1898, 7, 30, 0, 'https://bkimg.cdn.bcebos.com/smart/500fd9f9d72a6059a43e1c1a2f34349b033bba80-bkimg-process', '', '', '', '', '', ''),
(2550, 'caprivi', '卡普里维', '列奥·冯·卡普里维', 'deyizhidiguo', '柏林', '', '军事家、政治家。出席中国“定远”舰下水仪式。与英国划分非洲势力范围；俄德关系恶化；对俄关税战促使俄法结盟。军制改革引发议会危机。', 'https://baike.baidu.com/item/列奥·冯·卡普里维/6056547', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1831, 2, 24, '', 1899, 2, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/ac6eddc451da81cb202b0dae5766d01608243187-bkimg-process', '', '', '', '', '', ''),
(2551, 'hohenlohe', '霍恩洛厄', '霍恩洛厄-希灵斯菲斯特', 'deyizhidiguo', '', '', '支持北德意志联盟和支持恢复关税同盟。促使巴伐利亚加入德意志，任首相期间竭力防止或弥补德皇威廉二世狂热的宗教情绪造成不必要的损失。', 'https://baike.baidu.com/item/霍恩洛厄-希灵斯菲斯特/2109385', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1819, 3, 31, '', 1901, 7, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/d01373f082025aaf8249f098f4edab64034f1a6d-bkimg-process', '', '', '', '', '', ''),
(2552, 'bilow', '比洛', '伯恩哈德·冯·比洛', 'deyizhidiguo', '', '', '政治家，延续俾斯麦政策，主张“世界政策”，导致摩洛哥危机；未能抑制德国军事集团的形成，未阻止德皇威廉二世在《每日电讯》发言。', 'https://baike.baidu.com/item/伯恩哈德·冯·比洛/10929679', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1849, 5, 3, '', 1929, 10, 28, 0, 'https://bkimg.cdn.bcebos.com/smart/fc1f4134970a304e31873747d1c8a786c8175ce1-bkimg-process', '', '', '', '', '', ''),
(2553, 'hollweg', '霍尔维格', '特奥巴登·冯·贝特曼·霍尔维格', 'deyizhidiguo', '霍恩菲尔德', '', '政治家，试图缓和英德矛盾未果；试图通过\"空头支票\"策略将冲突限制在巴尔干地区；反对改革三级选举制度。明确战争目标，同时推动和平方案。', 'https://baike.baidu.com/item/特奥巴登·冯·贝特曼·霍尔维格/4007385', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1856, 11, 29, '', 1921, 1, 1, 0, 'https://bkimg.cdn.bcebos.com/smart/a5c27d1ed21b0ef400cd1fe6dac451da81cb3e64-bkimg-process', '', '', '', '', '', ''),
(2554, 'michaelis', '米夏埃利斯', '乔治·米夏埃利斯', 'deyizhidiguo', '', '', '法学家、政治家。在职15个星期。德国历史上首个非贵族出身的帝国宰相，其执政时期正值战争关键阶段。', 'https://baike.baidu.com/item/乔治·米夏埃利斯/15548220', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1857, 9, 8, '', 1936, 7, 24, 0, 'https://bkimg.cdn.bcebos.com/smart/b8389b504fc2d5621e50034ce21190ef76c66c33-bkimg-process', '', '', '', '', '', ''),
(2555, 'hertling', '赫特林', '乔治·弗里德里希·格拉夫·冯·赫特林', 'deyizhidiguo', '', '', '任首相期间，帝国长期存在的领导层问题进一步凸显。社会民主党认为其施政能力不足，无法有效推动和平谈判进程。', 'https://baike.baidu.com/item/乔治·弗里德里希·格拉夫·冯·赫特林/17558998', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1843, 8, 31, '', 1919, 7, 4, 0, '', '', '', '', '', '', ''),
(2556, 'baden', '巴登', '马克斯·冯·巴登', 'deyizhidiguo', '', '', '宣布皇帝退位。把权力移交给社会民主党主席艾伯特。使德皇得以逃亡海外。但他主动将政权移交给温和派的做法招来了极右派与军事集团的怨恨。', 'https://baike.baidu.com/item/马克斯·冯·巴登/10929527', '君主', '其他', '大国和组织/德国/德意志帝国/君主', 0, '', 1867, 7, 10, '', 1929, 11, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/d52a2834349b033b27b0107115ce36d3d539bd65-bkimg-process', '', '', '', '', '', ''),
(2557, 'lenin', '列宁', '弗拉基米尔·伊里奇·列宁', 'ussr', '乌里扬诺夫斯克市', '', '伟大的无产阶级革命家、政治家、理论家、思想家，苏联的缔造者。领导了俄国十月社会主义革命，开辟了马克思主义民族化之路。', 'https://baike.baidu.com/item/弗拉基米尔·伊里奇·列宁/8676059', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1870, 4, 22, '', 1924, 1, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/eaf81a4c510fd9f9d72a67770b76c32a2834349b0e20-bkimg-process', '', '', '', '', '', ''),
(2558, 'stalin', '斯大林', '约瑟夫·维萨里奥诺维奇·斯大林', 'ussr', '第比利斯省哥里', '', '无产阶级革命家 、政治家、军事家。协助领导十月革命，实现工业化和农业集体化。击败轴心国。个人崇拜，李森科主义，“大清洗”运动。', 'https://baike.baidu.com/item/约瑟夫·维萨里奥诺维奇·斯大林/8676088', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1878, 12, 18, '', 1953, 3, 5, 0, 'https://bkimg.cdn.bcebos.com/smart/1e30e924b899a9014c08ea0d9dcd1d7b02087bf45fcd-bkimg-process', '', '', '', '', '', ''),
(2559, 'khrushchev', '赫鲁晓夫', '尼基塔·谢尔盖耶维奇·赫鲁晓夫', 'ussr', '', '', '否定斯大林，加强社会主义民主和法制建设。震动了社会主义阵营，主导了中苏交恶，第二次柏林危机、古巴导弹危机。被解除党内外一切职务。', 'https://baike.baidu.com/item/尼基塔·谢尔盖耶维奇·赫鲁晓夫/8676074', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1894, 4, 17, '', 1971, 9, 11, 0, 'https://bkimg.cdn.bcebos.com/smart/f3d3572c11dfa9ec8a1388e7479fe003918fa1ec6bb9-bkimg-process', '', '', '', '', '', ''),
(2560, 'brezhnev', '勃列日涅夫', '列昂尼德·伊里奇·勃列日涅夫', 'ussr', '', '', '政治家。参与政变推翻赫鲁晓夫。军事力量大大增强，推出了勃列日涅夫主义。经济改革趋于保守，大搞个人崇拜，苏联经济陷于停滞。', 'https://baike.baidu.com/item/列昂尼德·伊里奇·勃列日涅夫/10407648', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1906, 12, 19, '', 1982, 11, 10, 0, 'https://bkimg.cdn.bcebos.com/smart/77c6a7efce1b9d16096235faf3deb48f8d546480-bkimg-process', '', '', '', '', '', ''),
(2561, 'andropov', '安德罗波夫', '尤里·弗拉基米罗维奇·安德罗波夫', 'ussr', '', '', '进行了大胆的改革工作，大刀阔斧地进行人事调整，在整顿劳动纪律和完善经济机制的试验方面取得了比较显著的成效。', 'https://baike.baidu.com/item/尤里·弗拉基米罗维奇·安德罗波夫/10446145', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1914, 6, 15, '', 1982, 2, 9, 0, 'https://bkimg.cdn.bcebos.com/smart/eac4b74543a982260f862f678482b9014a90eb2f-bkimg-process', '', '', '', '', '', ''),
(2562, 'chernenko', '契尔年科', '康斯坦丁·乌斯季诺维奇·契尔年科', 'ussr', '', '', '政治家。受勃列日涅夫赏识。基本延续了安德罗波夫执政时期的政治和经济政策，保持了苏联政局的稳定。', 'https://baike.baidu.com/item/康斯坦丁·乌斯季诺维奇·契尔年科/5834149', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1911, 9, 24, '', 1985, 3, 10, 0, 'https://bkimg.cdn.bcebos.com/smart/a9d3fd1f4134970a304e563abc91c6c8a786c917f729-bkimg-process', '', '', '', '', '', ''),
(2563, 'gorbachev', '戈尔巴乔夫', '米哈伊尔·谢尔盖耶维奇·戈尔巴乔夫', 'ussr', '', '', '政治家，苏联末任领导人。推动苏联的经济、政治和军事等多项领域体制改革。获得诺贝尔和平奖。', 'https://baike.baidu.com/item/米哈伊尔·谢尔盖耶维奇·戈尔巴乔夫/3488813', '君主', '其他', '大国和组织/俄国/苏联/总书记', 0, '', 1931, 3, 2, '', 2022, 8, 30, 0, 'https://bkimg.cdn.bcebos.com/smart/4d086e061d950a7b0208b502308a75d9f2d3562c63fb-bkimg-process', '', '', '', '', '', ''),
(2564, 'agha', '阿迦沙', '阿迦·穆罕默德·汗', 'kaijiawangchao', '', '阿斯塔拉巴', '恺加王朝缔造者。以卓越的军事才能和残暴统治著称。重新统一了萨法维王朝。远征格鲁吉亚时，被卫兵刺杀身亡。', 'https://baike.baidu.com/item/阿迦·穆罕默德·汗/9859429', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1742, 0, 0, '', 1791, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/8694a4c27d1ed21b0ef44ca0ce34cac451da81cb9166-bkimg-process', '', '', '', '', '', ''),
(2565, 'fathali', '法特赫阿里沙', '法特赫-阿里沙·卡扎尔', 'kaijiawangchao', '', '伊朗达姆甘', '推动波斯艺术复兴，创建孔雀宝座等王权标志。两次俄波战争战败，失去南高加索地区、埃里温等地。', 'https://baike.baidu.com/item/法特赫-阿里沙·卡扎尔/7150105', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1772, 9, 5, '', 1834, 10, 23, 0, 'https://bkimg.cdn.bcebos.com/smart/4034970a304e251f95caac8b86ddde177f3e6709f537-bkimg-process', '', '', '', '', '', ''),
(2566, 'mohammadshah', '穆罕默德沙', '穆罕默德沙·卡扎尔', 'kaijiawangchao', '', '波斯大不里士', '平定叔父阿里·米尔扎的40日篡位；推行现代化改革，引入西方军事教官；确定狮子和太阳国旗样式；试图对俾路支斯坦地区实施管辖。', 'https://baike.baidu.com/item/穆罕默德沙·卡扎尔/2864656', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1808, 1, 5, '', 1848, 10, 5, 0, 'https://bkimg.cdn.bcebos.com/smart/838ba61ea8d3fd1f2fcfd2b8304e251f94ca5f69-bkimg-process', '', '', '', '', '', ''),
(2567, 'nasreddin', '纳赛尔丁沙', '纳赛尔丁·沙', 'kaijiawangchao', '', '', '爆发了巴布教徒起义。国内少数民族要求民族独立，欧洲列强的侵略；尼扎姆改革失败，使波斯一度中兴的局面迅速消失，国势又日渐衰落。', 'https://baike.baidu.com/item/纳赛尔丁·沙/7025091', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1831, 0, 0, '', 1896, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/314e251f95cad1c895d6b13f703e6709c93d51bc-bkimg-process', '', '', '', '', '', ''),
(2568, 'muzaffaruddin', '穆扎法尔丁沙', '穆扎法尔丁·沙', 'kaijiawangchao', '', '', '在哥萨克旅和沙俄支持下继承王位。向英国出让石油开采权维持奢靡开支。向沙俄借贷陷入债务危机。宪政运动爆发启动君主立宪进程。', 'https://baike.baidu.com/item/穆扎法尔丁·沙/10033249', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1853, 3, 23, '', 1907, 1, 13, 0, '', '', '', '', '', '', ''),
(2569, 'mohammadali', '穆罕默德阿里', '穆罕默德·阿里·沙', 'kaijiawangchao', '', '', '其父因伊朗立宪革命而被迫传位给他。在英国和俄国的支持下多次企图破坏革命政权，失败后被迫流亡，最终死在意大利圣雷莫。', 'https://baike.baidu.com/item/穆罕默德·阿里·沙/7025043', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1872, 6, 21, '', 1925, 4, 5, 0, 'https://bkimg.cdn.bcebos.com/smart/8d5494eef01f3a292df51aa01a74ab315c6034a8d619-bkimg-process', '', '', '', '', '', ''),
(2570, 'ahmadshah', '艾哈迈德沙', '艾哈迈德沙·卡扎尔', 'kaijiawangchao', '', '', '大议会实施废除阶级制度等改革。面临英俄势力干预及第一次世界大战影响。礼萨汗发动政变夺取实权。流亡欧洲。拒绝土耳其援助复位提议。', 'https://baike.baidu.com/item/艾哈迈德沙·卡扎尔/5563140', '君主', '其他', '帝国历史/波斯/恺加/沙阿', 0, '', 1898, 1, 21, '', 1930, 2, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/574e9258d109b3de0247d6accdbf6c81810a4c7d-bkimg-process', '', '', '', '', '', ''),
(2571, 'capet', '雨果·卡佩', '雨果·卡佩', 'kapeiwangchao', '', '', '终结加洛林王朝，建立卡佩王朝。被十大封建公国割据，贵族普遍不服从管辖。确立长子继承制、构建血统连续性等手段强化王权，不断领地。', 'https://baike.baidu.com/item/雨果·卡佩/3799156', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 938, 0, 0, '', 996, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/94cad1c8a786c9177f3e9153656e67cf3bc79f3df907-bkimg-process', '', '', '', '', '', ''),
(2572, 'robert_2', '罗贝尔二世', '罗贝尔二世', 'kapeiwangchao', '奥尔良', '', '996年，因与表妹伯莎结婚被教皇格列高利五世处以绝罚。1016年，合并勃艮第伯爵领地。1027年即已为儿子亨利一世加冕称王。', 'https://baike.baidu.com/item/罗贝尔二世/67095', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 972, 3, 27, '', 1031, 7, 20, 0, 'https://bkimg.cdn.bcebos.com/smart/54fbb2fb43166d224f4a5da2e47a1ef79052982274c9-bkimg-process', '', '', '', '', '', ''),
(2573, 'hugo_2', '于格二世', '于格二世', 'kapeiwangchao', '', '', '其父效仿卡佩生前为子加冕的做法，为其加冕，形成父子共治。图发动反对罗贝尔二世的叛乱，策动期间因坠马身亡。', 'https://baike.baidu.com/item/于格二世/3370184', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1007, 0, 0, '', 1025, 9, 17, 0, '', '', '', '', '', '', ''),
(2574, 'henri_1', '亨利一世', '亨利一世', 'kapeiwangchao', '', '', '即位前为勃艮第公爵。帮助其外甥诺曼底公爵威廉平叛。后入侵诺曼底被击败。威廉征伐法兰西，若非威廉意外坠马，卡佩王朝几乎灭国。', 'https://baike.baidu.com/item/亨利一世/10574235', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1008, 5, 4, '', 1060, 8, 4, 0, 'https://bkimg.cdn.bcebos.com/smart/fcfaaf51f3deb48f43d7214bfe1f3a292cf578ed-bkimg-process', '', '', '', '', '', ''),
(2575, 'philippe_1', '腓力一世', '腓力一世', 'kapeiwangchao', '', '', '由母亲安娜与博杜安五世摄政至1066年。通过武力扩张领土。因再婚遭教廷绝罚，所以不支持1096年教皇乌尔班二世发起的第一次十字军东征。', 'https://baike.baidu.com/item/腓力一世/14220', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1052, 5, 23, '', 1108, 7, 29, 0, 'https://bkimg.cdn.bcebos.com/smart/3b292df5e0fe9925bc31f3fce5f249df8db1cb13db5e-bkimg-process', '', '', '', '', '', ''),
(2576, 'louis_6', '路易六世', '路易六世', 'kapeiwangchao', '', '', '持续压制王室封臣势力，实行绥靖政策与教会保持良好关系。设立御前会议，与英格兰国王亨利一世交战。统一的法兰西意识开始显现。', 'https://baike.baidu.com/item/路易六世/5387622', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1081, 0, 0, '', 1137, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/a6efce1b9d16fdfa6318467bba8f8c5494ee7b2b-bkimg-process', '', '', '', '', '', ''),
(2577, 'philip', '菲利普', '菲利普', 'kapeiwangchao', '', '', '与父亲路易六世实行共治。其弟路易七世原在圣丹尼修道院学习并准备成为神职人员，因菲利普意外亡故才继承王位。', 'https://baike.baidu.com/item/菲利普/23477803', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1116, 0, 0, '', 1131, 0, 0, 0, '', '', '', '', '', '', ''),
(2578, 'louis_7', '路易七世', '路易七世', 'kapeiwangchao', '', '', '与神罗康拉德三世主导第二次十字军东征(1147-49年)。埃莉诺王后与他离婚后改嫁英王亨利二世。后卡佩王朝与金雀花王朝争斗不止。', 'https://baike.baidu.com/item/路易七世/14217', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1121, 0, 0, '', 1180, 9, 18, 0, 'https://bkimg.cdn.bcebos.com/smart/cefc1e178a82b90175be40a67d8da9773912ef10-bkimg-process', '', '', '', '', '', ''),
(2579, 'philippe_2', '腓力二世', '腓力二世', 'kapeiwangchao', '', '', '对内进行改革，打击贵族；对外扩大疆域。使法国王权由弱转强，突破国王实控仅限于“法兰西岛”的局面，向中央集权迈出了最关键的一步。', 'https://baike.baidu.com/item/腓力二世/9816542', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1165, 8, 21, '', 1223, 7, 14, 0, 'https://bkimg.cdn.bcebos.com/smart/3b292df5e0fe9925bc31707160f049df8db1cb13dbc0-bkimg-process', '', '', '', '', '', ''),
(2580, 'louis_8', '路易八世', '路易八世', 'kapeiwangchao', '', '', '在穆瓦讷的罗歇城堡战役中击败英王约翰。吞并加龙河以北全部英属领地。遗嘱规定将阿图瓦、普瓦图、安茹等领地分封给诸子。', 'https://baike.baidu.com/item/路易八世/3799404', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1187, 9, 5, '', 1226, 11, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/342ac65c10385343fbf2784cec46a77eca806538221a-bkimg-process', '', '', '', '', '', ''),
(2581, 'louis_9', '路易九世', '路易九世', 'kapeiwangchao', '', '', '击败反叛者与英王亨利三世的联合入侵。发动两次十字军东征(曾被俘)，加强在地中海沿岸势力。加强中央集权发展文化，王朝达到鼎盛时期。', 'https://baike.baidu.com/item/路易九世/4385981', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1214, 4, 25, '', 1270, 8, 25, 0, 'https://bkimg.cdn.bcebos.com/smart/0b46f21fbe096b63f624e17eaf659044ebf81a4c06dc-bkimg-process', '', '', '', '', '', ''),
(2582, 'philippe_4', '腓力三世', '腓力三世', 'kapeiwangchao', '普瓦西', '', '与父亲一起参加第八次十字军，远征突尼斯；性格软弱、优柔寡断善于骑马打仗。政策方面往往受到权臣布罗切、那不勒斯国王查理一世影响。', 'https://baike.baidu.com/item/腓力三世/14620220', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1245, 4, 30, '', 1285, 10, 5, 0, 'https://bkimg.cdn.bcebos.com/smart/8718367adab44aed738e3b36b11c8701a08bfb24-bkimg-process', '', '', '', '', '', ''),
(2583, 'louis_10', '腓力四世', '腓力四世', 'kapeiwangchao', '', '', '设立大理院等中央司法机构，1302年召开首次三级会议强化王权基础。驱逐犹太人、打击意大利银行家。将教廷迁至阿维农城。', 'https://baike.baidu.com/item/腓力四世/10914607', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1268, 4, 28, '', 1314, 11, 29, 0, 'https://bkimg.cdn.bcebos.com/smart/6159252dd42a2834349b16c87eeddeea15ce37d311e2-bkimg-process', '', '', '', '', '', ''),
(2584, 'jean_1', '路易十世', '路易十世', 'kapeiwangchao', '巴黎', '', '发布了“关于农民赎金”的敕令，进一步废除奴隶制度。绝释放因卷入丑闻而被判终身监禁的妻子玛格丽特。', 'https://baike.baidu.com/item/路易十世/3799448', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1289, 10, 4, '', 1316, 6, 5, 0, 'https://bkimg.cdn.bcebos.com/smart/f9198618367adab44aed5c00088ea41c8701a18b4e67-bkimg-process', '', '', '', '', '', ''),
(2585, 'philippe_5', '约翰一世', '约翰一世', 'kapeiwangchao', '', '', '出生数日后即夭折，但约翰一世仍被视为合法的国王。传言说腓力五世谋杀了婴儿国王。', 'https://baike.baidu.com/item/约翰一世/10975618', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1316, 11, 15, '', 1316, 11, 19, 0, 'https://bkimg.cdn.bcebos.com/smart/241f95cad1c8a786c917614ae453de3d70cf3bc7fa67-bkimg-process', '', '', '', '', '', ''),
(2586, 'charles_4', '腓力五世', '腓力五世', 'kapeiwangchao', '里昂', '', '镇压牧童十字军运动并处罚反犹暴徒。要求英格兰国王爱德华二世履行封建义务。推行财政改革，1318年颁布法令区分皇室核心土地与贵族领地。', 'https://baike.baidu.com/item/腓力五世/10573592', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1293, 11, 17, '', 1322, 1, 3, 0, 'https://bkimg.cdn.bcebos.com/smart/3bf33a87e950352ac65cb146f60becf2b21193131d6e-bkimg-process', '', '', '', '', '', ''),
(2587, 'zhalisishi', '查理四世', '查理四世', 'kapeiwangchao', '', '', '不善于治理，不善于治理，不善于治理。教皇约翰二十二世支持查理四世为皇帝未果。合谋其妹，英格兰王后废黜其丈夫英格兰国王爱德华二世。', 'https://baike.baidu.com/item/查理四世/14224', '君主', '其他', '大国和组织/法国/卡佩王朝/国王', 0, '', 1294, 0, 0, '', 1328, 2, 1, 0, 'https://bkimg.cdn.bcebos.com/smart/b7003af33a87e950352a230d70634443fbf2b2111e04-bkimg-process', '', '', '', '', '', ''),
(2588, 'edward_7', '爱德华七世', '爱德华七世', 'sakesenkgwangchao', '伦敦', '', '因生活方式不拘礼节长期被维多利亚女王禁止参与政务，直至60岁继位。恢复君主制度威望重塑王室形象。', 'https://baike.baidu.com/item/爱德华七世/943452', '君主', '其他', '大国和组织/英国/萨克森王朝/国王', 0, '', 1841, 11, 9, '', 1910, 5, 6, 0, '', '', '', '', '', '', ''),
(2589, 'george_1', '乔治一世', '乔治一世', 'hannuoweiwangchao', '汉诺威', '', '德意志汉诺威选帝侯。德意志人，母语为德语，不会说英语。西班牙王位继承战争中，带队冲锋。开启的王朝英国历史上的黄金时代。', 'https://baike.baidu.com/item/乔治一世/15190', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1660, 5, 28, '', 1727, 6, 11, 0, 'https://bkimg.cdn.bcebos.com/smart/d1160924ab18972bd40748caac9a6c899e510fb39c2e-bkimg-process', '', '', '', '', '', ''),
(2590, 'george_2', '乔治二世', '乔治二世', 'hannuoweiwangchao', '汉诺威', '', '主导创建的哥廷根大学，支持启蒙运动理念。依靠首相沃波尔巩固统治，德廷根战役中亲自指挥击败法国。度关注汉诺威利益引发议会反对。', 'https://baike.baidu.com/item/乔治二世/15187', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1683, 11, 9, '', 1760, 10, 29, 0, 'https://bkimg.cdn.bcebos.com/smart/279759ee3d6d55fbb2fb91262775584a20a446237721-bkimg-process', '', '', '', '', '', ''),
(2591, 'george_3', '乔治三世', '乔治三世', 'hannuoweiwangchao', '', '', '推动工业革命，建皇家植物园。瓦解辉格党势力，控制内阁与议会两院。确立海洋霸权，击败拿破仑。美国独立。\"戈登暴乱\"后失去实权。', 'https://baike.baidu.com/item/乔治三世/4586191', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1738, 6, 4, '', 1820, 1, 29, 0, 'https://bkimg.cdn.bcebos.com/smart/ac345982b2b7d0a20cf4916b7cb561094b36adaf2c88-bkimg-process', '', '', '', '', '', ''),
(2592, 'george_4', '乔治四世', '乔治四世', 'hannuoweiwangchao', '', '', '1811年开始摄政，由首相利物浦勋爵主导政务。英国在拿破仑战争中取得胜利并参与战后秩序重建。以奢华生活闻名，重建温莎城堡。', 'https://baike.baidu.com/item/乔治四世/4586567', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1762, 8, 12, '', 1830, 6, 26, 0, 'https://bkimg.cdn.bcebos.com/smart/f9dcd100baa1cd11728b6e133a45dffcc3cec3fd87f3-bkimg-process', '', '', '', '', '', ''),
(2593, 'william_4', '威廉四世', '威廉四世', 'hannuoweiwangchao', '', '', '参与北美独立战争，简化加冕仪式。能力相对平庸但心肠慈善。任命辉格党与托利党轮流组阁，是最后一位违背议会意愿任命首相的英国君主。', 'https://baike.baidu.com/item/威廉四世/4586700', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1765, 8, 21, '', 1837, 6, 20, 0, 'https://bkimg.cdn.bcebos.com/smart/5fdf8db1cb13495409232a37c6168558d109b3dedc15-bkimg-process', '', '', '', '', '', ''),
(2594, 'victoria', '维多利亚女王', '维多利亚女王', 'hannuoweiwangchao', '', '', '长期受自由主义思想的熏陶。史称维多利亚时代。自由资本主义到垄断资本主义。工商业、科技领先，国力强大，君主立宪制得到充分发展。', 'https://baike.baidu.com/item/维多利亚女王/21775', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1819, 5, 24, '', 1901, 1, 22, 0, 'https://bkimg.cdn.bcebos.com/smart/cc11728b4710b912c8fcec9c43aaeb039245d6888400-bkimg-process', '', '', '', '', '', ''),
(2595, 'august_1', '奥古斯特一世', '恩斯特·奥古斯特一世', 'hannuoweiwangchao', '', '', '结束英国与汉诺威共主邦联。废除1833年自由主义宪法。在镇压1848年革命后被迫颁布新宪法。因驱逐抗议其违宪行为的学者引发争议。', 'https://baike.baidu.com/item/恩斯特·奥古斯特一世/6876861', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1771, 6, 5, '', 1851, 11, 18, 0, 'https://bkimg.cdn.bcebos.com/smart/4afbfbedab64034f78f0c42f069b6e310a55b319b7d8-bkimg-process', '', '', '', '', '', ''),
(2596, 'georg_5', '格奥尔格五世', '格奥尔格五世', 'hannuoweiwangchao', '', '普鲁士柏林', '汉诺威王国末代国王，因事故双目失明。坚持专制制度与议会频繁冲突。普奥战争中汉诺威遭普鲁士占领兼并。', 'https://baike.baidu.com/item/格奥尔格五世/5462735', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1819, 5, 27, '', 1878, 6, 12, 0, 'https://bkimg.cdn.bcebos.com/smart/1b4c510fd9f9d72a6059e9f0be703f34349b023b0d91-bkimg-process', '', '', '', '', '', ''),
(2597, 'august_3', '奥古斯特三世', '恩斯特·奥古斯特三世', 'hannuoweiwangchao', '', '', '汉诺威王位继承人，不伦瑞克公爵。与德皇威廉二世之女维多利亚·路易丝联姻，促成韦尔夫家族与霍亨索伦家族和解。德国革命后被废黜。', 'https://baike.baidu.com/item/恩斯特·奥古斯特三世/5463145', '君主', '其他', '大国和组织/英国/汉诺威王朝/国王', 0, '', 1887, 11, 17, '', 1953, 1, 30, 0, 'https://bkimg.cdn.bcebos.com/smart/54fbb2fb43166d224f4a035fba751ef79052992274fb-bkimg-process', '', '', '', '', '', ''),
(2618, 'osman_1', '奥斯曼一世', '奥斯曼一世', 'ottoman', '', '', '落首领埃尔图鲁尔加齐的儿子。镇守罗姆王朝边境，1299年登基称加齐，以自己的名字作为国号。励精图治，奠定王朝基础。', 'https://baike.baidu.com/item/奥斯曼一世/1185321', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1259, 0, 0, '', 1326, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/e824b899a9014c08c6d67084037b02087bf4f426-bkimg-process', '', '', '', '', '', ''),
(2619, 'orhan', '奥尔汗', '奥尔汗', 'ottoman', '', '', '拜占庭皇帝约翰六世的女婿。占领了安那托利亚西部的大多数地区，帮约翰六世成为拜占庭皇帝。长子帕夏占据了加里波利。奠定帝国扩张基础。', 'https://baike.baidu.com/item/奥尔汗/1062313', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1285, 0, 0, '', 1359, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/2fdda3cc7cd98d10ca9199282e3fb80e7bec9066-bkimg-process', '', '', '', '', '', ''),
(2620, 'murad_1', '穆拉德一世', '穆拉德一世', 'ottoman', '', '', '尔汗之子。改称号为苏丹(意为君主或统治者)。推行扩张政策，征服东南欧和西亚的许多国家，为帝国的崛起奠定了基础。', 'https://baike.baidu.com/item/穆拉德一世/3376666', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1326, 0, 0, '', 1389, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/503d269759ee3d6d55fba7fd454d7a224f4a20a470c8-bkimg-process', '', '', '', '', '', ''),
(2621, 'bayezid_1', '巴耶塞特一世', '巴耶塞特一世', 'ottoman', '', '', '穆拉德一世之子，著名的军事统帅，外号“闪电”；其父遇刺身亡后，继续统帅军队作战。1402年在安卡拉与帖木儿决战。兵败被俘，后死于狱中。', 'https://baike.baidu.com/item/巴耶塞特一世/5843171', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1354, 0, 0, '', 1403, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/3c6d55fbb2fb43166d22580b27f8512309f790527534-bkimg-process', '', '', '', '', '', ''),
(2622, 'mehmed_1', '穆罕默德一世', '穆罕默德一世', 'ottoman', '', '', '在埃迪尔内自封为苏丹。以武力统一全国，巩固了帝国的统治，故享有“胜利者”之称。1421年因中风死于埃迪尔内。', 'https://baike.baidu.com/item/穆罕默德一世/1315002', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1381, 0, 0, '', 1421, 6, 26, 0, 'https://bkimg.cdn.bcebos.com/smart/c8177f3e6709c93d70cfa9148c66efdcd100bba1fe87-bkimg-process', '', '', '', '', '', ''),
(2623, 'murad_2', '穆拉德二世', '穆拉德二世', 'ottoman', '', '', '杀死反叛的弟弟穆斯塔法。振兴国力，整顿军备。1430年打败强国威尼斯。逐渐厌恶政事，于1443年让位其儿子穆罕默德二世(征服者穆罕默德)。', 'https://baike.baidu.com/item/穆拉德二世/5843207', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1404, 6, 0, '', 1451, 2, 3, 0, 'https://bkimg.cdn.bcebos.com/smart/f31fbe096b63f624a5697c228e44ebf81a4ca3df-bkimg-process', '', '', '', '', '', ''),
(2624, 'mehmed_2', '穆罕默德二世', '穆罕默德二世', 'ottoman', '', '', '穆拉德二世第四子。在政治、经济、宗教和文化等方面施行的一系列政策，被认为是奥斯曼帝国真正的创建者。', 'https://baike.baidu.com/item/穆罕默德二世/1094003', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1432, 3, 30, '', 1481, 5, 3, 0, 'https://bkimg.cdn.bcebos.com/smart/023b5bb5c9ea15ce36d3d8bb844b2df33a87e9501464-bkimg-process', '', '', '', '', '', ''),
(2625, 'bayezid_2', '巴耶塞特二世', '巴耶塞特二世', 'ottoman', '', '', '穆罕默德二世的儿子，成功的对抗了萨法维帝国。', 'https://baike.baidu.com/item/巴耶塞特二世/8736611', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1447, 0, 0, '', 1512, 5, 26, 0, 'https://bkimg.cdn.bcebos.com/smart/0ff41bd5ad6eddc451da4ee0d681a1fd5266d016952f-bkimg-process', '', '', '', '', '', ''),
(2626, 'selim_1', '塞利姆一世', '塞利姆一世', 'ottoman', '', '', '杰出的君主。帝国全面进入极盛时期。帝国舰队称霸地中海、红海和波斯湾。阿巴斯大帝、阿克巴大帝齐名。', 'https://baike.baidu.com/item/塞利姆一世/6551243', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1467, 0, 0, '', 1520, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/b7003af33a87e950352ab700c4624443fbf2b2111e1e-bkimg-process', '', '', '', '', '', ''),
(2627, 'suleiman_1', '苏莱曼一世', '苏莱曼一世', 'ottoman', '', '', '杰出的君主。帝国全面进入极盛时期。帝国舰队称霸地中海、红海和波斯湾。阿巴斯大帝、阿克巴大帝齐名。', 'https://baike.baidu.com/item/苏莱曼一世/3375698', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1494, 11, 6, '', 1566, 9, 7, 0, 'https://bkimg.cdn.bcebos.com/smart/3801213fb80e7bec54e7eb56a676ae389b504fc23d49-bkimg-process', '', '', '', '', '', ''),
(2628, 'selim_2', '塞利姆二世', '塞利姆二世', 'ottoman', '', '', '苏莱曼一世之子。沉迷酒色，因此被称为“酒鬼塞利姆”。国政大多由他的大维齐尔穆罕默德.索库鲁（Mehmed Sokollu）负责。', 'https://baike.baidu.com/item/塞利姆二世/6551457', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1524, 5, 28, '', 1574, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/43a7d933c895d143ad4b1d1175ab95025aafa40fa9f4-bkimg-process', '', '', '', '', '', ''),
(2629, 'murad_3', '穆拉德三世', '穆拉德三世', 'ottoman', '', '', '塞利姆二世之子。政务由索库鲁主导。出兵萨法维王朝，占领第比利斯，控制大不里士，持续对奥地利用兵，因禁卫军威胁隐居宫中。', 'https://baike.baidu.com/item/穆拉德三世/8736630', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1546, 7, 4, '', 1595, 1, 15, 0, 'https://bkimg.cdn.bcebos.com/smart/f31fbe096b63f6246b60aba8001ffcf81a4c510f055e-bkimg-process', '', '', '', '', '', ''),
(2630, 'mehmed_3', '穆罕默德三世', '穆罕默德三世', 'ottoman', '', '', '将十六个弟弟处以绞刑，凶残懒散，政务交给母亲皇太后。奥地利—奥斯曼帝国战争。未有重大挫折，但帝国正在衰落中。', 'https://baike.baidu.com/item/穆罕默德三世/8736682', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1566, 5, 26, '', 1603, 12, 22, 0, 'https://bkimg.cdn.bcebos.com/smart/9f510fb30f2442a71266d521d143ad4bd01302cd-bkimg-process', '', '', '', '', '', ''),
(2631, 'ahmed_1', '艾哈迈德一世', '艾哈迈德一世', 'ottoman', '', '', '穆罕默德三世之子。各地接连暴乱。镇压叙利亚兵变，处决和流放贪赃枉法的大臣和显贵，政局好转。被萨法维帝国阿巴斯大帝所败。', 'https://baike.baidu.com/item/艾哈迈德一世/470019', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1590, 4, 18, '', 1617, 11, 22, 0, 'https://bkimg.cdn.bcebos.com/smart/faedab64034f78f0f73641ea966b1d55b319ebc4b62d-bkimg-process', '', '', '', '', '', ''),
(2632, 'mustafa_1', '穆斯塔法一世', '穆斯塔法一世', 'ottoman', '', '', '艾哈迈德一世之子。精通多种语言，曾以诗人身份闻名。推行改革，整编军队引发近卫军政变。在七塔监狱遭勒杀，首位被弑君主。', 'https://baike.baidu.com/item/穆斯塔法一世/8736648', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1592, 0, 0, '', 1639, 1, 20, 0, 'https://bkimg.cdn.bcebos.com/smart/574e9258d109b3de9c82565bcae47b81800a19d8e6f7-bkimg-process', '', '', '', '', '', ''),
(2633, 'osman_2', '奥斯曼二世', '奥斯曼二世', 'ottoman', '', '', '艾哈迈德一世之子。精通多种语言，曾以诗人身份闻名。推行改革，整编军队引发近卫军政变。在七塔监狱遭勒杀，首位被弑君主。', 'https://baike.baidu.com/item/奥斯曼二世/5569720', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1603, 11, 15, '', 1622, 5, 20, 0, 'https://bkimg.cdn.bcebos.com/smart/4b90f603738da97739125ed4b10aef198618377a4582-bkimg-process', '', '', '', '', '', ''),
(2634, 'murad_4', '穆拉德四世', '穆拉德四世', 'ottoman', '', '', '艾哈迈德一世之子。初期，由柯塞姆苏丹代为统治。在战场上发号施令(最后一位)，统治卓有成效，重振了军力，阻止了帝国的衰弱。', 'https://baike.baidu.com/item/穆拉德四世/1277491', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1612, 7, 27, '', 1640, 2, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/5bafa40f4bfbfbedab643b92daa6e036afc37831b19a-bkimg-process', '', '', '', '', '', ''),
(2635, 'ibrahim_1', '易卜拉欣一世', '易卜拉欣一世', 'ottoman', '', '', '穆拉德四世的弟弟。“苏丹落入后宫的亲信和同伴、保儒、哑巴、宦官及女人们的手中，他们一道把所有的事情都弄得一团糟。”', 'https://baike.baidu.com/item/易卜拉欣一世/9988649', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1615, 11, 5, '', 1648, 8, 2, 0, 'https://bkimg.cdn.bcebos.com/smart/d4628535e5dde7119817f772a7efce1b9c166168-bkimg-process', '', '', '', '', '', ''),
(2636, 'mehmed_4', '穆罕默德四世', '穆罕默德四世', 'ottoman', '', '', '其父易卜拉欣被废黜后即位，时年6岁，朝政先后由其祖母和母后主持。帝国的行政权力落入科普鲁律家族。科普鲁律大维齐尔主政带来一些转机。', 'https://baike.baidu.com/item/穆罕默德四世/1358627', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1642, 1, 2, '', 1693, 1, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/1b4c510fd9f9d72a60598ab753713f34349b033b0d5f-bkimg-process', '', '', '', '', '', ''),
(2637, 'suleiman_2', '苏莱曼二世', '苏莱曼二世', 'ottoman', '', '', '穆罕默德四世的弟弟。难于自己施行自己的政策。阻止了奥地利进军塞尔维亚并粉碎了保加利亚所发生的起义。被神圣罗马帝国军队打败。', 'https://baike.baidu.com/item/苏莱曼二世/9988798', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1642, 4, 15, '', 1691, 6, 23, 0, 'https://bkimg.cdn.bcebos.com/smart/7acb0a46f21fbe096b63cb08843a1b338744ebf8072e-bkimg-process', '', '', '', '', '', ''),
(2638, 'ahmed_2', '艾哈迈德二世', '艾哈迈德二世', 'ottoman', '', '', '易卜拉欣一世之子。灾难不断，其本人也因此忧虑过度筋疲力尽而死。', 'https://baike.baidu.com/item/艾哈迈德二世/8736697', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1643, 2, 25, '', 1695, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/0d338744ebf81a4cc4e26caed52a6059242da681-bkimg-process', '', '', '', '', '', ''),
(2639, 'mustafa_2', '穆斯塔法二世', '穆斯塔法二世', 'ottoman', '', '', '穆罕默德四世之子。积极进取，励精图治，但很多理想都因为各种因素没能变为现实。变法失败后被罢免。', 'https://baike.baidu.com/item/穆斯塔法二世/8736663', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1664, 2, 6, '', 1703, 12, 28, 0, 'https://bkimg.cdn.bcebos.com/smart/91ef76c6a7efce1b9d1678d7400be4deb48f8c54cf21-bkimg-process', '', '', '', '', '', ''),
(2640, 'ahmed_3', '艾哈迈德三世', '艾哈迈德三世', 'ottoman', '', '', '开创了改革的郁金香时代。包围彼得大帝，对俄作战最大的胜利。后屡败于奥地利，失去蒂米什瓦拉(今罗马尼亚境内)和贝尔格莱德。', 'https://baike.baidu.com/item/艾哈迈德三世/469456', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1673, 0, 0, '', 1736, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/80cb39dbb6fd5266d016b83eb943802bd40735fa98dc-bkimg-process', '', '', '', '', '', ''),
(2641, 'mahmoud_1', '马哈茂德一世', '马哈茂德一世', 'ottoman', '', '', '绰号“驼背”，穆斯塔法二世之子。引进欧式军事教育，推行小规模的改革，以沉重代价击败俄国与奥地利的联军，收复巴尔干半岛失地。', 'https://baike.baidu.com/item/马哈茂德一世/9988862', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1696, 8, 2, '', 1754, 12, 13, 0, 'https://bkimg.cdn.bcebos.com/smart/c2cec3fdfc039245d68863a57aceb3c27d1ed21b8f5c-bkimg-process', '', '', '', '', '', ''),
(2642, 'osman_3', '奥斯曼三世', '奥斯曼三世', 'ottoman', '', '', '穆斯塔法二世之子。与众不同的怪癖。换了七次大维齐尔。在阿尔及利亚的统治衰落了。对非穆斯林不宽容，伊斯坦布尔多场大火。', 'https://baike.baidu.com/item/奥斯曼三世/9954077', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1699, 1, 2, '', 1757, 10, 29, 0, 'https://bkimg.cdn.bcebos.com/smart/91ef76c6a7efce1b9d165da77b0be4deb48f8c54cf11-bkimg-process', '', '', '', '', '', ''),
(2643, 'mustafa_3', '穆斯塔法三世', '穆斯塔法三世', 'ottoman', '', '', '艾哈迈德三世之子。明智且有所作为，试图改革军队和管理体系。叶卡捷琳娜吞并克里米亚。伏尔泰给叶卡捷琳娜的信称其“肥胖和无知”。', 'https://baike.baidu.com/item/穆斯塔法三世/8736591', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1717, 1, 28, '', 1771, 1, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/c83d70cf3bc79f3df8dc7cec41fbda11728b461083ee-bkimg-process', '', '', '', '', '', ''),
(2644, 'abdulhamid_1', '哈米德一世', '阿卜杜勒·哈米德一世', 'ottoman', '', '', '艾哈迈德三世之子，即位之前被监禁在后宫中。推行改革但失败告终。俄国企图攫取整个克里米亚。', 'https://baike.baidu.com/item/阿卜杜勒·哈米德一世/8736717', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1725, 3, 20, '', 1789, 4, 7, 0, 'https://bkimg.cdn.bcebos.com/smart/3c6d55fbb2fb43166d22435032ff512309f7905275dc-bkimg-process', '', '', '', '', '', ''),
(2645, 'selim_3', '塞利姆三世', '塞利姆三世', 'ottoman', '', '', '穆斯塔法三世之子。因改革引起禁卫军暴乱而被废黜幽禁。试图自杀未果。禁卫军暴乱，欲拥护塞利姆三世。被穆斯塔法四世杀死。', 'https://baike.baidu.com/item/塞利姆三世/9873186', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1761, 12, 24, '', 1808, 7, 28, 0, 'https://bkimg.cdn.bcebos.com/smart/a5c27d1ed21b0ef41bd54a33099e46da81cb39db9011-bkimg-process', '', '', '', '', '', ''),
(2646, 'mustafa_4', '穆斯塔法四世', '穆斯塔法四世', 'ottoman', '', '', '第29任苏丹，哈米德一世之子。致力于消除塞利姆三世改革的影响，但他最终失败了。被新任苏丹马哈茂德二世下令处死。', 'https://baike.baidu.com/item/穆斯塔法四世/10158445', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1779, 9, 8, '', 1808, 11, 17, 0, 'https://bkimg.cdn.bcebos.com/smart/faedab64034f78f0b535001c7c310a55b3191c26-bkimg-process', '', '', '', '', '', ''),
(2647, 'mahmoud_2', '马哈茂德二世', '马哈茂德二世', 'ottoman', '', '', '哈米德一世之子。推行社会改革，加强帝国力量。被称为奥斯曼改革的始祖，有开明专制君主之称。1829年被迫承认希腊独立。', 'https://baike.baidu.com/item/马哈茂德二世/10152611', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1785, 7, 20, '', 1839, 7, 1, 0, 'https://bkimg.cdn.bcebos.com/smart/8694a4c27d1ed21b0ef40cf60e36cac451da81cb91d2-bkimg-process', '', '', '', '', '', ''),
(2648, 'abdulmajid_1', '迈吉德一世', '阿卜杜勒-迈吉德一世', 'ottoman', '', '', '马哈茂德二世之子。尝试推行奥斯曼主义，尝试巩固与西欧主要势力的关系，推行坦志麦特改革，结果成功使土耳其于1839年现代化。', 'https://baike.baidu.com/item/阿卜杜勒-迈吉德一世/22035981', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1823, 4, 23, '', 1861, 6, 25, 0, 'https://bkimg.cdn.bcebos.com/smart/4d086e061d950a7b32139c4400d162d9f2d3c908-bkimg-process', '', '', '', '', '', ''),
(2649, 'abdulaziz_1', '阿齐兹一世', '阿卜杜勒·阿齐兹一世', 'ottoman', '', '', '支持新疆脱离清朝统治(真特么畜生)。早期颇有政绩，制定法典，保持在英法俄国等距。后去渐次开始采取较高压统治。1876年，遭民众反抗罢黜。', 'https://baike.baidu.com/item/阿卜杜勒·阿齐兹一世/5121049', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1830, 2, 9, '', 1876, 6, 4, 0, 'https://bkimg.cdn.bcebos.com/smart/3c6d55fbb2fb43166d22cf93beed512309f79152758a-bkimg-process', '', '', '', '', '', ''),
(2650, 'murad_5', '穆拉德五世', '穆罕默德·穆拉德五世', 'ottoman', '', '', '其叔父阿齐兹被废黜后，被拥立为苏丹。受法国文化影响较深，但与俄罗斯帝国关系恶化。因未能推动宪法颁布和患精神疾病被废黜。', 'https://baike.baidu.com/item/穆罕默德·穆拉德五世/7340178', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1840, 9, 21, '', 1904, 8, 29, 0, 'https://bkimg.cdn.bcebos.com/smart/962bd40735fae6cd7b89cfaa76e5182442a7d833a1f8-bkimg-process', '', '', '', '', '', ''),
(2651, 'abdulhamid_2', '哈米德二世', '阿卜杜勒·哈米德二世', 'ottoman', '', '', '迈吉德一世幼子。建立恐怖统治，推行泛伊斯兰主义，迫害少数民族。被称为血腥的苏丹。青年土耳其党武装革命，废黜了哈米德二世。', 'https://baike.baidu.com/item/阿卜杜勒·哈米德二世/8736732', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1842, 9, 21, '', 1918, 2, 10, 0, 'https://bkimg.cdn.bcebos.com/smart/7a899e510fb30f2442a78276bbc3c643ad4bd113a532-bkimg-process', '', '', '', '', '', ''),
(2652, 'mehmed_5', '穆罕默德五世', '穆罕默德五世', 'ottoman', '', '', '哈米德二世的弟弟。政府实权为青年土耳其党，穆罕默德是该党建立君主立宪制的理想人选。土耳其版图为欧洲国家所肢解。', 'https://baike.baidu.com/item/穆罕默德五世/53602', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1844, 11, 2, '', 1918, 7, 3, 0, 'https://bkimg.cdn.bcebos.com/smart/a50f4bfbfbedab64034f34de787fb8c379310a55b0de-bkimg-process', '', '', '', '', '', ''),
(2653, 'mehmed_6', '穆罕默德六世', '穆罕默德六世', 'ottoman', '伊斯坦布尔', '', '穆罕默德五世的弟弟，末代苏丹。土耳其议会废除苏丹体制，在英国庇护下，流亡到马耳他岛，后移居叙利亚，在意大利病故。', 'https://baike.baidu.com/item/穆罕默德六世/54172', '君主', '其他', '帝国历史/阿拉伯/奥斯曼/苏丹', 0, '', 1861, 1, 14, '', 1926, 5, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/d000baa1cd11728bcae68171c9fcc3cec2fd2c9d-bkimg-process', '', '', '', '', '', ''),
(2654, 'henri_4', '亨利四世', '亨利四世', 'bopangwangchao', '', '', '为了继承法国王位，改信天主教。原为纳瓦拉国王。彻底结束了法国宗教战争。对内加强君主专制，对外则避免卷入大规模的战争。', 'https://baike.baidu.com/item/亨利四世/9813591', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1553, 12, 13, '', 1610, 5, 14, 0, 'https://bkimg.cdn.bcebos.com/smart/adaf2edda3cc7cd98d10db2abf58363fb80e7aec3bb4-bkimg-process', '', '', '', '', '', ''),
(2655, 'louis_13', '路易十三', '路易十三', 'bopangwangchao', '', '', '继位后由母亲摄政，倚重红衣主教黎塞留推行中央集权。主导法国参与三十年战争。压制贵族叛乱、强化专制制度，为之后的法国霸权奠定基础。', 'https://baike.baidu.com/item/路易十三/18259', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1601, 9, 27, '', 1643, 5, 14, 0, 'https://bkimg.cdn.bcebos.com/smart/6159252dd42a2834349b2f5c55eddeea15ce36d31116-bkimg-process', '', '', '', '', '', ''),
(2656, 'louis_14', '路易十四', '路易十四', 'bopangwangchao', '', '', '母亲奥地利的安妮摄政。建立了一个君主专制的中央集权王国。遗产战争、法荷战争和大同盟战争，成为西欧霸主；西班牙王位继承战争负面作用。', 'https://baike.baidu.com/item/路易十四/15294', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1638, 9, 5, '', 1715, 9, 1, 0, 'https://bkimg.cdn.bcebos.com/smart/adaf2edda3cc7cd98d1052c53459363fb80e7bec3b2d-bkimg-process', '', '', '', '', '', ''),
(2657, 'louis_15', '路易十五', '路易十五', 'bopangwangchao', '', '', '执政的早期受到法国人民的拥戴。但是，他无力改革法国君主制和他在欧洲的绥靖政策，使他大失民心。美洲、印度和非洲的殖民地让给英国。', 'https://baike.baidu.com/item/路易十五/3799788', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1710, 2, 15, '', 1774, 5, 10, 0, 'https://bkimg.cdn.bcebos.com/smart/8cb1cb1349540923dd54da256e0dc609b3de9c82e368-bkimg-process', '', '', '', '', '', ''),
(2658, 'louis_16', '路易十六', '路易十六', 'bopangwangchao', '', '', '即位后大权由不懂政治，喜欢奢侈享受的王后玛丽左右。激发7月14日巴黎人民起义。批准《1791年宪法》，接受君主立宪制。1793年被执行死刑。', 'https://baike.baidu.com/item/路易十六/455224', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1754, 8, 23, '', 1793, 1, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/a71ea8d3fd1f4134970a71a07f4882cad1c8a686f0ec-bkimg-process', '', '', '', '', '', ''),
(2659, 'louis_18', '路易十八', '路易十八', 'bopangwangchao', '', '', '声称侄子路易十七为国王。先后两次回到法国复辟波旁王朝，并尝试进行改革，接受君主立宪；君主立宪改革没能取得多少成果。', 'https://baike.baidu.com/item/路易十八/3799809', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1755, 11, 17, '', 1824, 9, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/e6508eef8bc1ded1ce1b3ee3-bkimg-process', '', '', '', '', '', ''),
(2660, 'charles_10', '查理十世', '查理十世', 'bopangwangchao', '凡尔赛宫', '', '大革命期间作为极端保皇派流亡海外。推行传统贵族特权恢复政策，强化宗教管制。限制新闻自由、修改选举制度，触发七月革命。', 'https://baike.baidu.com/item/查理十世/4553262', '君主', '其他', '大国和组织/法国/波旁王朝/国王', 0, '', 1757, 10, 9, '', 1836, 11, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/0d338744ebf81a4c510f70545d737759252dd52a08ae-bkimg-process', '', '', '', '', '', ''),
(2661, 'henry_2', '亨利二世', '亨利二世', 'jinquehuawangchao', '', '', '侵入爱尔兰并要求理查·德·克莱尔臣服。推行什一税。亨利二世晚年因后代争权夺位而精神饱受摧残。全欧洲最有权力的三个人之一。', 'https://baike.baidu.com/item/亨利二世/9816015', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1133, 3, 5, '', 1189, 7, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/6a63f6246b600c33a4d9f36b144c510fd8f9a1f4-bkimg-process', '', '', '', '', '', ''),
(2662, 'henry_young', '幼王亨利', '幼王亨利', 'jinquehuawangchao', '', '', '在父王生前加冕为共治国王。联合母后埃莉诺及法王路易七世发动叛乱，次年与父王和解。以慷慨宽厚著称，缺乏政治能力。', 'https://baike.baidu.com/item/幼王亨利/64986836', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1155, 2, 28, '', 1183, 6, 11, 0, 'https://bkimg.cdn.bcebos.com/smart/37d3d539b6003af36c191396392ac65c1138b6a1-bkimg-process', '', '', '', '', '', ''),
(2663, 'richard_1', '理查一世', '理查一世', 'jinquehuawangchao', '', '', '英格兰的王权得到加强，国内基本稳定，民众自治和代议制度已有雏形。主导十字军率军击萨拉丁。是“这个时代最为出色的人物”。', 'https://baike.baidu.com/item/理查一世/1440575', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1157, 9, 8, '', 1199, 4, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/a6efce1b9d16fdfaaf512eb42dd79b5494eef01fcd6a-bkimg-process', '', '', '', '', '', ''),
(2664, 'john_1', '约翰一世', '约翰一世', 'jinquehuawangchao', '', '', '导致国实力严重衰退，最失败且最不得人心的君主之一。拒绝承认坎特伯雷大主教引发与教廷冲突。贵族叛乱迫使其于1215年签署《大宪章》。', 'https://baike.baidu.com/item/约翰一世/15938635', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1166, 12, 24, '', 1216, 10, 19, 0, 'https://bkimg.cdn.bcebos.com/smart/91529822720e0cf33bf33d5f0446f21fbe09aa0a-bkimg-process', '', '', '', '', '', ''),
(2665, 'henry_3', '亨利三世', '亨利三世', 'jinquehuawangchao', '', '', '英格兰历史上最无名的国王之一。伯爵可以按大宪章作为国王的执政人来统治英格兰。孟福尔大评议会后来演变为议会，分为上议院和下议院。', 'https://baike.baidu.com/item/亨利三世/14212', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1207, 10, 1, '', 1272, 11, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/4e4a20a4462309f7825884b17c0e0cf3d7cad659-bkimg-process', '', '', '', '', '', ''),
(2666, 'edward_1', '爱德华一世', '爱德华一世', 'jinquehuawangchao', '', '', '曾帮助父亲击败孟福尔叛乱。吞并威尔士。征服试图独立的苏格兰。推行司法和行政改革，加强王权。获得“英格兰的查士丁尼”的雅号。', 'https://baike.baidu.com/item/爱德华一世/2335185', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1239, 6, 17, '', 1307, 7, 7, 0, 'https://bkimg.cdn.bcebos.com/smart/f31fbe096b63f6246b60c77be41efcf81a4c510f050a-bkimg-process', '', '', '', '', '', ''),
(2667, 'edward_2', '爱德华二世', '爱德华二世', 'jinquehuawangchao', '', '', '一生皆为其宠信的弄臣和叛乱的贵族所主宰。', 'https://baike.baidu.com/item/爱德华二世/82557', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1284, 4, 25, '', 1327, 9, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/9358d109b3de9c82850389d46281800a19d84302-bkimg-process', '', '', '', '', '', ''),
(2668, 'edward_3', '爱德华三世', '爱德华三世', 'jinquehuawangchao', '', '', '百年战争发动者，对法国和苏格兰造成巨大的打击。展现出恶魔般的活力。自我放纵，沉溺女色。异端的罗拉德派宗教改革运动盛行。', 'https://baike.baidu.com/item/爱德华三世/3001977', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1312, 11, 13, '', 1377, 6, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/94cad1c8a786c9177f3e367c986b67cf3bc79f3df962-bkimg-process', '', '', '', '', '', ''),
(2669, 'richard_2', '理查二世', '理查二世', 'jinquehuawangchao', '', '', '即位后，由叔父兰开斯特公爵冈特的约翰摄政。掌权后驱逐约翰的长子亨利。后亨利拘捕并废黜了国王。亨利即位，开启兰开斯特王朝。', 'https://baike.baidu.com/item/理查二世/15200', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1367, 1, 6, '', 1400, 2, 14, 0, 'https://bkimg.cdn.bcebos.com/smart/bba1cd11728b4710b9126928ce92d4fdfc0393458599-bkimg-process', '', '', '', '', '', ''),
(2670, 'henry_4', '亨利四世', '亨利四世', 'jinquehuawangchao', '', '', '支持堂兄理查二世镇压格洛斯特公爵叛乱。起兵征讨理查。由于受议会拥戴而即位，开创了国王尊重议会意见的先河。', 'https://baike.baidu.com/item/亨利四世/9813576', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1367, 4, 3, '', 1413, 3, 20, 0, 'https://bkimg.cdn.bcebos.com/smart/7aec54e736d12f2ee7098d3b41c2d56285356858-bkimg-process', '', '', '', '', '', ''),
(2671, 'henry_5', '亨利五世', '亨利五世', 'jinquehuawangchao', '', '', '即位后镇压罗拉德派叛乱，并以叛国罪处置反对教会者。成为法国王位继承人并控制诺曼底大部，构建\"英法帝国\"政治构想。', 'https://baike.baidu.com/item/亨利五世/1428746', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1386, 9, 16, '', 1422, 3, 31, 0, 'https://bkimg.cdn.bcebos.com/smart/a044ad345982b2b789cd06a83dadcbef76099b0f-bkimg-process', '', '', '', '', '', ''),
(2672, 'henry_6', '亨利六世', '亨利六世', 'jinquehuawangchao', '', '', '英格兰在亨利五世时代取得的丰硕战果丧失殆尽，且陷入血腥的玫瑰战争之中。惨败于约克王朝国王爱德华四世。', 'https://baike.baidu.com/item/亨利六世/9732591', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1421, 12, 6, '', 1471, 5, 21, 0, 'https://bkimg.cdn.bcebos.com/smart/8644ebf81a4c510fd9f9be68ab03322dd42a28340f34-bkimg-process', '', '', '', '', '', ''),
(2673, 'edward_4', '爱德华四世', '爱德华四世', 'jinquehuawangchao', '', '', '父战死后成为约克派首领。莫提梅路口战役击败亨利六世即位。剿灭兰开斯特势力。调节君主与议会关系为都铎王朝奠定统治基础。', 'https://baike.baidu.com/item/爱德华四世/4402998', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1442, 4, 28, '', 1483, 4, 9, 0, '', '', '', '', '', '', ''),
(2674, 'edward_5', '爱德华五世', '爱德华五世', 'jinquehuawangchao', '', '', '和他唯一的弟弟约克公爵理查一起神秘失踪。由他们的叔父，护国公格洛斯特公爵理查即位。传说兄弟俩是被国王下令活活钉死在墙里的。', 'https://baike.baidu.com/item/爱德华五世/3891726', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1470, 11, 4, 'probably', 1483, 0, 0, 0, '', '', '', '', '', '', ''),
(2675, 'richard_3', '理查三世', '理查三世', 'jinquehuawangchao', '', '', '镇压白金汉公爵叛乱，建立法律援助体系、保释制度，设立北方议会，并援助大学及教堂。与亨利·都铎交战中战死于博斯沃思战役。', 'https://baike.baidu.com/item/理查三世/15198', '君主', '其他', '大国和组织/英国/金雀花王朝/国王', 0, '', 1452, 10, 2, '', 1485, 8, 22, 0, '', '', '', '', '', '', ''),
(2676, 'james_1', '詹姆斯一世', '詹姆斯一世', 'situyatewangchao', '', '', '召开汉普顿王宫会议，要求全体教士承认王室的最高权威。两度解散议会，宣扬君权神授，将王权凌驾于法律之上。对内挥霍无度。', 'https://baike.baidu.com/item/詹姆斯一世/8796302', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1566, 6, 19, '', 1625, 3, 27, 0, 'https://bkimg.cdn.bcebos.com/smart/5ab5c9ea15ce36d3d5394f677da82d87e950352a1b6a-bkimg-process', '', '', '', '', '', ''),
(2677, 'charles_1', '查理一世', '查理一世', 'situyatewangchao', '', '', '被公开处死的君主。精通拉丁文和希腊文。宗教改革引发主教战争。内战战败后拒绝君主立宪制。二次内战后以叛国罪判处死刑。', 'https://baike.baidu.com/item/查理一世/3752337', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1600, 11, 19, '', 1649, 1, 30, 0, 'https://bkimg.cdn.bcebos.com/smart/37d3d539b6003af33a87621e8d70d15c103853431800-bkimg-process', '', '', '', '', '', ''),
(2678, 'charles_2', '查理二世', '查理二世', 'situyatewangchao', '', '', '对克伦威尔遗体掘墓枭首。发动两次英荷战争。签署《人权保护法》保障基本人权。击败辉格党强化王权，长期维持英国公教信仰。', 'https://baike.baidu.com/item/查理二世/15996', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1630, 5, 29, '', 1685, 2, 6, 0, 'https://bkimg.cdn.bcebos.com/smart/6f061d950a7b02087bf489f9e480e5d3572c11df622b-bkimg-process', '', '', '', '', '', ''),
(2679, 'james_2', '詹姆斯二世', '詹姆斯二世', 'situyatewangchao', '', '', '试图实施宗教宽容政策引发冲突。推行中央集权政策，导致托利党-国教会联盟破裂。反对派贵族邀请奥兰治威廉亲王主政。', 'https://baike.baidu.com/item/詹姆斯二世/4587245', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1633, 10, 14, '', 1701, 9, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/d058ccbf6c81800a19d8f307f26224fa828ba61ee939-bkimg-process', '', '', '', '', '', ''),
(2680, 'mary_2', '玛丽二世', '玛丽二世', 'situyatewangchao', '', '', '支持光荣革命推翻其父统治，通过《权利法案》确立君主立宪制。威廉三世主理军事外交期间，玛丽二世独立处理内政，展现执政能力。', 'https://baike.baidu.com/item/玛丽二世/2635725', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1662, 4, 30, '', 1694, 12, 28, 0, 'https://bkimg.cdn.bcebos.com/smart/0d338744ebf81a4c510f30d69d7d7759252dd42a082e-bkimg-process', '', '', '', '', '', ''),
(2681, 'willem_3', '威廉三世', '威廉三世', 'situyatewangchao', '', '', '荷兰政治家、军事家，作为荷兰执政维持了海上马车夫的独立和强盛。他在英国进行了财政和军事的改革，为“日不落帝国”的强大奠定了基础。', 'https://baike.baidu.com/item/威廉三世/15193', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1650, 11, 14, '', 1702, 3, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/b21bb051f8198618367a8856ebba39738bd4b21c4893-bkimg-process', '', '', '', '', '', ''),
(2682, 'anne_king', '安妮女王', '安妮女王', 'situyatewangchao', '', '', '议会选举和政党竞争机制初步形成，为汉诺威王朝奠定基础。发动西班牙王位继承战争，合并英格兰与苏格兰建立大不列颠王国。', 'https://baike.baidu.com/item/安妮女王/15191', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1665, 2, 6, '', 1714, 8, 1, 0, 'https://bkimg.cdn.bcebos.com/smart/50da81cb39dbb6fd5266af204a73bc18972bd4079924-bkimg-process', '', '', '', '', '', ''),
(2683, 'cromwell', '克伦威尔', '奥利弗·克伦威尔', 'situyatewangchao', '亨廷登郡', '', '政治家、军事家、宗教领袖。资产阶级新贵族集团的代表人物、独立派的首领。驱散议会，自任护国主。经济恶化，阶级矛盾尖锐，未能稳定局势。', 'https://baike.baidu.com/item/奥利弗·克伦威尔/974294', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1599, 4, 25, '', 1658, 9, 3, 0, '', '', '', '', '', '', ''),
(2684, 'richardcromwell', '护国主理查', '理查·克伦威尔', 'situyatewangchao', '', '', '治国和用人才能都远远不如其父。很快就被议会和人民赶下了台。议会恢复君主制，并迎接查理二世复位，理查流亡法国。', 'https://baike.baidu.com/item/理查·克伦威尔/4403489', '君主', '其他', '大国和组织/英国/斯图亚特王朝/国王', 0, '', 1626, 0, 0, '', 1712, 0, 0, 0, '', '', '', '', '', '', ''),
(2685, 'octavius', '屋大维', '盖乌斯·屋大维', 'rome', '', '', '后三头同盟之一，元首制的创始人。对外积极扩张。开创了相对安定的政治局面，为帝国初期的繁荣打下基础。', 'https://baike.baidu.com/item/盖乌斯·屋大维/1934636', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_克劳狄王朝', 0, '', -63, 9, 23, '', 14, 8, 9, 0, 'https://bkimg.cdn.bcebos.com/smart/c995d143ad4bd113fdddd0d557afa40f4afb05c0-bkimg-process', '', '', '', '', '', ''),
(2686, 'tiberius', '提比略', '提比略·恺撒·奥古斯都', 'rome', '', '', '在日耳曼地区取得军事胜利。推行紧缩财政政策，退隐卡普里岛遥控朝政。任内发生日耳曼军团哗变，晚年性格阴郁残暴。维持了帝国稳定。', 'https://baike.baidu.com/item/提比略·恺撒·奥古斯都/60677514', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_克劳狄王朝', 0, '', -42, 11, 16, '', 37, 3, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/6dc09e0a9818aa7eb0351d25-bkimg-process', '', '', '', '', '', ''),
(2687, 'caligula', '卡利古拉', '盖乌斯·尤里乌斯·恺撒·奥古斯都·日耳曼尼库斯', 'rome', '', '', '典型的暴君。建立恐怖统治，神化皇权，行事荒唐、暴虐。帝国的财政急剧恶化。苛捐赋税引起公愤。被近卫军大队长卡瑞亚刺杀身亡。', 'https://baike.baidu.com/item/盖乌斯·尤里乌斯·恺撒·奥古斯都·日耳曼尼库斯/60677516', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_克劳狄王朝', 0, '', 12, 8, 31, '', 41, 1, 24, 0, 'https://bkimg.cdn.bcebos.com/smart/024f78f0f736afc39d2d03beb819ebc4b64512c3-bkimg-process', '', '', '', '', '', ''),
(2688, 'claudius', '克劳狄一世', '克劳狄一世', 'rome', '', '', '力求各阶层的和谐，凡事采取中庸之道，修补了卡利古拉时期皇帝与元老议员之间的破裂关系，提高行省公民在罗马的政治权力，并兴建国家的实业。', 'https://baike.baidu.com/item/克劳狄一世/3605363', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_克劳狄王朝', 0, '', -10, 8, 1, '', 54, 10, 13, 0, 'https://bkimg.cdn.bcebos.com/smart/6a211233991efcc71a4cffbe-bkimg-process', '', '', '', '', '', ''),
(2689, 'nero', '尼禄', '尼禄·克劳狄乌斯·德鲁苏斯·日耳曼尼库斯', 'rome', '', '', '过分醉心希腊文化中的庸俗享乐部分。邪恶与奢靡的化身，然而他的荒淫行径几乎未撼动帝国的整体繁荣。罗马大火重建元老院宣布尼禄为国家公敌。', 'https://baike.baidu.com/item/尼禄·克劳狄乌斯·德鲁苏斯·日耳曼尼库斯/5101737', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_克劳狄王朝', 0, '', 37, 12, 15, '', 68, 6, 9, 0, 'https://bkimg.cdn.bcebos.com/smart/b3fb43166d224f4a20a4ac1f3fad87529822720e7b3e-bkimg-process', '', '', '', '', '', ''),
(2690, 'galba', '加尔巴', '塞尔维乌斯·苏尔皮基乌斯·加尔巴·恺撒·奥古斯都', 'rome', '', '', '并未稳定帝国的内外混乱局势，反而推行了一系列不得人心的政策，仅仅在位七个月就遭到奥托杀害。', 'https://baike.baidu.com/item/塞尔维乌斯·苏尔皮基乌斯·加尔巴·恺撒·奥古斯都/62492984', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝弗拉维', 0, '', -3, 12, 24, '', 69, 1, 15, 0, 'https://bkimg.cdn.bcebos.com/smart/d1160924ab18972bd3a7fb11edcd7b899f510a4f-bkimg-process', '', '', '', '', '', ''),
(2691, 'otho', '奥托', '奥托', 'rome', '', '', '日耳曼军团因反对加尔巴而造反，现转而与奥托对抗。奥托因指挥失误，在贝德里亚库姆战役中战败，自杀而死。', 'https://baike.baidu.com/item/奥托/9135728', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝弗拉维', 0, '', 32, 4, 28, '', 69, 4, 16, 0, 'https://bkimg.cdn.bcebos.com/smart/96dda144ad34598252f55bc60ff431adcbef8463-bkimg-process', '', '', '', '', '', ''),
(2692, 'vitellius', '维特里乌斯', '维特里乌斯', 'rome', '', '', '被拥立为帝的维特里乌斯击败奥托，进入罗马城。韦帕芗在东方及多瑙河军团的支持下称帝，率军攻入罗马，维提里乌斯兵败被杀。', 'https://baike.baidu.com/item/维特里乌斯/4873473', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝弗拉维', 0, '', 15, 9, 24, '', 69, 12, 22, 0, 'https://bkimg.cdn.bcebos.com/smart/72f082025aafa40f1ca57401a064034f79f0198e-bkimg-process', '', '', '', '', '', ''),
(2693, 'vespasianus', '韦帕芗', '韦帕芗', 'rome', '', '', '积极与罗马元老院合作，致力改革内政，恢复因内战而受到影响的政治、经济等社会各方面的秩序；加强了皇帝的专制权力，使元首制日趋发展成熟。', 'https://baike.baidu.com/item/韦帕芗/4675780', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝弗拉维', 0, '', 9, 11, 17, '', 79, 6, 23, 0, 'https://bkimg.cdn.bcebos.com/smart/f9198618367adab489576c6182d4b31c8701e409-bkimg-process', '', '', '', '', '', '');
INSERT INTO `wp_figure` (`id`, `code`, `name`, `name_card`, `country_code`, `native_place`, `native_place_history`, `description`, `baidu_url`, `path_label`, `path_gather`, `path_point`, `status`, `birth_accurate`, `birth_year`, `birth_month`, `birth_day`, `death_accurate`, `death_year`, `death_month`, `death_day`, `active_at`, `baidu_picture`, `extfield`, `path_old`, `dynasty`, `nationality`, `era`, `codebak`) VALUES
(2694, 'titus', '提图斯', '提图斯·弗拉维乌斯·维斯帕西亚努斯', 'rome', '', '', '70年攻陷耶路撒冷终结犹太战争。维苏威火山爆发，庞贝被毁；完成弗拉维圆形竞技场建设，元老院追封其为“神圣的提图斯”。', 'https://baike.baidu.com/item/提图斯·弗拉维乌斯·维斯帕西亚努斯/1501391', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝弗拉维', 0, '', 39, 12, 30, '', 81, 9, 13, 0, 'https://bkimg.cdn.bcebos.com/smart/64380cd7912397dd259571d95282b2b7d1a2877b-bkimg-process', '', '', '', '', '', ''),
(2695, 'domitian', '图密善', '图密善', 'rome', '', '', '改革罗马货币，发起了大规模的建筑计划。受到人民和军队的欢迎与尊敬，但被罗马元老院视为专横独裁的暴君。在一场阴谋中被刺杀。', 'https://baike.baidu.com/item/图密善/3605996', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝弗拉维', 0, '', 51, 10, 24, '', 96, 9, 18, 0, 'https://bkimg.cdn.bcebos.com/smart/1b4c510fd9f9d72a6059e686a77c3f34349b023b0dab-bkimg-process', '', '', '', '', '', ''),
(2696, 'nerva', '涅尔瓦', '涅尔瓦', 'rome', '', '', '尼禄顾问，支持韦帕芗恢复元老院权威，实施土地分配及减税政策，建立罗马首个济贫制度。被元老院追封为神。开创的养子继任制。，多次出任执政官。', 'https://baike.baidu.com/item/涅尔瓦/3607283', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 30, 11, 8, '', 98, 1, 27, 0, 'https://bkimg.cdn.bcebos.com/smart/b2de9c82d158ccbf6c81957a628eab3eb13533faeb6f-bkimg-process', '', '', '', '', '', ''),
(2697, 'traianus', '图拉真', '图拉真', 'rome', '', '', '改革财政，减免赋税，扩建公共工程。推行对外扩张政策。使罗马帝国版图达到最大规模。引起两河流域及地中海东岸一带人民的反抗，遂率军镇压。', 'https://baike.baidu.com/item/图拉真/490549', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 53, 9, 18, '', 117, 8, 9, 0, 'https://bkimg.cdn.bcebos.com/smart/e824b899a9014c08f71c6046027b02087bf4f42a-bkimg-process', '', '', '', '', '', ''),
(2698, 'hadrianus', '哈德良', '普布利乌斯·埃利乌斯·哈德良', 'rome', '', '', '停止东方战争，与帕提亚国王缔结和约，改革官僚制度和法律。在不列颠岛北部建“哈德良长城”。是一位博学多才的皇帝。', 'https://baike.baidu.com/item/普布利乌斯·埃利乌斯·哈德良/2707433', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 76, 1, 24, '', 138, 7, 10, 0, 'https://bkimg.cdn.bcebos.com/smart/dbb44aed2e738bd41109e965a08b87d6277ff9be-bkimg-process', '', '', '', '', '', ''),
(2699, 'augustuspius', '庇护', '安东尼·庇护', 'rome', '', '', '帝国达到全盛，这一时期也因他的名字被称为安敦尼王朝。大力发展经济，加强对行省的监督和管理，促进了行省经济和帝国的繁荣。', 'https://baike.baidu.com/item/安东尼·庇护/6513388', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 86, 9, 19, '', 161, 3, 7, 0, 'https://bkimg.cdn.bcebos.com/smart/79f0f736afc379313ed976daebc4b74542a9118b-bkimg-process', '', '', '', '', '', ''),
(2700, 'marcusaurelius', '奥勒留', '马可·奥勒留', 'rome', '', '', '政治家、军事家、哲学家。有以希腊文写成的著作《沉思录》传世。他向往和平，却具有非凡的军事领导才干。', 'https://baike.baidu.com/item/马可·奥勒留/6720350', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 121, 4, 26, '', 180, 3, 17, 0, 'https://bkimg.cdn.bcebos.com/smart/279759ee3d6d55fbf2f8a4f163224f4a20a4dd2f-bkimg-process', '', '', '', '', '', ''),
(2701, 'verus', '维鲁斯', '路奇乌斯·维鲁斯', 'rome', '', '', '与奥勒留共同执政。率军东征帕提亚王国，收复亚美尼亚与美索不达米亚地区，但实际作战由其部将完成；抵御马科曼尼人入侵。', 'https://baike.baidu.com/item/路奇乌斯·维鲁斯/6754743', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 130, 12, 15, '', 169, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/80cb39dbb6fd526632ddf38eab18972bd50736b2-bkimg-process', '', '', '', '', '', ''),
(2702, 'cassius', '卡西乌斯', '阿维狄乌斯·卡西乌斯', 'rome', '', '', '罗马帝国军事将领及叛乱者，曾任东部诸省总督。在埃及和叙利亚行省发动叛乱，自立为帝。不足三月便因部众倒戈而瓦解，卡西乌斯遭刺杀身亡。', 'https://baike.baidu.com/item/阿维狄乌斯·卡西乌斯/3743727', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 130, 0, 0, '', 175, 0, 0, 0, '', '', '', '', '', '', ''),
(2703, 'commodus', '康茂德', '康茂德', 'rome', '', '', '与蛮族签订合约维持边境稳定。因元老院指使的刺杀而实施高压统治；将政务委托佞臣佩伦尼斯与克利安德；沉迷角斗竞技；被情妇玛琪亚毒杀后勒毙。', 'https://baike.baidu.com/item/康茂德/3619571', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_安敦尼王朝', 0, '', 161, 8, 31, '', 192, 12, 31, 0, 'https://bkimg.cdn.bcebos.com/smart/b03533fa828ba61ea8d3adeb096f800a304e241ff3e6-bkimg-process', '', '', '', '', '', ''),
(2704, 'severus', '塞维鲁', '塞普蒂米乌斯·塞维鲁', 'rome', '', '', '被部队拥立为皇帝，结束内战。加强皇权，扩充军队规模，提高士兵待遇，并进行货币贬值。入侵帕提亚王国，将美索不达米亚地区行省化。', 'https://baike.baidu.com/item/塞普蒂米乌斯·塞维鲁/15618380', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 145, 4, 11, '', 211, 2, 4, 0, 'https://bkimg.cdn.bcebos.com/smart/d041a4a13920ced2471064a8-bkimg-process', '', '', '', '', '', ''),
(2705, 'caracalla', '卡拉卡拉', '卡拉卡拉', 'rome', '', '', '杀死他的弟弟盖塔和盖塔的支持者来巩固他的皇位。颁布安扥尼努斯敕令，让罗马公民权赋予全体罗马人民。这也标志着罗马帝国由盛转衰。', 'https://baike.baidu.com/item/卡拉卡拉/6716576', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 188, 4, 4, '', 217, 4, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/c75c10385343fbf2b211f33a5a24dd8065380cd7212d-bkimg-process', '', '', '', '', '', ''),
(2706, 'geta', '盖塔', '塞普提米乌斯·盖塔', 'rome', '', '', '随父参与帕提亚战争并获封恺撒，成为共治者。遭兄长密谋杀害。临终前逃至母亲怀中求救，仍被击杀。卡拉卡拉试图抹除其历史记录。', 'https://baike.baidu.com/item/塞普提米乌斯·盖塔/7525432', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 189, 3, 7, '', 212, 2, 27, 0, 'https://bkimg.cdn.bcebos.com/smart/38dbb6fd5266d0165ff92e7a952bd40734fa35fb-bkimg-process', '', '', '', '', '', ''),
(2707, 'macrinus', '马克里努斯', '马克里努斯', 'rome', '', '', '经历奴隶、角斗士、邮差等职业。被军队拥立为帝，主导尼西比斯战役并与波斯签订和约。实施十一抽杀律、活人缝牛尸等酷刑。', 'https://baike.baidu.com/item/马克里努斯/7526240', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 165, 0, 0, '', 218, 6, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/267f9e2f070828381f30a5400cd7be014c086e065b1a-bkimg-process', '', '', '', '', '', ''),
(2708, 'diadumenian', '迪亚杜门尼安', '迪亚杜门尼安', 'rome', '', '', '埃拉伽巴路斯战胜马克里努斯之后，俘虏并处死了迪亚杜门尼安。', 'https://baike.baidu.com/item/迪亚杜门尼安/7526512', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 208, 9, 14, '', 218, 6, 8, 0, 'https://bkimg.cdn.bcebos.com/smart/9213b07eca8065380cd74e7fe785b644ad345982241c-bkimg-process', '', '', '', '', '', ''),
(2709, 'elagabalus', '埃拉伽巴路斯', '埃拉伽巴路斯', 'rome', '', '', '东方军团拥立这位流有塞维鲁王族血统的少年继位；以其古怪的行为著称。', 'https://baike.baidu.com/item/埃拉伽巴路斯/2547883', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 203, 0, 0, '', 222, 3, 11, 0, 'https://bkimg.cdn.bcebos.com/smart/6f061d950a7b02087bf4c33c2282e5d3572c10df62e0-bkimg-process', '', '', '', '', '', ''),
(2710, 'alexanderseverus', '亚历山大·塞维鲁', '亚历山大·塞维鲁', 'rome', '', '', '即位后政权由外祖母、母亲与元老院组成的摄政团掌控。推行减免赋税、缩减军费等政策，但因削减军费引发军队不满。被叛军弑杀。', 'https://baike.baidu.com/item/亚历山大·塞维鲁/747877', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 208, 10, 1, '', 235, 3, 18, 0, 'https://bkimg.cdn.bcebos.com/smart/b999a9014c086e061d95b9bf51516cf40ad163d95db7-bkimg-process', '', '', '', '', '', ''),
(2711, 'maximus', '马克西姆斯', '盖利乌斯·马克西姆斯', 'rome', '', '', '叙利亚地区的军事将领，曾任卡拉卡拉皇帝的主治医生，后成为叛军首领。被俘后被处决，加剧了叙利亚驻军与中央政权的矛盾。', 'https://baike.baidu.com/item/盖利乌斯·马克西姆斯/64857493', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 0, 0, 0, '', 219, 0, 0, 0, '', '', '', '', '', '', ''),
(2712, 'velus', '维鲁斯', '维鲁斯', 'rome', '', '', '士兵对埃拉伽巴路斯统治不满，维鲁斯率第三军团发动叛乱并自立为帝，最终被埃拉伽巴路斯处决，其军团亦遭解散。', 'https://baike.baidu.com/item/维鲁斯/64201499', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 0, 0, 0, '', 219, 0, 0, 0, '', '', '', '', '', '', ''),
(2713, 'pertinax', '佩蒂纳克斯', '佩蒂纳克斯', 'rome', '', '', '被释放奴隶之子。任不列颠总督。禁卫军长官莱图斯刺杀康茂德后拥立其为帝，试图整顿财政危机，触及禁卫军利益，遭叛乱士兵杀害。', 'https://baike.baidu.com/item/佩蒂纳克斯/9589103', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 126, 8, 1, '', 193, 3, 28, 0, '', '', '', '', '', '', ''),
(2714, 'julianus', '尤利安努斯', '尤利安努斯', 'rome', '', '', '击败日耳曼部族，晋升执政官。通过竞拍皇位继位，统治66天后被潘诺尼亚总督塞普蒂米乌斯·塞维鲁推翻并处决。', 'https://baike.baidu.com/item/尤利安努斯/12586935', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 137, 2, 2, '', 193, 6, 1, 0, '', '', '', '', '', '', ''),
(2715, 'niger', '奈哲尔', '佩斯切尼乌斯·奈哲尔', 'rome', '', '', '被东部军团拥立为皇帝，自称合法统治者并占据拜占庭城作为统治中心。194年伊苏斯决战惨败后逃往安条克，途中被捕并被斩首。', 'https://baike.baidu.com/item/佩斯切尼乌斯·奈哲尔/62630452', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 135, 0, 0, '', 194, 0, 0, 0, '', '', '', '', '', '', ''),
(2716, 'albinus', '阿尔拜努斯', '克洛狄乌斯·阿尔拜努斯', 'rome', '', '', '历任比利时高卢及不列颠尼亚总督。被不列颠尼亚与西班牙军团拥立为帝，与塞维鲁决战失败后自杀或被处决，遗体被抛入罗讷河。', 'https://baike.baidu.com/item/克洛狄乌斯·阿尔拜努斯/62670413', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_塞维鲁王朝', 0, '', 150, 0, 0, '', 197, 2, 19, 0, '', '', '', '', '', '', ''),
(2717, 'diocletianus', '戴克里先', '盖约·奥里略·瓦勒里乌斯·戴克里先', 'rome', '', '', '结束了罗马帝国的三世纪危机。建立了四帝共治制，使其成为罗马帝国后期的主要政体。使罗马帝国对各境内地区的统治得以存续。', 'https://baike.baidu.com/item/盖约·奥里略·瓦勒里乌斯·戴克里先/65680849', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 244, 0, 0, '', 312, 0, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/3bf33a87e950352a01e385505043fbf2b3118bec-bkimg-process', '', '', '', '', '', ''),
(2718, 'galerius', '伽列里乌斯', '伽列里乌斯', 'rome', '', '', '掌管东部与塞维鲁斯为共治皇帝。因君士坦丁、马克森提乌斯等人争夺帝位引发内战，至308年形成六位奥古斯都对峙局面。', 'https://baike.baidu.com/item/伽列里乌斯/5924274', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 260, 0, 0, '', 311, 6, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/78310a55b319ebc4b09ea8758826cffc1f171673-bkimg-process', '', '', '', '', '', ''),
(2719, 'maximian', '马克西米安', '马克西米安', 'rome', '', '', '与戴克里先同为奥古斯都，掌管西部。于306年复出，支持其子马克森提乌斯的叛乱。310年，发动叛变，被君士坦丁一世擒于马赛。', 'https://baike.baidu.com/item/马克西米安/748409', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 250, 0, 0, '', 310, 7, 0, 0, 'https://bkimg.cdn.bcebos.com/smart/d31b0ef41bd5ad6eddc42764c6902edbb6fd536696b0-bkimg-process', '', '', '', '', '', ''),
(2720, 'constantius', '君士坦提乌斯一世', '君士坦提乌斯一世', 'rome', '', '', '西罗马帝国的皇帝。君士坦丁王朝的开创者。十五个月后就死在了英格兰的约克城，他的儿子君士坦丁就在约克被父亲的军团拥立为皇帝。', 'https://baike.baidu.com/item/君士坦提乌斯一世/748100', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 250, 3, 31, '', 306, 7, 25, 0, 'https://bkimg.cdn.bcebos.com/smart/902397dda144ad345982bf7797f91bf431adcaef2fb2-bkimg-process', '', '', '', '', '', ''),
(2721, 'severusii', '塞维鲁二世', '塞维鲁二世', 'rome', '', '', '于305年受任恺撒，307年晋升奥古斯都。掌管西部与伽列里乌斯为共治皇帝。在内战中败于马克森提乌斯后遭处决。', 'https://baike.baidu.com/item/塞维鲁斯/5923140', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, 'unknown', 0, 0, 0, '', 307, 9, 16, 0, '', '', '', '', '', '', ''),
(2722, 'maxentius', '马克森提乌斯', '马克森提乌斯', 'rome', '', '', '意大利和非洲推行暴虐统治。312年，君士坦丁率军攻入意大利，马克森提乌斯在罗马郊区的米尔维安大桥战役中兵败被杀。', 'https://baike.baidu.com/item/马克森提乌斯/5921273', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 278, 0, 0, '', 312, 0, 0, 0, '', '', '', '', '', '', ''),
(2723, 'licinius', '李锡尼', '李锡尼', 'rome', '', '', '生于色雷斯农民家庭。罗马帝国东部皇帝。君士坦丁在米兰会晤，联合颁布《米兰敕令》。与君士坦丁爆发内战，战败投降后被处死。', 'https://baike.baidu.com/item/李锡尼/6600660', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 263, 0, 0, '', 325, 0, 0, 0, '', '', '', '', '', '', ''),
(2724, 'domitiusalexander', '多米提乌斯', '多米提乌斯·亚历山大', 'rome', '', '', '马克森提乌斯的对手。作为马克森提乌斯的篡位者，他在西方帝国的权力斗争中崛起，但最终被马克森提乌斯击败。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 0, 0, 0, '', 311, 0, 0, 0, '', '', '', '', '', '', ''),
(2725, 'maximinusdaia', '代亚', '代亚', 'rome', '', '', '代亚与李锡尼、君士坦丁形成三足鼎立的奥古斯都共治格局。313年战败于李锡尼后身亡，其统治终结标志着四帝共治制度的瓦解。', 'https://baike.baidu.com/item/代亚/614724', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 270, 11, 20, '', 313, 0, 0, 0, '', '', '', '', '', '', ''),
(2726, 'valeriusvalens', '瓦伦斯', '瓦伦斯', 'rome', '', '', '与李锡尼为共治皇帝。被君士坦丁一世处死。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2727, 'martinianus', '马提尼安努斯', '马提尼安努斯', 'rome', '', '', '324年，成为奥古斯都，掌管西部与李锡尼为共治皇帝。被杀。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_四帝共治', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2728, 'honorius', '霍诺里乌斯', '霍诺里乌斯', 'rome', '', '', '继承西罗马皇位。统治初期由大将斯提利科摄政。西哥特人三次围攻罗马并于410年攻陷该城。迁都至拉文纳。帝国陷入分裂状态。', 'https://baike.baidu.com/item/弗拉维乌斯·奥古斯都·霍诺留/9917045', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 384, 9, 9, '', 423, 8, 15, 0, '', '', '', '', '', '', ''),
(2729, 'priscusattalus', '阿塔卢斯', '阿塔卢斯', 'rome', '', '', '西哥特人首领阿拉里克入侵意大利后支持阿塔卢斯称帝。在霍诺里乌斯的反击和内部压力下被废黜或被迫退位。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2730, 'constantineiii', '君士坦丁三世', '君士坦丁三世', 'rome', '', '', '争位者。西罗马帝国的将军，407年在不列颠尼亚自立为皇帝。军事上的失败使得他于411年退位。后被捕获并被处死。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 411, 9, 18, 0, '', '', '', '', '', '', ''),
(2731, 'constansii', '君士坦斯二世', '君士坦斯二世', 'rome', '', '', '争位者。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2732, 'jovinus', '约维努斯', '约维努斯', 'rome', '', '', '争位者。君士坦丁三世叛乱失败后，高卢贵族约维努斯趁机称帝，企图篡夺西罗马皇位。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2733, 'sebastianus', '塞巴斯蒂安努斯', '塞巴斯蒂安努斯', 'rome', '', '', '争位者。与约维努斯共同发动叛乱，对抗皇帝霍诺里乌斯，最终被西哥特首领阿陶尔夫击败并处决。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2734, 'constantiusiii', '君士坦提乌斯三世', '君士坦提乌斯三世', 'rome', '', '', '平定僭位者君士坦丁三世、约维努斯等势力。处理西班牙的哥特冲突；主导高卢地区重建。与霍诺里乌斯为共治皇帝。', 'https://baike.baidu.com/item/君士坦提乌斯三世/7600158', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, 'unknown', 0, 0, 0, '', 421, 0, 0, 0, '', '', '', '', '', '', ''),
(2735, 'joannes', '约翰尼斯', '约翰尼斯', 'rome', '', '', '争位者。西罗马的宫廷官员和军队推举高级文官约翰内斯为皇帝，导致东西罗马对立。狄奥多西二世攻占拉文纳，约翰内斯被俘后被处决。', '', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 425, 0, 0, 0, '', '', '', '', '', '', ''),
(2736, 'valentinianiii', '瓦伦提尼安三世', '瓦伦提尼安三世', 'rome', '', '', '母后干政，权臣倾轧。与西哥特人结盟抵御匈奴王阿提拉入侵，未能阻止汪达尔人占据北非粮仓。遭政变者马克西穆斯刺杀身亡。', 'https://baike.baidu.com/item/瓦伦提尼安三世/1631813', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 419, 7, 2, '', 455, 3, 16, 0, '', '', '', '', '', '', ''),
(2737, 'petroniusmaximus', '马克西穆斯', '马克西穆斯', 'rome', '', '', '通过政变篡位。因汪达尔人进攻罗马而逃亡，途中被民众捕获并处决，尸体被抛入台伯河。', 'https://baike.baidu.com/item/佩特罗尼乌斯·马克西穆斯/9916982', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 396, 0, 0, '', 455, 5, 31, 0, '', '', '', '', '', '', ''),
(2738, 'avitus', '阿维图斯', '阿维图斯', 'rome', '', '', '高卢行省联席会议及西哥特国王推举为皇帝。西哥特人在高卢扩张引发民怨、国库空虚导致粮食危机，遭将领墨乔里安与里西默武力胁迫退位。', 'https://baike.baidu.com/item/阿维图斯/9916945', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 385, 0, 0, '', 457, 0, 0, 0, '', '', '', '', '', '', ''),
(2739, 'majorian', '马约里安', '马约里安', 'rome', '', '', '试图重振已经分崩离析的帝国。收复了帝国在欧罗巴大陆上几乎所有的领土，并几乎成功的遏制了帝国长时间的衰落趋势。', 'https://baike.baidu.com/item/马约里安/9916894', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 420, 0, 0, '', 461, 8, 7, 0, '', '', '', '', '', '', ''),
(2740, 'libiusseverus', '塞维鲁', '塞维鲁', 'rome', '', '', '典型的傀儡君主，受军事强人里西默实际控制。', 'https://baike.baidu.com/item/利比乌斯·塞维鲁/9916842', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 420, 0, 0, '', 465, 0, 0, 0, '', '', '', '', '', '', ''),
(2741, 'anthemius', '安特米乌斯', '安特米乌斯', 'rome', '', '', '曾任东罗马高级将领并参与击败匈奴人。承认西哥特对西班牙统治；东西罗马联合远征汪达尔王国失败。与里西默决裂，在罗马城破后被杀。', 'https://baike.baidu.com/item/安特米乌斯/9916803', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 420, 0, 0, '', 472, 0, 0, 0, '', '', '', '', '', '', ''),
(2742, 'olybrius', '奥利布里乌斯', '奥利布里乌斯', 'rome', '', '', '罗马贵族。安特米乌斯与权臣里西默爆发冲突，奥利布里乌斯被里西默拥立为帝。与里西默相继去世，导致西罗马陷入权力真空。', 'https://baike.baidu.com/item/奥利布里乌斯/9916752', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, 'unknown', 0, 0, 0, '', 472, 0, 0, 0, '', '', '', '', '', '', ''),
(2743, 'glycerius', '格利凯里乌斯', '格利凯里乌斯', 'rome', '', '', '被部下推举为皇帝。东罗马派遣尼波斯率军进入意大利，被迫退位。退位后转任萨罗纳主教。', 'https://baike.baidu.com/item/格利凯里乌斯/9916713', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2744, 'juliusnepos', '尼波斯', '尼波斯', 'rome', '', '', '试图维持对意大利和南高卢的控制。将高卢大部分领土割让给西哥特。475年拉文纳失守流亡达尔马提亚，480年，在达尔马提亚被部下杀害。', 'https://baike.baidu.com/item/朱利乌斯·尼波斯/7468386', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 480, 0, 0, 0, '', '', '', '', '', '', ''),
(2745, 'romulusaugustulus', '罗慕路斯', '罗慕路斯', 'rome', '', '', '欧瑞斯特攻占都拉文纳推翻尼波斯，拥立其子罗慕路斯为帝。日耳曼雇佣兵首领奥多亚克击杀欧瑞斯特后废黜罗慕路斯二世，西罗马帝国灭亡。', 'https://baike.baidu.com/item/罗慕路斯·奥古斯都/5684115', '君主', '其他', '帝国历史/大罗马/罗马帝国/元首_西罗马帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2746, 'theodosius_1', '狄奥多西一世', '狄奥多西一世', 'byzantium', '', '', '最后一位统治统一帝国的君主。宣布基督教为国教，以异教活动为由废止古奥运会。年临终前将帝国分予次子霍诺里乌斯与长子阿卡迪乌斯。', 'https://baike.baidu.com/item/狄奥多西一世/1664721', '君主', '狄奥多西王朝', '帝国历史/大罗马/拜占庭/皇帝_狄奥多西王朝', 0, 'probably', 346, 0, 0, '', 395, 1, 17, 0, '', '', '', '', '', '', ''),
(2747, 'valentiniani', '瓦伦提尼安一世', '瓦伦提尼安一世', 'rome', '', '', '西帝。与瓦伦斯、格拉提安共治。沿莱茵河构筑防御工事。在边境地区多次对蛮族作战。抗击外敌入侵多有建树，因性格暴躁和残酷而留有恶名。', 'https://baike.baidu.com/item/瓦伦提尼安一世/9609445', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, 'probably', 312, 0, 0, '', 375, 11, 17, 0, '', '', '', '', '', '', ''),
(2748, 'valens', '瓦伦斯', '瓦伦斯', 'rome', '', '', '东帝。定都君士坦丁堡。镇压普罗科皮乌斯叛乱。委托尤特罗比乌斯和费斯图斯撰写罗马史简编。支持阿里乌教派。亲征哥特联军时阵亡。', 'https://baike.baidu.com/item/瓦伦斯/4495689', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, '', 328, 0, 0, '', 378, 8, 9, 0, '', '', '', '', '', '', ''),
(2749, 'procopiusleader', '普罗科皮乌斯', '普罗科皮乌斯', 'rome', '', '', '篡位者。被部分军队拥立为元首。战败逃往小亚细亚，被部下出卖给瓦伦斯后，被瓦伦斯处死。', '', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, 'probably', 322, 0, 0, '', 366, 0, 0, 0, '', '', '', '', '', '', ''),
(2750, 'gratian', '格拉提安', '格拉提安', 'rome', '', '', '由诗人奥索尼乌斯进行教育。管辖高卢、西班牙和不列颠。册立狄奥多西一世为东部的罗马皇帝。马克西穆斯反叛。格拉提安被叛军所杀。', 'https://baike.baidu.com/item/格拉提安/6392076', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, '', 359, 0, 0, '', 383, 0, 0, 0, '', '', '', '', '', '', ''),
(2751, 'valentinianii', '瓦伦提尼安二世', '瓦伦提尼安二世', 'rome', '', '', '被拥立为帝，管辖意大利、北非及伊利里亚西部。实权被法兰克将领阿波加斯特掌控。被发现死于宫中，阿波加斯特宣称其为自杀。', 'https://baike.baidu.com/item/瓦伦提尼安二世/12019611', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, '', 371, 0, 0, '', 392, 5, 15, 0, '', '', '', '', '', '', ''),
(2752, 'magnusmaximus', '马克西穆斯', '马克西穆斯', 'rome', '', '', '不列颠尼亚军区司令，西部的篡位者。控制高卢、西班牙和不列颠。入侵意大利，引发狄奥多西一世率大军西征。马克西穆斯兵败被杀。', '', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, 'unknown', 0, 0, 0, '', 388, 0, 0, 0, '', '', '', '', '', '', ''),
(2753, 'flaviusvictor', '维克托', '维克托', 'rome', '', '', '与其父马克西穆斯共治。维克托被狄奥多西一世部将阿波加斯特擒获并处决。', '', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, 'unknown', 0, 0, 0, '', 388, 0, 0, 0, '', '', '', '', '', '', ''),
(2754, 'eugenius', '欧根尼乌斯', '欧根尼乌斯', 'rome', '', '', '西部的篡位者。阿波加斯特拥立的异教徒皇帝。争取罗马元老院中强大的异教保守派的支持。狄奥多西一世西征，欧根尼乌斯被俘后被处决。', '', '君主', '瓦伦蒂尼安王朝', '帝国历史/大罗马/罗马帝国/元首_瓦伦蒂尼安王朝', 0, 'unknown', 0, 0, 0, '', 394, 0, 0, 0, '', '', '', '', '', '', ''),
(2755, 'maximinusthrax', '马克西米努斯', '马克西米努斯', 'rome', '', '', '第一位出身蛮族的罗马皇帝。勇而无谋，被人们称为野兽。捏造罪状，处死许多富豪并没收其钱财。在元老院发起内战中战败自杀。', 'https://baike.baidu.com/item/马克西米努斯/6209158', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 173, 0, 0, '', 238, 0, 0, 0, '', '', '', '', '', '', ''),
(2756, 'gordiani', '戈尔迪安一世', '戈尔迪安一世', 'rome', '', '', '统治仅22天。兴建蒂斯杜斯竞技场，卡佩里亚努斯举兵反叛后，戈尔迪安二世战败身亡，戈尔迪安一世遂自尽于迦太基。', 'https://baike.baidu.com/item/戈尔迪安一世/7875987', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'probably', 159, 0, 0, '', 238, 4, 12, 0, '', '', '', '', '', '', ''),
(2757, 'gordianii', '戈尔迪安二世', '戈尔迪安二世', 'rome', '', '', '外貌出众且性格仁爱，幼年专注学问，六万二千卷藏书，其兴趣广泛且注重实用。在迦太基附近作战身亡。年内五个皇帝身亡。', 'https://baike.baidu.com/item/戈尔迪安二世/7891142', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'probably', 192, 0, 0, '', 238, 4, 12, 0, '', '', '', '', '', '', ''),
(2758, 'pupienusmaximus', '普皮恩努斯', '普皮恩努斯', 'rome', '', '', '元老院推举普皮恩努斯与巴尔比努斯为共治皇帝，普皮恩努斯负责率军抵御马克西米努斯。禁卫军发动袭击，将普皮恩努斯当街处决。', 'https://baike.baidu.com/item/普皮恩努斯/7549056', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 164, 0, 0, '', 238, 0, 0, 0, '', '', '', '', '', '', ''),
(2759, 'balbinus', '巴尔比努斯', '巴尔比努斯', 'rome', '', '', '普皮恩努斯共同执政，以执政官制为模式共享权力。巴尔比努斯负责国内管理。禁卫军发动暴乱，巴尔比努斯被当街处决。', 'https://baike.baidu.com/item/巴尔比努斯/9469759', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 165, 0, 0, '', 238, 0, 0, 0, '', '', '', '', '', '', ''),
(2760, 'gordianiii', '戈尔迪安三世', '戈尔迪安三世', 'rome', '', '', '元老院推举的元首先后身亡后。尔迪安三世即位。受到近卫军的控制。被阿拉伯人菲利普部下的九个人劫掠后用剑杀害。', 'https://baike.baidu.com/item/戈尔迪安三世/7859477', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 222, 0, 0, '', 244, 0, 0, 0, '', '', '', '', '', '', ''),
(2761, 'sabinianus', '萨宾尼亚努斯', '萨宾尼亚努斯', 'rome', '', '', '阿非利加行省的资深执政官。发起反抗戈尔迪安三世的叛乱，自称皇帝。被毛里塔尼亚行省的总督击败。被迦太基的支持者献给了帝国。', 'https://baike.baidu.com/item/萨宾尼亚努斯/66829137', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'unknown', 0, 0, 0, '', 240, 0, 0, 0, '', '', '', '', '', '', ''),
(2762, 'philipthearab', '阿拉伯人菲利普', '阿拉伯人菲利普', 'rome', '', '', '自立为帝并获元老院承认。镇压多起叛乱，并应对日耳曼人入侵。庆祝罗马建城千年。在德基乌斯发动叛乱的战斗中阵亡。', 'https://baike.baidu.com/item/阿拉伯人菲利普/7249411', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 204, 0, 0, '', 249, 0, 0, 0, '', '', '', '', '', '', ''),
(2763, 'pacatianus', '帕卡提亚努斯', '帕卡提亚努斯', 'rome', '', '', '被军团士兵拥立为皇帝。被自己的士兵杀害，首级被送往皇帝菲利普处。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'unknown', 0, 0, 0, '', 248, 0, 0, 0, '', '', '', '', '', '', ''),
(2764, 'iotapianus', '伊奥塔皮亚努斯', '伊奥塔皮亚努斯', 'rome', '', '', '当地军队和居民拥立为帝。很快被菲利普一世或其继任者德基乌斯镇压。伊奥塔皮亚努斯被自己的部下所杀。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'unknown', 0, 0, 0, '', 248, 0, 0, 0, '', '', '', '', '', '', ''),
(2765, 'silbannacus', '希尔班纳库斯', '希尔班纳库斯', 'rome', '', '', '可能是莱茵河边境（日耳曼防线）的军官，在高卢或日耳曼地区自立为帝。很快被菲利普一世的将领镇压。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'unknown', 0, 0, 0, 'unknown', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2766, 'decius', '德基乌斯', '德基乌斯', 'rome', '', '', '本是普通元老，被部下拥立为帝，在内战中消灭了菲利普父子。和哥特人的战争中阵亡。', 'https://baike.baidu.com/item/德基乌斯/7079425', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 201, 0, 0, '', 251, 0, 0, 0, '', '', '', '', '', '', ''),
(2767, 'priscus', '普里斯库斯', '普里斯库斯', 'rome', '', '', '在哥哥菲利普身亡后，被部下拥立为皇帝，试图控制东方行省。很可能在德基乌斯或后续皇帝的镇压下迅速失败、被杀或失踪。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2768, 'licinianus', '李锡尼亚努斯', '李锡尼亚努斯', 'rome', '', '', '据称是元老院成员，可能具有贵族血统。可能在罗马城或意大利起事。可能被德基乌斯留守罗马的官员迅速平定。起事后不久即被处决。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2769, 'herenniusetruscus', '赫伦尼乌斯', '赫伦尼乌斯', 'rome', '', '', '被其父德基乌斯皇帝立为共治皇帝。同年罗马帝国与哥特人爆发阿伯里图斯战役，德基乌斯父子率军抵抗哥特国王尼瓦的进攻，最终双双阵亡。', 'https://baike.baidu.com/item/赫伦尼乌斯/7092843', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 227, 0, 0, '', 251, 0, 0, 0, '', '', '', '', '', '', ''),
(2770, 'hostilian', '霍斯蒂利安', '霍斯蒂利安', 'rome', '', '', '元老院与罗马民众拥立霍斯蒂利安，军队将领加卢斯被军队拥立。遭遇大规模瘟疫，即位仅数月即病逝。', 'https://baike.baidu.com/item/霍斯蒂利安/14767418', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 230, 0, 0, '', 251, 0, 0, 0, '', '', '', '', '', '', ''),
(2771, 'gallus', '加卢斯', '加卢斯', 'rome', '', '', '与儿子沃鲁西安努斯共治。任内处理瘟疫并安葬死者，潘诺尼亚将领埃米利安努斯自立为帝并进攻意大利。被部下暗杀，其子同时遇害。', 'https://baike.baidu.com/item/加卢斯/7120994', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 206, 0, 0, '', 253, 0, 0, 0, '', '', '', '', '', '', ''),
(2772, 'volusianus', '沃鲁西安努斯', '沃鲁西安努斯', 'rome', '', '', '加卢斯率军抵御埃米利安努斯，但在途中遭部下暗杀，沃鲁西安努斯亦在此次事件中遇害。', 'https://baike.baidu.com/item/沃鲁西安努斯/7127475', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2773, 'aemilianus', '埃米利安努斯', '埃米利安努斯', 'rome', '', '', '率军击败哥特人并截取贡金赏赐部下，被拥立为帝。瓦勒良的军队以替加卢斯复仇为名击败埃米利安努斯，导致其被杀，在位不足四个月。', 'https://baike.baidu.com/item/埃米利安努斯/7125433', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2774, 'valerian', '瓦勒良', '瓦莱里安', 'rome', '', '', '整顿多瑙河军团防御哥特人入侵。颁布敕令迫害基督徒，率军东征萨珊波斯时被俘。导致高卢帝国与巴尔米拉王国相继独立。', 'https://baike.baidu.com/item/瓦勒良/10349870', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 193, 0, 0, 'probably', 260, 0, 0, 0, '', '', '', '', '', '', ''),
(2775, 'gallienus', '加里恩努斯', '伽利埃努斯', 'rome', '', '', '统治罗马帝国西半部。极力维护帝国的统一局面。三世纪危机中有所作为皇帝。对基督教采取宽容态度。被克劳狄二世等军官杀害。', 'https://baike.baidu.com/item/加里恩努斯/7531673', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 218, 0, 0, '', 268, 0, 0, 0, '', '', '', '', '', '', ''),
(2776, 'saloninus', '萨洛尼努斯', '萨洛尼努斯', 'rome', '', '', '因军事冲突被围于科隆城，守军拥立其为奥古斯都以巩固地位，但最终城破被杀。导致波斯图穆斯建立高卢帝国。', 'https://baike.baidu.com/item/萨洛尼努斯/14733848', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2777, 'ingenuus', '因格努乌斯', '因格努乌斯', 'rome', '', '', '被麾下军团拥立为皇帝，伽利埃努斯迅速率军从高卢返回多瑙河前线。因格努乌斯战败，逃亡后被杀（一说被部下所杀）。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2778, 'regalianus', '雷加里安努斯', '雷加里安努斯', 'rome', '', '', '得到了多瑙河军团的支持而自立。在内战或政变中被击败或处决。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2779, 'macrianusmajor', '大马克里亚努斯', '大马克里亚努斯', 'rome', '', '', '部地区自立为帝的僭主。埃及总督埃米利亚努斯曾支持他们。在与伽里埃努斯支持者的冲突中阵亡。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2780, 'macrianusminor', '小马克里亚努斯', '小马克里亚努斯', 'rome', '', '', '与父亲大马克里亚努斯一同在东方行省自立为帝。奥略卢斯奉命狙击马克里亚努斯父子，最终在公元261年击败并处死了他们。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2781, 'quietus', '奎伊图斯', '奎伊图斯', 'rome', '', '', '奎伊图斯与将军巴拉里斯塔斯被留下镇守叙利亚和美索不达米亚。埃美萨市民暴动，最终被市民或奥登纳图斯的军队杀死。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2782, 'mussiusaemilianus', '穆斯乌斯', '穆斯乌斯·埃米利安努斯', 'rome', '', '', '在埃及地区自立。加里恩努斯派狄奥多图斯平叛。埃米利安努斯被俘后遭处决。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'unknown', 0, 0, 0, '', 261, 0, 0, 0, '', '', '', '', '', '', ''),
(2783, 'aureolus', '奥里奥路斯', '奥里奥路斯', 'rome', '', '', '加里恩努斯麾下骑兵长官，战功卓著。在米兰自立为帝。被克劳狄二世围攻，战败被俘，随即被处决。', '', '君主', '三世纪危机', '帝国历史/大罗马/罗马帝国/元首_三世纪危机', 0, 'unknown', 0, 0, 0, '', 268, 0, 0, 0, '', '', '', '', '', '', ''),
(2784, 'claudiusii', '克劳狄二世', '克劳狄二世', 'rome', '', '', '获称哥特征服者。平定米兰僭位者奥略卢斯；着手收复高卢帝国领土；征讨汪达尔人时感染瘟疫病逝，指定奥勒良继位。元老院将其奉为神明。', 'https://baike.baidu.com/item/克劳狄二世/7532022', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 214, 5, 10, '', 270, 1, 0, 0, '', '', '', '', '', '', ''),
(2785, 'quintillus', '昆提卢斯', '昆提卢斯', 'rome', '', '', '被罗马元老院拥立继位。军队拥立时任骑兵总司令的奥勒良为新任皇帝，元老院只能予以追认。无法忍受这种耻辱的昆提卢斯自杀。', 'https://baike.baidu.com/item/昆提卢斯/7532118', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, 'unknown', 0, 0, 0, '', 270, 0, 0, 0, '', '', '', '', '', '', ''),
(2786, 'aurelian', '奥勒良', '奥勒良', 'rome', '', '', '尊称为世界重建者。收复高卢帝国与帕尔米拉帝国，初步解决三世纪危机，推行军事与货币改革。远征萨珊波斯途中遭秘书官艾洛斯谋杀。', 'https://baike.baidu.com/item/奥勒良/10813718', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 214, 9, 9, '', 275, 9, 0, 0, '', '', '', '', '', '', ''),
(2787, 'septimius', '赛普蒂米乌斯', '赛普蒂米乌斯', 'rome', '', '', '原为罗马军队将领，在达尔马提亚地区被士兵拥立为帝，但统治时间短暂，很快便被杀。', '', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2788, 'claudiustacitus', '塔西佗', '塔西佗', 'rome', '', '', '出身贵族，仕途顺利。是元老院最后一次行使选举皇帝权力的皇帝。赏赐禁卫军，稳定局势。', 'https://baike.baidu.com/item/克劳狄·塔西佗/7532718', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 200, 0, 0, '', 276, 0, 0, 0, '', '', '', '', '', '', ''),
(2789, 'florianus', '弗洛里安努斯', '弗洛里安努斯', 'rome', '', '', '被西部军队拥立为帝，东部军队随即拥立普罗布斯为帝，双方爆发内战。塔尔苏斯被部下刺杀。军队成为拥立皇帝的主导力量。', 'https://baike.baidu.com/item/弗洛里安努斯/7537699', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 232, 8, 19, '', 276, 9, 9, 0, '', '', '', '', '', '', ''),
(2790, 'probus', '普罗布斯', '普罗布斯', 'rome', '', '', '一位卓越的将领。光复了高卢，击败了并赶走了法兰克人和汪达尔人。平定了数场叛乱。安排军队开垦土地，栽种灌溉。被兵变的士兵杀死。', 'https://baike.baidu.com/item/普罗布斯/7188930', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 232, 0, 0, '', 282, 0, 0, 0, '', '', '', '', '', '', ''),
(2791, 'saturninus', '萨图尼努斯', '萨图尼努斯', 'rome', '', '', '于埃及自立为帝。他可能曾是普罗布斯的朋友或同僚。叛乱很快被平定，萨图尼努斯被杀。', '', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, 'unknown', 0, 0, 0, '', 280, 0, 0, 0, '', '', '', '', '', '', ''),
(2792, 'proculus', '普罗库鲁斯', '普罗库鲁斯', 'rome', '', '', '据说是阿尔卑斯地区的军阀或土匪头目，利用高卢地区的混乱，自立为帝。很快被另一股势力（可能是皇帝普罗布斯的军队）击败并杀害。', '', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2793, 'bonosus', '博诺苏斯', '博诺苏斯', 'rome', '', '', '博诺苏斯负责守卫的莱茵河防线被日耳曼部落突破，为躲避惩罚铤而走险，自立为帝。普罗布斯皇帝率军征讨，城破后选择自缢身亡。', '', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 0, 0, 0, '', 281, 0, 0, 0, '', '', '', '', '', '', ''),
(2794, 'marcusaureliuscarus', '卡鲁斯', '卡鲁斯', 'rome', '', '', '被军队拥立为帝，击败入侵潘诺尼亚的萨尔马提亚人和夸迪人。攻占塞琉西亚和泰西封。在军营中因雷击（或疾病或毒杀）突然死亡。', 'https://baike.baidu.com/item/马可·奥勒留·卡鲁斯/7540951', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 224, 0, 0, '', 283, 0, 0, 0, '', '', '', '', '', '', ''),
(2795, 'carinus', '卡里努斯', '卡里努斯', 'rome', '', '', '卡里努斯与弟弟努梅里安共同继承帝位。发行了减重的安敦尼银币。与戴克里先争夺帝国统治权。遭部下刺杀。', 'https://baike.baidu.com/item/卡里努斯/7557155', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, 'unknown', 0, 0, 0, '', 285, 0, 0, 0, '', '', '', '', '', '', ''),
(2796, 'numerian', '努梅里安', '努梅里安', 'rome', '', '', '分管东部军事。东征军撤退至小亚细亚时被发现死亡，其死因存在谋杀与自然死亡的争议。戴克里先登上舞台。', 'https://baike.baidu.com/item/努梅里安/7541659', '君主', '伊利里亚王朝', '帝国历史/大罗马/罗马帝国/元首_伊利里亚王朝', 0, '', 0, 0, 0, '', 284, 11, 0, 0, '', '', '', '', '', '', ''),
(2797, 'postumus', '波斯杜穆斯', '波斯杜穆斯', 'gaoludiguo', '', '', '罗马帝国叛将，高卢帝国建立者，统治高卢、日耳曼行省、不列颠行省和伊比利亚行省。遭士兵杀害。', 'https://baike.baidu.com/item/波斯杜穆斯/12600950', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 268, 0, 0, 0, '', '', '', '', '', '', ''),
(2798, 'laelianus', '莱利阿努斯', '莱利阿努斯', 'gaoludiguo', '', '', '高卢帝国的一名高级将领。在美因茨被军团拥立为帝，起兵对抗维克托里努斯。维克托里努斯率军攻破美因茨。莱利阿努斯被自己的士兵杀死。', '', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 269, 0, 0, 0, '', '', '', '', '', '', ''),
(2799, 'marius', '马里乌斯', '马里乌斯', 'gaoludiguo', '', '', '仅执政 2-3天或数周。铁匠（或兵器匠人）。醉酒后被人用自己打造的剑杀死（一说被下属所杀，一说被竞争者维克托里努斯派系清除）。', '', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 269, 0, 0, 0, '', '', '', '', '', '', ''),
(2800, 'victorinus', '维克托利努斯', '维克托利努斯', 'gaoludiguo', '', '', '高卢贵族，其母维多利亚颇具影响力。在高卢军队和其母的支持下被拥立为帝。因桃色丑闻被一名军官杀害。', '', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 271, 0, 0, 0, '', '', '', '', '', '', ''),
(2801, 'domitianus', '多米提安努斯', '多米提安努斯', 'gaoludiguo', '', '', '可能是高卢帝国军队中的一名高级军官。在位时间极短，几天或几周。被支持泰特里库斯的势力（或泰特里库斯本人）镇压并处决。', '', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 271, 0, 0, 0, '', '', '', '', '', '', ''),
(2802, 'tetricusi', '泰特里库斯一世', '泰特里库斯一世', 'gaoludiguo', '', '', '向奥勒良投降，高卢帝国灭亡。', 'https://baike.baidu.com/item/泰特里库斯一世/7648982', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2803, 'tetricusii', '泰特里库斯二世', '泰特里库斯二世', 'gaoludiguo', '', '', '与泰特里库斯一世为共治皇帝。投降后，父子二人得以保全性命，此后以普通公民身份度过余生。', 'https://baike.baidu.com/item/泰特里库斯二世/0', '君主', '元首', '大国和组织/法国/高卢帝国/元首', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2804, 'carausius', '卡劳修斯', '卡劳修斯', 'rome', '', '', '自封为“不列颠及高卢北部皇帝”。精明强干、颇有建树的地方割据者。君士坦提乌斯攻打不列颠之前，卡劳修斯被其财政官 阿勒克图斯 谋杀并取代。', '', '君主', '不列颠帝国', '帝国历史/大罗马/罗马帝国/元首_不列颠帝国', 0, '', 0, 0, 0, '', 293, 0, 0, 0, '', '', '', '', '', '', ''),
(2805, 'allectus', '阿勒克图斯', '阿勒克图斯', 'rome', '', '', '被君士坦提乌斯一世击败。不列颠重新纳入罗马帝国版图。', '', '君主', '不列颠帝国', '帝国历史/大罗马/罗马帝国/元首_不列颠帝国', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2806, 'constantineithegreat', '君士坦丁一世', '君士坦丁一世', 'rome', '', '', '曾为戴克里先服务。重新统一罗马帝国。实施了一系列的改革。吸收蛮族在帝国境内定居并入伍。与李锡尼颁布“米兰敕令”，迁都拜占庭。', 'https://baike.baidu.com/item/君士坦丁一世/2276656', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 272, 2, 27, '', 337, 5, 22, 0, '', '', '', '', '', '', ''),
(2807, 'constantineii', '君士坦丁二世', '君士坦丁二世', 'rome', '', '', '与两弟君士坦提二世和君士坦斯一世共分帝国，获得高卢、不列颠和西班牙。340年与君士坦斯一世争夺意大利，战败被杀。', 'https://baike.baidu.com/item/君士坦丁二世/22847578', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 0, 0, 0, '', 340, 0, 0, 0, '', '', '', '', '', '', ''),
(2808, 'constantiusii', '君士坦提乌斯二世', '君士坦提乌斯二世', 'rome', '', '', '掌管东部。重新统一帝国。为应对波斯与蛮族威胁，任命堂弟尤利安为西部凯撒，后尤利安反叛。在东征途中病逝。', 'https://baike.baidu.com/item/君士坦提乌斯二世/748673', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 317, 0, 0, '', 361, 0, 0, 0, '', '', '', '', '', '', ''),
(2809, 'constans', '君士坦斯一世', '君士坦斯一世', 'rome', '', '', '统治意大利、阿非利加和伊利里库姆。击败君士坦丁二世的入侵，得了整个帝国的西部地区。被篡位者马格嫩提乌斯杀死。', 'https://baike.baidu.com/item/君士坦斯一世/12623467', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 323, 0, 0, '', 350, 0, 0, 0, '', '', '', '', '', '', ''),
(2810, 'magnentius', '马格嫩提乌斯', '马格尼提乌斯', 'rome', '', '', '马格嫩提乌斯杀死君士坦斯一世后自立。君士坦提乌斯二世挥兵西进，平定了马格嫩提乌斯的叛乱，重新统一了罗马帝国。', 'https://baike.baidu.com/item/马格尼提乌斯/23517237', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 303, 0, 0, '', 353, 8, 11, 0, '', '', '', '', '', '', ''),
(2811, 'vetriano', '维特里亚诺', '维特拉尼奥', 'rome', '', '', '为对抗篡位者马格嫩提乌斯，被临时拥立为帝。与君士坦提乌斯二世会面后当场摘下皇冠，跪拜君士坦提乌斯二世，宣布效忠。', '', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 0, 0, 0, '', 356, 0, 0, 0, '', '', '', '', '', '', ''),
(2812, 'nepotianus', '尼波提亚努斯', '尼波提亚努斯', 'rome', '', '', '君士坦丁王朝皇室成员。马格嫩提乌斯派兵镇压，尼波提亚努斯在逃亡时被抓获，斩首。母亲尤特罗皮娅以及许多支持他的元老、贵族被处决。', '', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 0, 0, 0, '', 350, 0, 0, 0, '', '', '', '', '', '', ''),
(2813, 'juliantheapostate', '背教者尤利安', '背教者尤利安', 'rome', '', '', '最后一位多神信仰的统治者，推行恢复异教神庙政策。施行政改革，包括财税改革，削减宫廷开支，颁布教育法令。亲征波斯萨珊王朝战死。', 'https://baike.baidu.com/item/尤利安/2641717', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 331, 0, 0, '', 363, 0, 0, 0, '', '', '', '', '', '', ''),
(2814, 'jovian', '约维安', '约维安', 'rome', '', '', '被军队拥立为帝。废除尤利安的异教复兴政策，恢复基督教正统地位，在撤退途中死亡，死因可能为食用毒蘑菇或一氧化碳中毒。', 'https://baike.baidu.com/item/约维安/3624050', '君主', '君士坦丁王朝', '帝国历史/大罗马/罗马帝国/元首_君士坦丁王朝', 0, '', 332, 0, 0, '', 364, 2, 17, 0, '', '', '', '', '', '', ''),
(2827, 'michaelviii', '米海尔八世', '米海尔八世', 'byzantium', '', '尼西亚', '巴列奥略王朝的奠基人。成为尼西亚帝国约翰四世的共治皇帝。在热那亚的支持下占领君士坦丁堡，重建拜占庭帝国。', 'https://baike.baidu.com/item/米海尔八世/6403591', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1224, 0, 0, '', 1282, 12, 11, 0, '', '', '', '', '', '', ''),
(2828, 'andronicusii', '安德罗尼卡二世', '安德罗尼卡二世', 'byzantium', '', '', '大幅削减陆军；并解散海军。导致奥斯曼控制安纳托利亚地区。中央集权瓦解；经济衰退；推动拜占庭文化艺术复兴；支持东正教独立。', 'https://baike.baidu.com/item/安德罗尼卡二世/9594087', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1259, 3, 25, '', 1332, 2, 13, 0, '', '', '', '', '', '', ''),
(2829, 'michaelix', '米海尔九世', '米海尔九世', 'byzantium', '', '', '雇佣弗洛尔的加泰隆军团对抗土耳其人。因暴行不断杀害弗洛尔，导致加泰隆人叛乱并长期蹂躏色雷斯地区。', 'https://baike.baidu.com/item/迈克尔九世·帕里奥洛加斯/9618766', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1277, 4, 17, '', 1320, 10, 12, 0, '', '', '', '', '', '', ''),
(2830, 'andronicusiii', '安德罗尼卡三世', '安德罗尼卡三世', 'byzantium', '', '', '因帝位与祖父安德洛尼卡二世引发内战。与保加利亚君主米哈伊尔·希什曼联手战胜与塞尔维亚君主斯特凡·乌罗什三世联手的祖父。', 'https://baike.baidu.com/item/安德罗尼卡三世/9594369', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1297, 3, 25, '', 1341, 6, 15, 0, '', '', '', '', '', '', ''),
(2831, 'ioannesv', '约翰五世', '约翰五世', 'byzantium', '', '', '约翰六世、安德洛尼卡四世先后摄政。奥斯曼占领拜占廷大片土地。不得不承认土耳其人的宗主权。帝国危如累卵。对西方给予无限的遐想。', 'https://baike.baidu.com/item/约翰五世/2246788', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1331, 11, 0, '', 1391, 2, 16, 0, '', '', '', '', '', '', ''),
(2832, 'ioannesvikantakouzenos', '约翰六世', '约翰六世', 'byzantium', '', '君士坦丁堡', '任安德洛尼卡三世的首相，推行造船计划。因权力斗争被定为叛国者；借助奥斯曼军队攻入君士坦丁堡，加冕为约翰五世的共治皇帝。', 'https://baike.baidu.com/item/约翰六世/9615980', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1292, 0, 0, '', 1383, 6, 15, 0, '', '', '', '', '', '', ''),
(2833, 'andronicusiv', '安德罗尼卡四世', '安德罗尼卡四世', 'byzantium', '', '', '借助热那亚军队于攻占君士坦丁堡，废黜并囚禁其父自立为帝。约翰五世在威尼斯与奥斯曼土耳其支持下复辟，被迫恢复储君身份。', 'https://baike.baidu.com/item/安德罗尼卡四世/9616376', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1348, 4, 2, '', 1385, 6, 28, 0, '', '', '', '', '', '', ''),
(2834, 'ioannesvii', '约翰七世', '约翰七世', 'byzantium', '', '', '继承西利夫里总督职位。在奥斯曼土耳其与热那亚支持下称帝。后被约翰五世驱逐。后任曼努埃尔二世摄政。', 'https://baike.baidu.com/item/约翰七世/7019429', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1370, 0, 0, '', 1408, 0, 0, 0, '', '', '', '', '', '', ''),
(2835, 'manuelii', '曼努埃尔二世', '曼努埃尔二世', 'byzantium', '', '', '奥斯曼围困君士坦丁堡，曾赴欧洲寻求西方援军并与罗马教廷展开长期谈判。后奥斯曼帝国在安卡拉战役战败。推动了莫利亚文化复兴。', 'https://baike.baidu.com/item/曼努埃尔二世/49960', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1350, 6, 27, '', 1425, 7, 21, 0, '', '', '', '', '', '', ''),
(2836, 'ioannesviii', '约翰八世', '约翰八世', 'byzantium', '', '君士坦丁堡', '仅余君士坦丁堡及少数孤立领土。成功抵御奥斯曼对都城的围攻。教皇组织的十字军在瓦尔纳战役溃败。任命多个弟弟导致国内权力分散。', 'https://baike.baidu.com/item/约翰八世/9816240', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1390, 0, 0, '', 1448, 10, 31, 0, '', '', '', '', '', '', ''),
(2837, 'constantinexi', '君士坦丁十一世', '君士坦丁十一世', 'byzantium', '', '', '东罗马帝国末代皇帝。穆罕默德二世率军围攻君士坦丁堡，君士坦丁十一世便冲入敌阵，战死沙场。', 'https://baike.baidu.com/item/君士坦丁十一世/2108390', '君主', '巴列奥略王朝', '帝国历史/大罗马/拜占庭/皇帝_巴列奥略王朝', 0, '', 1404, 2, 9, '', 1453, 5, 29, 0, '', '', '', '', '', '', ''),
(2838, 'theodorei', '狄奥多尔一世', '狄奥多尔一世', 'byzantium', '', '', '十字军攻陷君士坦丁堡之际，流亡至小亚细亚建立政权。与塞尔柱人建立联盟，并在巴尔干半岛击败保加尔人。', 'https://baike.baidu.com/item/狄奥多一世·拉斯卡里斯/15577319', '君主', '拉斯卡利斯王朝', '帝国历史/大罗马/拜占庭/皇帝_拉斯卡利斯王朝', 0, '', 1174, 0, 0, '', 1221, 0, 0, 0, '', '', '', '', '', '', ''),
(2839, 'ioannesiii', '约翰三世', '约翰三世', 'byzantium', '', '', '征服小亚细亚并获得拉丁帝国承认。复兴希腊文化并重建军队舰队。为拜占庭帝国光复奠定基础，被誉为尼西亚乃至拜占庭后期的最强英主。', 'https://baike.baidu.com/item/约翰三世/15088139', '君主', '拉斯卡利斯王朝', '帝国历史/大罗马/拜占庭/皇帝_拉斯卡利斯王朝', 0, '', 1193, 0, 0, '', 1254, 11, 3, 0, '', '', '', '', '', '', ''),
(2840, 'theodoreii', '狄奥多尔二世', '狄奥多尔二世', 'byzantium', '土耳其的布尔萨', '尼西亚', '哲学家、神学家和作家。深信皇帝应兼具智慧与虔诚，认为帝国应由受过良好教育的精英统治。', 'https://baike.baidu.com/item/提奥多雷二世/868973', '君主', '拉斯卡利斯王朝', '帝国历史/大罗马/拜占庭/皇帝_拉斯卡利斯王朝', 0, '', 1221, 0, 0, '', 1258, 8, 16, 0, '', '', '', '', '', '', ''),
(2841, 'ioannesiv', '约翰四世', '约翰四世', 'byzantium', '', '', '米海尔趁约翰四世年幼发动政变，杀死摄政木扎伦并于次年成为共治皇帝。米海尔收复君士坦丁堡建立巴列奥略王朝。尼西亚帝国终止。', 'https://baike.baidu.com/item/约翰四世/19492725', '君主', '拉斯卡利斯王朝', '帝国历史/大罗马/拜占庭/皇帝_拉斯卡利斯王朝', 0, '', 1250, 12, 25, '', 1305, 0, 0, 0, '', '', '', '', '', '', ''),
(2847, 'isaacii', '伊萨克二世', '伊萨克二世', 'byzantium', '', '', '抵御西西里诺曼人入侵，镇压保加利亚叛乱；允许第三次十字军穿越帝国领土；击败塞尔维亚大公内马尼亚。阿历克塞三世政变废黜并致盲。', 'https://baike.baidu.com/item/伊萨克二世/10183380', '君主', '安格鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_安格鲁斯王朝', 0, 'unknown', 0, 0, 0, '', 1204, 0, 0, 0, '', '', '', '', '', '', ''),
(2848, 'alexiusiii', '阿历克塞三世', '阿历克塞三世', 'byzantium', '', '', '第四次十字军东征攻击了君士坦丁堡，并最终使得拜占庭帝国崩溃，分解为多个小国家。', 'https://baike.baidu.com/item/阿历克塞三世/19917429', '君主', '安格鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_安格鲁斯王朝', 0, '', 1153, 0, 0, '', 1211, 0, 0, 0, '', '', '', '', '', '', ''),
(2849, 'alexiusiv', '阿历克塞四世', '阿历克塞四世', 'byzantium', '', '', '在十字军及威尼斯盟友协助下，阿历克塞四世与伊萨克二世夺回帝位并共治。很快被阿历克塞五世推翻，被缢死。', 'https://baike.baidu.com/item/阿历克塞四世·安格洛斯/15717636', '君主', '安格鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_安格鲁斯王朝', 0, '', 1182, 0, 0, '', 1204, 2, 8, 0, '', '', '', '', '', '', ''),
(2850, 'alexiusv', '阿历克塞五世', '阿历克塞五世', 'byzantium', '', '', '利用民众起义推翻伊萨克二世与阿历克塞四世联合统治。君士坦丁堡沦陷后，逃亡投奔阿历克塞三世，遭其致盲后被十字军俘获，被处死。', 'https://baike.baidu.com/item/阿历克塞五世/15529507', '君主', '安格鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_安格鲁斯王朝', 0, '', 0, 0, 0, '', 1204, 0, 0, 0, '', '', '', '', '', '', ''),
(2851, 'constantinex', '君士坦丁十世', '君士坦丁十世', 'byzantium', '', '', '科穆宁王朝皇帝伊萨克一世被废黜后称帝。合格的神学辩论家，宫廷阴谋家，极度失败的帝国皇帝。', 'https://baike.baidu.com/item/君士坦丁十世/9617402', '君主', '杜卡斯王朝', '帝国历史/大罗马/拜占庭/皇帝_杜卡斯王朝', 0, 'probably', 1006, 0, 0, 'probably', 1067, 0, 0, 0, '', '', '', '', '', '', ''),
(2852, 'eudokia', '尤多西娅', '尤多西娅', 'byzantium', '', '', '拜占庭皇后、摄政太后、作家。为拯救帝国危机，嫁给了杰出的将军罗曼努斯·狄奥吉尼斯为夫并加冕为帝（罗曼努斯四世）。', '', '君主', '杜卡斯王朝', '帝国历史/大罗马/拜占庭/皇帝_杜卡斯王朝', 0, 'probably', 1021, 0, 0, 'probably', 1096, 0, 0, 0, '', '', '', '', '', '', ''),
(2853, 'romanosiv', '罗曼努斯四世', '罗曼努斯四世', 'byzantium', '', '', '致力于收复安纳托利亚失地。曼齐刻尔特战役惨败，帝国衰落转折点丧失小亚细亚控制权，帝国衰落转折点。被俘获释后被刺瞎流放后去世。', 'https://baike.baidu.com/item/罗曼努斯四世/8435257', '君主', '杜卡斯王朝', '帝国历史/大罗马/拜占庭/皇帝_杜卡斯王朝', 0, 'unknown', 0, 0, 0, '', 1072, 0, 0, 0, '', '', '', '', '', '', ''),
(2854, 'michaelvii', '米海尔七世', '米海尔七世', 'byzantium', '', '君士坦丁堡', '推行增税政策，导致军费短缺。诺曼雇佣军反叛，小亚细亚被突厥占据并建立鲁姆苏丹国。因粮食垄断政策导致堡物价动荡。军事逼宫后退位。', 'https://baike.baidu.com/item/米海尔七世/15545744', '君主', '杜卡斯王朝', '帝国历史/大罗马/拜占庭/皇帝_杜卡斯王朝', 0, '', 1050, 0, 0, '', 1090, 0, 0, 0, '', '', '', '', '', '', ''),
(2855, 'nikepholosiii', '尼基弗鲁斯三世', '尼基弗鲁斯三世', 'byzantium', '', '小亚细亚半岛', '军事政变自立为帝。将政务委托门客处理。统治后期国内叛乱频发，被阿历克塞·科穆宁率军推翻，退入修道院后病逝。', 'https://baike.baidu.com/item/尼基弗鲁斯三世/15614691', '君主', '杜卡斯王朝', '帝国历史/大罗马/拜占庭/皇帝_杜卡斯王朝', 0, '', 1001, 0, 0, '', 1081, 0, 0, 0, '', '', '', '', '', '', ''),
(2856, 'isaaci', '伊萨克一世', '伊萨克一世', 'byzantium', '', '', '政变中被拥立为皇帝。企图抑制教会和官僚，被以米海尔·普塞尔乌斯为首的帝都贵族推翻。基于功绩而非亲属关系提名君士坦丁十世为继任者。', 'https://baike.baidu.com/item/伊萨克一世/9861531', '君主', '科穆宁王朝', '帝国历史/大罗马/拜占庭/皇帝_科穆宁王朝', 0, 'probably', 1007, 0, 0, 'probably', 1061, 0, 0, 0, '', '', '', '', '', '', ''),
(2857, 'alexiusi', '阿历克塞一世', '阿历克塞一世', 'byzantium', '', '', '重建科穆宁王朝。加强中央集权，建立常备陆海军。促成第一次十字军东征。借机收复小亚细亚西部地区。', 'https://baike.baidu.com/item/阿历克塞一世/6405092', '君主', '科穆宁王朝', '帝国历史/大罗马/拜占庭/皇帝_科穆宁王朝', 0, 'probably', 1056, 0, 0, '', 1118, 8, 15, 0, '', '', '', '', '', '', ''),
(2858, 'ioannesi', '约翰二世', '约翰二世', 'byzantium', '', '', '虔诚且极富恻隐之心。拜占庭与十字军联军的领导者，并挺进穆斯林占据的叙利亚地区。展示了拜占庭皇帝在基督教世界中的领导者地位。', 'https://baike.baidu.com/item/约翰二世/22939', '君主', '科穆宁王朝', '帝国历史/大罗马/拜占庭/皇帝_科穆宁王朝', 0, '', 1087, 9, 13, '', 1143, 4, 8, 0, '', '', '', '', '', '', ''),
(2859, 'manueli', '曼努埃尔一世', '曼努埃尔一世', 'byzantium', '', '', '推行积极扩张政策。挑动意大利城邦与神圣罗马帝国对立；恢复帝国商业地位。地中海最具影响力的政权。过度消耗国力；惨败于塞尔柱突厥。', 'https://baike.baidu.com/item/曼努埃尔一世/8295421', '君主', '科穆宁王朝', '帝国历史/大罗马/拜占庭/皇帝_科穆宁王朝', 0, '', 1118, 11, 28, '', 1180, 9, 24, 0, '', '', '', '', '', '', ''),
(2860, 'alexiusii', '阿历克塞二世', '阿历克塞二世', 'byzantium', '', '', '由其母安条克的玛丽摄政。安德罗尼卡发动叛乱，加冕为共治皇帝。阿莱克修斯二世遭弓弦勒杀。', 'https://baike.baidu.com/item/阿历克塞二世/9243314', '君主', '科穆宁王朝', '帝国历史/大罗马/拜占庭/皇帝_科穆宁王朝', 0, '', 1169, 9, 10, '', 1183, 10, 0, 0, '', '', '', '', '', '', ''),
(2861, 'andronicusi', '安德罗尼卡一世', '安德罗尼卡一世', 'byzantium', '', '君士坦丁堡', '推行禁止售卖官职、打击贵族特权等改革，并断绝与西方的联系，导致曼努埃尔一世中兴后的帝国迅速衰败。首都爆发叛乱，遭暴民处决。', 'https://baike.baidu.com/item/安德罗尼卡一世/3785569', '君主', '科穆宁王朝', '帝国历史/大罗马/拜占庭/皇帝_科穆宁王朝', 0, 'probably', 1118, 0, 0, '', 1185, 9, 12, 0, '', '', '', '', '', '', ''),
(2862, 'arcadius', '阿卡狄奥斯', '阿卡狄奥斯', 'byzantium', '', '', '继承东部帝国统治权。朝政先后由权臣鲁菲努斯、宦官优特罗皮乌斯及禁卫军长官安特米乌斯掌控。边境持续遭受哥特人侵扰。', 'https://baike.baidu.com/item/阿卡狄奥斯/14762033', '君主', '狄奥多西王朝', '帝国历史/大罗马/拜占庭/皇帝_狄奥多西王朝', 0, '', 377, 0, 0, '', 408, 5, 1, 0, '', '', '', '', '', '', ''),
(2863, 'theodosiusii', '狄奥多西二世', '狄奥多西二世', 'byzantium', '', '', '颁布西方首部官方法典《狄奥多西法典》。多次向匈人纳贡并割让边境城市互市。', 'https://baike.baidu.com/item/狄奥多西二世/8521186', '君主', '狄奥多西王朝', '帝国历史/大罗马/拜占庭/皇帝_狄奥多西王朝', 0, '', 401, 4, 0, '', 450, 7, 28, 0, '', '', '', '', '', '', ''),
(2864, 'pulcheria', '普尔喀丽娅', '普尔喀丽娅', 'byzantium', '', '', '曾为弟弟狄奥多西二世摄政。将皇冠授给年迈的元老马西安，并与马西安结婚，仍与之共治至死。', 'https://baike.baidu.com/item/普尔喀丽亚/22854218', '君主', '狄奥多西王朝', '帝国历史/大罗马/拜占庭/皇帝_狄奥多西王朝', 0, '', 398, 0, 0, '', 453, 0, 0, 0, '', '', '', '', '', '', ''),
(2865, 'marcian', '马尔西安', '马尔西安', 'byzantium', '', '', '国家局势稳定，是帝国的黄金时代。拒绝向阿提拉纳贡，导致匈人入侵。召集卡尔西顿会议，坚持基督有神人二性，反对基督一性论。', 'https://baike.baidu.com/item/马尔西安/17006617', '君主', '狄奥多西王朝', '帝国历史/大罗马/拜占庭/皇帝_狄奥多西王朝', 0, '', 392, 3, 0, '', 457, 0, 0, 0, '', '', '', '', '', '', ''),
(2872, 'leoi', '利奥一世', '利奥一世', 'byzantium', '', '', '重要的军事统治者，首开圣索菲亚教堂加冕仪式的先河，确立君权神授的合法性。挫败统帅阿斯帕尔的阴谋集团。', 'https://baike.baidu.com/item/利奥一世/7112256', '君主', '利奥王朝', '帝国历史/大罗马/拜占庭/皇帝_利奥王朝', 0, 'unknown', 0, 0, 0, '', 474, 0, 0, 0, '', '', '', '', '', '', ''),
(2873, 'leoii', '利奥二世', '利奥二世', 'byzantium', '', '', '政权由其父芝诺掌控。474年加冕其父为共治皇帝后，利奥二世在位仅10个月即病逝，传言其母阿里阿德涅为助芝诺掌权而毒杀亲子。', 'https://baike.baidu.com/item/利奥二世/14707464', '君主', '利奥王朝', '帝国历史/大罗马/拜占庭/皇帝_利奥王朝', 0, '', 467, 0, 0, '', 474, 11, 17, 0, '', '', '', '', '', '', ''),
(2874, 'zeno', '芝诺', '芝诺', 'byzantium', '', '', '通过联姻进入权力核心。因军事政变流亡伊索里亚，次年复位推行改革。试图调解正教与基督一性论派争端。为查士丁尼一世时期扩张奠定基础。', 'https://baike.baidu.com/item/芝诺/10142453', '君主', '利奥王朝', '帝国历史/大罗马/拜占庭/皇帝_利奥王朝', 0, 'probably', 425, 0, 0, '', 491, 0, 0, 0, '', '', '', '', '', '', ''),
(2875, 'basiliskos', '瓦西里斯科斯', '瓦西里斯科斯', 'byzantium', '', '', '在皇后维丽娜（他的妹妹）和部分朝臣的支持下称帝。因治国无方、树敌过多而迅速垮台。', '', '君主', '利奥王朝', '帝国历史/大罗马/拜占庭/皇帝_利奥王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2876, 'anastasiusi', '阿纳斯塔修斯一世', '阿纳斯塔修斯一世', 'byzantium', '', '', '经芝诺遗孀阿里阿德纳指定继承皇位，并与其完婚。推行财政改革废除官职出售制度。坚持基督一性论引发维塔里安领导的色雷斯叛乱。', 'https://baike.baidu.com/item/阿纳斯塔修斯一世/5852863', '君主', '利奥王朝', '帝国历史/大罗马/拜占庭/皇帝_利奥王朝', 0, 'probably', 430, 0, 0, '', 518, 7, 9, 0, '', '', '', '', '', '', ''),
(2877, 'justinusi', '查士丁一世', '查士丁一世', 'byzantium', '', '', '任阿纳斯塔修斯一世时期禁卫军队长，外甥查士丁尼一世通过政治运作助其登基。取消前任皇帝的一性论宗教政策，恢复与西部教会关系。', 'https://baike.baidu.com/item/查士丁一世/22854222', '君主', '查士丁尼王朝', '帝国历史/大罗马/拜占庭/皇帝_查士丁尼王朝', 0, '', 450, 0, 0, '', 527, 8, 0, 0, '', '', '', '', '', '', ''),
(2878, 'justiniani', '查士丁尼一世', '查士丁尼一世', 'byzantium', '', '', '一个帝国、一个教会（圣索菲亚大教堂）和一部法典（查士丁尼民法大全）。古典时期的东罗马帝国向希腊化的拜占庭帝国转型的重要过渡期。', 'https://baike.baidu.com/item/查士丁尼一世/991558', '君主', '查士丁尼王朝', '帝国历史/大罗马/拜占庭/皇帝_查士丁尼王朝', 0, 'probably', 482, 0, 0, '', 565, 11, 14, 0, '', '', '', '', '', '', ''),
(2879, 'justinusii', '查士丁二世', '查士丁二世', 'byzantium', '', '', '面临国库空虚与军事危机，因战事失利退位，将权力移交提比略二世。实施退还民众贷款、减免赋税等政策。被迫支付波斯巨额赔偿。', 'https://baike.baidu.com/item/查士丁二世/11007836', '君主', '查士丁尼王朝', '帝国历史/大罗马/拜占庭/皇帝_查士丁尼王朝', 0, '', 520, 0, 0, '', 578, 10, 4, 0, '', '', '', '', '', '', ''),
(2880, 'tiberiusii', '提比略二世', '提比略二世', 'byzantium', '', '', '引入马镫技术，推动中世纪骑士阶级形成。资助了耶路撒冷西部一座拜占庭教堂的扩建工程。', 'https://baike.baidu.com/item/提比略二世/11008203', '君主', '查士丁尼王朝', '帝国历史/大罗马/拜占庭/皇帝_查士丁尼王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2881, 'mauricei', '莫里斯一世', '莫里斯一世', 'byzantium', '', '', '军事家、军事理论家。采守势战略，建立边防体系。组织编写军事著作《战略》。实施财政紧缩政策引发军队与民众不满，被驻军推翻并处决。', 'https://baike.baidu.com/item/莫里斯一世/11008765', '君主', '查士丁尼王朝', '帝国历史/大罗马/拜占庭/皇帝_查士丁尼王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2882, 'heraclius', '希拉克略', '希拉克略', 'byzantium', '', '', '对内完成希腊化改革，对外收复被波斯人侵占的领土。军事上实行军区制度。被认为是军区制的缔造者。', 'https://baike.baidu.com/item/希拉克略/9564719', '君主', '伊拉克略王朝', '帝国历史/大罗马/拜占庭/皇帝_伊拉克略王朝', 0, '', 575, 0, 0, '', 641, 2, 11, 0, '', '', '', '', '', '', ''),
(2883, 'constantineiiidong', '君士坦丁三世', '君士坦丁三世', 'byzantium', '', '', '与异母弟赫拉克洛纳斯共治，但因病重仅执政三个月。', '', '君主', '伊拉克略王朝', '帝国历史/大罗马/拜占庭/皇帝_伊拉克略王朝', 0, '', 612, 0, 0, '', 641, 0, 0, 0, '', '', '', '', '', '', ''),
(2884, 'heraclonas', '赫拉克洛纳斯', '赫拉克洛纳斯', 'byzantium', '', '', '将领因质疑玛蒂娜毒杀继子发动兵变，要求立君士坦斯为帝。赫拉克洛纳斯被迫同意共治，随后遭元老院、民众与军队联合废黜并流放。', 'https://baike.baidu.com/item/赫拉克洛纳斯/6491924', '君主', '伊拉克略王朝', '帝国历史/大罗马/拜占庭/皇帝_伊拉克略王朝', 0, 'probably', 615, 0, 0, 'probably', 641, 0, 0, 0, '', '', '', '', '', '', ''),
(2885, 'constansiidong', '君士坦斯二世', '君士坦斯二世', 'byzantium', '', '', '因整顿了波斯战争、阿拉伯入侵导致的乱局，建立对阿拉伯人进一步入侵的防御体系而被称作“救世之主”。', 'https://baike.baidu.com/item/君士坦斯二世/9591888', '君主', '伊拉克略王朝', '帝国历史/大罗马/拜占庭/皇帝_伊拉克略王朝', 0, '', 630, 0, 0, '', 668, 0, 0, 0, '', '', '', '', '', '', ''),
(2886, 'constantineiv', '君士坦丁四世', '君士坦丁四世', 'byzantium', '', '', '迫使哈里发穆阿维叶一世签订和约。召开第六次普教会议，宣布基督一志论为异端。为帝国军事体系转型奠定基础。', 'https://baike.baidu.com/item/君士坦丁四世/11010627', '君主', '伊拉克略王朝', '帝国历史/大罗马/拜占庭/皇帝_伊拉克略王朝', 0, '', 652, 0, 0, '', 685, 0, 0, 0, '', '', '', '', '', '', ''),
(2887, 'justinianii', '查士丁尼二世', '查士丁尼二世', 'byzantium', '', '', '意大利部分的很多城市企图独立。远征色雷斯和马其顿。间接促进了斯拉夫民族的发展及接受基督教。政变中被割掉了鼻子。第二次政变被杀害。', 'https://baike.baidu.com/item/查士丁尼二世/3624579', '君主', '伊拉克略王朝', '帝国历史/大罗马/拜占庭/皇帝_伊拉克略王朝', 0, 'probably', 670, 0, 0, '', 711, 12, 11, 0, '', '', '', '', '', '', ''),
(2888, 'leoiii', '利奥三世', '利奥三世', 'byzantium', '', '', '伟大的军事家、改革家、政治家。终结政局动荡，击退阿拉伯军队；禁止圣像崇拜，没收教会土地并强制征税，迫使大批教士还俗。', 'https://baike.baidu.com/item/利奥三世/3624645', '君主', '伊苏里亚王朝', '帝国历史/大罗马/拜占庭/皇帝_伊苏里亚王朝', 0, 'probably', 680, 0, 0, '', 741, 6, 18, 0, '', '', '', '', '', '', ''),
(2889, 'constantinev', '君士坦丁五世', '君士坦丁五世', 'byzantium', '', '', '开展破除圣像运动，镇压修道院势力。夺取叙利亚北部地区。获得“保加利亚屠夫”称号。遗骨被东正教会焚毁。', 'https://baike.baidu.com/item/君士坦丁五世/7843746', '君主', '伊苏里亚王朝', '帝国历史/大罗马/拜占庭/皇帝_伊苏里亚王朝', 0, '', 718, 0, 0, '', 755, 0, 0, 0, '', '', '', '', '', '', ''),
(2890, 'artabasdos', '阿尔塔瓦兹德', '阿尔塔瓦兹德', 'byzantium', '', '', '阿塔瓦斯德斯在亚美尼亚军区起兵，占领首都，宣称帝位。君士坦丁五世收复首都，阿塔瓦斯德斯被捕。关入修道院，终老于此。', '', '君主', '伊苏里亚王朝', '帝国历史/大罗马/拜占庭/皇帝_伊苏里亚王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2891, 'leoiv', '利奥四世', '利奥四世', 'byzantium', '', '', '镇压了同父异母兄弟的反叛，筹备进攻保加利亚时病逝。指定皇后伊琳娜为幼子君士坦丁六世的唯一监护人，为其妻后续掌权埋下伏笔。', 'https://baike.baidu.com/item/利奥四世/9621453', '君主', '伊苏里亚王朝', '帝国历史/大罗马/拜占庭/皇帝_伊苏里亚王朝', 0, '', 750, 1, 25, '', 780, 9, 8, 0, '', '', '', '', '', '', ''),
(2892, 'constantinevi', '君士坦丁六世', '君士坦丁六世', 'byzantium', '', '君士坦丁堡', '迫使伊琳娜放弃摄政权。对保加利亚及小亚细亚的军事行动中接连失利，并因镇压亲属及盟友引发政局动荡。伊琳娜集团政变刺瞎双目后废黜囚禁。', 'https://baike.baidu.com/item/君士坦丁六世/22186810', '君主', '伊苏里亚王朝', '帝国历史/大罗马/拜占庭/皇帝_伊苏里亚王朝', 0, '', 0, 0, 0, '', 805, 0, 0, 0, '', '', '', '', '', '', ''),
(2893, 'irene', '伊琳娜', '伊琳娜', 'byzantium', '', '', '镇压叛乱并于787年召开第二次尼西亚公会议恢复圣像崇拜。遭贵族政变推翻，被流放至莱斯博斯岛后贫病去世。被东正教修道院尊为圣人。', 'https://baike.baidu.com/item/伊琳娜/7019740', '君主', '伊苏里亚王朝', '帝国历史/大罗马/拜占庭/皇帝_伊苏里亚王朝', 0, '', 752, 0, 0, '', 803, 8, 9, 0, '', '', '', '', '', '', ''),
(2894, 'nikepholosi', '尼基弗鲁斯一世', '尼基弗鲁斯一世', 'byzantium', '', '', '原本为财政大臣，伊琳娜女皇被废后通过政继位，开展了一系列军事、内政改革。与保加利亚的战争中死亡。头顶骨被做成酒杯。', 'https://baike.baidu.com/item/尼基弗鲁斯一世/8943134', '君主', '尼基弗鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_尼基弗鲁斯王朝', 0, 'probably', 750, 0, 0, '', 811, 7, 26, 0, '', '', '', '', '', '', ''),
(2895, 'staurakios', '斯陶拉基奥斯', '斯陶拉基奥斯', 'byzantium', '', '', '普利斯卡战役中受重伤，被被残余军队拥立为皇帝。在妻子与妹妹两派斗争后，军方和元老院最终迫使瘫痪在床的斯陶拉基奥斯退位，进入修道院。', '', '君主', '尼基弗鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_尼基弗鲁斯王朝', 0, 'unknown', 0, 0, 0, '', 812, 1, 11, 0, '', '', '', '', '', '', ''),
(2896, 'michaeli', '迈克尔一世', '迈克尔一世', 'byzantium', '', '', '推行赏赐政策以巩固统治，支持圣像使用，承认查理曼大帝为巴塞勒斯（国王）。威尔西尼阿战役中因士兵哗变惨败。被利奥五世推翻。', 'https://baike.baidu.com/item/迈克尔一世/11032692', '君主', '尼基弗鲁斯王朝', '帝国历史/大罗马/拜占庭/皇帝_尼基弗鲁斯王朝', 0, 'unknown', 0, 0, 0, '', 844, 0, 0, 0, '', '', '', '', '', '', ''),
(2897, 'michaelii', '迈克尔二世', '迈克尔二世', 'byzantium', '土耳其阿菲永卡拉希萨尔省', '阿摩里奥人', '被神职人员称为无知的农民。使帝国军事力量得以恢复，带来了长时间的稳定。', 'https://baike.baidu.com/item/迈克尔二世/11022259', '君主', '弗里吉亚王朝', '帝国历史/大罗马/拜占庭/皇帝_弗里吉亚王朝', 0, '', 770, 0, 0, '', 829, 0, 0, 0, '', '', '', '', '', '', ''),
(2898, 'theophilus', '狄奥菲洛斯', '狄奥菲洛斯', 'byzantium', '', '', '颁布禁止偶像崇拜诏令，并强化司法权威。长期与阿巴斯王朝交战，后被迫议和。因军事失利与财政压力，圣像破坏政策式微。', 'https://baike.baidu.com/item/狄奥斐卢斯/14081217', '君主', '弗里吉亚王朝', '帝国历史/大罗马/拜占庭/皇帝_弗里吉亚王朝', 0, '', 800, 0, 0, '', 842, 1, 20, 0, '', '', '', '', '', '', ''),
(2899, 'michaeliii', '米海尔三世', '米海尔三世', 'byzantium', '', '', '由母亲狄奥多拉皇后摄政。颁布反对破坏圣像的法令。迫使保加利亚鲍里斯一世改宗东正教。重用巴西尔一世，867年被其暗杀。', 'https://baike.baidu.com/item/米海尔三世/4676036', '君主', '弗里吉亚王朝', '帝国历史/大罗马/拜占庭/皇帝_弗里吉亚王朝', 0, '', 840, 1, 9, '', 867, 9, 23, 0, '', '', '', '', '', '', ''),
(2917, 'basili', '瓦西里一世', '瓦西里一世', 'byzantium', '', '', '极力扩张帝国疆土。重视拜占庭海军的作用，并指挥其海军把阿拉伯海盗从地中海东部赶了出去。卒于狩猎时的一次事故。', 'https://baike.baidu.com/item/巴西尔一世/823294', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 812, 0, 0, '', 886, 0, 0, 0, '', '', '', '', '', '', ''),
(2918, 'leovi', '利奥六世', '利奥六世', 'byzantium', '', '', '完成了《皇帝立法》的编纂。引发教会法争议，最终促使拜占庭皇位继承制度发展。尽管面临外部战争压力，其内政管理为后继者奠定基础。', 'https://baike.baidu.com/item/利奥六世/11022534', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, 'unknown', 0, 0, 0, '', 912, 0, 0, 0, '', '', '', '', '', '', '');
INSERT INTO `wp_figure` (`id`, `code`, `name`, `name_card`, `country_code`, `native_place`, `native_place_history`, `description`, `baidu_url`, `path_label`, `path_gather`, `path_point`, `status`, `birth_accurate`, `birth_year`, `birth_month`, `birth_day`, `death_accurate`, `death_year`, `death_month`, `death_day`, `active_at`, `baidu_picture`, `extfield`, `path_old`, `dynasty`, `nationality`, `era`, `codebak`) VALUES
(2919, 'alexanderiii_dong', '亚历山大三世', '亚历山大三世', 'byzantium', '', '', '重新启用被贬贵族尼古拉斯·米斯提库斯。拜占庭与保加利亚国王西蒙一世爆发战争。战争全面爆发前去世。', 'https://baike.baidu.com/item/亚历山大三世/12646164', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 870, 0, 0, '', 913, 6, 6, 0, '', '', '', '', '', '', ''),
(2920, 'constantinevii', '君士坦丁七世', '君士坦丁七世', 'byzantium', '', '', '热心学术研究。妥协对待保加利亚，以及基辅罗斯的入侵。内政上和父亲一样精明，没有什么危机。为后世君主的征服打定了基础。', 'https://baike.baidu.com/item/君士坦丁七世/10909975', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 905, 9, 2, '', 955, 11, 9, 0, '', '', '', '', '', '', ''),
(2921, 'romanosi', '罗曼努斯一世', '罗曼努斯一世', 'byzantium', '', '', '逐步将佐伊皇后及其亲信清除出政府。大权独揽。其子发动政变，把他囚禁在王子岛群上。政变被君士坦丁七世镇压。', 'https://baike.baidu.com/item/罗曼努斯一世/5296312', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 870, 0, 0, '', 948, 6, 15, 0, '', '', '', '', '', '', ''),
(2922, 'romanosii', '罗马努斯二世', '罗马努斯二世', 'byzantium', '', '', '庸碌无能。派福卡斯率军从阿拉伯人手中收复克里特岛。遭皇后西奥法诺毒害，西奥法诺与福卡斯(即尼基弗鲁斯二世)结婚。', 'https://baike.baidu.com/item/罗马努斯二世/22854224', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, 'probably', 937, 0, 0, '', 963, 3, 0, 0, '', '', '', '', '', '', ''),
(2923, 'nikepholosii', '尼基弗鲁斯二世', '尼基弗鲁斯二世', 'byzantium', '', '', '凭借军事政变成为皇帝。被塞奥法诺与约翰一世谋害。建立了特塔特伦和希斯塔麦伦两种金币并行的制度。', 'https://baike.baidu.com/item/尼基弗鲁斯二世/15936103', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, 'probably', 912, 0, 0, '', 969, 12, 10, 0, '', '', '', '', '', '', ''),
(2924, 'ioannesidong', '约翰一世', '约翰一世', 'byzantium', '', '', '通过宫廷政变谋杀尼基弗鲁斯自立。消除了拜占庭北方的威胁。扩张了帝国的领土，并大幅增强了帝国的军事实力。', 'https://baike.baidu.com/item/约翰一世/10975612', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, 'probably', 925, 0, 0, '', 976, 1, 10, 0, '', '', '', '', '', '', ''),
(2925, 'basilii', '瓦西里二世', '瓦西里二世', 'byzantium', '', '', '杰出的君主、政治家、军事家。灭亡了盛极一时的保加利亚第一王国。重申保护小农的法律，缓和国内矛盾。帝国达到了第二次黄金时期。', 'https://baike.baidu.com/item/瓦西里二世/2923272', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 958, 0, 0, '', 1025, 12, 15, 0, '', '', '', '', '', '', ''),
(2926, 'constantineviii', '君士坦丁八世', '君士坦丁八世', 'byzantium', '', '', '马其顿王朝末代男性君主。独掌皇权后耽于享乐，官僚贵族重掌国政，导致帝国财政迅速消耗。令次女佐伊与罗曼诺斯三世成婚。', 'https://baike.baidu.com/item/君士坦丁八世/10922426', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 960, 0, 0, '', 1028, 11, 15, 0, '', '', '', '', '', '', ''),
(2927, 'zoe', '佐伊', '佐伊', 'byzantium', '', '', '三度婚姻共治时期。涉嫌谋害罗曼努斯三世后改嫁米海尔四世，养子米海尔五世流放佐伊；佐伊与妹妹狄奥多拉恢复共治。嫁君士坦丁九世。', 'https://baike.baidu.com/item/佐伊女皇/2700385', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 978, 0, 0, '', 1050, 6, 0, 0, '', '', '', '', '', '', ''),
(2928, 'romanosiii', '罗曼努斯三世', '罗曼努斯三世', 'byzantium', '', '', '废止限制大贵族的法令。亲征阿勒颇酋长国遭遇惨败。经济政策引发国库储备锐减与财政混乱。遭米海尔及其同党杀害。', 'https://baike.baidu.com/item/罗曼努斯三世/11023038', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 968, 0, 0, '', 1034, 0, 0, 0, '', '', '', '', '', '', ''),
(2929, 'michaeliv', '米海尔四世', '米海尔四世', 'byzantium', '', '', '掌权后褫夺佐伊权力，依赖宦官约翰执政并推行加税政策，导致多地饥荒与暴动。抱病镇压塞尔维亚与保加利亚起义。退位入修道院后病逝。', 'https://baike.baidu.com/item/米海尔四世/11023215', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, 'unknown', 0, 0, 0, '', 1041, 0, 0, 0, '', '', '', '', '', '', ''),
(2930, 'michaelv', '米海尔五世', '米海尔五世', 'byzantium', '', '', '试图摆脱皇室监护人的控 制，这直接导致了 1042 年的民众起义。其统治仅持续八个月即被废除，因家族从事船舶修缮业而获得\"敛缝锤\"称号。', 'https://baike.baidu.com/item/米海尔五世/10922509', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, 'unknown', 0, 0, 0, '', 1042, 8, 24, 0, '', '', '', '', '', '', ''),
(2931, 'constantineix', '君士坦丁九世', '君士坦丁九世', 'byzantium', '', '', '与佐伊举行了牧首缺席的婚礼。对外收缩边疆防御；内政推行行省赋税减免政策，加速土地封建化进程。调解东西教会大分裂未果。', 'https://baike.baidu.com/item/君士坦丁九世/4676192', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 1000, 0, 0, '', 1055, 1, 11, 0, '', '', '', '', '', '', ''),
(2932, 'theodora', '狄奥多拉', '狄奥多拉', 'byzantium', '', '', '镇压尼科弗鲁斯·普罗透昂叛乱，重用利奥·帕拉斯庞迪洛斯等近臣。1056年临终前指定米海尔六世继位，马其顿王朝随其逝世终结。', 'https://baike.baidu.com/item/狄奥多拉女皇/2700436', '君主', '马其顿王朝', '帝国历史/大罗马/拜占庭/皇帝_马其顿王朝', 0, '', 984, 0, 0, '', 1056, 9, 0, 0, '', '', '', '', '', '', ''),
(2933, 'phocas', '福卡斯', '福卡斯', 'byzantium', '', '', '发动政变，杀了莫里斯一世皇帝即位(福卡斯之乱)。 在首都大肆屠杀反对者。老希拉克略之子希拉克略抓获并砍了福卡斯的脑袋。', 'https://baike.baidu.com/item/福卡斯/11009192', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, 'unknown', 0, 0, 0, '', 610, 0, 0, 0, '', '', '', '', '', '', ''),
(2934, 'leontios', '利昂提乌斯', '利昂提乌斯', 'byzantium', '', '', '被将军们拥立，开启20年内乱期。缺乏强有力的执政能力。永久失去北非。被政变推翻囚禁于修道院。查士丁尼二世复辟后，将他逮捕并处决。', '', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, 'unknown', 0, 0, 0, '', 705, 0, 0, 0, '', '', '', '', '', '', ''),
(2935, 'tiberiosiii', '提比略三世', '提比略三世', 'byzantium', '', '', '日耳曼雇佣军将领，在迦太基被阿拉伯军队击败回师政变。查士丁尼二世联合保加利亚大汗特尔维尔反攻，与列昂提乌斯一同游街示众后遭处决。', 'https://baike.baidu.com/item/提比略三世/11010767', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, 'unknown', 0, 0, 0, '', 705, 0, 0, 0, '', '', '', '', '', '', ''),
(2936, 'philippikos', '菲利皮科斯', '菲利皮科斯', 'byzantium', '', '', '亚美尼亚贵族出身，依靠基督一志论派支持称帝。罢免东正教大主教塞勒斯，宗教政策加剧帝国东西教会分裂。被奥普西金军区军队刺瞎废黜。', '', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, 'unknown', 0, 0, 0, 'unknown', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2937, 'anastasiusii', '阿纳斯塔修斯二世', '阿纳斯塔修斯二世', 'byzantium', '', '', '组建了一支舰队并派驻罗得岛，重组军队。军队发动叛乱并拥立税务官狄奥多西为帝。流亡至塞萨洛尼卡后皈依修道。后复辟失败被处死。', 'https://baike.baidu.com/item/阿纳斯塔修斯二世/11009036', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, '', 0, 0, 0, '', 721, 0, 0, 0, '', '', '', '', '', '', ''),
(2938, 'theodosiusiii', '狄奥多西三世', '狄奥多西三世', 'byzantium', '', '', '原为奥普西金军区财政官员。面临阿拉伯海陆入侵，与保加利亚缔结条约争取军事支持。利奥三世联合亚美尼亚军区发动政变，被迫退位。', 'https://baike.baidu.com/item/狄奥多西三世/56223393', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2939, 'leov', '利奥五世', '利奥五世', 'byzantium', '', '', '第34位皇帝。一般认为他处于无王朝时期。在位期间曾击败保加利亚，并开始了拜占庭帝国第二次“毁坏圣像运动”时期。', 'https://baike.baidu.com/item/利奥五世/8173513', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, 'probably', 775, 0, 0, '', 820, 12, 25, 0, '', '', '', '', '', '', ''),
(2940, 'michaelvi', '米海尔六世', '米海尔六世', 'byzantium', '', '', '狄奥多拉女皇去世前，将皇位传给了她的宠臣米海尔。11天后，米海尔六世退位，没有受到承认，也不被列入马其顿王朝世系。', 'https://baike.baidu.com/item/米海尔六世/11032783', '君主', '非王朝', '帝国历史/大罗马/拜占庭/皇帝_非王朝', 0, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '', '', '', '', ''),
(2958, 'humayun', '胡马雍', '胡马雍', 'mowoerdiguo', '', '', '由于后来被舍尔沙打败，使得这个阿富汗人统治了印度北部15年之久。死前一直致力于收复失地，1556年死于意外。', 'https://baike.baidu.com/item/胡马雍/8736541', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1508, 0, 0, '', 1556, 0, 0, 0, '', '', '', '', '', '', ''),
(2959, 'akbar', '阿克巴', '阿克巴', 'mowoerdiguo', '', '', '著名的政治家、军事家、宗教改革家。建立有力的军事系统，进行政治及社会的改革。使文化和艺术达到顶峰。建立了多元文化的基础。', 'https://baike.baidu.com/item/阿克巴/443549', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1542, 10, 15, '', 1605, 10, 27, 0, '', '', '', '', '', '', ''),
(2960, 'mohammadsalim', '贾汉吉尔', '贾汉吉尔', 'mowoerdiguo', '', '', '推动波斯文化发展，政局稳定且经济繁荣。册封皇后努尔·贾汗引发外戚专权。与艺妓安娜卡丽的情史是各类文学作品的题材。通晓绘画。', 'https://baike.baidu.com/item/贾汉吉尔/8801350', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1569, 0, 0, '', 1627, 0, 0, 0, '', '', '', '', '', '', ''),
(2961, 'shahjahan', '沙·贾汗', '沙·贾汗', 'mowoerdiguo', '', '', '为第二个妻子（波斯人，传说貌美无比，皮肤如玻璃一样透明，死于难产，奥朗则布皇帝的母亲）修筑了举世闻名的泰姬陵。', 'https://baike.baidu.com/item/沙·贾汗/5927394', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1592, 1, 5, '', 1666, 1, 22, 0, '', '', '', '', '', '', ''),
(2962, 'aurangzeb', '奥朗则布', '奥朗则布', 'mowoerdiguo', '', '', '学识渊博，通晓经训和伊斯兰教法。舍弃宗教宽容国策，激化了国内矛盾。奔波于查特族起义、锡克教徒武装反抗以及拉杰普特人的叛乱中。', 'https://baike.baidu.com/item/奥朗则布/1062425', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1618, 11, 3, '', 1707, 3, 3, 0, '', '', '', '', '', '', ''),
(2963, 'qutbdin', '巴哈杜尔·沙', '巴哈杜尔·沙', 'mowoerdiguo', '', '', '其父在世时负责管理西北部及旁遮普地区。持续面临马拉地人、锡克教徒和拉其普特人的叛乱，帝国统治逐渐衰落。', 'https://baike.baidu.com/item/巴哈杜尔·沙/11045423', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1643, 10, 14, '', 1712, 0, 0, 0, '', '', '', '', '', '', ''),
(2964, 'jahangirshah', '贾汗达尔·沙', '贾汗达尔·沙', 'mowoerdiguo', '', '', '击败弟弟夺取皇位。沉迷宫廷娱乐，生活奢靡，因晋升舞娘为皇后引发争议。在阿格拉战役中被侄儿法鲁克锡亚击败并流放，最终遇刺身亡。', 'https://baike.baidu.com/item/贾汗达尔·沙/20157608', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1661, 0, 0, '', 1713, 0, 0, 0, '', '', '', '', '', '', ''),
(2965, 'farrukhsiyar', '法鲁赫·西亚尔', '法鲁赫·西亚尔', 'mowoerdiguo', '', '', '在萨伊德兄弟支持下处死叔父贾汉达尔沙。镇压锡克人运动并处死领袖班达。授予英国东印度公司多项贸易特权。遭废黜、刺瞎双目并处死。', 'https://baike.baidu.com/item/法鲁赫西亚尔/22928262', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, 'unknown', 0, 0, 0, '', 1719, 0, 0, 0, '', '', '', '', '', '', ''),
(2966, 'rafidallajat', '拉菲·达拉贾特', '拉菲·乌德·达拉贾特', 'mowoerdiguo', '', '', '被赛义德兄弟拥立为傀儡皇帝，执政期间与尼库斯亚尔形成政权对峙。多个君主共存，反映帝国后期皇权更迭的混乱局面。', 'https://baike.baidu.com/item/拉菲·达拉贾特/20157606', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1699, 11, 30, '', 1719, 6, 9, 0, '', '', '', '', '', '', ''),
(2967, 'lafayettedola', '沙贾汗二世', '拉菲·乌德·道拉', 'mowoerdiguo', '', '', '赛义德兄弟的傀儡。他的堂叔父尼库斯亚尔被打败，从新占领阿格拉堡，结束帝国分裂。赛义德兄弟将阿格拉洗劫一空。', 'https://baike.baidu.com/item/沙贾汗二世/20157610', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1696, 0, 0, '', 1719, 0, 0, 0, '', '', '', '', '', '', ''),
(2968, 'roshanakhtar', '穆罕默德沙', '穆罕默德沙', 'mowoerdiguo', '', '', '除掉赛义德兄弟，委任贾赫一世为首相。波斯攻占和洗劫了德里。从此走向衰落。此战后，帝国开始解体，孟加拉、阿富汗等地独立。', 'https://baike.baidu.com/item/穆罕默德沙/22930494', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1702, 0, 0, '', 1748, 0, 0, 0, '', '', '', '', '', '', ''),
(2969, 'ahmedshah', '艾哈迈德沙', '艾哈迈德沙', 'mowoerdiguo', '', '', '阿富汗势力再度入侵后，首相菲罗兹·姜格三世逐步掌控政权，并于1754年将其废黜并拥立阿拉姆吉尔二世。', 'https://baike.baidu.com/item/艾哈迈德沙/22927401', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1725, 0, 0, '', 1775, 0, 0, 0, '', '', '', '', '', '', ''),
(2970, 'alamgirii', '阿拉姆吉尔二世', '阿拉姆吉尔二世', 'mowoerdiguo', '', '', '受控于首相菲罗兹·姜格三世。东印度公司在他任内取得多项决定性的权利。姜格三世策划刺杀行动杀死阿拉姆吉尔二世。', 'https://baike.baidu.com/item/阿拉姆吉尔二世/20175338', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1699, 0, 0, '', 1759, 0, 0, 0, '', '', '', '', '', '', ''),
(2971, 'aligauhar', '沙·阿拉姆二世', '沙·阿拉姆二世', 'mowoerdiguo', '', '', '将莫卧儿帝国的征税权转包给了东印度公司。1771年后成为占领德里的马拉塔人的傀儡。连同其首都转入东印度公司“保护”之下。', 'https://baike.baidu.com/item/沙·阿拉姆二世/20175343', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1728, 0, 0, '', 1806, 0, 0, 0, '', '', '', '', '', '', ''),
(2972, 'mirzaakbar', '阿克巴二世', '阿克巴二世', 'mowoerdiguo', '', '', '第16任皇帝。英国透过东印度公司在印度的影响力日渐増加，阿克巴二世的实权越来越少。', 'https://baike.baidu.com/item/阿克巴二世/20175344', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1760, 4, 22, '', 1837, 9, 28, 0, '', '', '', '', '', '', ''),
(2973, 'bahadurshahii', '巴哈杜尔·沙二世', '巴哈杜尔·沙二世', 'mowoerdiguo', '', '', '莫卧儿帝国末代皇帝，乌尔都语诗人。总督戴贺胥抛出“丧失权利论”。被流放至缅甸。于仰光大金寺去世。', 'https://baike.baidu.com/item/巴哈杜尔·沙二世/7308159', '君主', '莫卧儿', '大国和组织/印度/莫卧儿/君主', 0, '', 1775, 10, 24, '', 1862, 11, 7, 0, '', '', '', '', '', '', ''),
