(3760, 'antiochusviiigrypus', '安条克八世·格吕布波斯', '安条克八世·格吕布波斯', 'sailiuguwangchao', '', '', '绰号\"格吕布波斯\"（鹰钩鼻），与安条克九世内战', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -96, 0, 0, 0, '', '', '', '', '', '', ''),
(3761, 'antiochusixcyzicenus', '安条克九世·基齐库斯', '安条克九世·基齐库斯', 'sailiuguwangchao', '', '', '绰号\"基齐库斯\"（出生地），与安条克八世分割叙利亚', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -95, 0, 0, 0, '', '', '', '', '', '', ''),
(3762, 'seleucusvi', '塞琉古六世', '塞琉古六世', 'sailiuguwangchao', '', '', '被安条克九世之子击败，逃亡中被杀', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -94, 0, 0, 0, '', '', '', '', '', '', ''),
(3763, 'antiochusxeusebes', '安条克十世·埃乌塞贝斯', '安条克十世·埃乌塞贝斯', 'sailiuguwangchao', '', '', '绰号\"埃乌塞贝斯\"（虔诚者），与塞琉古六世兄弟作战', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -92, 0, 0, 0, '', '', '', '', '', '', ''),
(3764, 'demetriusiiieucaerus', '德米特里三世·尤卡鲁斯', '德米特里三世·尤卡鲁斯', 'sailiuguwangchao', '', '', '统治大马士革，被帕提亚俘虏', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -87, 0, 0, 0, '', '', '', '', '', '', ''),
(3765, 'antiochusxi', '安条克十一世', '安条克十一世', 'sailiuguwangchao', '', '', '与腓力一世共治，试图复仇但淹死', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -93, 0, 0, 0, '', '', '', '', '', '', ''),
(3766, 'philipiphiladelphus', '腓力一世·菲拉德尔福斯', '腓力一世·菲拉德尔福斯', 'sailiuguwangchao', '', '', '绰号\"菲拉德尔福斯\"（爱兄弟者，讽刺其杀害兄弟）', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -83, 0, 0, 0, '', '', '', '', '', '', ''),
(3767, 'antiochusxii', '安条克十二世', '安条克十二世', 'sailiuguwangchao', '', '', '统治大马士革，与阿拉伯人作战阵亡', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -84, 0, 0, 0, '', '', '', '', '', '', ''),
(3768, 'seleucusvii', '塞琉古七世', '塞琉古七世', 'sailiuguwangchao', '', '', '统治时期模糊，可能为共治君主', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -69, 0, 0, 0, '', '', '', '', '', '', ''),
(3769, 'antiochusxiiiasiaticus', '安条克十三世·亚细亚提库斯', '安条克十三世·亚细亚提库斯', 'sailiuguwangchao', '', '', '最后一位塞琉古君主，被罗马将军庞培废黜，王朝终结', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -64, 0, 0, 0, '', '', '', '', '', '', ''),
(3770, 'philipiiphiloromaeus', '腓力二世·菲罗罗马乌斯', '腓力二世·菲罗罗马乌斯', 'sailiuguwangchao', '', '', '短暂统治部分领土，被罗马吞并', '', '君主', '塞琉古王朝', '帝国历史/波斯/塞琉古/君主', 0, '', 0, 0, 0, '', -64, 0, 0, 0, '', '', '', '', '', '', ''),
(3771, 'ptolemyisoter', '托勒密一世·索特尔', '托勒密一世·索特尔', 'tuolemiwangchao', '', '', '建立亚历山大图书馆和缪斯宫（博物馆）；参与继业者战争；将亚历山大遗体运至亚历山大港', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -282, 0, 0, 0, '', '', '', '', '', '', ''),
(3772, 'ptolemyiiphiladelphus', '托勒密二世', '托勒密二世·费拉德尔甫斯', 'tuolemiwangchao', '', '', '与姐姐阿尔西诺伊二世结婚（王室内婚始）；扩建亚历山大图书馆；法罗斯岛灯塔建成；与塞琉古帝国的叙利亚战争', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -246, 0, 0, 0, '', '', '', '', '', '', ''),
(3773, 'ptolemyiiieuergetes', '托勒密三世', '托勒密三世·欧厄尔葛忒斯', 'tuolemiwangchao', '', '', '第三次叙利亚战争，短暂占领安条克；领土扩张至王朝最大范围；支持希腊化文化繁荣', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -222, 0, 0, 0, '', '', '', '', '', '', ''),
(3774, 'ptolemyivphilopator', '托勒密四世', '托勒密四世·菲洛帕托尔', 'tuolemiwangchao', '', '', '拉菲亚战役击败安条克三世；任用佞臣索西比乌斯；王室权威开始衰落；埃及人起义频发；可能被谋杀', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -204, 0, 0, 0, '', '', '', '', '', '', ''),
(3775, 'ptolemyvepiphanes', '托勒密五世', '托勒密五世·埃庇法涅斯', 'tuolemiwangchao', '', '', '幼年即位，摄政乱政；失去海外大部分领土；罗塞塔石碑刻制（前196年）；与塞琉古王室联姻；可能被毒杀', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -180, 0, 0, 0, '', '', '', '', '', '', ''),
(3776, 'ptolemyviphilometor', '托勒密六世', '托勒密六世·菲洛墨托尔', 'tuolemiwangchao', '', '', '与弟弟托勒密八世、妹妹克娄巴特拉二世共治；被安条克四世俘虏；罗马介入埃及事务；王朝内斗加剧；与亚历山大·巴拉斯的战斗负伤', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -145, 0, 0, 0, '', '', '', '', '', '', ''),
(3777, 'ptolemyviiieuergetesii', '托勒密八世', '托勒密八世·欧厄尔葛忒斯二世', 'tuolemiwangchao', '', '', '残忍镇压亚历山大港居民；与姐姐克娄巴特拉二世内战；遗嘱将埃及遗赠给罗马（未执行）', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -116, 0, 0, 0, '', '', '', '', '', '', ''),
(3778, 'cleopatraii', '克娄巴特拉二世', '克娄巴特拉二世', 'tuolemiwangchao', '', '', '与两兄弟结婚；领导反对托勒密八世的起义；短暂单独统治（前131-127年）', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -116, 0, 0, 0, '', '', '', '', '', '', ''),
(3779, 'cleopatraiii', '克娄巴特拉三世', '克娄巴特拉三世', 'tuolemiwangchao', '', '', '与儿子托勒密九世、十世争夺权力；实际掌权者；被儿子托勒密十世谋杀', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -101, 0, 0, 0, '', '', '', '', '', '', ''),
(3780, 'ptolemyixsoterii', '托勒密九世', '托勒密九世·索特尔二世', 'tuolemiwangchao', '', '', '被母亲克娄巴特拉三世废黜两次；统治期间亚历山大港内乱；塞浦路斯分离', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -81, 0, 0, 0, '', '', '', '', '', '', ''),
(3781, 'ptolemyxalexanderi', '托勒密十世', '托勒密十世·亚历山大一世', 'tuolemiwangchao', '', '', '谋杀母亲克娄巴特拉三世；被亚历山大港民众驱逐；为筹军饷熔毁亚历山大金棺；海战阵亡', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -88, 0, 0, 0, '', '', '', '', '', '', ''),
(3782, 'ptolemyxialexanderii', '托勒密十一世', '托勒密十一世·亚历山大二世', 'tuolemiwangchao', '', '', '罗马苏拉扶持上位；谋杀妻子贝勒尼基三世；被愤怒的民众私刑处死', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -80, 0, 0, 0, '', '', '', '', '', '', ''),
(3783, 'ptolemyxiiauletes', '托勒密十二世', '托勒密十二世·奥勒忒斯', 'tuolemiwangchao', '', '', '为获罗马承认大肆行贿；被民众驱逐后由罗马恢复王位；将埃及变为罗马保护国；父亲是埃及最后独立君主', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -51, 0, 0, 0, '', '', '', '', '', '', ''),
(3784, 'cleopatraviiphilopator', '克娄巴特拉七世', '克娄巴特拉七世·菲洛帕托尔', 'tuolemiwangchao', '', '', '埃及最后一位法老；与凯撒结盟，生下凯撒里昂；与马克·安东尼结盟；亚克兴角战役败于屋大维；自杀身亡，埃及成为罗马行省；传统说法是毒蛇咬伤', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -30, 0, 0, 0, '', '', '', '', '', '', ''),
(3785, 'ptolemyxiiitheosphilopator', '托勒密十三世', '托勒密十三世·狄奥斯·菲洛帕托尔', 'tuolemiwangchao', '', '', '与姐姐克娄巴特拉七世内战；谋杀庞培；尼罗河战役败于凯撒；逃亡途中溺亡', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -47, 0, 0, 0, '', '', '', '', '', '', ''),
(3786, 'ptolemyxivphilopator', '托勒密十四世', '托勒密十四世·菲洛帕托尔', 'tuolemiwangchao', '', '', '凯撒扶持的傀儡；名义上与克娄巴特拉共同统治；可能对凯撒里昂构成威胁；被克娄巴特拉毒杀（推测）', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -44, 0, 0, 0, '', '', '', '', '', '', ''),
(3787, 'ptolemyxvphilopator', '托勒密十五世', '托勒密十五世·菲洛帕托尔·菲洛墨托尔', 'tuolemiwangchao', '', '', '最后一位托勒密王朝男性成员；名义上与母亲克娄巴特拉共治；屋大维下令处决；王朝血脉终结', '', '君主', '托勒密王朝', '帝国历史/尼罗河流域/托勒密王朝/君主', 0, '', 0, 0, 0, '', -30, 0, 0, 0, '', '', '', '', '', '', ''),
(3788, 'ardashiri', '阿尔达希尔一世', '阿尔达希尔一世', 'sashanwangchao', '', '', '224年击败帕提亚帝国末代皇帝阿尔塔巴努斯四世；建立萨珊王朝，定都泰西封；确立琐罗亚斯德教为国教；推行中央集权改革', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 241, 0, 0, 0, '', '', '', '', '', '', ''),
(3789, 'shapuri', '沙普尔一世', '沙普尔一世', 'sashanwangchao', '', '', '三次与罗马帝国战争；260年在埃德萨战役俘虏罗马皇帝瓦勒良；建造沙普尔洞窟雕像；宽容对待摩尼教，摩尼曾献《沙卜拉干》', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 272, 0, 0, 0, '', '', '', '', '', '', ''),
(3790, 'hormizdi', '霍尔米兹德一世', '霍尔米兹德一世', 'sashanwangchao', '', '', '短暂统治；继续父亲的政策；镇压亚美尼亚叛乱', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 273, 0, 0, 0, '', '', '', '', '', '', ''),
(3791, 'bahrami', '巴赫拉姆一世', '巴赫拉姆一世', 'sashanwangchao', '', '', '迫害摩尼教徒，处死摩尼；受琐罗亚斯德教祭司卡尔提尔影响；与罗马保持和平', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 276, 0, 0, 0, '', '', '', '', '', '', ''),
(3792, 'bahramii', '巴赫拉姆二世', '巴赫拉姆二世', 'sashanwangchao', '', '', '面临弟弟霍尔米兹德叛乱；283年罗马皇帝卡鲁斯入侵；与罗马签订和约；大量钱币和浮雕留存', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 293, 0, 0, 0, '', '', '', '', '', '', ''),
(3793, 'bahramiii', '巴赫拉姆三世', '巴赫拉姆三世', 'sashanwangchao', '', '', '统治仅4个月；被贵族废黜；293年后被废，结局不明', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 293, 0, 0, 0, '', '', '', '', '', '', ''),
(3794, 'narseh', '纳尔斯', '纳尔斯', 'sashanwangchao', '', '', '废黜侄子巴赫拉姆三世；296年在卡利尼古姆战役败于罗马；签订《尼西比斯和约》，割让领土；允许基督教在帝国传播', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 302, 0, 0, 0, '', '', '', '', '', '', ''),
(3795, 'hormizdii', '霍尔米兹德二世', '霍尔米兹德二世', 'sashanwangchao', '', '', '相对和平的统治；镇压东方贵霜和粟特叛乱；建造桥梁和城市；309年被贵族谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 309, 0, 0, 0, '', '', '', '', '', '', ''),
(3796, 'adhurnarseh', '阿杜尔·纳尔斯', '阿杜尔·纳尔斯', 'sashanwangchao', '', '', '统治极短；以残酷著称；被贵族废黜；309年被废后处决', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 309, 0, 0, 0, '', '', '', '', '', '', ''),
(3797, 'shapurii', '沙普尔二世', '沙普尔二世', 'sashanwangchao', '', '', '在位70年，萨珊最长统治；未出生即被加冕；337–350年与罗马长期战争；363年击败朱利安皇帝，收复失地；迫害基督徒；对抗匈尼特人等游牧民族', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 379, 0, 0, 0, '', '', '', '', '', '', ''),
(3798, 'ardashirii', '阿尔达希尔二世', '阿尔达希尔二世', 'sashanwangchao', '', '', '沙普尔二世的兄弟；统治平庸；383年被贵族废黜；383年被废后处决', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 383, 0, 0, 0, '', '', '', '', '', '', ''),
(3799, 'shapuriii', '沙普尔三世', '沙普尔三世', 'sashanwangchao', '', '', '384年与罗马签订和平条约；亚美尼亚被两国瓜分；塔克基布斯塔岩刻；388年疑似被贵族谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 388, 0, 0, 0, '', '', '', '', '', '', ''),
(3800, 'bahramiv', '巴赫拉姆四世', '巴赫拉姆四世', 'sashanwangchao', '', '', '统治期间相对和平；镇压克尔曼叛乱；399年被叛乱士兵杀死', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 399, 0, 0, 0, '', '', '', '', '', '', ''),
(3801, 'yazdegerdi', '伊嗣俟一世', '伊嗣俟一世', 'sashanwangchao', '', '', '绰号\"罪人\"（基督教观点）或\"仁慈者\"；宗教宽容政策；与罗马皇帝阿尔卡迪乌斯友好；允许基督教发展；迫害琐罗亚斯德教祭司；420年被贵族谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 420, 0, 0, 0, '', '', '', '', '', '', ''),
(3802, 'bahramv', '巴赫拉姆五世', '巴赫拉姆五世', 'sashanwangchao', '', '', '绰号\"野驴\"；在阿拉伯拉赫姆王朝支持下即位；421–422年与罗马战争；镇压亚美尼亚叛乱；波斯文学中传奇人物；438年狩猎中意外死亡', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 438, 0, 0, 0, '', '', '', '', '', '', ''),
(3803, 'yazdegerdii', '伊嗣俟二世', '伊嗣俟二世', 'sashanwangchao', '', '', '441年与东罗马短暂战争；迫害基督徒和犹太人；对抗嚈哒人；451年亚美尼亚瓦尔丹·马米科尼扬起义', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 457, 0, 0, 0, '', '', '', '', '', '', ''),
(3804, 'hormizdiii', '霍尔米兹德三世', '霍尔米兹德三世', 'sashanwangchao', '', '', '与兄弟卑路斯争位；统治仅限于部分地区；459年被卑路斯击败处决', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 459, 0, 0, 0, '', '', '', '', '', '', ''),
(3805, 'perozi', '卑路斯一世', '卑路斯一世', 'sashanwangchao', '', '', '与嚈哒人多次战争；两次被嚈哒人俘虏；支付巨额赎金；484年在赫拉特战役阵亡；导致帝国危机；484年与嚈哒人作战阵亡', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 484, 0, 0, 0, '', '', '', '', '', '', ''),
(3806, 'balash', '巴拉什', '巴拉什', 'sashanwangchao', '', '', '卑路斯一世的兄弟；向嚈哒人纳贡；宗教宽容；488年被贵族和祭司废黜；488年被废后失明囚禁', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 488, 0, 0, 0, '', '', '', '', '', '', ''),
(3807, 'kavadi', '卡瓦德一世', '卡瓦德一世', 'sashanwangchao', '', '', '两次在位；支持马兹达克运动（社会改革）；496年被贵族废黜；在嚈哒人帮助下复位；502–506年与东罗马战争；建立城市和灌溉系统', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 531, 0, 0, 0, '', '', '', '', '', '', ''),
(3808, 'jamasp', '扎马斯普', '扎马斯普', 'sashanwangchao', '', '', '卡瓦德一世的兄弟；贵族拥立的傀儡；镇压马兹达克运动；统治温和但短暂；498年让位给卡瓦德一世后结局不明', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 498, 0, 0, 0, '', '', '', '', '', '', ''),
(3809, 'khosrowi', '库思老一世', '库思老一世', 'sashanwangchao', '', '', '绰号\"不朽的灵魂\"；萨珊王朝最伟大的统治者；推行全面改革（行政、军事、财政）；540年洗劫安条克；561年与东罗马签订50年和约；灭嚈哒人；庇护希腊哲学家；文学艺术繁荣', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 579, 0, 0, 0, '', '', '', '', '', '', ''),
(3810, 'hormizdiv', '霍尔米兹德四世', '霍尔米兹德四世', 'sashanwangchao', '', '', '与东罗马和突厥两线作战；宗教宽容政策；镇压贵族和祭司势力；被将军巴赫拉姆·楚宾叛乱推翻；590年被政变处决', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 590, 0, 0, 0, '', '', '', '', '', '', ''),
(3811, 'bahramvichobin', '巴赫拉姆六世·楚宾', '巴赫拉姆六世·楚宾', 'sashanwangchao', '', '', '出身米赫兰贵族家族；590年击败霍尔米兹德四世自立；非萨珊正统，统治不被广泛承认；被库思老二世和东罗马联军击败；591年败逃突厥后被谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 591, 0, 0, 0, '', '', '', '', '', '', ''),
(3812, 'khosrowii', '库思老二世', '库思老二世', 'sashanwangchao', '', '', '绰号\"胜利者\"；在东罗马莫里斯皇帝帮助下复位；619年占领埃及；626年围攻君士坦丁堡失败；627年尼尼微战役惨败；被贵族废黜；628年被儿子卡瓦德二世处决', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 628, 0, 0, 0, '', '', '', '', '', '', ''),
(3813, 'kavadii', '卡瓦德二世', '卡瓦德二世', 'sashanwangchao', '', '', '绰号\"瘟疫之王\"；即位后处决所有兄弟（17人）；与东罗马签订屈辱和约；归还征服领土和真十字架；628年瘟疫去世', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 628, 0, 0, 0, '', '', '', '', '', '', ''),
(3814, 'ardashiriii', '阿尔达希尔三世', '阿尔达希尔三世', 'sashanwangchao', '', '', '即位时仅7岁；实权在将军沙赫尔巴拉兹手中；傀儡皇帝；629年被沙赫尔巴拉兹谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 629, 0, 0, 0, '', '', '', '', '', '', ''),
(3815, 'shahrbaraz', '沙赫尔巴拉兹', '沙赫尔巴拉兹', 'sashanwangchao', '', '', '库思老二世时期的名将；谋杀阿尔达希尔三世自立；非萨珊正统，统治仅40天；629年被政变杀死', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 629, 0, 0, 0, '', '', '', '', '', '', ''),
(3816, 'hormizdv', '霍尔米兹德五世', '霍尔米兹德五世', 'sashanwangchao', '', '', '混乱时期的短暂统治者；控制范围有限；632年被推翻', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 632, 0, 0, 0, '', '', '', '', '', '', ''),
(3817, 'boran', '布兰德女王', '布兰德女王', 'sashanwangchao', '', '', '萨珊王朝唯一的女王；两次在位；试图稳定帝国；与东罗马修复关系；重建行政系统；632年被政变推翻并谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 632, 0, 0, 0, '', '', '', '', '', '', ''),
(3818, 'azarmidokht', '阿扎米女王', '阿扎米女王', 'sashanwangchao', '', '', '库思老二世之女；布兰德的姐妹；短暂统治；631年被将军法鲁克·霍尔米兹德谋杀', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 631, 0, 0, 0, '', '', '', '', '', '', ''),
(3819, 'hormizdvi', '霍尔米兹德六世', '霍尔米兹德六世', 'sashanwangchao', '', '', '混乱时期的地区统治者；控制尼西比斯地区；632年后结局不明', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 632, 0, 0, 0, '', '', '', '', '', '', ''),
(3820, 'yazdegerdiii', '伊嗣俟三世', '伊嗣俟三世', 'sashanwangchao', '', '', '萨珊王朝末代皇帝；即位时帝国已分崩离析；636年卡迪西亚战役惨败于阿拉伯人；642年尼哈旺德战役决定性失败；逃亡东方各省；651年在木鹿被谋杀；651年被谋杀，萨珊王朝灭亡', '', '君主', '萨珊王朝', '帝国历史/波斯/萨珊/君主', 0, '', 0, 0, 0, '', 651, 0, 0, 0, '', '', '', '', '', '', ''),
