(4970, 'wakatsuki_reijiro', '若槻礼次郎', '若槻礼次郎', 'jp', '', '', '两度组阁，因金融危机和满洲事件辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_大正时期', 0, '', 1866, 0, 0, '', 1949, 0, 0, 0, '', '', '', '', '', '', ''),
(4971, 'tanaka_giichi', '田中义一', '田中义一', 'jp', '', '', '陆军大将，推行对华强硬政策，因皇姑屯事件辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1864, 0, 0, '', 1929, 0, 0, 0, '', '', '', '', '', '', ''),
(4972, 'hamaguchi_osachi', '滨口雄幸', '滨口雄幸', 'jp', '', '', '推行金解禁政策，在东京站遭狙击，后因伤重辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1870, 0, 0, '', 1931, 0, 0, 0, '', '', '', '', '', '', ''),
(4973, 'inukai_tsuyoshi', '犬养毅', '犬养毅', 'jp', '', '', '政友会总裁，因“五一五事件”被军人暗杀。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1855, 0, 0, '', 1932, 0, 0, 0, '', '', '', '', '', '', ''),
(4974, 'saito_makoto', '斋藤实', '斋藤实', 'jp', '', '', '海军大将，组建“举国一致”内阁，因帝人事件辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1858, 0, 0, '', 1936, 0, 0, 0, '', '', '', '', '', '', ''),
(4975, 'okada_keisuke', '冈田启介', '冈田启介', 'jp', '', '', '海军大将，因“二二六事件”被迫辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1868, 0, 0, '', 1952, 0, 0, 0, '', '', '', '', '', '', ''),
(4976, 'hirota_koki', '广田弘毅', '广田弘毅', 'jp', '', '', '外交官出身，推行国家总动员体制，战后被处决。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1878, 0, 0, '', 1948, 0, 0, 0, '', '', '', '', '', '', ''),
(4977, 'hayashi_senjuro', '林铣十郎', '林铣十郎', 'jp', '', '', '陆军大将，组阁仅4个月便倒台。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1876, 0, 0, '', 1943, 0, 0, 0, '', '', '', '', '', '', ''),
(4978, 'konoe_fumimaro', '近卫文麿', '近卫文麿', 'jp', '', '', '贵族出身，三次组阁，发动全面侵华战争，战后自杀。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1891, 0, 0, '', 1945, 0, 0, 0, '', '', '', '', '', '', ''),
(4979, 'hiranuma_kiichiro', '平沼骐一郎', '平沼骐一郎', 'jp', '', '', '司法官僚出身，因诺门罕战役问题辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1867, 0, 0, '', 1952, 0, 0, 0, '', '', '', '', '', '', ''),
