(4981, 'yonai_mitsumasa', '米内光政', '米内光政', 'jp', '', '', '海军大将，因陆军反对倒台。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1880, 0, 0, '', 1948, 0, 0, 0, '', '', '', '', '', '', ''),
(4982, 'tojo_hideki', '东条英机', '东条英机', 'jp', '', '', '陆军大将，发动太平洋战争，战后被处决。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1884, 0, 0, '', 1948, 0, 0, 0, '', '', '', '', '', '', ''),
(4983, 'koiso_kuniaki', '小矶国昭', '小矶国昭', 'jp', '', '', '陆军大将，因战局不利辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1880, 0, 0, '', 1950, 0, 0, 0, '', '', '', '', '', '', ''),
(4984, 'suzuki_kantaro', '铃木贯太郎', '铃木贯太郎', 'jp', '', '', '海军大将，主持终战工作，战后辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1868, 0, 0, '', 1948, 0, 0, 0, '', '', '', '', '', '', ''),
(4985, 'higashikuni_naruhiko', '东久迩宫稔彦王', '东久迩宫稔彦王', 'jp', '', '', '皇族，首位皇族首相，负责战后处理。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1887, 0, 0, '', 1990, 0, 0, 0, '', '', '', '', '', '', ''),
(4986, 'shidehara_kijuro', '币原喜重郎', '币原喜重郎', 'jp', '', '', '外交官出身，推行“币原外交”，制定新宪法草案。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和二战', 0, '', 1872, 0, 0, '', 1951, 0, 0, 0, '', '', '', '', '', '', ''),
(4987, 'yoshida_shigeru', '吉田茂', '吉田茂', 'jp', '', '', '战后日本奠基人，五次组阁，签订《旧金山和约》。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1878, 0, 0, '', 1967, 0, 0, 0, '', '', '', '', '', '', ''),
(4988, 'katayama_tetsu', '片山哲', '片山哲', 'jp', '', '', '首位社会党出身首相，组建联合内阁。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1887, 0, 0, '', 1978, 0, 0, 0, '', '', '', '', '', '', ''),
(4989, 'ashida_hitoshi', '芦田均', '芦田均', 'jp', '', '', '民主党总裁，因昭和电工事件辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1887, 0, 0, '', 1959, 0, 0, 0, '', '', '', '', '', '', ''),
(4990, 'hatoyama_ichiro', '鸠山一郎', '鸠山一郎', 'jp', '', '', '自民党创始人，实现日苏邦交正常化。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1883, 0, 0, '', 1959, 0, 0, 0, '', '', '', '', '', '', ''),
(4991, 'ishibashi_tanzan', '石桥湛山', '石桥湛山', 'jp', '', '', '财政专家，因健康问题辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1884, 0, 0, '', 1973, 0, 0, 0, '', '', '', '', '', '', ''),
(4992, 'kishi_nobusuke', '岸信介', '岸信介', 'jp', '', '', '安倍晋三外祖父，修订《日美安保条约》，遇刺后辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1896, 0, 0, '', 1987, 0, 0, 0, '', '', '', '', '', '', ''),
(4993, 'ikeda_hayato', '池田勇人', '池田勇人', 'jp', '', '', '推行“国民收入倍增计划”，因病辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1899, 0, 0, '', 1965, 0, 0, 0, '', '', '', '', '', '', ''),
(4994, 'sato_eisaku', '佐藤荣作', '佐藤荣作', 'jp', '', '', '岸信介之弟，执政时间最长，实现冲绳回归。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和战后', 0, '', 1901, 0, 0, '', 1975, 0, 0, 0, '', '', '', '', '', '', ''),
(4995, 'tanaka_kakuei', '田中角荣', '田中角荣', 'jp', '', '', '实现日中邦交正常化，因洛克希德事件辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和繁荣', 0, '', 1918, 0, 0, '', 1993, 0, 0, 0, '', '', '', '', '', '', ''),
