(4998, 'ohira_masayoshi', '大平正芳', '大平正芳', 'jp', '', '', '推行“综合安全保障”政策，病逝于任内。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和繁荣', 0, '', 1910, 0, 0, '', 1980, 0, 0, 0, '', '', '', '', '', '', ''),
(4999, 'suzuki_zenko', '铃木善幸', '铃木善幸', 'jp', '', '', '自民党主流派领袖，因行政改革问题辞职。', '', '首相', '日本', '大国和组织/日本/人物/首相_昭和繁荣', 0, '', 1911, 0, 0, '', 2004, 0, 0, 0, '', '', '', '', '', '', ''),
