(69, 'burckhardt', '布克哈特', '雅各布·布克哈特', 'ch', '', '', '19世纪瑞士著名文化艺术史学家，致力于欧洲文化史研究，以期更开阔的视野来展现欧洲各个历史时期的文化特征与时代风貌。', 'https://baike.baidu.com/item/布克哈特/19175372', '', '', '', 1, '', 1818, 1, 25, '', 1897, 8, 8, 0, '', '1818-1897 (81岁)', 'books/学术名著/其他国家/瑞士/布克哈特/figure', '', '瑞士', '', 'bukehate'),
(191, 'buren', '范布伦', '马丁·范布伦', 'us', '', '', '美国第八任副总统（1833年－\r\n1837年）及第八任总统（1837年－1841年），他是《美国独立宣言》正式签署后出生的第一位总统。', 'https://baike.baidu.com/item/马丁·范布伦/2652550', '', '', '', 9, '', 1782, 12, 5, '', 1862, 7, 24, 0, '', '', '', '', '美国', '', 'buren'),
