(846, 'burlamaqui', '布拉马克', '让-雅克·布拉马克', 'ch', '', '', '18世纪瑞士日内瓦重要的自然法理论家，属于被广泛征引的自然法理论家之列，其思想对美国革命和建国时期的政治思想产生了重大影响。', '', '', '', '', 0, '', 1694, 0, 0, '', 1748, 0, 0, 0, '', '1694-1748 (54岁)', 'books/学术名著/其他国家/瑞士/布拉马克/figure', '', '瑞士', '', ''),
(279, 'burtt', '伯特', '埃德温·阿瑟·伯特', 'us', '', '', '美国哲学家、历史学家。哥伦比亚大学哲学博士，康奈尔大学哲学教授。', 'https://www.douban.com/personage/35460209/', '', '', '', 1, '', 1892, 0, 0, '', 1989, 0, 0, 0, '', '1892-1989 (97岁)', 'books/学术名著/美国/伯特/figure', '', '美国', '', ''),
