(587, 'duanyifu', '段义孚', '段义孚', 'us', '', '', '华裔地理学家。他将人的种种主观情性与客观地理环境的丰富关系进行了极具智慧的阐发，吸引了众多学者的目光。', 'https://baike.baidu.com/item/段义孚', '', '', '', 1, '', 1930, 12, 5, '', 2022, 8, 10, 0, '', '1930-2022/8/10 (92岁)', 'books/学术名著/美国/段义孚/figure', '', '美国', '', ''),
(2442, 'duanzhigui', '段芝贵', '段芝贵', 'beiyang', '安徽合肥', '', '皖系军阀，民国时期京畿警备司令、陆军总长。参加镇压义和团被保升为道员。直皖战争失败后被通缉，置居天津。', 'https://baike.baidu.com/item/段芝贵/2679253', '', '', '', 0, '', 1869, 0, 0, '', 1925, 3, 0, 0, '', '', '', '', '', '', ''),
