(413, 'febvre', '费弗尔', '吕西安·费弗尔', 'fr', '', '', '二十世纪史学大师、年鉴学派的创始人。', 'https://baike.baidu.com/item/吕西安·费弗尔', '', '', '', 1, '', 1878, 7, 22, '', 1956, 9, 11, 0, '', '1878/7/22-1956/9/11 (78岁)', 'books/学术名著/法国/费弗尔/figure', '', '法国', '', ''),
(1215, 'fen', '鲁共公', '奋', 'luguo', '', '', '前382年—前353年(杨宽)。前373年，齐田午弑其君田剡(yǎn)自立，鲁伐齐。前356年朝魏，与楚宣王饮酒不欢，楚联齐伐鲁。鲁共公择言。', 'https://baike.baidu.com/item/鲁共公/0', '', '', '', 9, 'unknown', 0, 0, 0, '', -353, 0, 0, 0, '', '', '古代中国/先秦时期/诸侯国/鲁国/人物/奋/figure', 'luguo', '', '', ''),
