(1651, 'fujiangaozu', '苻健', '苻健', 'qianqin', '', '', '', 'https://baike.baidu.com/item/苻健/24813', '', '', '', 9, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '古代中国/魏晋南北朝/十六国/前秦/人物/苻健/figure', 'qianqin', '', '', ''),
(60, 'fukuzawa', '福泽谕吉', '福泽谕吉', 'jp', '', '', '日本近代著名启蒙思想家、明治时期杰出的教育家、日本近代第一位军国主义理论家、日本著名私立大学庆应义塾大学的创立者。', 'https://baike.baidu.com/item/福泽谕吉/1137850', '', '', '', 1, '', 1835, 1, 10, '', 1901, 2, 3, 0, '', '1835/1/10-1901/2/3 (66岁)', 'books/学术名著/其他国家/日本/福泽谕吉/figure', '', '日本', '', 'fuzeyuji'),
(2083, 'fulin', '福临', '福临', 'qingchao', '辽宁沈阳', '', '迁都北京。睿亲王多尔衮摄政。加强皇权，停止圈地，缓和民族矛盾。大规模的抗清武装力量基本被平定。', 'https://baike.baidu.com/item/爱新觉罗·福临/2163834', '君主', '', '', 9, '', 1638, 3, 15, '', 1661, 2, 5, 0, '', '', '古代中国/明清时期/清朝/人物/福临/figure', 'qingchao', '', '', ''),
(472, 'fuller', '富勒', '朗·富勒', 'us', '', '', '当代美国著名法理学家，第二次世界大战后新自然法学派的主要代表之一。', 'https://baike.baidu.com/item/朗·富勒/5355776', '', '', '', 1, '', 1902, 0, 0, '', 1978, 0, 0, 0, '', '1902-1978 (76岁)', 'books/学术名著/美国/富勒/figure', '', '美国', '', ''),
(2077, 'fuman', '福满', '福满', 'qingchao', '', '', '努尔哈赤的曾祖父，清朝追封兴祖直皇帝。', 'https://baike.baidu.com/item/爱新觉罗·福满/2469834', '君主', '其他', '', 9, 'unknown', 0, 0, 0, 'unknown', 0, 0, 0, 0, '', '', '古代中国/明清时期/清朝/人物/福满/figure', 'qingchao', '', '', ''),
