(578, 'gregory', '格雷戈里', '格雷戈里', 'fr', '', '', '格雷戈里是法兰克第一位典型的历史学家。他的当代史写作风格像希罗多德，因此被称为 “蛮族的希罗多德” 。', 'https://baike.baidu.com/item/格雷戈里/6104781', '', '', '', 1, '', 539, 0, 0, '', 594, 0, 0, 0, '', '539-594 (55岁)', 'books/学术名著/法国/格雷戈里/figure', '', '法国', '', ''),
(747, 'grekov', '格列科夫', '鲍里斯·德米特里耶维奇·格列科夫', 'ussr', '', '', '苏联历史学家、社会活动家，主要研究俄国封建时期的历史。', 'https://baike.baidu.com/item/鲍里斯·德米特里耶维奇·格列科夫/22887110', '', '', '', 1, '', 1882, 0, 0, '', 1953, 0, 0, 0, '', '1882-1953 (71岁)', 'books/学术名著/俄罗斯/苏联/格列科夫/figure', '', '苏联', '', ''),
(894, 'grice', '格莱斯', '保罗·格莱斯', 'gb', '', '', '著名英国哲学家，属于分析哲学学派，著作以语言哲学为主。', 'https://baike.baidu.com/item/保罗·格莱斯/19276062', '', '', '', 0, '', 1913, 3, 13, '', 1988, 8, 28, 0, '', '1913/3/13-1988/8/28 (75岁)', 'books/学术名著/英国/格莱斯/figure', '', '英国', '', ''),
