(917, 'jgray', 'J·格雷', '约翰·格雷', 'gb', '', '', '当代英国著名政治哲学家、思想史家，曾任牛津大学政治学教授、伦敦政治经济学院欧洲思想教授。', '', '', '', '', 0, '', 1948, 0, 0, 'running', 0, 0, 0, 0, '', '1948-', 'books/学术名著/英国/J_格雷/figure', '', '英国', '', ''),
(660, 'jhering', '耶林', '鲁道夫·冯·耶林', 'de', '', '', '19世纪西欧最伟大的法学家，也是新功利主义（目的）法学派的创始人，其思想不仅对西欧，而且对全世界都产生了巨大的影响。', 'https://baike.baidu.com/item/耶林', '', '', '', 1, '', 1818, 8, 22, '', 1892, 9, 17, 0, '', '1818/8/22-1892/9/17 (74岁)', 'books/学术名著/德国/耶林/figure', '', '德国', '', ''),
