(774, 'kongzi', '孔子', '孔子', 'luguo', '', '', '中国古代思想家、政治家、教育家，儒家学派创始人。孔子创立的儒家学说精华是中华优秀传统文化的重要组成部分。', 'https://baike.baidu.com/item/孔子/1584', '', '', '', 0, '', -551, 9, 28, '', -479, 4, 11, 0, '', '前551/9/28-前479/4/11 (72岁)', '古代中国/先秦时期/春秋/孔子', '', '', '', ''),
(418, 'kopernik', '哥白尼', '尼古拉·哥白尼', 'pl', '', '', '文艺复兴时期波兰天文学家、数学家、教会法博士、神父。哥白尼的“日心说”更正了人们的宇宙观。', 'https://baike.baidu.com/item/尼古拉·哥白尼', '', '', '', 1, '', 1473, 2, 19, '', 1543, 5, 24, 0, '', '1473/2/19-1543/5/24 (70岁)', 'books/学术名著/其他国家/波兰/哥白尼/figure', '', '波兰', '', ''),
(343, 'kornai', '科尔奈', '雅诺什·科尔奈', 'hu', '', '', '匈牙利科学院院士、哈佛大学教授。曾多次提名诺贝尔经济学奖。', 'https://baike.baidu.com/item/雅诺什·科尔奈/4455426', '', '', '', 1, '', 1928, 1, 21, '', 2021, 10, 18, 0, '', '1928/1/21-2021/10/18 (93岁)', 'books/学术名著/其他国家/匈牙利/科尔奈/figure', '', '匈牙利', '', ''),
