(761, 'mozi', '墨子', '墨子', 'songguo', '', '', '', 'https://baike.baidu.com/item/墨子/245', '', '', '', 0, 'probably', -476, 0, 0, 'probably', -390, 0, 0, 0, '', '约前476-约前390年 (86岁)', '古代中国/先秦时期/春秋/墨子', '', '', '', ''),
(677, 'mufwene', '穆夫温', '萨利科科·S·穆夫温', 'us', '', '', '美国享有国际声望的社会语言学家，曽任芝加哥大学语言学系教授和系主任。', '', '', '', '', 1, '', 1947, 0, 0, 'running', 0, 0, 0, 0, '', '', 'books/学术名著/美国/穆夫温/figure', '', '美国', '', ''),
(478, 'mulk', '莫尼克', '尼扎姆·莫尼克', 'ir', '', '', '阿尔普·阿尔斯兰在他的帮助下夺取了大塞尔柱帝国苏丹王位，并任命他为大塞尔柱帝国宰相。', '', '', '', '', 9, '', 1019, 0, 0, '', 1092, 0, 0, 0, '', '', 'books/学术名著/其他国家/波斯/莫尼克/figure', '', '伊朗', '', ''),
(100, 'mumby', '姆贝', '丹尼斯.姆贝', 'gb', '', '', '美国著名组织传播学学者，专注于批判理论、话语分析、权力与组织文化研究。', '', '', '', '', 1, 'unknown', 0, 0, 0, 'unknown', 0, 0, 0, 0, '', '', 'books/学术名著/英国/姆贝/figure', '', '英国', '', 'mubei'),
