(40, 'pascal', '帕斯卡', '布莱士·帕斯卡', 'fr', '', '', '法国数学家、物理学家、哲学家、散文家。后人为纪念帕斯卡，用他的名字来命名压强的单位“帕斯卡”，简称“帕”。', 'https://baike.baidu.com/item/布莱士·帕斯卡/8791342', '', '', '', 1, '', 1623, 6, 19, '', 1662, 8, 19, 0, '', '1623/6/19-1662/8/19 (39岁)', 'books/学术名著/法国/帕斯卡/figure', '', '法国', '', 'pasikaer'),
(822, 'pashukanis', '帕舒卡尼斯', '帕舒卡尼斯', 'ussr', '', '', '享有国际学术声誉的法学家。', 'https://baike.baidu.com/item/帕舒卡尼斯/10068583', '', '', '', 0, '', 1891, 2, 23, '', 1937, 0, 0, 0, '', '1891/2/23-1937 (46岁)', 'books/学术名著/俄罗斯/苏联/帕舒卡尼斯/figure', '', '苏联', '', ''),
