(1642, 'zhangxuanjing', '张玄靓', '张玄靓', 'qianliang', '', '', '', 'https://baike.baidu.com/item/张玄靓/9575114', '', '', '', 9, '', 0, 0, 0, '', 0, 0, 0, 0, '', '', '古代中国/魏晋南北朝/十六国/前凉/人物/张玄靓/figure', 'qianliang', '', '', ''),
(2450, 'zhangxueliang', '张学良', '张学良', 'beiyang', '奉天台安', '', '近代著名爱国将领。宣布东北易帜，服从南京国民政府。同杨虎城一起发动“西安事变”。遭蒋介石父子长期软禁，病逝于檀香山。', 'https://baike.baidu.com/item/张学良/385', '', '', '', 0, '', 1901, 6, 3, '', 2001, 10, 14, 0, '', '', '', '', '', '', ''),
